import { createHash } from "node:crypto"
import path from "node:path"
import { defaultSummarizeOptions, recoveryLine, summarize } from "hugr-lean/core"
import { RawStore, recallLines } from "hugr-lean/raw"
import { Global } from "../global"

export { defaultSummarizeOptions, recallLines, recoveryLine, summarize }

/** Native tools whose model-visible text Lean 2.0 summarizes or compacts. */
export const tools = ["bash", "read", "webfetch", "glob", "grep"] as const
export type Tool = (typeof tools)[number]
export const supported = (tool: string): tool is Tool => tools.some((item) => item === tool)

export const MAX_BYTES = 64 * 1024 * 1024
export const TTL_MS = 7 * 24 * 60 * 60 * 1000
const stores = new Map<string, RawStore>()

/** Same identity as the Lean profile preferences: one project at one directory. */
export function directory(owner: { readonly projectID: string; readonly directory: string }, root = Global.Path.data) {
  const id = createHash("sha256").update(JSON.stringify([owner.projectID, owner.directory])).digest("hex")
  return path.join(root, "lean", "raw", id)
}

/** Bounded, self-cleaning store of complete originals: expired records go on every write, the oldest when full. */
export function store(owner: { readonly projectID: string; readonly directory: string }, root?: string) {
  const location = directory(owner, root)
  const existing = stores.get(location)
  if (existing) return existing
  const created = new RawStore({ directory: location, maxBytes: MAX_BYTES, ttlMs: TTL_MS, evict: true })
  stores.set(location, created)
  return created
}

export * as LeanProcessor from "./lean-processor"

import { filter, getProfiles, tokenizeCommand, type Observation } from "hugr-lean/core"
import { LeanCoverage } from "@orchestra/schema/lean-coverage"

const profiles = getProfiles()

/** Classify all actual built-ins before applying settings; disabled profiles cannot hide overlap. */
export function identify(command: string): LeanCoverage.ItemID | undefined {
  const argv = tokenizeCommand(command)
  if (!argv) return undefined
  const matched = profiles.filter((profile) => profile.match(argv))
  if (matched.length > 1) return undefined
  if (matched.length === 1) return LeanCoverage.forProfile(matched[0]!.id)
  return exactItem(argv)
}

/** One actual package engine; settings only select profiles, never rewrite observations. */
export function process(observation: Observation, items?: LeanCoverage.Settings) {
  try {
    const id = identify(observation.command)
    const selected = id && items?.[id] === false ? [] : profiles
    return filter(observation, { profiles: selected })
  } catch {
    // Keep the package's own fail-open boundary for malformed observations or host settings.
    return filter(observation, { profiles: [] })
  }
}

function exactItem(argv: readonly string[]): LeanCoverage.ItemID | undefined {
  // Preservation attribution only. Prefixes inspected in fixtures/profiles/*/cases.json at leanPin.commit;
  // no output grammar, shell wrappers, inferred script aliases, or invented reducers.
  if (argv.length > 64) return undefined
  const tool = argv[0]!.split("/").at(-1)
  if (tool === "cargo" && ["bench", "doc", "fetch", "install", "fmt", "nextest"].includes(argv[1] ?? "")) return "cargo"
  if (tool === "go" && (["build", "vet"].includes(argv[1] ?? "") || argv[1] === "test" && argv.slice(2).some((arg) => arg === "-bench" || arg.startsWith("-bench=")))) return "go"
  if (tool === "bun" && ["install", "test"].includes(argv[1] ?? "")) return "bun"
  if (tool === "npm" && ["install", "ci"].includes(argv[1] ?? "")) return "npm"
  if (tool === "yarn" && argv[1] === "install") return "yarn"
  if (tool === "pip" && argv[1] === "install") return "pip"
  if (tool === "python" && argv[1] === "-m" && argv[2] === "pip" && argv[3] === "install") return "pip"
  if (tool === "uv" && (["sync", "lock"].includes(argv[1] ?? "") || argv[1] === "pip" && ["install", "sync"].includes(argv[2] ?? ""))) return "uv"
  if (tool === "golangci-lint" && argv[1] === "run") return "golangci"
  if (tool === "vite" && argv[1] === "build") return "vite"
  if (tool === "node" && /(?:^|\/)node_modules\/next\/dist\/bin\/next$/.test(argv[1] ?? "") && argv[2] === "build") return "next"
  if (tool === "npx" && (argv[1] === "prettier" || argv[1] === "--no-install" && argv[2] === "prettier")) return "prettier"
  const direct = { esbuild: "esbuild", "markdownlint-cli2": "markdownlint", mypy: "mypy", prettier: "prettier",
    rollup: "rollup", shellcheck: "shellcheck", stylelint: "stylelint", webpack: "webpack" } as const
  return tool && Object.hasOwn(direct, tool) ? direct[tool as keyof typeof direct] : undefined
}

export * as LeanTelemetry from "./lean-telemetry"

import { LeanMetrics } from "@orchestra/schema/lean-metrics"
import { LeanEngine } from "@orchestra/schema/lean-engine"
import { Token } from "../util/token"

export interface Input {
  readonly owner: LeanMetrics.Decision["owner"]
  readonly model: LeanMetrics.Decision["model"]
  readonly orchestraProfile?: string
  readonly producer: LeanMetrics.Decision["producer"]
  readonly eligible: boolean
  readonly status: LeanMetrics.Decision["status"]
  readonly reason: string
  readonly filterProfile?: string
  readonly itemID?: LeanMetrics.Decision["itemID"]
  readonly before: string
  readonly after: string
  readonly durationMs: number
}

/** Frozen measurement seam; metrics author replaces explicit unavailable scaffold. */
export const measure: (input: Input) => LeanMetrics.Decision | undefined = (input) => {
  try {
    const { owner, model, orchestraProfile, producer, eligible, status, reason, filterProfile, itemID, before, after, durationMs } = input
    if (typeof before !== "string" || typeof after !== "string"
      || [before, after].some((text) => /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u.test(text))
      || (status === "passthrough" && before !== after)) return undefined
    const beforeBytes = Buffer.byteLength(before, "utf8")
    const afterBytes = Buffer.byteLength(after, "utf8")
    const beforeTokens = Token.estimate(before)
    const afterTokens = Token.estimate(after)
    return LeanMetrics.decode({
      version: 1, scope: "standard-registry", engine: LeanEngine.current,
      owner, model, orchestraProfile, producer, eligible, status, reason, filterProfile, itemID, durationMs,
      bytes: { before: beforeBytes, after: afterBytes, saved: beforeBytes - afterBytes },
      tokens: { kind: "estimated", counter: "chars-per-token-4", before: beforeTokens, after: afterTokens, saved: beforeTokens - afterTokens },
    })
  } catch {
    return undefined
  }
}

import { Effect, Stream } from "effect"
import { HttpClientResponse } from "effect/unstable/http"

export const collectBoundedResponseBody = (
  response: HttpClientResponse.HttpClientResponse,
  maximumBytes: number,
  tooLarge: () => Error,
) =>
  Effect.gen(function* () {
    const contentLength = response.headers["content-length"]
    const parsedSize = contentLength ? Number.parseInt(contentLength, 10) : undefined
    const declaredSize =
      parsedSize !== undefined && Number.isSafeInteger(parsedSize) && parsedSize >= 0 ? parsedSize : undefined
    if (declaredSize !== undefined && declaredSize > maximumBytes) return yield* Effect.fail(tooLarge())
    let body = Buffer.allocUnsafe(Math.min(maximumBytes, declaredSize || 64 * 1024))
    let size = 0
    yield* Stream.runForEach(response.stream, (chunk) => {
      if (chunk.byteLength === 0) return Effect.void
      if (size + chunk.byteLength > maximumBytes) return Effect.fail(tooLarge())
      if (size + chunk.byteLength > body.byteLength) {
        const grown = Buffer.allocUnsafe(Math.min(maximumBytes, Math.max(size + chunk.byteLength, body.byteLength * 2)))
        body.copy(grown, 0, 0, size)
        body = grown
      }
      body.set(chunk, size)
      size += chunk.byteLength
      return Effect.void
    })
    return body.subarray(0, size)
  })

export * as WebFetchTool from "./webfetch"

import { ToolFailure } from "@orchestra/llm"
import { Duration, Effect, Layer, Schema } from "effect"
import { HttpClient, HttpClientRequest, HttpClientResponse } from "effect/unstable/http"
import { Parser } from "htmlparser2"
import TurndownService from "turndown"
import { makeLocationNode } from "../effect/app-node"
import { LayerNodePlatform } from "../effect/app-node-platform"
import { PermissionV2 } from "../permission"
import { collectBoundedResponseBody } from "./http-body"
import { ToolRegistry } from "./registry"
import { Tool } from "./tool"
import { Tools } from "./tools"

export const name = "webfetch"
export const MAX_RESPONSE_BYTES = 5 * 1024 * 1024
export const DEFAULT_TIMEOUT_SECONDS = 30
export const MAX_TIMEOUT_SECONDS = 120

export const description = `Fetch a public web page or text file and return it as Markdown (the default), plain text or raw HTML.

- The request is a plain GET without cookies, login or JavaScript, so a page that needs a signed-in session or renders in the browser comes back empty or as a sign-in page.
- The URL must start with \`http://\` or \`https://\` and is fetched as given. Error statuses, responses over ${MAX_RESPONSE_BYTES / 1024 / 1024} MB, images and other binary files fail.
- \`timeout\` is in seconds: ${DEFAULT_TIMEOUT_SECONDS} by default, ${MAX_TIMEOUT_SECONDS} at most.
- A long result keeps its start and end, and the full text is saved to a file the result names.`

const Timeout = Schema.Number.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(MAX_TIMEOUT_SECONDS))

export const Input = Schema.Struct({
  url: Schema.String.annotate({ description: "The HTTP or HTTPS URL to fetch content from" }),
  format: Schema.Literals(["text", "markdown", "html"])
    .annotate({ description: "The format to return the content in. Defaults to markdown." })
    .pipe(Schema.withDecodingDefault(Effect.succeed("markdown" as const))),
  timeout: Timeout.pipe(Schema.optional).annotate({
    description: `Optional timeout in seconds (maximum: ${MAX_TIMEOUT_SECONDS})`,
  }),
})

const Output = Schema.Struct({
  url: Schema.String,
  contentType: Schema.String,
  format: Input.fields.format,
  output: Schema.String,
})

type Format = (typeof Input.Type)["format"]

const acceptHeader = (format: Format) => {
  switch (format) {
    case "markdown":
      return "text/markdown;q=1.0, text/x-markdown;q=0.9, text/plain;q=0.8, text/html;q=0.7, */*;q=0.1"
    case "text":
      return "text/plain;q=1.0, text/markdown;q=0.9, text/html;q=0.8, */*;q=0.1"
    case "html":
      return "text/html;q=1.0, application/xhtml+xml;q=0.9, text/plain;q=0.8, text/markdown;q=0.7, */*;q=0.1"
  }
  return "*/*"
}

const headers = (format: Format, userAgent: string) => ({
  "User-Agent": userAgent,
  Accept: acceptHeader(format),
  "Accept-Language": "en-US,en;q=0.9",
})

const browserUserAgent =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36"

const isCloudflareChallenge = (error: unknown) => {
  if (!error || typeof error !== "object" || !("reason" in error)) return false
  const reason = error.reason
  if (
    !reason ||
    typeof reason !== "object" ||
    !("_tag" in reason) ||
    reason._tag !== "StatusCodeError" ||
    !("response" in reason)
  )
    return false
  const response = reason.response as HttpClientResponse.HttpClientResponse
  return response.status === 403 && response.headers["cf-mitigated"] === "challenge"
}

const request = (url: string, format: Format, userAgent = browserUserAgent) =>
  HttpClientRequest.get(url).pipe(HttpClientRequest.setHeaders(headers(format, userAgent)))

const assertHttpUrl = (url: URL) => {
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error("URL must use http:// or https://")
}

const execute = (http: HttpClient.HttpClient, url: string, format: Format, userAgent = browserUserAgent) =>
  http.execute(request(url, format, userAgent)).pipe(Effect.flatMap(HttpClientResponse.filterStatusOk))

const collectBody = (response: HttpClientResponse.HttpClientResponse) =>
  collectBoundedResponseBody(
    response,
    MAX_RESPONSE_BYTES,
    () => new Error(`Response too large (exceeds ${MAX_RESPONSE_BYTES} byte limit)`),
  )

const mimeFrom = (contentType: string) => contentType.split(";", 1)[0]?.trim().toLowerCase() ?? ""
const isImageAttachment = (mime: string) =>
  mime.startsWith("image/") && mime !== "image/svg+xml" && mime !== "image/vnd.fastbidsheet"
const isTextualMime = (mime: string) =>
  !mime ||
  mime.startsWith("text/") ||
  mime === "application/json" ||
  mime.endsWith("+json") ||
  mime === "application/xml" ||
  mime.endsWith("+xml") ||
  mime === "application/javascript" ||
  mime === "application/x-javascript"
export const convert = (content: string, contentType: string, format: Format) => {
  if (!contentType.includes("text/html")) return content
  if (format === "markdown") return convertHTMLToMarkdown(content)
  if (format === "text") return extractTextFromHTML(content)
  return content
}

/**
 * The GET webfetch runs, without its permission: the final URL, its content type and the bounded received bytes.
 * Research capture retains those bytes before it converts them, so it calls this under webfetch's own permission.
 */
export const fetch = (http: HttpClient.HttpClient, url: string, format: Format, timeout = DEFAULT_TIMEOUT_SECONDS) =>
  Effect.gen(function* () {
    yield* Effect.try({ try: () => assertHttpUrl(new URL(url)), catch: (error) => error })
    const response = yield* execute(http, url, format).pipe(
      Effect.catchIf(isCloudflareChallenge, () => execute(http, url, format, "orchestra")),
    )
    const contentType = response.headers["content-type"] || ""
    const mime = mimeFrom(contentType)
    if (isImageAttachment(mime)) return yield* Effect.fail(new Error(`Unsupported fetched image content type: ${mime}`))
    if (!isTextualMime(mime)) return yield* Effect.fail(new Error(`Unsupported fetched file content type: ${mime}`))
    return { url: response.request.url, contentType, body: yield* collectBody(response) }
  }).pipe(
    Effect.timeoutOrElse({
      duration: Duration.seconds(timeout),
      orElse: () => Effect.fail(new Error("Request timed out")),
    }),
  )

const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const tools = yield* Tools.Service
    const http = yield* HttpClient.HttpClient
    const permission = yield* PermissionV2.Service

    yield* tools
      .register({
        [name]: Tool.make({
          description,
          input: Input,
          output: Output,
          toModelOutput: ({ output }) => [{ type: "text", text: output.output }],
          // Native fetch results are attested for Lean 2.0; same-named application tools are not.
          modelCapture: ({ output }) => ({
            textIndex: 0,
            observation: { source: "other", command: name, output: output.output, termination: { kind: "exited", code: 0 },
              completeness: "complete", presentation: "unknown" },
          }),
          execute: (input, context) =>
            Effect.gen(function* () {
              yield* Effect.try({
                try: () => assertHttpUrl(new URL(input.url)),
                catch: (error) => error,
              })

              yield* permission.assert({
                action: name,
                resources: [input.url],
                save: ["*"],
                metadata: input,
                sessionID: context.sessionID,
                agent: context.agent,
                source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
              })

              const { body, contentType } = yield* fetch(http, input.url, input.format, input.timeout)
              const content = new TextDecoder().decode(body)
              const output = yield* Effect.try({
                try: () => convert(content, contentType, input.format),
                catch: (error) => error,
              })
              return {
                url: input.url,
                contentType,
                format: input.format,
                output,
              }
            }).pipe(Effect.mapError(() => new ToolFailure({ message: `Unable to fetch ${input.url}` }))),
        }),
      })
      .pipe(Effect.orDie)
  }),
)

export const node = makeLocationNode({
  name: "tool/webfetch",
  layer,
  deps: [ToolRegistry.node, PermissionV2.node, LayerNodePlatform.httpClient],
})

export function extractTextFromHTML(html: string) {
  let text = ""
  let skipDepth = 0
  const parser = new Parser({
    onopentag(name) {
      if (skipDepth > 0 || ["script", "style", "noscript", "iframe", "object", "embed"].includes(name)) skipDepth++
    },
    ontext(input) {
      if (skipDepth === 0) text += input
    },
    onclosetag() {
      if (skipDepth > 0) skipDepth--
    },
  })
  parser.write(html)
  parser.end()
  return text.trim()
}

export function convertHTMLToMarkdown(html: string) {
  assertHTMLNestingBounded(html)
  const turndown = new TurndownService({
    headingStyle: "atx",
    hr: "---",
    bulletListMarker: "-",
    codeBlockStyle: "fenced",
    emDelimiter: "*",
  })
  turndown.remove(["script", "style", "meta", "link"])
  return turndown.turndown(html)
}

function assertHTMLNestingBounded(html: string) {
  let depth = 0
  const parser = new Parser({
    onopentag() {
      depth++
      if (depth > 512) throw new Error("HTML nesting exceeds conversion limit")
    },
    onclosetag() {
      depth--
    },
  })
  parser.write(html)
  parser.end()
}

export * as WebSearchTool from "./websearch"

import { ToolFailure } from "@orchestra/llm"
import { Context, Duration, Effect, Layer, Schema } from "effect"
import { HttpClient, HttpClientRequest } from "effect/unstable/http"
import { makeLocationNode } from "../effect/app-node"
import { LayerNodePlatform } from "../effect/app-node-platform"
import { truthy } from "../flag/flag"
import { InstallationVersion } from "../installation/version"
import { PositiveInt } from "../schema"
import { PermissionV2 } from "../permission"
import { Tool } from "./tool"
import { Tools } from "./tools"
import { collectBoundedResponseBody } from "./http-body"
import { checksum } from "../util/encode"
import { ToolRegistry } from "./registry"
import { ToolText } from "./text"

export const name = "websearch"
export const NO_RESULTS = "No search results found. Please try a different query."
export const EXA_URL = "https://mcp.exa.ai/mcp"
export const PARALLEL_URL = "https://search.parallel.ai/mcp"
export const MAX_NUM_RESULTS = 20
export const MAX_CONTEXT_CHARACTERS = 50_000
export const MAX_RESPONSE_BYTES = 256 * 1024

/**
 * Provider-independent local web search retained in V2 core for launch parity.
 * This invokes the legacy Exa/Parallel product backends itself. It is distinct
 * from provider-hosted web search tools, which remain route-owned and execute
 * at the model provider. Ownership of this compromise can be revisited later.
 */
export const description = ToolText.websearch(new Date().getFullYear())

export const Input = Schema.Struct({
  query: Schema.String.annotate({ description: "Websearch query" }),
  numResults: Schema.optional(PositiveInt.check(Schema.isLessThanOrEqualTo(MAX_NUM_RESULTS))).annotate({
    description: `Number of search results to return (default: 8, maximum: ${MAX_NUM_RESULTS})`,
  }),
  livecrawl: Schema.optional(Schema.Literals(["fallback", "preferred"])).annotate({
    description:
      "Live crawl mode - 'fallback': use live crawling as backup if cached unavailable, 'preferred': prioritize live crawling (default: 'fallback')",
  }),
  type: Schema.optional(Schema.Literals(["auto", "fast", "deep"])).annotate({
    description: "Search type - 'auto': balanced search (default), 'fast': quick results, 'deep': comprehensive search",
  }),
  contextMaxCharacters: Schema.optional(PositiveInt.check(Schema.isLessThanOrEqualTo(MAX_CONTEXT_CHARACTERS))).annotate(
    {
      description: `Maximum characters for context string optimized for models (default: 10000, maximum: ${MAX_CONTEXT_CHARACTERS})`,
    },
  ),
})

/** A lower-case host name; a result passes when its host is the name or a subdomain of it. */
export const Domain = Schema.String.check(
  Schema.isPattern(/^(?=.{1,253}(?![\s\S]))(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,62}(?![\s\S])/),
)
export const Domains = Schema.Array(Domain).check(Schema.isMinLength(1), Schema.isMaxLength(32))

/**
 * The dispatch's web domain list (J1.9). The host provides it around one research dispatch; no model input sets it.
 * Absent means unrestricted.
 */
export const AllowedDomains = Context.Reference<ReadonlyArray<string> | undefined>("@orchestra/WebSearch/AllowedDomains", {
  defaultValue: () => undefined,
})

export function allows(domains: ReadonlyArray<string>, url: string) {
  const parsed = URL.parse(url)
  if (!parsed || !["http:", "https:"].includes(parsed.protocol)) return false
  const host = parsed.hostname.toLowerCase().replace(/\.$/, "")
  return domains.some((domain) => host === domain || host.endsWith(`.${domain}`))
}

/** Parallel honours `site:` operators: one query per allowed domain (at most four) steers it before the host filter. */
export function parallelQueries(query: string, domains: ReadonlyArray<string> | undefined) {
  return domains?.length ? domains.slice(0, 4).map((domain) => `${query} site:${domain}`) : [query]
}

/**
 * Keeps only results whose URL the domain list admits. Neither backend filters by domain itself, so this is the
 * enforcement. Parallel answers JSON with `results[].url`; Exa answers text blocks that open with `Title:` and carry one
 * `URL:` line. A response that cannot be attributed to URLs returns nothing rather than an unchecked result.
 */
export function restrict(provider: Provider, text: string, domains: ReadonlyArray<string>) {
  const scope = `Results restricted to ${domains.join(", ")}`
  if (!text.trim() || text === NO_RESULTS) return { text: `${scope}. ${NO_RESULTS}`, withheld: 0 }
  const kept = provider === "parallel" ? parallelResults(text, domains) : exaResults(text, domains)
  if (!kept) return { text: `${scope}. The search response could not be matched to URLs, so no result is returned.`, withheld: undefined }
  if (kept.count === 0) return { text: `${scope}. No result within those domains (${kept.withheld} withheld).`, withheld: kept.withheld }
  return { text: `${scope}; ${kept.withheld} result(s) outside them withheld.\n\n${kept.text}`, withheld: kept.withheld }
}

function parallelResults(text: string, domains: ReadonlyArray<string>) {
  const decoded = Schema.decodeUnknownOption(Schema.UnknownFromJsonString)(text)
  if (decoded._tag === "None" || !record(decoded.value) || !Array.isArray(decoded.value.results)) return
  const results: unknown[] = decoded.value.results
  if (!results.every((item) => record(item) && typeof item.url === "string")) return
  const kept = results.filter((item) => record(item) && typeof item.url === "string" && allows(domains, item.url))
  return { text: JSON.stringify({ ...decoded.value, results: kept }, null, 2), count: kept.length, withheld: results.length - kept.length }
}

function exaResults(text: string, domains: ReadonlyArray<string>) {
  const blocks = text.split(/(?=^Title: )/m)
  const urls = blocks.map((block) => /^URL: (\S+)$/m.exec(block)?.[1])
  if (urls.some((url) => url === undefined)) return
  const kept = blocks.filter((_, index) => allows(domains, urls[index] ?? ""))
  return { text: kept.join(""), count: kept.length, withheld: blocks.length - kept.length }
}

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

export const Provider = Schema.Literals(["exa", "parallel"])
export type Provider = typeof Provider.Type

export interface Config {
  readonly provider?: Provider
  readonly enableExa: boolean
  readonly enableParallel: boolean
  readonly exaApiKey?: string
  readonly parallelApiKey?: string
}

export class ConfigService extends Context.Service<ConfigService, Config>()("@orchestra/v2/WebSearchConfig") {}

/** Isolates the retained product environment contract from the generic tool implementation. */
export const defaultConfigLayer = Layer.sync(ConfigService, () =>
  ConfigService.of({
    provider:
      process.env.ORCHESTRA_WEBSEARCH_PROVIDER === "exa" || process.env.ORCHESTRA_WEBSEARCH_PROVIDER === "parallel"
        ? process.env.ORCHESTRA_WEBSEARCH_PROVIDER
        : undefined,
    enableExa: truthy("ORCHESTRA_EXPERIMENTAL") || truthy("ORCHESTRA_ENABLE_EXA") || truthy("ORCHESTRA_EXPERIMENTAL_EXA"),
    enableParallel: truthy("ORCHESTRA_ENABLE_PARALLEL") || truthy("ORCHESTRA_EXPERIMENTAL_PARALLEL"),
    exaApiKey: process.env.EXA_API_KEY,
    parallelApiKey: process.env.PARALLEL_API_KEY,
  }),
)

export const configNode = makeLocationNode({ service: ConfigService, layer: defaultConfigLayer, deps: [] })

export function selectProvider(
  sessionID: string,
  flags: Pick<Config, "enableExa" | "enableParallel"> = { enableExa: false, enableParallel: false },
  override?: Provider,
): Provider {
  if (override) return override
  if (flags.enableParallel) return "parallel"
  if (flags.enableExa) return "exa"
  return Number.parseInt(checksum(sessionID) ?? "0", 36) % 2 === 0 ? "exa" : "parallel"
}

const McpResult = Schema.Struct({
  result: Schema.Struct({
    content: Schema.Array(Schema.Struct({ type: Schema.String, text: Schema.String })),
  }),
})
const decodeMcpResult = Schema.decodeUnknownEffect(Schema.fromJsonString(McpResult))

const parsePayload = (payload: string) =>
  Effect.gen(function* () {
    const trimmed = payload.trim()
    if (!trimmed.startsWith("{")) return undefined
    return (yield* decodeMcpResult(trimmed)).result.content.find((item) => item.text)?.text
  })

export const parseResponse = Effect.fn("WebSearchTool.parseResponse")(function* (body: string) {
  const trimmed = body.trim()
  const direct = trimmed ? yield* parsePayload(trimmed) : undefined
  if (direct) return direct
  for (const line of body.split("\n")) {
    if (!line.startsWith("data: ")) continue
    const data = yield* parsePayload(line.substring(6))
    if (data) return data
  }
  return undefined
})

const ExaArgs = Schema.Struct({
  query: Schema.String,
  type: Schema.String,
  numResults: Schema.Number,
  livecrawl: Schema.String,
  contextMaxCharacters: Schema.optional(Schema.Number),
})
const ParallelArgs = Schema.Struct({
  objective: Schema.String,
  search_queries: Schema.Array(Schema.String),
  session_id: Schema.String,
})
const McpRequest = <F extends Schema.Struct.Fields>(args: Schema.Struct<F>) =>
  Schema.Struct({
    jsonrpc: Schema.Literal("2.0"),
    id: Schema.Literal(1),
    method: Schema.Literal("tools/call"),
    params: Schema.Struct({ name: Schema.String, arguments: args }),
  })

const exaUrl = (apiKey: string | undefined) => {
  if (!apiKey) return EXA_URL
  const url = new URL(EXA_URL)
  url.searchParams.set("exaApiKey", apiKey)
  return url.toString()
}

const callMcp = <F extends Schema.Struct.Fields>(
  http: HttpClient.HttpClient,
  url: string,
  tool: string,
  args: Schema.Struct<F>,
  value: Schema.Struct.Type<F>,
  headers: Record<string, string> = {},
) =>
  Effect.gen(function* () {
    const request = yield* HttpClientRequest.post(url).pipe(
      HttpClientRequest.accept("application/json, text/event-stream"),
      HttpClientRequest.setHeaders(headers),
      HttpClientRequest.schemaBodyJson(McpRequest(args))({
        jsonrpc: "2.0" as const,
        id: 1 as const,
        method: "tools/call" as const,
        params: { name: tool, arguments: value },
      }),
    )
    return yield* Effect.gen(function* () {
      const response = yield* HttpClient.filterStatusOk(http).execute(request)
      const body = yield* collectBoundedResponseBody(
        response,
        MAX_RESPONSE_BYTES,
        () => new Error(`${tool} response exceeded ${MAX_RESPONSE_BYTES} bytes`),
      )
      return yield* parseResponse(body.toString("utf8"))
    }).pipe(
      Effect.timeoutOrElse({
        duration: Duration.seconds(25),
        orElse: () => Effect.fail(new Error(`${tool} request timed out`)),
      }),
    )
  })

const Output = Schema.Struct({
  provider: Provider,
  text: Schema.String,
})

const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const tools = yield* Tools.Service
    const http = yield* HttpClient.HttpClient
    const config = yield* ConfigService
    const permission = yield* PermissionV2.Service

    yield* tools
      .register({
        [name]: Tool.make({
          description,
          input: Input,
          output: Output,
          toModelOutput: ({ output }) => [{ type: "text", text: output.text }],
          execute: (input, context) => {
            const provider = selectProvider(context.sessionID, config, config.provider)
            return Effect.gen(function* () {
              const domains = yield* AllowedDomains
              yield* permission.assert({
                action: name,
                resources: [input.query],
                save: ["*"],
                metadata: { ...input, provider, ...(domains ? { allowedDomains: domains } : {}) },
                sessionID: context.sessionID,
                agent: context.agent,
                source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
              })

              const text =
                provider === "exa"
                  ? yield* callMcp(http, exaUrl(config.exaApiKey), "web_search_exa", ExaArgs, {
                      query: input.query,
                      type: input.type || "auto",
                      numResults: input.numResults || 8,
                      livecrawl: input.livecrawl || "fallback",
                      contextMaxCharacters: input.contextMaxCharacters,
                    })
                  : yield* callMcp(
                      http,
                      PARALLEL_URL,
                      "web_search",
                      ParallelArgs,
                      {
                        objective: input.query,
                        search_queries: parallelQueries(input.query, domains),
                        session_id: context.sessionID,
                        // V2 invocation context does not safely expose the model yet.
                      },
                      {
                        "User-Agent": `orchestra/${InstallationVersion}`,
                        ...(config.parallelApiKey ? { Authorization: `Bearer ${config.parallelApiKey}` } : {}),
                      },
                    )
              return {
                provider,
                text: domains ? restrict(provider, text ?? NO_RESULTS, domains).text : (text ?? NO_RESULTS),
              }
            }).pipe(Effect.mapError(() => new ToolFailure({ message: `Unable to search the web for ${input.query}` })))
          },
        }),
      })
      .pipe(Effect.orDie)
  }),
)

export const node = makeLocationNode({
  name: "tool/websearch",
  layer,
  deps: [ToolRegistry.node, PermissionV2.node, LayerNodePlatform.httpClient, configNode],
})

export * as GlobTool from "./glob"

import { ToolFailure } from "@orchestra/llm"
import { Effect, Layer, Schema } from "effect"
import path from "path"
import { makeLocationNode } from "../effect/app-node"
import { FileSystem } from "../filesystem"
import { Location } from "../location"
import { LocationMutation } from "../location-mutation"
import { Ripgrep } from "../ripgrep"
import { RelativePath } from "../schema"
import { PermissionV2 } from "../permission"
import { ToolRegistry } from "./registry"
import { Tool } from "./tool"
import { Tools } from "./tools"

export const name = "glob"

export const Input = Schema.Struct({
  pattern: FileSystem.GlobInput.fields.pattern.annotate({ description: "Glob pattern to match files against" }),
  path: RelativePath.pipe(Schema.optional).annotate({
    description: "The directory to search, relative to the working directory, which is the default",
  }),
  limit: FileSystem.GlobInput.fields.limit.annotate({
    description: "Maximum results to return",
  }),
})

export const Output = Schema.Array(FileSystem.Entry)
type ModelOutput = typeof Output.Encoded

/** Format raw search results into the concise line-oriented output models expect. */
export const toModelOutput = (output: ModelOutput) => {
  const lines = output.length === 0 ? ["No files found"] : output.map((item) => item.path)
  return lines.join("\n")
}

/** Glob leaf that defaults its filesystem root to the active Location. */
const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const tools = yield* Tools.Service
    const ripgrep = yield* Ripgrep.Service
    const location = yield* Location.Service
    const permission = yield* PermissionV2.Service
    const mutation = yield* LocationMutation.Service
    const text = (output: ModelOutput) =>
      toModelOutput(output.map((entry) => ({ ...entry, path: path.resolve(location.directory, entry.path) })))

    yield* tools
      .register({
        [name]: Tool.make({
          description: `Find files whose paths match a glob pattern, such as \`**/*.tsx\` or \`src/**/config.*\`. A pattern without \`/\`, such as \`*.ts\`, matches file names at any depth.

- \`path\` is the directory to search, the working directory by default.
- Hidden files and directories, and those excluded by \`.gitignore\`, are not searched.
- The result is a list of absolute paths in no particular order, or "No files found". \`limit\` caps how many come back; without it, every match does.`,
          input: Input,
          output: Output,
          toModelOutput: ({ output }) => [{ type: "text", text: text(output) }],
          // Native search results are attested for Lean 2.0; same-named application tools are not.
          modelCapture: ({ output }) => ({
            textIndex: 0,
            observation: { source: "other", command: name, output: text(output), termination: { kind: "exited", code: 0 },
              completeness: "complete", presentation: "unknown" },
          }),
          execute: (input, context) =>
            Effect.gen(function* () {
              // Same boundary as read: a search root outside the Location needs external_directory approval first.
              const external = (yield* mutation.resolve({ path: input.path ?? ".", kind: "directory" })).externalDirectory
              if (external)
                yield* permission.assert({
                  ...LocationMutation.externalDirectoryPermission(external),
                  sessionID: context.sessionID,
                  agent: context.agent,
                  source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
                })
              yield* permission.assert({
                action: name,
                resources: [input.pattern],
                save: ["*"],
                metadata: {
                  root: input.path ?? ".",
                  path: input.path,
                  limit: input.limit,
                },
                sessionID: context.sessionID,
                agent: context.agent,
                source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
              })
              const cwd = path.resolve(location.directory, input.path ?? ".")
              return yield* ripgrep
                .glob({
                  cwd,
                  pattern: input.pattern,
                  limit: input.limit ?? Number.MAX_SAFE_INTEGER,
                })
                .pipe(
                  Effect.map((result) =>
                    result.map((entry) =>
                      FileSystem.Entry.make({
                        ...entry,
                        path: RelativePath.make(path.relative(location.directory, path.resolve(cwd, entry.path))),
                      }),
                    ),
                  ),
                )
            }).pipe(
              // Ripgrep's reason (missing, still downloading) is the actionable part.
              Effect.mapError(
                (error) =>
                  new ToolFailure({
                    message:
                      error instanceof Ripgrep.Error
                        ? `Unable to find files matching ${input.pattern}: ${error.message}`
                        : `Unable to find files matching ${input.pattern}`,
                  }),
              ),
            ),
        }),
      })
      .pipe(Effect.orDie)
  }),
)

export const node = makeLocationNode({
  name: "tool/glob",
  layer,
  deps: [ToolRegistry.node, Ripgrep.node, Location.node, LocationMutation.node, PermissionV2.node],
})

export * as GrepTool from "./grep"

import { ToolFailure } from "@orchestra/llm"
import { Effect, Layer, Schema } from "effect"
import path from "path"
import { makeLocationNode } from "../effect/app-node"
import { FileSystem } from "../filesystem"
import { FSUtil } from "../fs-util"
import { Location } from "../location"
import { LocationMutation } from "../location-mutation"
import { PermissionV2 } from "../permission"
import { Ripgrep } from "../ripgrep"
import { RelativePath } from "../schema"
import { ToolRegistry } from "./registry"
import { Tool } from "./tool"
import { Tools } from "./tools"

export const name = "grep"

export const Input = Schema.Struct({
  pattern: FileSystem.GrepInput.fields.pattern.annotate({
    description: "Regex pattern to search for in file contents",
  }),
  path: RelativePath.pipe(Schema.optional).annotate({
    description: "The file or directory to search, relative to the working directory, which is the default",
  }),
  include: FileSystem.GrepInput.fields.include.annotate({
    description: 'File glob to include in the search (for example, "*.js" or "*.{ts,tsx}")',
  }),
  limit: FileSystem.GrepInput.fields.limit.annotate({
    description: "Maximum matches to return",
  }),
})

export const Output = Schema.Array(FileSystem.Match)
type ModelOutput = typeof Output.Encoded

/** Format raw search matches into the familiar concise model output. */
export const toModelOutput = (output: ModelOutput) => {
  const lines = output.length === 0 ? ["No files found"] : [`Found ${output.length} matches`]
  let current = ""
  for (const match of output) {
    if (current !== match.entry.path) {
      if (current) lines.push("")
      current = match.entry.path
      lines.push(`${match.entry.path}:`)
    }
    lines.push(`  Line ${match.line}: ${match.text}`)
  }
  return lines.join("\n")
}

/** Grep leaf that defaults its filesystem root to the active Location. */
const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const tools = yield* Tools.Service
    const fs = yield* FSUtil.Service
    const ripgrep = yield* Ripgrep.Service
    const location = yield* Location.Service
    const permission = yield* PermissionV2.Service
    const mutation = yield* LocationMutation.Service
    const text = (output: ModelOutput) =>
      toModelOutput(output.map((match) => ({ ...match, entry: { ...match.entry, path: path.resolve(location.directory, match.entry.path) } })))

    yield* tools
      .register({
        [name]: Tool.make({
          description: `Search file contents with a regular expression in ripgrep syntax, such as \`function\\s+\\w+\` or \`TODO|FIXME\`.

- \`path\` is a directory or a single file, such as one a long tool result was saved to; the working directory by default. \`include\` limits the search to file names that match a glob, such as \`*.ts\` or \`*.{ts,tsx}\`.
- Matching is case-sensitive and works line by line; start the pattern with \`(?i)\` to ignore case.
- Hidden files are searched; files and directories excluded by \`.gitignore\` are not.
- The result counts the matches and lists each matching line with its line number, grouped by file. \`limit\` caps the number of matches; without it, every match is listed.`,
          input: Input,
          output: Output,
          toModelOutput: ({ output }) => [{ type: "text", text: text(output) }],
          // Native search results are attested for Lean 2.0; same-named application tools are not.
          modelCapture: ({ output }) => ({
            textIndex: 0,
            observation: { source: "other", command: name, output: text(output), termination: { kind: "exited", code: 0 },
              completeness: "complete", presentation: "unknown" },
          }),
          execute: (input, context) =>
            Effect.gen(function* () {
              // Same boundary as read: a search root outside the Location needs external_directory approval first.
              const external = (yield* mutation.resolve({ path: input.path ?? ".", kind: "directory" })).externalDirectory
              if (external)
                yield* permission.assert({
                  ...LocationMutation.externalDirectoryPermission(external),
                  sessionID: context.sessionID,
                  agent: context.agent,
                  source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
                })
              yield* permission.assert({
                action: name,
                resources: [input.pattern],
                save: ["*"],
                metadata: {
                  root: ".",
                  path: input.path,
                  include: input.include,
                  limit: input.limit,
                },
                sessionID: context.sessionID,
                agent: context.agent,
                source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
              })
              const target = path.resolve(location.directory, input.path ?? ".")
              const info = yield* fs.stat(target).pipe(Effect.catch(() => Effect.succeed(undefined)))
              return yield* ripgrep
                .grep({
                  cwd: info?.type === "Directory" ? target : path.dirname(target),
                  pattern: input.pattern,
                  file: info?.type === "File" ? path.basename(target) : undefined,
                  include: input.include,
                  limit: input.limit ?? Number.MAX_SAFE_INTEGER,
                })
                .pipe(
                  Effect.map((result) =>
                    result.map((match) =>
                      FileSystem.Match.make({
                        ...match,
                        entry: FileSystem.Entry.make({
                          ...match.entry,
                          path: RelativePath.make(
                            path.relative(
                              location.directory,
                              path.resolve(
                                info?.type === "Directory" ? target : path.dirname(target),
                                match.entry.path,
                              ),
                            ),
                          ),
                        }),
                      }),
                    ),
                  ),
                )
            }).pipe(
              // Ripgrep's reason (missing, still downloading, an invalid pattern) is the actionable part.
              Effect.mapError(
                (error) =>
                  new ToolFailure({
                    message:
                      error instanceof Ripgrep.Error || error instanceof Ripgrep.InvalidPatternError
                        ? `Unable to grep for ${input.pattern}: ${error.message}`
                        : `Unable to grep for ${input.pattern}`,
                  }),
              ),
            ),
        }),
      })
      .pipe(Effect.orDie)
  }),
)

export const node = makeLocationNode({
  name: "tool/grep",
  layer,
  deps: [ToolRegistry.node, FSUtil.node, Ripgrep.node, Location.node, LocationMutation.node, PermissionV2.node],
})

export * as TaskPermission from "./task-permission"

import type { Permission } from "@orchestra/schema/permission"
import type { Config } from "../config"

// Kept apart from the task tool so the Session runner, which the task tool depends on, can derive a child's rules too.
/**
 * The rules every Task child inherits, as the earlier runtime derived them: the parent Session's deny and `external_directory` rules, so a
 * child is never more permissive than its parent on a denied pattern, then a deny of each `experimental.primary_tools`
 * tool, which only primary agents may use.
 */
export function inheritedPermissions(parent: Permission.Ruleset, primary: ReadonlyArray<string>): Permission.Ruleset {
  const inherited = parent.filter((rule) => rule.action === "external_directory" || rule.effect === "deny")
  return [
    ...inherited,
    ...primary
      .map((action) => ({ action, resource: "*", effect: "deny" as const }))
      .filter((deny) => !inherited.some((rule) => rule.action === deny.action && rule.resource === deny.resource && rule.effect === deny.effect)),
  ]
}

/** The configured `experimental.primary_tools`, from the highest-priority document that sets it. */
export function primaryTools(entries: ReadonlyArray<Config.Entry>) {
  return (
    entries
      .filter((entry): entry is Config.Document => entry.type === "document")
      .findLast((entry) => entry.info.experimental?.primary_tools !== undefined)?.info.experimental?.primary_tools ?? []
  )
}

export * as SkillTool from "./skill"

import path from "path"
import { ToolFailure } from "@orchestra/llm"
import { Effect, Layer, Option, Schema } from "effect"
import { ConfigMarkdown } from "../config/markdown"
import { makeLocationNode } from "../effect/app-node"
import { FSUtil } from "../fs-util"
import { SkillV2 } from "../skill"
import { PermissionV2 } from "../permission"
import { ToolRegistry } from "./registry"
import { ToolText } from "./text"
import { Tool } from "./tool"
import { Tools } from "./tools"

export const name = "skill"
const FILE_LIMIT = 10

export const Input = Schema.Struct({
  name: Schema.String.annotate({ description: "The name of the skill from the available skills list" }),
})

export const Output = Schema.Struct({
  name: Schema.String,
  directory: Schema.String,
  output: Schema.String,
})

export const description = ToolText.skill

export const toModelOutput = (skill: SkillV2.Info, files: ReadonlyArray<string>, next: ReadonlyArray<Node> = []) => {
  const directory = path.dirname(skill.location)
  return [
    `<skill_content name="${skill.name}">`,
    `# Skill: ${skill.name}`,
    "",
    skill.content.trim(),
    "",
    ...(next.length === 0
      ? []
      : [
          "## Next level",
          "",
          "Load the one node that covers the work with the skill tool, one level at a time. Stop at the first node that covers it.",
          "",
          ...next.map((node) =>
            [
              `- \`${node.name}\`: ${node.description ?? ""}`,
              node.when ? ` When: ${node.when}` : "",
              node.notWhen ? ` Not when: ${node.notWhen}` : "",
            ].join(""),
          ),
          "",
        ]),
    `Base directory for this skill: ${directory}`,
    "Relative paths in this skill (e.g., scripts/, reference/) are relative to this base directory.",
    "Note: file list is sampled.",
    "",
    "<skill_files>",
    ...files.map((file) => `<file>${file}</file>`),
    "</skill_files>",
    "</skill_content>",
  ].join("\n")
}

/** A child node as its parent's "Next level" index shows it. */
export type Node = {
  readonly name: string
  readonly description?: string
  readonly when?: string
  readonly notWhen?: string
}

const Routing = Schema.Struct({
  when: Schema.String.pipe(Schema.optional),
  "not-when": Schema.String.pipe(Schema.optional),
})
const decodeRouting = Schema.decodeUnknownOption(Routing)

/**
 * The skill's model-facing content with a sample of the files beside its `SKILL.md` and, for a skill tree node, the
 * "Next level" index of its `children` built from their frontmatter.
 */
export const load = Effect.fn("SkillTool.load")(function* (
  fs: FSUtil.Interface,
  skill: SkillV2.Info,
  children: ReadonlyArray<SkillV2.Info> = [],
) {
  const directory = path.dirname(skill.location)
  const files =
    path.basename(skill.location) === "SKILL.md"
      ? (yield* fs.glob("**/*", { cwd: directory, absolute: true, include: "file", dot: true }))
          .filter((file) => path.basename(file) !== "SKILL.md")
          .toSorted()
          .slice(0, FILE_LIMIT)
      : []
  const next = yield* Effect.forEach(children, (child) =>
    fs.readFileStringSafe(child.location).pipe(
      Effect.catch(() => Effect.succeed(undefined)),
      Effect.map((content) => {
        const markdown = content === undefined ? undefined : ConfigMarkdown.parseOption(content)
        const routing = markdown ? decodeRouting(markdown.data).pipe(Option.getOrUndefined) : undefined
        return { name: child.name, description: child.description, when: routing?.when, notWhen: routing?.["not-when"] }
      }),
    ),
  )
  return toModelOutput(skill, files, next)
})

const unableToLoad = (name: string, error?: unknown) =>
  new ToolFailure({ message: `Unable to load skill ${name}`, error })

const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const tools = yield* Tools.Service
    const fs = yield* FSUtil.Service
    const skills = yield* SkillV2.Service
    const permission = yield* PermissionV2.Service
    yield* tools
      .register({
        [name]: Tool.make({
          description,
          input: Input,
          output: Output,
          toModelOutput: ({ output }) => [{ type: "text", text: output.output }],
          execute: (input, context) =>
            Effect.gen(function* () {
              const current = yield* skills.list()
              const skill = current.find((skill) => skill.name === input.name)
              if (!skill) return yield* unableToLoad(input.name)
              return yield* Effect.gen(function* () {
                yield* permission.assert({
                  action: name,
                  resources: [skill.name],
                  save: [skill.name],
                  sessionID: context.sessionID,
                  agent: context.agent,
                  source: { type: "tool", messageID: context.assistantMessageID, callID: context.toolCallID },
                })
                return {
                  name: skill.name,
                  directory: path.dirname(skill.location),
                  output: yield* load(fs, skill, SkillV2.children(current, skill)),
                }
              }).pipe(Effect.mapError((error) => unableToLoad(input.name, error)))
            }),
        }),
      })
      .pipe(Effect.orDie)
  }),
)

export const node = makeLocationNode({
  name: "tool/skill",
  layer,
  deps: [ToolRegistry.node, FSUtil.node, SkillV2.node, PermissionV2.node],
})

export * as ToolModelCapture from "./model-capture"

import type { ToolContent } from "@orchestra/schema/llm"
import { isDeepStrictEqual } from "node:util"

/** Same structural boundary as @orchestra/llm ToolOutput, without a runtime dependency. */
export interface Output {
  readonly structured: unknown
  readonly content: ReadonlyArray<ToolContent>
}

/** Host-owned execution facts. Structurally compatible with hugr-lean/core's Observation. */
export interface Observation {
  readonly source: "shell" | "other"
  readonly command: string
  readonly output: string
  readonly termination: { readonly kind: "exited"; readonly code: number } | { readonly kind: "unknown" | "timed_out" }
  readonly completeness: "complete" | "truncated" | "unknown"
  readonly presentation: "unknown" | "terminal-rendered"
}

export interface Input {
  readonly observation: Observation
  readonly textIndex: number
}

export interface Owner {
  readonly sessionID: string
  readonly callID: string
}

declare const CandidateId: unique symbol
export interface Candidate extends Input {
  readonly [CandidateId]: true
  readonly owner: Owner
  readonly template: Output
}

declare const BindingId: unique symbol
export interface Binding {
  readonly [BindingId]: true
  readonly candidate: Candidate
  /** Detached pre-hook snapshot, including structured status and media. */
  readonly baseline: Output
}

const captures = new WeakMap<object, Candidate>()
const issued = new WeakSet<object>()
const bindings = new WeakSet<object>()

/** Internal native-producer capability. Tool names and serialized metadata cannot issue it. */
export function record(carrier: Output, input: Input, owner: Owner): void {
  const part = carrier.content[input.textIndex]
  if (!Number.isSafeInteger(input.textIndex) || input.textIndex < 0 || part?.type !== "text" || part.text !== input.observation.output) return
  const template = snapshot(carrier)
  if (!template || !owner.sessionID || !owner.callID) return
  const observation = Object.freeze({ ...input.observation, termination: Object.freeze({ ...input.observation.termination }) })
  const candidate = Object.freeze({ observation, textIndex: input.textIndex, owner: Object.freeze({ ...owner }), template }) as Candidate
  issued.add(candidate)
  captures.set(carrier, candidate)
}

export const get = (carrier: object): Candidate | undefined => captures.get(carrier)
export const authentic = (candidate: Candidate): boolean => issued.has(candidate)

/** Called by the host only for this call's actual bounded policy view. */
export function bind(carrier: Output, baseline: Output, owner: Owner): Binding | undefined {
  const candidate = get(carrier)
  if (!candidate || candidate.owner.sessionID !== owner.sessionID || candidate.owner.callID !== owner.callID) return
  const copy = snapshot(baseline)
  if (!copy) return
  if (!isDeepStrictEqual(candidate.template.structured, copy.structured)) return
  if (!isDeepStrictEqual(candidate.template.content.filter((part) => part.type === "file"), copy.content.filter((part) => part.type === "file"))) return
  const binding = Object.freeze({ candidate, baseline: copy }) as Binding
  bindings.add(binding)
  return binding
}

export const bound = (binding: Binding): boolean => bindings.has(binding)

function snapshot(output: Output): Output | undefined {
  try {
    if (!plain(output)) return undefined
    const copy = structuredClone(output)
    if (!plain(copy)) return undefined
    return freeze(copy)
  } catch {
    return undefined
  }
}

function plain(value: unknown, parents = new Set<object>()): boolean {
  if (value === null || value === undefined || typeof value === "string" || typeof value === "boolean") return true
  if (typeof value === "number") return Number.isFinite(value)
  if (typeof value !== "object" || parents.has(value)) return false
  const prototype = Object.getPrototypeOf(value)
  if (Array.isArray(value) ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null) return false
  parents.add(value)
  const valid = Object.values(Object.getOwnPropertyDescriptors(value)).every((property) =>
    "value" in property && plain(property.value, parents))
  parents.delete(value)
  return valid
}

function freeze<T>(value: T, seen = new WeakSet<object>()): T {
  if (value === null || typeof value !== "object" || seen.has(value)) return value
  seen.add(value)
  for (const child of Object.values(value)) freeze(child, seen)
  return Object.freeze(value)
}

export * as LeanOutput from "./lean-output"

import type { ToolOutput } from "@orchestra/llm"
import { LeanCoverage } from "@orchestra/schema/lean-coverage"
import { LeanMetrics } from "@orchestra/schema/lean-metrics"
import { Effect } from "effect"
import { Config } from "../config"
import { LeanProcessor } from "./lean-processor"
import { LeanSummary } from "./lean-summary"
import { LeanTelemetry } from "./lean-telemetry"
import { ToolModelCapture } from "./model-capture"
import { ToolModelProjection } from "./model-projection"

/**
 * Lean projection over one settled ToolOutput.
 * The registry calls it after inspection and generic bounding, so `output` is the approved model view.
 */
export interface Input {
  readonly output: ToolOutput
  readonly binding?: ToolModelCapture.Binding
  readonly owner: ToolModelCapture.Owner
  readonly tool: string
  readonly args: Readonly<Record<string, unknown>>
  readonly enabled: boolean
  readonly unavailable?: "config_unavailable" | "preferences_unavailable" | "preferences_scope_mismatch"
  readonly items?: LeanCoverage.Settings
  readonly limits: { readonly maxLines: number; readonly maxBytes: number }
  /** Where complete originals go before a lossy summary replaces them; no store means no lossy summary. */
  readonly store?: { readonly put: (text: string) => Promise<string> }
  readonly telemetry?: Pick<LeanTelemetry.Input, "owner" | "model" | "orchestraProfile">
}

export interface Result {
  readonly output: ToolOutput
  readonly lean?: LeanMetrics.Decision
}

type Decision = ToolModelProjection.FilterResult | { readonly status: "summarized" | "rewritten"; readonly reason: string }
type Selection = { readonly output: ToolOutput; readonly reason: string; readonly decision?: Decision }

const refused = ["config_unavailable", "preferences_unavailable", "preferences_scope_mismatch", "disabled", "item_disabled",
  "processorfailed", "projection_budget_max_lines", "projection_budget_max_bytes"]

/** The `tool_output.lean.enabled` switch of the Location's config; Lean is on unless a document turns it off. */
export const configured = Effect.fn("LeanOutput.configured")(function* () {
  const config = yield* Config.Service
  // The highest-priority document that sets the switch wins, even when a later one sets only other thresholds.
  const entries = yield* config.entries()
  return entries
    .filter((entry): entry is Config.Document => entry.type === "document")
    .findLast((entry) => entry.info.tool_output?.lean?.enabled !== undefined)?.info.tool_output?.lean?.enabled !== false
})

/** Never fails: any refusal or measurement failure keeps the approved output, without or with partial metadata. */
export async function project(input: Input): Promise<Result> {
  const start = now()
  const trusted = attested(input)
  const identity = identify(input, trusted)
  // Unattributed attested shell commands and native read/fetch/search results have their own item toggles.
  const item = identity.itemID
    ?? (trusted ? trusted.source === "shell" ? "shell" : LeanCoverage.ids.find((id) => id === input.tool) : undefined)
  const selected = await condense(input, trusted, select(input, item, identity.failed))
  const end = now()
  if (!input.telemetry || start === undefined || end === undefined) return { output: selected.output }
  try {
    // Media results keep their exact settled view and carry no text measurement.
    if (selected.output.content.some((part) => part.type === "file")) return { output: selected.output }
    const status = selected.decision?.status
    const profile = selected.decision && "profile" in selected.decision ? selected.decision.profile : undefined
    // Attribution: the command's item, else the lossless profile's item, else the tool's own row.
    const lean = LeanTelemetry.measure({
      owner: input.telemetry.owner, model: input.telemetry.model, orchestraProfile: input.telemetry.orchestraProfile,
      itemID: identity.itemID ?? (profile ? LeanCoverage.forProfile(profile) : undefined) ?? item,
      producer: !trusted ? "unverified" : trusted.source === "shell" ? "native-shell" : "native-tool", eligible: !!trusted,
      status: status === "reduced" || status === "summarized" || status === "rewritten" ? "applied"
        : status === "normalized" ? "normalized" : "passthrough",
      reason: !trusted && selected.reason === "projection_declined" ? "not_eligible" : selected.reason,
      filterProfile: profile, before: view(input.output), after: view(selected.output), durationMs: end - start,
    })
    return lean ? { output: selected.output, lean } : { output: selected.output }
  } catch {
    // Optional measurement must never undo the already settled output selection.
    return { output: selected.output }
  }
}

function now() {
  try {
    return performance.now()
  } catch {
    return undefined
  }
}

function view(output: ToolOutput) {
  return output.content.flatMap((part) => part.type === "text" ? [part.text] : []).join("\n")
}

/** The native producer's attested observation for exactly this call, or nothing. */
function attested(input: Input): ToolModelCapture.Observation | undefined {
  try {
    const candidate = input.binding?.candidate
    if (!input.binding || !ToolModelCapture.bound(input.binding) || !candidate || !ToolModelCapture.authentic(candidate)
      || candidate.owner.sessionID !== input.owner.sessionID || candidate.owner.callID !== input.owner.callID) return undefined
    const observation = candidate.observation
    if (observation.source === "shell") return input.tool === "bash" ? observation : undefined
    return input.tool !== "bash" && observation.command === input.tool && LeanSummary.supported(input.tool) ? observation : undefined
  } catch {
    return undefined
  }
}

function identify(input: Input, trusted: ToolModelCapture.Observation | undefined): { itemID?: LeanCoverage.ItemID; failed?: boolean } {
  try {
    const command = trusted?.source === "shell" ? trusted.command
      : input.tool === "bash" && typeof input.args.command === "string" ? input.args.command : undefined
    if (command === undefined) return {}
    if (command.length === 0 || command.length > 65536) return { failed: true }
    const itemID = LeanProcessor.identify(command)
    return { itemID: LeanCoverage.ids.find((id) => id === itemID) }
  } catch {
    return { failed: true }
  }
}

/** Lossless processor pass through the frozen projection seam. */
function select(input: Input, itemID: LeanCoverage.ItemID | undefined, identityFailed: boolean | undefined): Selection {
  const declined = (reason: string) => ({ output: input.output, reason })
  if (input.unavailable) return declined(input.unavailable)
  if (!input.enabled) return declined("disabled")
  if (identityFailed) return declined("processorfailed")
  try {
    if (itemID && input.items?.[itemID] === false) return declined("item_disabled")
    if (!input.binding) return declined("not_eligible")
    const observed: { result?: ToolModelProjection.FilterResult; failed?: boolean } = {}
    const projection = { enabled: true, owner: input.owner, binding: input.binding, approved: input.output, limits: input.limits }
    const selected = ToolModelProjection.project({
      ...projection,
      filter: (observation) => {
        try {
          return observed.result = LeanProcessor.process(observation, input.items)
        } catch (error) {
          observed.failed = true
          throw error
        }
      },
    })
    if (selected.decision)
      return { output: { structured: input.output.structured, content: selected.output.content }, decision: selected.decision,
        reason: selected.decision.reason }
    if (observed.failed) return declined("processorfailed")
    if (observed.result?.status === "passthrough" || observed.result?.status === "failed_open") return declined(observed.result.reason)
    // Reuse the observed result, never re-run the processor. Acceptance without the budget proves the refusal seam.
    const unlimited = observed.result
      ? ToolModelProjection.project({ ...projection, limits: { maxLines: Number.MAX_SAFE_INTEGER, maxBytes: Number.MAX_SAFE_INTEGER },
        filter: () => observed.result! })
      : undefined
    if (!unlimited?.decision) return declined("projection_declined")
    const text = view(unlimited.output)
    if (text.split("\n").length > input.limits.maxLines) return declined("projection_budget_max_lines")
    if (Buffer.byteLength(text, "utf8") > input.limits.maxBytes) return declined("projection_budget_max_bytes")
    return declined("projection_declined")
  } catch {
    return declined("projection_declined")
  }
}

/**
 * Lean 2.0 after the lossless stage: summarize the attested slot (failure lines kept whole, exit taken from the
 * native observation), store the complete original first and end the summary with its recall line.
 * Any refusal or storage failure keeps the lossless selection.
 */
async function condense(input: Input, trusted: ToolModelCapture.Observation | undefined, lossless: Selection): Promise<Selection> {
  try {
    const tool = trusted?.source === "shell" ? "bash" : input.tool
    if (!trusted || !input.binding || !LeanSummary.supported(tool) || refused.includes(lossless.reason)) return lossless
    const index = input.binding.candidate.textIndex
    const slot = lossless.output.content[index]
    const original = input.output.content[index]
    if (slot?.type !== "text" || original?.type !== "text") return lossless
    const result = LeanSummary.summarize({
      tool, output: slot.text, args: input.args,
      // Generic bounding already refused truncated results, so search output is complete here.
      metadata: tool === "bash" ? { exit: trusted.termination.kind === "exited" ? trusted.termination.code : undefined } : { truncated: false },
    })
    const ineligible = lossless.reason === "projection_declined" || lossless.reason === "not_eligible"
    if (result.status === "unchanged") return ineligible ? { ...lossless, reason: result.reason } : lossless
    if (result.status === "rewritten") return { output: replace(lossless.output, index, result.replacement), reason: result.reason, decision: result }
    if (!input.store) return lossless
    const id = await input.store.put(original.text)
    return { output: replace(lossless.output, index, result.replacement + LeanSummary.recoveryLine(id)), reason: result.reason, decision: result }
  } catch {
    return lossless
  }
}

function replace(output: ToolOutput, index: number, text: string): ToolOutput {
  return {
    structured: output.structured,
    content: output.content.map((part, position) => position === index && part.type === "text" ? { type: "text" as const, text } : part),
  }
}

// The registry settles a call and the runner publishes its result separately; this carries the metadata between them.
const MAX_PENDING = 1024
const pending = new Map<string, Readonly<Record<string, unknown>>>()

/** Host-only handoff from settlement to the Tool.Success/Failed event of the same Session call. */
export function offer(owner: ToolModelCapture.Owner, metadata: Readonly<Record<string, unknown>>) {
  const key = JSON.stringify([owner.sessionID, owner.callID])
  pending.delete(key)
  pending.set(key, metadata)
  // Settlements whose result is never published (interruption) must not grow the process without bound.
  for (const stale of pending.keys()) {
    if (pending.size <= MAX_PENDING) break
    pending.delete(stale)
  }
}

export function take(owner: ToolModelCapture.Owner) {
  const key = JSON.stringify([owner.sessionID, owner.callID])
  const metadata = pending.get(key)
  pending.delete(key)
  return metadata
}

export * as PluginHost from "./host"

import type { PluginContext as Interface } from "@orchestra/plugin/v2/effect"
import { Effect, Schema } from "effect"
import { AgentV2 } from "../agent"
import { AISDK } from "../aisdk"
import { Catalog } from "../catalog"
import { CommandV2 } from "../command"
import { Credential } from "../credential"
import { Integration } from "../integration"
import { ModelV2 } from "../model"
import { PluginV2 } from "../plugin"
import { ProviderV2 } from "../provider"
import { Reference } from "../reference"
import type { DeepMutable } from "../schema"
import { SkillV2 } from "../skill"

const mutable = <T>(value: T) => value as DeepMutable<T>

export const make = Effect.fn("PluginHost.make")(function* (plugin: PluginV2.Interface) {
  const agents = yield* AgentV2.Service
  const aisdk = yield* AISDK.Service
  const catalog = yield* Catalog.Service
  const commands = yield* CommandV2.Service
  const integration = yield* Integration.Service
  const reference = yield* Reference.Service
  const skill = yield* SkillV2.Service

  return {
    options: {},
    agent: {
      reload: agents.reload,
      transform: (callback) =>
        agents.transform((draft) =>
          callback({
            list: () => mutable(draft.list()),
            get: (id) => mutable(draft.get(AgentV2.ID.make(id))),
            default: (id) => draft.default(id === undefined ? undefined : AgentV2.ID.make(id)),
            update: (id, update) => draft.update(AgentV2.ID.make(id), update),
            remove: (id) => draft.remove(AgentV2.ID.make(id)),
          }),
        ),
    },
    aisdk: {
      sdk: (callback) =>
        aisdk.hook.sdk((event) => {
          const output = {
            model: mutable(event.model),
            package: event.package,
            options: event.options,
            sdk: event.sdk,
          }
          const result = callback(output)
          return Effect.suspend(() => (Effect.isEffect(result) ? result : Effect.void)).pipe(
            Effect.tap(() => Effect.sync(() => (event.sdk = output.sdk))),
          )
        }),
      language: (callback) =>
        aisdk.hook.language((event) => {
          const output = {
            model: mutable(event.model),
            sdk: event.sdk,
            options: event.options,
            language: event.language,
          }
          const result = callback(output)
          return Effect.suspend(() => (Effect.isEffect(result) ? result : Effect.void)).pipe(
            Effect.tap(() => Effect.sync(() => (event.language = output.language))),
          )
        }),
    },
    catalog: {
      reload: catalog.reload,
      transform: (callback) =>
        catalog.transform((draft) =>
          callback({
            provider: {
              list: () => mutable(draft.provider.list()),
              get: (id) => mutable(draft.provider.get(ProviderV2.ID.make(id))),
              update: (id, update) => draft.provider.update(ProviderV2.ID.make(id), update),
              remove: (id) => draft.provider.remove(ProviderV2.ID.make(id)),
            },
            model: {
              get: (providerID, modelID) =>
                mutable(draft.model.get(ProviderV2.ID.make(providerID), ModelV2.ID.make(modelID))),
              update: (providerID, modelID, update) =>
                draft.model.update(ProviderV2.ID.make(providerID), ModelV2.ID.make(modelID), update),
              remove: (providerID, modelID) =>
                draft.model.remove(ProviderV2.ID.make(providerID), ModelV2.ID.make(modelID)),
              default: {
                get: draft.model.default.get,
                set: (providerID, modelID) =>
                  draft.model.default.set(ProviderV2.ID.make(providerID), ModelV2.ID.make(modelID)),
              },
            },
          }),
        ),
    },
    command: {
      reload: commands.reload,
      transform: commands.transform,
    },
    integration: {
      reload: integration.reload,
      connection: {
        active: (id) => integration.connection.active(Integration.ID.make(id)),
        resolve: (connection) =>
          integration.connection.resolve(
            connection.type === "credential" ? { ...connection, id: Credential.ID.make(connection.id) } : connection,
          ),
      },
      transform: (callback) =>
        integration.transform((draft) =>
          callback({
            list: () => mutable(draft.list()),
            get: (id) => mutable(draft.get(Integration.ID.make(id))),
            update: (id, update) => draft.update(Integration.ID.make(id), update),
            remove: (id) => draft.remove(Integration.ID.make(id)),
            method: {
              list: (id) => mutable(draft.method.list(Integration.ID.make(id))),
              update: (input) => {
                if ("authorize" in input) {
                  const methodID = Integration.MethodID.make(input.method.id)
                  const refresh = input.refresh
                  draft.method.update({
                    integrationID: Integration.ID.make(input.integrationID),
                    method: { ...input.method, id: methodID },
                    authorize: (inputs) =>
                      input.authorize(inputs).pipe(
                        Effect.map((authorization) => {
                          if (authorization.mode === "auto") {
                            return {
                              ...authorization,
                              callback: authorization.callback.pipe(
                                Effect.map((credential) =>
                                  Credential.OAuth.make({
                                    ...credential,
                                    methodID: Integration.MethodID.make(credential.methodID),
                                  }),
                                ),
                              ),
                            }
                          }
                          return {
                            ...authorization,
                            callback: (code: string) =>
                              authorization.callback(code).pipe(
                                Effect.map((credential) =>
                                  Credential.OAuth.make({
                                    ...credential,
                                    methodID: Integration.MethodID.make(credential.methodID),
                                  }),
                                ),
                              ),
                          }
                        }),
                      ),
                    ...(refresh
                      ? {
                          refresh: (value: Credential.OAuth) =>
                            refresh(value).pipe(
                              Effect.map((next) =>
                                Credential.OAuth.make({
                                  ...next,
                                  methodID: Integration.MethodID.make(next.methodID),
                                }),
                              ),
                            ),
                        }
                      : {}),
                    ...(input.label ? { label: input.label } : {}),
                  })
                  return
                }
                if (input.method.type === "env") {
                  draft.method.update({
                    integrationID: Integration.ID.make(input.integrationID),
                    method: { type: "env", names: input.method.names },
                  })
                  return
                }
                draft.method.update({
                  integrationID: Integration.ID.make(input.integrationID),
                  method: { type: "key", label: input.method.label, prompts: input.method.prompts },
                })
              },
              remove: (id, method) =>
                draft.method.remove(Integration.ID.make(id), Schema.decodeUnknownSync(Integration.Method)(method)),
            },
          }),
        ),
    },
    plugin: {
      add: (input) => plugin.add(PluginV2.ID.make(input.id), input.effect),
      remove: (id) => plugin.remove(PluginV2.ID.make(id)),
    },
    reference: {
      reload: reference.reload,
      transform: (callback) =>
        reference.transform((draft) =>
          callback({
            add: (name, source) => draft.add(name, Schema.decodeUnknownSync(Reference.Source)(source)),
            remove: draft.remove,
            list: draft.list,
          }),
        ),
    },
    skill: {
      reload: skill.reload,
      transform: (callback) =>
        skill.transform((draft) =>
          callback({
            source: (source) => draft.source(Schema.decodeUnknownSync(SkillV2.Source)(source)),
            list: draft.list,
          }),
        ),
    },
  } satisfies Interface
})

export * as PluginPromise from "./promise"

import { define } from "@orchestra/plugin/v2/effect"
import type { Plugin, PluginContext, Registration } from "@orchestra/plugin/v2/promise"
import { Effect, Scope } from "effect"

// The Effect host hands back this registration shape; mirror it structurally so
// we do not have to alias the Effect package's `Registration` against the Promise one.
type HostRegistration = { readonly dispose: Effect.Effect<void> }

/**
 * Adapts a Promise plugin into an Effect plugin so the existing Effect-only
 * loader (`PluginV2` / `PluginInternal`) can run it unchanged.
 *
 * Hook registrations created during the async `setup` attach to the plugin's
 * scope, so unloading the plugin disposes them. The captured fiber context
 * preserves boot-time batching, so Promise-plugin transforms still coalesce
 * into one reload per domain.
 */
export function fromPromise(plugin: Plugin) {
  return define({
    id: plugin.id,
    effect: (host) =>
      Effect.gen(function* () {
        const scope = yield* Scope.Scope
        const context = yield* Effect.context<Scope.Scope>()

        // Run a hook registration on the plugin scope and resolve once it is registered.
        const register = (effect: Effect.Effect<HostRegistration, never, Scope.Scope>): Promise<Registration> =>
          Effect.runPromiseWith(context)(Scope.provide(scope)(effect)).then((registration) => ({
            dispose: () => Effect.runPromiseWith(context)(registration.dispose),
          }))

        const run = (effect: Effect.Effect<void>) => Effect.runPromiseWith(context)(effect)

        const transform =
          <Draft>(domain: {
            transform: (
              callback: (draft: Draft) => Effect.Effect<void> | void,
            ) => Effect.Effect<HostRegistration, never, Scope.Scope>
          }) =>
          (callback: (draft: Draft) => Promise<void> | void) =>
            register(domain.transform((draft) => Effect.promise(() => Promise.resolve(callback(draft)))))

        const context2: PluginContext = {
          options: host.options,
          agent: {
            transform: transform(host.agent),
            reload: () => run(host.agent.reload()),
          },
          aisdk: {
            sdk: (callback) =>
              register(host.aisdk.sdk((event) => Effect.promise(() => Promise.resolve(callback(event))))),
            language: (callback) =>
              register(host.aisdk.language((event) => Effect.promise(() => Promise.resolve(callback(event))))),
          },
          catalog: {
            transform: transform(host.catalog),
            reload: () => run(host.catalog.reload()),
          },
          command: {
            transform: transform(host.command),
            reload: () => run(host.command.reload()),
          },
          integration: {
            transform: transform(host.integration),
            reload: () => run(host.integration.reload()),
            connection: {
              active: (id) => Effect.runPromiseWith(context)(host.integration.connection.active(id)),
              resolve: (connection) => Effect.runPromiseWith(context)(host.integration.connection.resolve(connection)),
            },
          },
          plugin: {
            add: (input) => {
              const child = fromPromise(input)
              return run(host.plugin.add(child))
            },
            remove: (id) => run(host.plugin.remove(id)),
          },
          reference: {
            transform: transform(host.reference),
            reload: () => run(host.reference.reload()),
          },
          skill: {
            transform: transform(host.skill),
            reload: () => run(host.skill.reload()),
          },
        }

        yield* Effect.promise(() => Promise.resolve(plugin.setup(context2)))
      }),
  })
}

export * as PluginSdkAdmission from "./sdk-admission"

import path from "node:path"
import { fileURLToPath } from "node:url"
import { realpath, stat } from "node:fs/promises"
import type Arborist from "@npmcli/arborist"
import { Schema } from "effect"
import { Global } from "../global"
import { Flock } from "../util/flock"
import { PluginSdkPackage } from "./sdk-package"
import { PluginSdkLimits } from "./sdk-limits"

const decodePackage = Schema.decodeUnknownSync(Schema.fromJsonString(Schema.Record(Schema.String, Schema.Unknown)))

function ancestry(directory: string): string[] {
  const parent = path.dirname(directory)
  return directory === parent ? [directory] : [directory, ...ancestry(parent)]
}

async function scope(file: string) {
  const parents = ancestry(path.dirname(file))
  for (const directory of parents) {
    if (await PluginSdkPackage.exists(path.join(directory, "package.json"))) return directory
    // Local configuration code has its own source envelope, even when the
    // containing application is a workspace with thousands of installed packages.
    if (["plugin", "plugins", "tool", "tools"].includes(path.basename(directory)) && path.basename(path.dirname(directory)) === ".orchestra")
      return path.dirname(file)
  }
  return path.dirname(file)
}

async function dependency(directory: string, name: string) {
  for (const dir of ancestry(directory)) {
    const slot = path.join(dir, "node_modules", name)
    if (await PluginSdkPackage.exists(slot)) return slot
  }
}

// Admit source envelopes and dependency roots, not the containing application.
// Inventory installed namespaces once without recursively walking their sources.
// Deliberate escapes and later filesystem mutation are not sandboxed here.
export async function prepare(specifier: string, sourceRoot?: string) {
  return admit(specifier, sourceRoot).catch((cause: unknown) => {
    if (cause instanceof PluginSdkPackage.SetupError) throw cause
    throw new PluginSdkPackage.SetupError({ path: specifier, reason: `Cannot prove external module footprint: ${String(cause)}` })
  })
}

async function admit(specifier: string, sourceRoot?: string) {
  const file = specifier.startsWith("file:") ? fileURLToPath(specifier) : specifier
  if (!path.isAbsolute(file)) throw new PluginSdkPackage.SetupError({ path: specifier, reason: "External import needs a concrete filesystem entrypoint" })
  const root = sourceRoot ?? await scope(file)
  if (!path.isAbsolute(root) || !PluginSdkPackage.contains(root, file))
    throw new PluginSdkPackage.SetupError({ path: root, reason: "External entrypoint is outside its source envelope" })
  return Flock.withLock(`sdk-admission:${root}`, async () => {
    const actual = await realpath(file)
    if (!(await stat(actual)).isFile()) throw new Error("External entrypoint is not a regular file")
    const { Arborist } = await import("@npmcli/arborist")
    const canonicalRoot = await realpath(root)
    const roots = new Set([root, PluginSdkPackage.contains(canonicalRoot, actual) ? canonicalRoot : await scope(actual)])
    const pending = new Set(roots)
    const visited = new Set<string>()
    const namespaces = new Map<string, Promise<Arborist.Node>>()
    const indexed = new Set<string>()
    const metadata = new Map<string, Record<string, unknown>>()
    const nodes = new Map<string, Arborist.Node>()
    const namespaceQueue = new Set<string>()
    const checkedAncestry = new Set<string>()
    const absentSlots = new Map<string, string>()
    const checkedIdentity = new Set<string>()
    const sdk = new Set<string>()
    const create = new Set<string>()
    const quota = PluginSdkLimits.budget()
    const bundledPath = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../../plugin")
    const bundled = await PluginSdkPackage.exists(bundledPath) ? await realpath(bundledPath) : undefined
    // This exact host package is already the authority backing runtime modules.
    // A different tree bearing its name (including any foreign link) is untrusted.
    const host = async (directory: string) => bundled !== undefined &&
      (directory === bundled || PluginSdkPackage.contains(path.dirname(bundled), directory) ||
        PluginSdkPackage.contains(path.join(path.dirname(path.dirname(bundled)), "node_modules"), directory)) &&
      await realpath(directory) === bundled
    const read = async (directory: string) => {
      const canonical = await realpath(directory)
      if (metadata.has(canonical)) return metadata.get(canonical)!
      const pkg = path.join(canonical, "package.json")
      const value = await PluginSdkPackage.exists(pkg) ? decodePackage((await PluginSdkLimits.read(pkg, quota)).toString("utf8")) : {}
      metadata.set(canonical, value)
      return value
    }
    const inspect = async (directory: string, canonical: string, bridges = true) => {
      for (const location of new Set([directory, canonical])) {
        if (!checkedIdentity.has(location)) {
          checkedIdentity.add(location)
          // Self-reference uses the nearest enclosing package before node_modules.
          // Read its identity/exports even when its sources are outside our envelope.
          for (const parent of ancestry(location)) {
            if (!(await PluginSdkPackage.exists(path.join(parent, "package.json")))) continue
            const pkg = await read(parent)
            if (pkg.name === PluginSdkPackage.manifest.name && !(await host(parent))) sdk.add(parent)
            break
          }
        }
        for (const parent of ancestry(location)) {
          if (checkedAncestry.has(parent)) {
            const slot = absentSlots.get(parent)
            if (bridges && slot) create.add(slot)
            continue
          }
          checkedAncestry.add(parent)
          const namespace = path.join(parent, "node_modules")
          if (!(await PluginSdkPackage.exists(namespace))) continue
          const slot = path.join(namespace, PluginSdkPackage.manifest.name)
          namespaceQueue.add(await realpath(namespace))
          if (await PluginSdkPackage.exists(slot)) {
            if (!(await host(slot))) sdk.add(slot)
            continue
          }
          absentSlots.set(parent, slot)
          if (bridges) create.add(slot)
        }
      }
    }
    // Bound the installed metadata before Arborist allocates its inventory. Only
    // namespace/package metadata is visited; .git, builds and assets never enter.
    const index = async (namespace: string): Promise<void> => {
      const canonical = await realpath(namespace)
      if (indexed.has(canonical)) return
      indexed.add(canonical)
      for await (const entry of PluginSdkLimits.entries(canonical, quota)) {
        if (entry.name.startsWith(".")) continue
        const directory = path.join(canonical, entry.name)
        if (!entry.isDirectory() && !entry.isSymbolicLink()) continue
        if (entry.name.startsWith("@")) {
          await index(directory)
          continue
        }
        await read(directory)
        const nested = path.join(await realpath(directory), "node_modules")
        if (await PluginSdkPackage.exists(nested)) await index(nested)
      }
    }
    const inventory = async (namespace: string) => {
      const canonical = await realpath(namespace)
      const previous = namespaces.get(canonical)
      if (previous) return previous
      const loading = (async () => {
        await index(canonical)
        // Global mode indexes node_modules without adopting the application's
        // package, workspace globs, lockfiles or missing dependency graph.
        const options = { path: path.dirname(canonical), global: true, ignoreMissing: true, workspacesEnabled: false }
        const tree = await new Arborist(options).loadActual()
        for (const node of tree.inventory.values()) {
          if (node.isRoot) continue
          // An installed package is reachable by computed imports without a
          // declared caller edge. Check both ancestries, but do not walk its sources.
          await inspect(node.path, node.realpath, false)
          nodes.set(node.path, node)
          nodes.set(node.realpath, node.isLink ? node.target : node)
          const nested = path.join(node.realpath, "node_modules")
          if (indexed.has(nested) && !namespaces.has(nested)) namespaces.set(nested, Promise.resolve(tree))
          if (node.errors.length) throw new Error(`Cannot prove package metadata at ${node.path}`)
          if (node.name === PluginSdkPackage.manifest.name || node.package.name === PluginSdkPackage.manifest.name) {
            if (!(await host(node.path))) sdk.add(node.path)
          }
          for (const edge of node.edgesOut.values()) {
            if (edge.name !== PluginSdkPackage.manifest.name && !edge.rawSpec.startsWith("npm:")) continue
            const slot = edge.to?.path ?? await dependency(node.realpath, edge.name)
            if (slot && edge.rawSpec.startsWith("workspace:") && await host(slot)) continue
            if (!PluginSdkPackage.request(edge.name, edge.rawSpec)) continue
            if (slot) {
              if (!(await host(slot))) sdk.add(slot)
            } else create.add(path.join(node.path, "node_modules", edge.name))
          }
        }
        return tree
      })()
      namespaces.set(canonical, loading)
      return loading
    }
    while (pending.size || namespaceQueue.size) {
      if (namespaceQueue.size) {
        const namespace = namespaceQueue.values().next().value
        if (!namespace) break
        namespaceQueue.delete(namespace)
        await inventory(namespace)
        continue
      }
      const directory = pending.values().next().value
      if (!directory) break
      pending.delete(directory)
      const canonical = await realpath(directory)
      await inspect(directory, canonical)
      // Finish namespace metadata before following this package's parsed edges.
      if (namespaceQueue.size) {
        pending.add(directory)
        continue
      }
      if (visited.has(canonical)) continue
      if (visited.size >= PluginSdkLimits.limits.directories) throw new Error("Module footprint exceeds admission bound")
      visited.add(canonical)
      const pkg = await read(canonical)
      if (pkg.name === PluginSdkPackage.manifest.name && !(await host(directory))) sdk.add(directory)
      if (sdk.has(directory) || sdk.has(canonical)) continue
      const node = nodes.get(canonical)
      for (const field of ["dependencies", "optionalDependencies", "peerDependencies", "devDependencies"]) {
        // Installed packages' development graphs are not runtime dependencies.
        if (field === "devDependencies" && node && !roots.has(directory)) continue
        if (pkg[field] === undefined) continue
        const requests = Schema.decodeUnknownSync(Schema.Record(Schema.String, Schema.String))(pkg[field])
        for (const [name, spec] of Object.entries(requests)) {
          const slot = node?.edgesOut.get(name)?.to?.path ?? await dependency(canonical, name)
          const request = (name === PluginSdkPackage.manifest.name || spec.startsWith("npm:")) && PluginSdkPackage.request(name, spec)
          if (request) {
            if (slot) {
              if (!(await host(slot))) sdk.add(slot)
            } else create.add(path.join(canonical, "node_modules", name))
            continue
          }
          if (slot) {
            // Installed application workspaces supply normal dependencies. Their
            // namespace metadata is indexed; their whole source repo is not ours.
            const resolved = node?.edgesOut.get(name)?.to
            if (!resolved?.isWorkspace && !(resolved?.isLink && bundled && PluginSdkPackage.contains(path.dirname(bundled), resolved.realpath))) pending.add(slot)
            continue
          }
          const peers = pkg.peerDependenciesMeta === undefined ? {} : Schema.decodeUnknownSync(
            Schema.Record(Schema.String, Schema.Struct({ optional: Schema.optional(Schema.Boolean) })),
          )(pkg.peerDependenciesMeta)
          const optional = field === "peerDependencies" && peers[name]?.optional === true
          if (field === "dependencies" || (field === "peerDependencies" && !optional))
            throw new Error(`Dependency ${name} is outside installed footprint at ${canonical}`)
        }
      }
      for await (const entry of PluginSdkLimits.entries(canonical, quota)) {
        if (entry.name === "node_modules") continue
        const target = path.join(canonical, entry.name)
        if (entry.isDirectory()) pending.add(target)
        if (entry.isSymbolicLink()) {
          const resolved = await realpath(target)
          if ((await stat(resolved)).isDirectory()) pending.add(target)
          else pending.add(await scope(resolved))
        }
      }
    }
    for (const directory of sdk) {
      if ((await PluginSdkPackage.exists(directory))?.isSymbolicLink())
        throw new PluginSdkPackage.SetupError({ path: directory, reason: "SDK symlink cannot be admitted; left intact" })
      if (await PluginSdkPackage.valid(directory)) continue
      if (!(await PluginSdkPackage.owned(directory, Global.Path.cache)))
        throw new PluginSdkPackage.SetupError({ path: directory, reason: "Foreign or altered SDK tree; left intact" })
      await PluginSdkPackage.write(directory, true)
    }
    for (const root of roots) create.add(path.join(root, "node_modules", PluginSdkPackage.manifest.name))
    // Only create absent bridges after the whole footprint has been admitted.
    // Existing directories must prove their bytes; no user SDK is overwritten.
    for (const directory of create) {
      if (sdk.has(directory)) continue
      await PluginSdkPackage.write(directory)
    }
  })
}

export * as PluginSdkRuntime from "./sdk-runtime"

import { lazy } from "../util/lazy"

// Known public imports resolve to bundled objects. Prepared external imports also
// receive closed, byte-checked filesystem bridges for aliases and unknown subpaths.
// Bun registration alone is not a process-wide unknown-import guard.
export const modules = {
  // The package root re-exports tool.ts and adds only types, whose declarations core cannot compile.
  "@orchestra/plugin": () => import("@orchestra/plugin/tool"),
  "@orchestra/plugin/tool": () => import("@orchestra/plugin/tool"),
  "@orchestra/plugin/tui": () => import("@orchestra/plugin/tui"),
  "@orchestra/plugin/v2/effect": () => import("@orchestra/plugin/v2/effect"),
  "@orchestra/plugin/v2/effect/integration": () => import("@orchestra/plugin/v2/effect/integration"),
  "@orchestra/plugin/v2/effect/plugin": () => import("@orchestra/plugin/v2/effect/plugin"),
  "@orchestra/plugin/v2/promise": () => import("@orchestra/plugin/v2/promise"),
}

const URL_PREFIX = "orchestra-plugin-sdk:"
const GLOBAL_KEY = Symbol.for("orchestra.plugin-sdk")

function requirePublic(specifier: string, loaded: Record<string, Record<string, unknown>>) {
  if (Object.hasOwn(loaded, specifier)) return true
  if (specifier === "@orchestra/plugin" || specifier.startsWith("@orchestra/plugin/"))
    throw Object.assign(new Error(`Bundled SDK does not export ${specifier}`), { name: "PluginSdkImportError" })
  return false
}

export async function prepareExternalImport(specifier: string, sourceRoot?: string) {
  const { PluginSdkAdmission } = await import("./sdk-admission")
  await PluginSdkAdmission.prepare(specifier, sourceRoot)
}

// Registration is process-wide and happens once; admission is separate and per import.
export const install = lazy(async () => {
  const loaded: Record<string, Record<string, unknown>> = Object.fromEntries(
    await Promise.all(Object.entries(modules).map(async ([specifier, load]) => [specifier, await load()] as const)),
  )
  if (typeof Bun !== "undefined") {
    Bun.plugin({
      name: "orchestra-plugin-sdk",
      setup(build) {
        for (const [specifier, exports] of Object.entries(loaded)) {
          build.module(specifier, () => ({ exports, loader: "object" }))
          build.module(URL_PREFIX + specifier, () => ({ exports, loader: "object" }))
        }
      },
    })
    return
  }
  const { registerHooks } = await import("node:module")
  if (typeof registerHooks !== "function") throw new Error("Bundled plugin SDK requires Node.js 22.15 or later")
  // A module that a load hook generates can reach objects from this one only through a global.
  Object.assign(globalThis, { [GLOBAL_KEY]: loaded })
  registerHooks({
    resolve: (specifier, context, nextResolve) =>
      specifier.startsWith(URL_PREFIX)
        ? (requirePublic(specifier.slice(URL_PREFIX.length), loaded), { url: specifier, shortCircuit: true })
        : requirePublic(specifier, loaded) ? { url: URL_PREFIX + specifier, shortCircuit: true }
        : nextResolve(specifier, context),
    load: (url, context, nextLoad) =>
      url.startsWith(URL_PREFIX)
        ? { format: "module", source: nodeSource(url.slice(URL_PREFIX.length), loaded), shortCircuit: true }
        : nextLoad(url, context),
  })
})

function nodeSource(specifier: string, loaded: Record<string, Record<string, unknown>>) {
  return [
    `const sdk = globalThis[Symbol.for("orchestra.plugin-sdk")][${JSON.stringify(specifier)}]`,
    ...Object.keys(loaded[specifier] ?? {}).map(
      (name, index) =>
        `const v${index} = sdk[${JSON.stringify(name)}]\nexport { v${index} as ${JSON.stringify(name)} }`,
    ),
  ].join("\n")
}

export * as PluginSdkPackage from "./sdk-package"

import npa from "npm-package-arg"
import semver from "semver"
import { Schema } from "effect"
import path from "node:path"
import { lstat, mkdir, realpath, rm, writeFile } from "node:fs/promises"
import { PluginSdkLimits, SetupError } from "./sdk-limits"
export { SetupError } from "./sdk-limits"
import sdk from "../../../plugin/package.json"

export class VersionError extends Schema.TaggedErrorClass<VersionError>()("PluginSdkVersionError", {
  requested: Schema.String,
  bundled: Schema.String,
}) {}

// Orchestra does not own the npm scope, so no install may fetch or place another package under it.
export class ScopeError extends Schema.TaggedErrorClass<ScopeError>()("PluginSdkScopeError", {
  requested: Schema.String,
}) {}

export const scope = sdk.name.slice(0, sdk.name.indexOf("/") + 1)

export function scoped(name: string | null | undefined) {
  return !!name && name !== sdk.name && name.startsWith(scope)
}

export const manifest = {
  name: sdk.name,
  version: sdk.version,
  license: sdk.license,
  type: "module" as const,
  main: "./index.js",
  exports: Object.fromEntries(Object.entries(sdk.exports).map(([key, value]) => [key, value.replace("./src/", "./").replace(/\.ts$/, ".js")])),
}

export const sources: Record<string, string> = Object.fromEntries([
  ["package.json", JSON.stringify(manifest)],
  ...Object.entries(manifest.exports).map(([key, file]) => [
    file.slice(2),
    `export * from ${JSON.stringify("orchestra-plugin-sdk:" + sdk.name + (key === "." ? "" : key.slice(1)))}\n`,
  ]),
])

export async function exists(file: string) {
  return lstat(file).catch((cause: unknown) => {
    if (cause && typeof cause === "object" && "code" in cause && cause.code === "ENOENT") return
    throw cause
  })
}

export function contains(root: string, file: string) {
  const relative = path.relative(root, file)
  return relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative)
}

// Check the complete generated tree, including bytes, closed exports and absence of extra code.
export async function valid(directory: string): Promise<boolean> {
  const leaf = await exists(directory)
  if (!leaf || !leaf.isDirectory()) return false
  const directories = new Set(Object.keys(sources).flatMap((file) => file.split("/").slice(0, -1).map((_, index, parts) => parts.slice(0, index + 1).join("/"))))
  const quota = PluginSdkLimits.budget({ ...PluginSdkLimits.limits,
    directories: directories.size + 1,
    entries: Object.keys(sources).length + directories.size,
    bytes: Object.values(sources).reduce((sum, source) => sum + Buffer.byteLength(source) + 1, 0),
  })
  const found = new Set<string>()
  const walk = async (dir: string, prefix: string): Promise<boolean> => {
    for await (const entry of PluginSdkLimits.entries(dir, quota)) {
      const file = prefix + entry.name
      if (entry.isDirectory()) {
        if (!directories.has(file) || !(await walk(path.join(dir, entry.name), file + "/"))) return false
        continue
      }
      if (!entry.isFile() || !Object.hasOwn(sources, file)) return false
      const expected = Buffer.from(sources[file])
      // A same-named file of another size is a foreign tree, not an admission failure: callers replace or
      // reject it. The bounded read below still fails closed if the file grows after this check.
      if ((await lstat(path.join(dir, entry.name))).size !== expected.length) return false
      if (!(await PluginSdkLimits.read(path.join(dir, entry.name), quota, expected.length)).equals(expected)) return false
      found.add(file)
    }
    return true
  }
  return (await walk(directory, "")) && found.size === Object.keys(sources).length
}

export async function write(directory: string, replace = false) {
  if ((await exists(directory))?.isSymbolicLink())
    throw new SetupError({ path: directory, reason: "SDK symlink requires a fresh owned installation; left intact" })
  if (await valid(directory)) return
  if ((await exists(directory)) && !replace)
    throw new SetupError({ path: directory, reason: "Foreign or altered SDK tree; left intact" })
  await mkdir(path.dirname(directory), { recursive: true })
  if (replace) await rm(directory, { recursive: true, force: true })
  await mkdir(directory)
  const results = await Promise.allSettled(Object.entries(sources).map(async ([file, source]) => {
    await mkdir(path.dirname(path.join(directory, file)), { recursive: true })
    await writeFile(path.join(directory, file), source, { flag: "wx" })
  }))
  const failure = results.find((result) => result.status === "rejected")
  if (failure?.status === "rejected") throw failure.reason
}

export async function owned(file: string, cache: string) {
  const root = path.join(cache, "packages")
  if (!contains(root, file) || !(await exists(root))) return false
  const parents = async (parent: string): Promise<string> => (await exists(parent)) ? realpath(parent) : parents(path.dirname(parent))
  return contains(await realpath(root), await parents(path.dirname(file)))
}

// npm aliases carry their real package identity in subSpec, not the dependency key.
export function request(name: string, rawSpec: string) {
  const parsed = npa.resolve(name, rawSpec)
  const target = parsed.type === "alias" ? parsed.subSpec : parsed
  if (scoped(parsed.name) || scoped(target.name)) throw new ScopeError({ requested: parsed.toString() })
  if (target.name !== sdk.name) return
  if ((target.type === "tag" && target.fetchSpec === "latest") ||
      ((target.type === "range" || target.type === "version") && target.fetchSpec && semver.satisfies(sdk.version, target.fetchSpec))) return target
  throw new VersionError({ requested: parsed.toString(), bundled: sdk.version })
}

export function requestSpec(specifier: string) {
  const parsed = npa(specifier)
  if (parsed.name) return request(parsed.name, parsed.rawSpec)
  if (parsed.type === "alias") return request(sdk.name, parsed.rawSpec)
}

export function versionFailure(cause: unknown) {
  if (cause instanceof VersionError) return cause
  if (cause instanceof SetupError) return cause
  if (cause instanceof ScopeError) return cause
  if (cause && typeof cause === "object" && "code" in cause && cause.code === "ETARGET" &&
      "name" in cause && cause.name === sdk.name && "wanted" in cause && typeof cause.wanted === "string")
    return new VersionError({ requested: `${sdk.name}@${cause.wanted}`, bundled: sdk.version })
}

export * as PluginSdkRegistry from "./sdk-registry"

import { createServer } from "node:http"
import { createHash, randomUUID } from "node:crypto"
import { gzipSync } from "node:zlib"
// @ts-expect-error Arborist's frozen packument-cache SPI has no published declarations.
import PackumentCache from "@npmcli/arborist/lib/packument-cache.js"
import { PluginSdkPackage } from "./sdk-package"

// Archive contains only generated, fixed SDK paths; no host files or workspace dependencies.
function archive() {
  return gzipSync(Buffer.concat([
    ...Object.entries(PluginSdkPackage.sources).flatMap(([file, source]) => {
      const bytes = Buffer.from(source)
      const header = Buffer.alloc(512)
      header.write(`package/${file}`, 0, 100)
      header.write("0000644\0", 100, 8)
      header.write("0000000\0", 108, 8)
      header.write("0000000\0", 116, 8)
      header.write(bytes.length.toString(8).padStart(11, "0") + "\0", 124, 12)
      header.write("00000000000\0", 136, 12)
      header.fill(32, 148, 156)
      header.write("0", 156, 1)
      header.write("ustar\0", 257, 6)
      header.write("00", 263, 2)
      header.write(header.reduce((sum, byte) => sum + byte, 0).toString(8).padStart(6, "0") + "\0 ", 148, 8)
      return [header, bytes, Buffer.alloc((512 - bytes.length % 512) % 512)]
    }),
    Buffer.alloc(1024),
  ]))
}

function sdkKey(key: string) {
  if (!key.startsWith("full:") && !key.startsWith("corgi:")) return false
  const raw = key.slice(key.indexOf(":") + 1)
  if (!URL.canParse(raw)) return false
  return decodeURIComponent(new URL(raw).pathname).endsWith("/" + PluginSdkPackage.manifest.name)
}

export async function open() {
  const Cache: unknown = PackumentCache
  if (!isPackumentCache(Cache))
    throw new PluginSdkPackage.SetupError({ path: "@npmcli/arborist/lib/packument-cache.js", reason: "Required packument-cache SPI is unavailable" })
  const bytes = archive()
  const endpoint = "/" + randomUUID() + ".tgz"
  // Installs point the whole SDK scope at this listener, so any other scoped
  // package fails here instead of being fetched from a registry we do not own.
  const denied: string[] = []
  const server = createServer((request, response) => {
    if (request.url !== endpoint || request.method !== "GET") {
      denied.push(decodeURIComponent(new URL(request.url ?? "/", "http://127.0.0.1").pathname.slice(1)))
      response.writeHead(404).end()
      return
    }
    response.writeHead(200, { "content-type": "application/octet-stream", "content-length": bytes.length }).end(bytes)
  })
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject)
    server.listen(0, "127.0.0.1", () => { server.off("error", reject); resolve() })
  })
  const address = server.address()
  if (!address || typeof address === "string") {
    server.close()
    throw new Error("SDK loopback listener has no TCP address")
  }
  const dist = {
    tarball: `http://127.0.0.1:${address.port}${endpoint}`,
    integrity: `sha512-${createHash("sha512").update(bytes).digest("base64")}`,
  }
  const packument = {
    name: PluginSdkPackage.manifest.name,
    "dist-tags": { latest: PluginSdkPackage.manifest.version },
    versions: { [PluginSdkPackage.manifest.version]: { ...PluginSdkPackage.manifest, dist } },
  }
  // Preserve Arborist's normal LRU behavior for every non-SDK key.
  const packumentCache = new class extends Cache {
    override has(key: string) { return sdkKey(key) || super.has(key) }
    override get(key: string) { return sdkKey(key) ? packument : super.get(key) }
  }()
  return {
    dist,
    registry: `http://127.0.0.1:${address.port}/`,
    denied,
    packumentCache,
    close: () => new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve())),
  }
}

// Arborist 9's private cache is an LRU, not the Map claimed by pacote's types.
// Keep its implementation and require the frozen SPI we actually consume.
function isPackumentCache(value: unknown): value is new () => {
  has(key: string): boolean
  get(key: string): unknown
  set(key: string, value: unknown): unknown
} {
  if (typeof value !== "function") return false
  const prototype: unknown = value.prototype
  return typeof prototype === "object" && prototype !== null &&
    "has" in prototype && typeof prototype.has === "function" &&
    "get" in prototype && typeof prototype.get === "function" &&
    "set" in prototype && typeof prototype.set === "function"
}

export * as PluginSdkReconcile from "./sdk-reconcile"

import path from "node:path"
import { realpath } from "node:fs/promises"
import type Arborist from "@npmcli/arborist"
import { PluginSdkPackage } from "./sdk-package"

export async function reconcile(tree: Arborist.Node, directory: string, dist: { tarball: string; integrity: string }, cache: string) {
  const nodes = Array.from(tree.inventory.values())
  // Bundled or previously installed copies never pass through the scope registry.
  const foreign = nodes.find((node) => !node.isRoot && (PluginSdkPackage.scoped(node.name) || PluginSdkPackage.scoped(node.package.name)))
  if (foreign) throw new PluginSdkPackage.ScopeError({ requested: foreign.package.name ?? foreign.name })
  const targets = new Set(nodes.filter((node) => !node.isRoot && !node.linksIn.size && (node.package.name === PluginSdkPackage.manifest.name || node.name === PluginSdkPackage.manifest.name)))
  nodes.forEach((node) => node.edgesOut.forEach((edge) => {
    if (PluginSdkPackage.request(edge.name, edge.spec) && edge.to) targets.add(edge.to)
  }))
  const root = await realpath(directory)
  for (const node of targets) {
    if (!(await PluginSdkPackage.valid(node.path))) {
      // Only replace regular cache-owned SDK trees; foreign links need a fresh install.
      if (!PluginSdkPackage.contains(root, node.path) || !(await PluginSdkPackage.owned(node.path, cache)))
        throw new PluginSdkPackage.SetupError({ path: node.path, reason: "Foreign SDK outside owned npm cache; left intact" })
      if (node.isLink)
        throw new PluginSdkPackage.SetupError({ path: node.path, reason: "Foreign SDK link requires a fresh owned installation; left intact" })
      await PluginSdkPackage.write(node.path, true)
    }
    node.package = PluginSdkPackage.manifest
    node.resolved = dist.tarball
    node.integrity = dist.integrity
    if (tree.meta) addMetadata(tree.meta, node)
  }
  if (targets.size) await tree.meta?.save()
}

// Shrinkwrap.add is present in the installed Arborist 9 SPI, but omitted from
// its public declarations. Fail if that capability disappears; never skip it.
function addMetadata(meta: Arborist.Shrinkwrap, node: Arborist.Node) {
  if (!("add" in meta) || typeof meta.add !== "function")
    throw new PluginSdkPackage.SetupError({ path: meta.path, reason: "Required Shrinkwrap.add SPI is unavailable" })
  meta.add(node)
}

export * as PluginSdkLimits from "./sdk-limits"

import { open, opendir } from "node:fs/promises"
import { Schema } from "effect"

export class SetupError extends Schema.TaggedErrorClass<SetupError>()("PluginSdkSetupError", {
  path: Schema.String,
  reason: Schema.String,
}) {
  override get message() { return `${this._tag}: ${this.reason} (${this.path})` }
}

export const limits = { directories: 4096, entries: 32768, directoryEntries: 4096, bytes: 8 * 1024 * 1024, packageBytes: 256 * 1024 }

export function budget(maximum = limits) {
  const used = { directories: 0, entries: 0, bytes: 0 }
  return {
    directoryEntries: maximum.directoryEntries,
    spend(kind: keyof typeof used, amount: number, file: string) {
      used[kind] += amount
      if (used[kind] > maximum[kind]) throw new SetupError({ path: file, reason: `Admission ${kind} bound exceeded` })
    },
  }
}

// Consume directory entries one at a time, including the quota check before the
// caller can append to a queue. Dir's async iterator closes on break/error.
export async function* entries(directory: string, quota: ReturnType<typeof budget>) {
  quota.spend("directories", 1, directory)
  const count = { value: 0 }
  for await (const entry of await opendir(directory, { bufferSize: 1 })) {
    if (++count.value > quota.directoryEntries) throw new SetupError({ path: directory, reason: "Admission directory-entry bound exceeded" })
    quota.spend("entries", 1, directory)
    yield entry
  }
}

// fstat before allocating, then a fixed-cap read also detects growth after fstat.
export async function read(file: string, quota: ReturnType<typeof budget>, maximum = limits.packageBytes) {
  const handle = await open(file, "r")
  try {
    const info = await handle.stat()
    if (!info.isFile() || info.size > maximum) throw new SetupError({ path: file, reason: "Admission file-byte bound exceeded or non-regular file" })
    quota.spend("bytes", info.size + 1, file)
    const bytes = Buffer.alloc(info.size + 1)
    const offset = { value: 0 }
    while (offset.value < bytes.length) {
      const result = await handle.read(bytes, offset.value, bytes.length - offset.value, null)
      if (!result.bytesRead) break
      offset.value += result.bytesRead
    }
    if (offset.value !== info.size) throw new SetupError({ path: file, reason: "File changed during bounded admission read" })
    return bytes.subarray(0, offset.value)
  } finally {
    await handle.close()
  }
}

export * as AgentPlugin from "./agent"

import path from "path"
import { define } from "./internal"
import { Effect } from "effect"
import { AgentV2 } from "../agent"
import { AgentPrompt } from "../agent/prompt"
import { Global } from "../global"
import { PermissionV2 } from "../permission"

const TRUNCATION_GLOB = path.join(Global.Path.data, "tool-output", "*")

export const Plugin = define({
  id: "agent",
  effect: Effect.fn(function* (ctx) {
    const whitelistedDirs = [TRUNCATION_GLOB, path.join(Global.Path.tmp, "*")]
    const readonlyExternalDirectory: PermissionV2.Ruleset = [
      { action: "external_directory", resource: "*", effect: "ask" },
      ...whitelistedDirs.map(
        (resource): PermissionV2.Rule => ({ action: "external_directory", resource, effect: "allow" }),
      ),
    ]
    // Reads every file but .env files, which hold secrets; .env.example stays readable. Last match wins, so an agent's
    // own read allow goes before these.
    const envRead: PermissionV2.Ruleset = [
      { action: "read", resource: "*", effect: "allow" },
      { action: "read", resource: "*.env", effect: "ask" },
      { action: "read", resource: "*.env.*", effect: "ask" },
      { action: "read", resource: "*.env.example", effect: "allow" },
    ]
    // Commands that publish work: Maestro and general ask the owner first, and configuration can allow them.
    const publish: PermissionV2.Ruleset = ["git push *", "git -C * push *", "gh pr create *", "gh pr merge *", "gh release *"].map(
      (resource) => ({ action: "bash", resource, effect: "ask" }),
    )
    const publishDeny: PermissionV2.Ruleset = publish.map((rule) => ({ ...rule, effect: "deny" }))
    const defaults: PermissionV2.Ruleset = [
      { action: "*", resource: "*", effect: "allow" },
      ...readonlyExternalDirectory,
      { action: "question", resource: "*", effect: "deny" },
      ...envRead,
    ]

    yield* ctx.agent.transform((draft) => {
      draft.update(AgentV2.defaultID, (item) => {
        item.description =
          "High-agency development orchestrator. Uses governed approval only when explicitly requested."
        item.system ??= AgentPrompt.maestro
        item.mode = "primary"
        item.permissions.push(...PermissionV2.merge(defaults, [{ action: "question", resource: "*", effect: "allow" }], publish))
      })

      draft.update(AgentV2.ID.make("general"), (item) => {
        item.description =
          "General-purpose work from a full brief: research, analysis or multi-step changes. Edits files and runs shell commands; cannot ask the owner questions or start teammates. Returns the outcome, what changed, how it was checked and what is left."
        item.system = AgentPrompt.general
        item.mode = "subagent"
        item.permissions.push(...PermissionV2.merge(defaults, [{ action: "todowrite", resource: "*", effect: "deny" }], publish))
      })

      draft.update(AgentV2.ID.make("explore"), (item) => {
        item.description =
          'Read-only codebase exploration: finds files and code and explains how they work. Reads and searches files and the web, and runs read-only shell commands; cannot edit. Say how thorough to be: "quick", "medium" or "very thorough". Returns findings with file and line references.'
        item.system = AgentPrompt.explore
        item.mode = "subagent"
        item.permissions.push(
          ...PermissionV2.merge(
            defaults,
            [
              { action: "*", resource: "*", effect: "deny" },
              { action: "grep", resource: "*", effect: "allow" },
              { action: "glob", resource: "*", effect: "allow" },
              // The shell is sandboxed with no write root (tool/bash.ts READ_ONLY_SHELL), and explore never publishes.
              { action: "bash", resource: "*", effect: "allow" },
              ...publishDeny,
              { action: "webfetch", resource: "*", effect: "allow" },
              { action: "websearch", resource: "*", effect: "allow" },
            ],
            envRead,
            readonlyExternalDirectory,
          ),
        )
      })

      draft.update(AgentV2.ID.make("compaction"), (item) => {
        item.mode = "primary"
        item.hidden = true
        item.system = AgentPrompt.compaction
        item.permissions.push(...PermissionV2.merge(defaults, [{ action: "*", resource: "*", effect: "deny" }]))
      })

      draft.update(AgentV2.ID.make("title"), (item) => {
        item.mode = "primary"
        item.hidden = true
        item.system = AgentPrompt.title
        item.permissions.push(...PermissionV2.merge(defaults, [{ action: "*", resource: "*", effect: "deny" }]))
      })

      draft.update(AgentV2.ID.make("summary"), (item) => {
        item.mode = "primary"
        item.hidden = true
        item.system = AgentPrompt.summary
        item.permissions.push(...PermissionV2.merge(defaults, [{ action: "*", resource: "*", effect: "deny" }]))
      })
    })
  }),
})

