export * as McpCatalog from "./catalog"

import type { Client } from "@modelcontextprotocol/sdk/client/index.js"
import { ListToolsResultSchema, ToolSchema } from "@modelcontextprotocol/sdk/types.js"
import type { ToolContent } from "@orchestra/llm"
import { Effect } from "effect"

const DEFAULT_TIMEOUT = 30_000
const MAX_LIST_PAGES = 1_000

const TolerantListToolsResultSchema = ListToolsResultSchema.extend({
  tools: ToolSchema.omit({ outputSchema: true }).array(),
})

export async function paginate<T, R extends { nextCursor?: string }>(
  list: (cursor?: string) => Promise<R>,
  items: (result: R) => T[],
) {
  const result: T[] = []
  const cursors = new Set<string>()
  let cursor: string | undefined

  for (let page = 0; page < MAX_LIST_PAGES; page++) {
    const page = await list(cursor)
    result.push(...items(page))
    if (page.nextCursor === undefined) return result
    if (cursors.has(page.nextCursor)) throw new Error(`MCP list returned duplicate cursor: ${page.nextCursor}`)
    cursors.add(page.nextCursor)
    cursor = page.nextCursor
  }

  throw new Error(`MCP list exceeded ${MAX_LIST_PAGES} pages`)
}

/** The server's tools, or undefined when listing fails (a list-changed refresh then keeps the previous set). */
export function defs(client: Client, timeout?: number) {
  return listTools(client, timeout ?? DEFAULT_TIMEOUT).pipe(Effect.catch(() => Effect.void))
}

/** The server's tools; a listing failure stays a typed failure so the caller can report it. */
export function tools(client: Client, timeout?: number) {
  return listTools(client, timeout ?? DEFAULT_TIMEOUT)
}

export function fetch<T extends { name: string }>(
  clientName: string,
  client: Client,
  list: (client: Client) => Promise<T[]>,
  label: string,
  key?: (item: T) => string,
) {
  return Effect.tryPromise({
    try: () => list(client),
    catch: (error) => error,
  }).pipe(
    Effect.tapError((error) =>
      Effect.logWarning(`failed to get ${label}`, {
        clientName,
        error: error instanceof Error ? error.message : String(error),
      }),
    ),
    Effect.map((items) => {
      const sanitizedClient = sanitize(clientName)
      // Escape both the separator and escape marker so `server:uri` keys remain unambiguous.
      const resourceClient = clientName.replaceAll("%", "%25").replaceAll(":", "%3A")
      return Object.fromEntries(
        items.map((item) => [
          key ? resourceClient + ":" + key(item) : sanitizedClient + ":" + sanitize(item.name),
          { ...item, client: clientName },
        ]),
      )
    }),
    Effect.orElseSucceed(() => undefined),
  )
}

export const sanitize = (value: string) => value.replace(/[^a-zA-Z0-9_-]/g, "_")

export const toolName = (clientName: string, name: string) => sanitize(clientName) + "_" + sanitize(name)

export function prompts(client: Client, timeout?: number) {
  if (!client.getServerCapabilities()?.prompts) return Promise.resolve([])
  return paginate(
    (cursor) => client.listPrompts(cursor === undefined ? undefined : { cursor }, { timeout }),
    (result) => result.prompts,
  )
}

export function resources(client: Client, timeout?: number) {
  if (!client.getServerCapabilities()?.resources) return Promise.resolve([])
  return paginate(
    (cursor) => client.listResources(cursor === undefined ? undefined : { cursor }, { timeout }),
    (result) => result.resources,
  )
}

export function resourceTemplates(client: Client, timeout?: number) {
  if (!client.getServerCapabilities()?.resources) return Promise.resolve([])
  return paginate(
    (cursor) => client.listResourceTemplates(cursor === undefined ? undefined : { cursor }, { timeout }),
    (result) => result.resourceTemplates,
  )
}

function listTools(client: Client, timeout: number) {
  return Effect.tryPromise({
    try: () =>
      paginate(
        async (cursor) => {
          const params = cursor === undefined ? undefined : { cursor }
          try {
            return await client.listTools(params, { timeout })
          } catch (error) {
            if (!(error instanceof Error) || !isOutputSchemaValidationError(error)) throw error
            return client.request({ method: "tools/list", params }, TolerantListToolsResultSchema, { timeout })
          }
        },
        (result) => result.tools,
      ),
    catch: (error) => (error instanceof Error ? error : new Error(String(error))),
  })
}

function isOutputSchemaValidationError(error: Error) {
  return /can't resolve reference|resolves to more than one schema|outputSchema|schema.*reference|reference.*schema/i.test(
    error.message,
  )
}

export function described(item: { description?: string; mimeType?: string }) {
  return {
    ...(item.description === undefined ? {} : { description: item.description }),
    ...(item.mimeType === undefined ? {} : { mimeType: item.mimeType }),
  }
}

// SDK 1.32 types `callTool`'s result as its own literal, a union with the legacy `toolResult` shape.
type CallToolResult = Extract<Awaited<ReturnType<Client["callTool"]>>, { content: unknown }>

/** The text parts of a tool result, for an error message. */
export function resultText(result: Pick<CallToolResult, "content">) {
  return result.content.flatMap((item) => (item.type === "text" && item.text.trim() ? [item.text] : [])).join("\n\n")
}

export function resultContent(result: Pick<CallToolResult, "content" | "structuredContent">): ToolContent[] {
  if (result.content.length === 0 && result.structuredContent !== undefined)
    return [{ type: "text", text: JSON.stringify(result.structuredContent) }]
  return result.content.map((item): ToolContent => {
    if (item.type === "text") return { type: "text", text: item.text }
    if (item.type === "image" || item.type === "audio")
      return { type: "file", uri: `data:${item.mimeType};base64,${item.data}`, mime: item.mimeType }
    return { type: "text", text: JSON.stringify(item) }
  })
}

export * as McpStdio from "./stdio"

// The MCP stdio transport on omni. The server's whole tree is omni's: close() ends it, and a crash of the host ends it
// too. stderr is always drained, so a chatty server never blocks before it connects. This replaces the MCP SDK's own
// stdio transport, which spawns outside the repo's spawn rules.

import { ReadBuffer, serializeMessage } from "@modelcontextprotocol/sdk/shared/stdio.js"
import type { Transport } from "@modelcontextprotocol/sdk/shared/transport.js"
import type { JSONRPCMessage } from "@modelcontextprotocol/sdk/types.js"
import { Omni } from "../omni"

const TAIL = 20
const CLOSE_WAIT = 2_000
const LONG_LINE = 64 * 1024

// The slice of hugr-omni's PipeChild<Uint8Array> used here (only core/src/omni.ts imports hugr-omni).
type Pipe = {
  readonly pid: number
  readonly output: AsyncIterable<{ stream: "stdout" | "stderr" | "pty"; data: Uint8Array }>
  write(data: string | Uint8Array): Promise<void>
  closeStdin(): Promise<void>
  wait(): Promise<unknown>
  stop(options?: { graceMs?: number }): Promise<unknown>
}

export interface Params {
  command: string
  args?: string[]
  cwd?: string
  env?: Record<string, string | undefined>
  /** Receives every stderr line of the server (the caller logs it at debug level). */
  log?: (line: string) => void
  /** Called once the server process is spawned, for the caller's spawn telemetry. */
  spawned?: () => void
}

export class OmniStdioTransport implements Transport {
  onclose?: () => void
  onerror?: (error: Error) => void
  onmessage?: (message: JSONRPCMessage) => void
  private child?: Pipe
  private readonly buffer = new ReadBuffer()
  private readonly decoder = new TextDecoder()
  private readonly lines: string[] = []
  private partial = ""
  private done = false
  private closing?: Promise<void>

  constructor(private readonly params: Params) {}

  get pid() {
    return this.child?.pid ?? null
  }

  /** The last 20 lines the server wrote to stderr, for a connect failure. */
  stderrTail() {
    return [...this.lines, ...(this.partial ? [this.partial] : [])].slice(-TAIL).join("\n")
  }

  async start() {
    if (this.child || this.done) throw new Error("OmniStdioTransport already started")
    const binding = await Omni.load()
    // close() may have run while omni loaded; spawning now would leave a child nobody stops.
    if (this.closing || this.done) throw new Error("OmniStdioTransport closed before start")
    // A missing command or a bad cwd throws here, so connect() rejects with omni's message.
    const child = binding.spawn(this.params.command, this.params.args ?? [], {
      cwd: this.params.cwd,
      inheritEnv: false,
      env: Omni.childEnv(this.params.env),
      stdin: "pipe",
      text: false,
      backpressure: true,
    })
    this.child = child
    Omni.count("spawns")
    this.params.spawned?.()
    void this.pump(child)
  }

  async send(message: JSONRPCMessage) {
    if (!this.child || this.done) throw new Error("Not connected")
    await this.child.write(serializeMessage(message))
  }

  /** Ends stdin, gives the server up to 2 s to exit on its own, then always stops the whole tree. */
  close() {
    this.closing ??= this.shutdown()
    return this.closing
  }

  private async shutdown() {
    const child = this.child
    if (child) {
      let timer: ReturnType<typeof setTimeout> | undefined
      await Promise.race([
        child
          .closeStdin()
          .catch(() => undefined)
          .then(() => child.wait()),
        new Promise((resolve) => (timer = setTimeout(resolve, CLOSE_WAIT))),
      ]).catch(() => undefined)
      clearTimeout(timer)
      await child.stop({ graceMs: CLOSE_WAIT }).catch(() => undefined)
    }
    this.buffer.clear()
    this.finish()
  }

  private async pump(child: Pipe) {
    try {
      for await (const chunk of child.output) {
        if (chunk.stream === "stderr") this.stderr(this.decoder.decode(chunk.data, { stream: true }))
        else this.read(chunk.data)
      }
    } catch (error) {
      this.onerror?.(error instanceof Error ? error : new Error(String(error)))
    }
    this.stderr(this.decoder.decode(), true)
    await child.wait().catch(() => undefined)
    this.finish()
  }

  private read(data: Uint8Array) {
    this.buffer.append(Buffer.from(data.buffer, data.byteOffset, data.byteLength))
    for (;;) {
      try {
        const message = this.buffer.readMessage()
        if (message === null) return
        this.onmessage?.(message)
      } catch (error) {
        this.onerror?.(error instanceof Error ? error : new Error(String(error)))
      }
    }
  }

  private stderr(text: string, end = false) {
    const parts = (this.partial + text).split("\n")
    this.partial = parts.pop() ?? ""
    if (end || this.partial.length > LONG_LINE) {
      if (this.partial) parts.push(this.partial)
      this.partial = ""
    }
    for (const part of parts) {
      const line = part.endsWith("\r") ? part.slice(0, -1) : part
      this.lines.push(line)
      if (this.lines.length > TAIL) this.lines.shift()
      this.params.log?.(line)
    }
  }

  private finish() {
    if (this.done) return
    this.done = true
    this.onclose?.()
  }
}

/** A connect failure's message, with the server's last stderr lines when the transport kept them. */
export function failure(transport: unknown, error: unknown) {
  const message = error instanceof Error ? error.message : String(error)
  const tail = transport instanceof OmniStdioTransport ? transport.stderrTail() : ""
  return tail ? `${message}\nLast stderr lines:\n${tail}` : message
}

import type { OAuthClientProvider } from "@modelcontextprotocol/sdk/client/auth.js"
import type {
  OAuthClientMetadata,
  OAuthTokens,
  OAuthClientInformation,
  OAuthClientInformationFull,
} from "@modelcontextprotocol/sdk/shared/auth.js"
import type { ConfigMCP } from "@orchestra/schema/config-mcp"
import type { Mcp } from "@orchestra/schema/mcp"
import { Effect } from "effect"
import { McpAuth } from "./auth"

const OAUTH_CALLBACK_PORT = 19876
const OAUTH_CALLBACK_PATH = "/mcp/oauth/callback"

export interface McpOAuthConfig {
  clientId?: string
  clientSecret?: string
  scope?: string
  callbackPort?: number
  redirectUri?: string
}

export interface McpOAuthCallbacks {
  onRedirect: (url: URL) => void | Promise<void>
}

export class McpOAuthProvider implements OAuthClientProvider {
  constructor(
    protected mcpName: string,
    protected serverUrl: string,
    protected config: McpOAuthConfig,
    private callbacks: McpOAuthCallbacks,
    protected auth: McpAuth.Interface,
  ) {}

  get redirectUrl(): string {
    if (this.config.redirectUri) {
      return this.config.redirectUri
    }
    const port = this.config.callbackPort ?? OAUTH_CALLBACK_PORT
    return `http://127.0.0.1:${port}${OAUTH_CALLBACK_PATH}`
  }

  get clientMetadata(): OAuthClientMetadata {
    return {
      redirect_uris: [this.redirectUrl],
      client_name: "Orchestra",
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
      ...(this.config.scope ? { scope: this.config.scope } : {}),
    }
  }

  async clientInformation(): Promise<OAuthClientInformation | undefined> {
    if (this.config.clientId) {
      return {
        client_id: this.config.clientId,
        client_secret: this.config.clientSecret,
      }
    }

    // Check stored client info (from dynamic registration)
    // Use getForUrl to validate credentials are for the current server URL
    const entry = await Effect.runPromise(this.auth.getForUrl(this.mcpName, this.serverUrl))
    if (entry?.clientInfo) {
      // Check if client secret has expired
      if (entry.clientInfo.clientSecretExpiresAt && entry.clientInfo.clientSecretExpiresAt < Date.now() / 1000) {
        return undefined
      }
      return {
        client_id: entry.clientInfo.clientId,
        client_secret: entry.clientInfo.clientSecret,
      }
    }

    // No client info or URL changed - will trigger dynamic registration
    return undefined
  }

  async saveClientInformation(info: OAuthClientInformationFull): Promise<void> {
    await Effect.runPromise(
      this.auth.updateClientInfo(
        this.mcpName,
        {
          clientId: info.client_id,
          clientSecret: info.client_secret,
          clientIdIssuedAt: info.client_id_issued_at,
          clientSecretExpiresAt: info.client_secret_expires_at,
        },
        this.serverUrl,
      ),
    )
  }

  async tokens(): Promise<OAuthTokens | undefined> {
    // Use getForUrl to validate tokens are for the current server URL
    const entry = await Effect.runPromise(this.auth.getForUrl(this.mcpName, this.serverUrl))
    if (!entry?.tokens) return undefined

    return {
      access_token: entry.tokens.accessToken,
      token_type: "Bearer",
      refresh_token: entry.tokens.refreshToken,
      expires_in: entry.tokens.expiresAt
        ? Math.max(0, Math.floor(entry.tokens.expiresAt - Date.now() / 1000))
        : undefined,
      scope: entry.tokens.scope,
    }
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    await Effect.runPromise(
      this.auth.updateTokens(
        this.mcpName,
        {
          accessToken: tokens.access_token,
          refreshToken: tokens.refresh_token,
          expiresAt: tokens.expires_in ? Date.now() / 1000 + tokens.expires_in : undefined,
          scope: tokens.scope,
        },
        this.serverUrl,
      ),
    )
  }

  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    await this.callbacks.onRedirect(authorizationUrl)
  }

  async saveCodeVerifier(codeVerifier: string): Promise<void> {
    await Effect.runPromise(this.auth.updateCodeVerifier(this.mcpName, codeVerifier))
  }

  async codeVerifier(): Promise<string> {
    const entry = await Effect.runPromise(this.auth.get(this.mcpName))
    if (!entry?.codeVerifier) {
      throw new Error(`No code verifier saved for MCP server: ${this.mcpName}`)
    }
    return entry.codeVerifier
  }

  async saveState(state: string): Promise<void> {
    await Effect.runPromise(this.auth.updateOAuthState(this.mcpName, state))
  }

  async state(): Promise<string> {
    const entry = await Effect.runPromise(this.auth.get(this.mcpName))
    if (entry?.oauthState) {
      return entry.oauthState
    }

    // Generate a new state if none exists — the SDK calls state() as a
    // generator, not just a reader, so we need to produce a value even when
    // startAuth() hasn't pre-saved one (e.g. during automatic auth on first
    // connect).
    const newState = Array.from(crypto.getRandomValues(new Uint8Array(32)))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("")
    await Effect.runPromise(this.auth.updateOAuthState(this.mcpName, newState))
    return newState
  }

  async invalidateCredentials(type: "all" | "client" | "tokens"): Promise<void> {
    const entry = await Effect.runPromise(this.auth.get(this.mcpName))
    if (!entry) return
    switch (type) {
      case "all":
        await Effect.runPromise(this.auth.remove(this.mcpName))
        break
      case "client":
        delete entry.clientInfo
        await Effect.runPromise(this.auth.set(this.mcpName, entry))
        break
      case "tokens":
        delete entry.tokens
        await Effect.runPromise(this.auth.set(this.mcpName, entry))
        break
    }
  }
}

export class McpOAuthPendingProvider extends McpOAuthProvider {
  private pendingClientInfo?: OAuthClientInformationFull
  private pendingTokens?: OAuthTokens

  override async clientInformation(): Promise<OAuthClientInformation | undefined> {
    if (!this.config.clientId) return this.pendingClientInfo
    return {
      client_id: this.config.clientId,
      client_secret: this.config.clientSecret,
    }
  }

  override async saveClientInformation(info: OAuthClientInformationFull): Promise<void> {
    this.pendingClientInfo = info
  }

  override async tokens(): Promise<OAuthTokens | undefined> {
    return this.pendingTokens
  }

  override async saveTokens(tokens: OAuthTokens): Promise<void> {
    this.pendingTokens = tokens
  }

  override async invalidateCredentials(type: "all" | "client" | "tokens"): Promise<void> {
    if (type === "all" || type === "client") this.pendingClientInfo = undefined
    if (type === "all" || type === "tokens") this.pendingTokens = undefined
  }

  async commit(): Promise<void> {
    if (!this.pendingTokens) return
    await Effect.runPromise(
      this.auth.set(
        this.mcpName,
        {
          tokens: {
            accessToken: this.pendingTokens.access_token,
            refreshToken: this.pendingTokens.refresh_token,
            expiresAt: this.pendingTokens.expires_in ? Date.now() / 1000 + this.pendingTokens.expires_in : undefined,
            scope: this.pendingTokens.scope,
          },
          clientInfo:
            this.pendingClientInfo && !this.config.clientId
              ? {
                  clientId: this.pendingClientInfo.client_id,
                  clientSecret: this.pendingClientInfo.client_secret,
                  clientIdIssuedAt: this.pendingClientInfo.client_id_issued_at,
                  clientSecretExpiresAt: this.pendingClientInfo.client_secret_expires_at,
                }
              : undefined,
        },
        this.serverUrl,
      ),
    )
  }
}

export { OAUTH_CALLBACK_PORT, OAUTH_CALLBACK_PATH }

/**
 * Parse a redirect URI to extract port and path for the callback server.
 * Returns defaults if the URI can't be parsed.
 */
export function parseRedirectUri(redirectUri?: string): { port: number; path: string } {
  if (!redirectUri) {
    return { port: OAUTH_CALLBACK_PORT, path: OAUTH_CALLBACK_PATH }
  }

  try {
    const url = new URL(redirectUri)
    const port = url.port ? parseInt(url.port, 10) : url.protocol === "https:" ? 443 : 80
    const path = url.pathname || OAUTH_CALLBACK_PATH
    return { port, path }
  } catch {
    return { port: OAUTH_CALLBACK_PORT, path: OAUTH_CALLBACK_PATH }
  }
}

export function oauthConfig(server: ConfigMCP.Remote): McpOAuthConfig {
  const oauth = server.oauth === false ? undefined : server.oauth
  return {
    clientId: oauth?.client_id,
    clientSecret: oauth?.client_secret,
    scope: oauth?.scope,
    callbackPort: oauth?.callback_port,
    redirectUri: oauth?.redirect_uri,
  }
}

export function unauthorized(error: Error) {
  return error.name === "UnauthorizedError" || /\b401\b|unauthorized/i.test(error.message)
}

// An OAuth failure needs a sign-in, unless the server cannot register a client and needs a configured client ID.
export function authStatus(error: Error, oauth: boolean): Mcp.Status | undefined {
  if (!unauthorized(error) && !(oauth && error.message.includes("OAuth"))) return undefined
  if (/registration|client_id/.test(error.message))
    return {
      status: "needs_client_registration",
      error: "The server does not support dynamic client registration. Set oauth.client_id in its MCP config.",
    }
  return { status: "needs_auth" }
}

import { createConnection } from "net"
import { createServer } from "http"
import { OauthCallbackPage } from "../oauth/page"
import { OAUTH_CALLBACK_PORT, OAUTH_CALLBACK_PATH, parseRedirectUri } from "./oauth-provider"

const OAUTH_CALLBACK_HOST = "127.0.0.1"

// Current callback server configuration (may differ from defaults if custom redirectUri is used)
let currentPort = OAUTH_CALLBACK_PORT
let currentPath = OAUTH_CALLBACK_PATH

interface PendingAuth {
  resolve: (code: string) => void
  reject: (error: Error) => void
  timeout: ReturnType<typeof setTimeout>
}

let server: ReturnType<typeof createServer> | undefined
let starting: Promise<void> | undefined
const pendingAuths = new Map<string, PendingAuth>()
// Reverse index: mcpName → oauthState, so cancelPending(mcpName) can
// find the right entry in pendingAuths (which is keyed by oauthState).
const mcpNameToState = new Map<string, string>()

const CALLBACK_TIMEOUT_MS = 5 * 60 * 1000 // 5 minutes

function cleanupStateIndex(oauthState: string) {
  for (const [name, state] of mcpNameToState) {
    if (state === oauthState) {
      mcpNameToState.delete(name)
      break
    }
  }
}

function stopIfIdle() {
  if (pendingAuths.size > 0 || !server) return

  server.close()
  server = undefined
}

function handleRequest(req: import("http").IncomingMessage, res: import("http").ServerResponse) {
  const url = new URL(req.url || "/", `http://localhost:${currentPort}`)

  if (url.pathname !== currentPath) {
    res.writeHead(404)
    res.end("Not found")
    return
  }

  const code = url.searchParams.get("code")
  const state = url.searchParams.get("state")
  const error = url.searchParams.get("error")
  const errorDescription = url.searchParams.get("error_description")

  // Enforce state parameter presence
  if (!state) {
    const errorMsg = "Missing required state parameter - potential CSRF attack"
    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" })
    res.end(OauthCallbackPage.error(errorMsg, { provider: "MCP" }))
    return
  }

  if (error) {
    const errorMsg = errorDescription || error
    if (pendingAuths.has(state)) {
      const pending = pendingAuths.get(state)!
      clearTimeout(pending.timeout)
      pendingAuths.delete(state)
      cleanupStateIndex(state)
      pending.reject(new Error(errorMsg))
    }
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" })
    res.end(OauthCallbackPage.error(errorMsg, { provider: "MCP" }))
    stopIfIdle()
    return
  }

  if (!code) {
    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" })
    res.end(OauthCallbackPage.error("No authorization code provided", { provider: "MCP" }))
    return
  }

  // Validate state parameter
  if (!pendingAuths.has(state)) {
    const errorMsg = "Invalid or expired state parameter - potential CSRF attack"
    res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" })
    res.end(OauthCallbackPage.error(errorMsg, { provider: "MCP" }))
    return
  }

  const pending = pendingAuths.get(state)!

  clearTimeout(pending.timeout)
  pendingAuths.delete(state)
  cleanupStateIndex(state)
  pending.resolve(code)

  res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" })
  res.end(OauthCallbackPage.success({ provider: "MCP" }))
  stopIfIdle()
}

export async function ensureRunning(redirectUri?: string): Promise<void> {
  // Parse the redirect URI to get port and path (uses defaults if not provided)
  const { port, path } = parseRedirectUri(redirectUri)

  // If server is running on a different port/path, stop it first
  if (server && (currentPort !== port || currentPath !== path)) {
    await stop()
  }

  if (server) return

  // Concurrent callers share one start: a second probe-then-listen would hit EADDRINUSE and,
  // before this, overwrite `server` with the dead handle.
  starting ??= start(port, path).finally(() => {
    starting = undefined
  })
  return starting
}

async function start(port: number, path: string) {
  // Fail now: nothing here would receive the browser's redirect, and the sign-in would wait for the 5 minute timeout.
  if (await isPortInUse(port)) throw portInUse(port)

  currentPort = port
  currentPath = path

  const candidate = createServer(handleRequest)
  await new Promise<void>((resolve, reject) => {
    candidate.on("error", (error: NodeJS.ErrnoException) => reject(error.code === "EADDRINUSE" ? portInUse(port) : error))
    candidate.listen(port, OAUTH_CALLBACK_HOST, () => resolve())
  })
  server = candidate
}

function portInUse(port: number) {
  return new Error(
    `OAuth callback port ${port} is already in use. Close the program using it, or set another port with oauth.callback_port in the server's MCP config.`,
  )
}

export function waitForCallback(oauthState: string, mcpName?: string): Promise<string> {
  if (mcpName) mcpNameToState.set(mcpName, oauthState)
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      if (pendingAuths.has(oauthState)) {
        pendingAuths.delete(oauthState)
        if (mcpName) mcpNameToState.delete(mcpName)
        reject(new Error("OAuth callback timeout - authorization took too long"))
        stopIfIdle()
      }
    }, CALLBACK_TIMEOUT_MS)

    pendingAuths.set(oauthState, { resolve, reject, timeout })
  })
}

export function cancelPending(mcpName: string): void {
  // Look up the oauthState for this mcpName via the reverse index
  const oauthState = mcpNameToState.get(mcpName)
  const key = oauthState ?? mcpName
  const pending = pendingAuths.get(key)
  if (pending) {
    clearTimeout(pending.timeout)
    pendingAuths.delete(key)
    mcpNameToState.delete(mcpName)
    pending.reject(new Error("Authorization cancelled"))
    stopIfIdle()
  }
}

export async function isPortInUse(port: number = OAUTH_CALLBACK_PORT): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = createConnection(port, "127.0.0.1")
    socket.on("connect", () => {
      socket.destroy()
      resolve(true)
    })
    socket.on("error", () => {
      resolve(false)
    })
  })
}

export async function stop(): Promise<void> {
  if (server) {
    await new Promise<void>((resolve) => server!.close(() => resolve()))
    server = undefined
  }

  for (const [_name, pending] of pendingAuths) {
    clearTimeout(pending.timeout)
    pending.reject(new Error("OAuth callback server stopped"))
  }
  pendingAuths.clear()
  mcpNameToState.clear()
}

export function isRunning(): boolean {
  return server !== undefined
}

export * as McpOAuthCallback from "./oauth-callback"

import { LayerNode } from "../effect/layer-node"
import path from "path"
import { serviceUse } from "../effect/service-use"
import { Global } from "../global"
import { Effect, Layer, Context, Option, Schema } from "effect"
import { FSUtil } from "../fs-util"
import { EffectFlock } from "../util/effect-flock"
import { CredentialCipher } from "../credential/cipher"

export const Tokens = Schema.Struct({
  accessToken: Schema.mutableKey(Schema.String),
  refreshToken: Schema.mutableKey(Schema.optional(Schema.String)),
  expiresAt: Schema.mutableKey(Schema.optional(Schema.Number)),
  scope: Schema.mutableKey(Schema.optional(Schema.String)),
})
export type Tokens = Schema.Schema.Type<typeof Tokens>

export const ClientInfo = Schema.Struct({
  clientId: Schema.mutableKey(Schema.String),
  clientSecret: Schema.mutableKey(Schema.optional(Schema.String)),
  clientIdIssuedAt: Schema.mutableKey(Schema.optional(Schema.Number)),
  clientSecretExpiresAt: Schema.mutableKey(Schema.optional(Schema.Number)),
})
export type ClientInfo = Schema.Schema.Type<typeof ClientInfo>

export const Entry = Schema.Struct({
  tokens: Schema.mutableKey(Schema.optional(Tokens)),
  clientInfo: Schema.mutableKey(Schema.optional(ClientInfo)),
  codeVerifier: Schema.mutableKey(Schema.optional(Schema.String)),
  oauthState: Schema.mutableKey(Schema.optional(Schema.String)),
  serverUrl: Schema.mutableKey(Schema.optional(Schema.String)),
})
export type Entry = Schema.Schema.Type<typeof Entry>

const decodeAuthData = Schema.decodeUnknownOption(Schema.Record(Schema.String, Entry))
const decodeAuthJson = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Record(Schema.String, Entry)))
type AuthData = Record<string, Entry>

/** The auth file is sealed under a key this process could not load. */
class LockedError extends Schema.TaggedErrorClass<LockedError>()("McpAuthLockedError", {}) {}

const filepath = path.join(Global.Path.data, "mcp-auth.json")
const lockKey = `mcp-auth:${filepath}`

export interface Interface {
  readonly all: () => Effect.Effect<Record<string, Entry>>
  readonly get: (mcpName: string) => Effect.Effect<Entry | undefined>
  readonly getForUrl: (mcpName: string, serverUrl: string) => Effect.Effect<Entry | undefined>
  readonly set: (mcpName: string, entry: Entry, serverUrl?: string) => Effect.Effect<void>
  readonly remove: (mcpName: string) => Effect.Effect<void>
  readonly updateTokens: (mcpName: string, tokens: Tokens, serverUrl?: string) => Effect.Effect<void>
  readonly updateClientInfo: (mcpName: string, clientInfo: ClientInfo, serverUrl?: string) => Effect.Effect<void>
  readonly updateCodeVerifier: (mcpName: string, codeVerifier: string) => Effect.Effect<void>
  readonly clearCodeVerifier: (mcpName: string) => Effect.Effect<void>
  readonly updateOAuthState: (mcpName: string, oauthState: string) => Effect.Effect<void>
  readonly getOAuthState: (mcpName: string) => Effect.Effect<string | undefined>
  readonly clearOAuthState: (mcpName: string) => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("@orchestra/McpAuth") {}

export const use = serviceUse(Service)

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* FSUtil.Service
    const flock = yield* EffectFlock.Service
    const cipher = yield* CredentialCipher.Service

    const write = (data: AuthData) => fs.writeJson(filepath, cipher.seal(JSON.stringify(data)), 0o600)

    // The file holds one sealed JSON string; a plain object is a file written before encryption, which is read and
    // sealed in place. A file that cannot be parsed or decodes to the wrong shape is moved aside, never overwritten,
    // so a later write cannot wipe every MCP login. A sealed file no loaded key opens (the keychain prompt was declined
    // or timed out, so this process fell back to the key file) is left in place and the read fails, so no write
    // replaces it. Any other read failure stops here instead of reading as empty.
    const read = Effect.fn("McpAuth.read")(function* () {
      const file = yield* fs.readJson(filepath).pipe(
        Effect.map((json) => {
          if (typeof json !== "string") return { legacy: true, locked: false, data: decodeAuthData(json) }
          const plain = CredentialCipher.isSealed(json) ? cipher.open(json) : undefined
          return {
            legacy: false,
            locked: CredentialCipher.isSealed(json) && plain === undefined,
            data: Option.flatMap(Option.fromUndefinedOr(plain), decodeAuthJson),
          }
        }),
        Effect.catchReason("PlatformError", "NotFound", () =>
          Effect.succeed({ legacy: false, locked: false, data: Option.some<AuthData>({}) }),
        ),
        Effect.catchTag("FileSystemError", () =>
          Effect.succeed({ legacy: false, locked: false, data: Option.none<AuthData>() }),
        ),
      )
      if (file.locked) {
        yield* Effect.logError(
          "mcp-auth.json is encrypted with a key this process could not load; it is left untouched. Restart Orchestra and allow the keychain prompt",
          { path: filepath },
        )
        return yield* new LockedError()
      }
      if (Option.isNone(file.data)) {
        const aside = `${filepath}.corrupt-${Date.now()}`
        yield* fs.rename(filepath, aside)
        yield* Effect.logError("mcp-auth.json could not be read and was moved aside; MCP servers need a new login", {
          path: aside,
        })
        return {} as AuthData
      }
      const data: AuthData = { ...file.data.value }
      if (file.legacy) yield* write(data)
      return data
    })

    const all = Effect.fn("McpAuth.all")(function* () {
      // A locked file reads as no logins; writes still fail, so the file is never replaced.
      return yield* read().pipe(
        Effect.catchTag("McpAuthLockedError", () => Effect.succeed({} as AuthData)),
        flock.withLock(lockKey),
        Effect.orDie,
      )
    })

    const mutate = Effect.fn("McpAuth.mutate")(function* (update: (data: AuthData) => AuthData | undefined) {
      yield* Effect.gen(function* () {
        const next = update(yield* read())
        if (!next) return
        yield* write(next).pipe(Effect.orDie)
      }).pipe(flock.withLock(lockKey), Effect.orDie)
    })

    const get = Effect.fn("McpAuth.get")(function* (mcpName: string) {
      const data = yield* all()
      return data[mcpName]
    })

    const getForUrl = Effect.fn("McpAuth.getForUrl")(function* (mcpName: string, serverUrl: string) {
      const entry = yield* get(mcpName)
      if (!entry) return undefined
      if (!entry.serverUrl) return undefined
      if (entry.serverUrl !== serverUrl) return undefined
      return entry
    })

    const set = Effect.fn("McpAuth.set")(function* (mcpName: string, entry: Entry, serverUrl?: string) {
      yield* mutate((data) => ({
        ...data,
        [mcpName]: serverUrl ? { ...entry, serverUrl } : entry,
      }))
    })

    const remove = Effect.fn("McpAuth.remove")(function* (mcpName: string) {
      yield* mutate((data) => {
        const next = { ...data }
        delete next[mcpName]
        return next
      })
    })

    const updateField = <K extends keyof Entry>(field: K, spanName: string) =>
      Effect.fn(`McpAuth.${spanName}`)(function* (mcpName: string, value: NonNullable<Entry[K]>, serverUrl?: string) {
        yield* mutate((data) => {
          const entry = data[mcpName] ?? {}
          entry[field] = value
          if (serverUrl) entry.serverUrl = serverUrl
          return { ...data, [mcpName]: entry }
        })
      })

    const clearField = (field: keyof Entry, spanName: string) =>
      Effect.fn(`McpAuth.${spanName}`)(function* (mcpName: string) {
        yield* mutate((data) => {
          const entry = data[mcpName]
          if (!entry) return undefined
          delete entry[field]
          return { ...data, [mcpName]: entry }
        })
      })

    const updateTokens = updateField("tokens", "updateTokens")
    const updateClientInfo = updateField("clientInfo", "updateClientInfo")
    const updateCodeVerifier = updateField("codeVerifier", "updateCodeVerifier")
    const updateOAuthState = updateField("oauthState", "updateOAuthState")
    const clearCodeVerifier = clearField("codeVerifier", "clearCodeVerifier")
    const clearOAuthState = clearField("oauthState", "clearOAuthState")

    const getOAuthState = Effect.fn("McpAuth.getOAuthState")(function* (mcpName: string) {
      const entry = yield* get(mcpName)
      return entry?.oauthState
    })

    return Service.of({
      all,
      get,
      getForUrl,
      set,
      remove,
      updateTokens,
      updateClientInfo,
      updateCodeVerifier,
      clearCodeVerifier,
      updateOAuthState,
      getOAuthState,
      clearOAuthState,
    })
  }),
)

export const node = LayerNode.make({ service: Service, layer: layer, deps: [FSUtil.node, EffectFlock.node, CredentialCipher.node] })

export * as McpAuth from "./auth"

export * as McpProjectConfig from "./project-config"

import path from "path"
import { Effect, Schema } from "effect"
import type { ConfigMCP } from "@orchestra/schema/config-mcp"
import { KeyedMutex } from "../effect/keyed-mutex"
import { applyEdits, modify, parse, parseTree, type ParseError, printParseErrorCode } from "jsonc-parser"
import { FSUtil } from "../fs-util"

/** A profile config file that cannot be read, parsed, or written as asked. */
export class FileError extends Schema.TaggedErrorClass<FileError>()("McpProjectConfig.FileError", {
  file: Schema.String,
  message: Schema.String,
}) {}

/** The fields the MCP page edits, exactly as written in the file (`{env:...}` stays unresolved). */
export const Entry = Schema.Struct({
  type: Schema.optional(Schema.Literals(["local", "remote"])),
  command: Schema.optional(Schema.Array(Schema.String)),
  url: Schema.optional(Schema.String),
})
export type Entry = Schema.Schema.Type<typeof Entry>

/** One server as `write` stores it: the shape `orchestra mcp add` writes, which V2 config reads through its legacy migration. */
export type Written = { readonly type: "local" | "remote"; readonly [key: string]: unknown }

type Document = { file: string; text?: string; value?: unknown; errors: readonly ParseError[] }

const format = { formattingOptions: { tabSize: 2, insertSpaces: true } }
// Keys that only make sense for one transport; switching transport drops the other side's keys.
const exclusive = {
  local: ["command", "cwd", "environment"],
  remote: ["url", "headers", "oauth"],
} as const
// One writer per profile directory; a directory's lock is dropped once no writer holds or waits for it.
export const writers = KeyedMutex.makeUnsafe<string>()

// The profile-scoped files `orchestra mcp add` writes, in load order (a later file wins).
export function files(directory: string) {
  return [
    path.join(directory, "orchestra.json"),
    path.join(directory, "orchestra.jsonc"),
    path.join(directory, ".orchestra", "orchestra.json"),
    path.join(directory, ".orchestra", "orchestra.jsonc"),
  ]
}

// Names become JSON keys and URL path segments.
export function validName(name: string) {
  return name.trim() !== "" && name !== "." && name !== ".." && name !== "__proto__" && !/[/\\\p{Cc}]/u.test(name)
}

/** Servers defined in the profile's own files, with the raw fields of the file that wins. */
export const entries = Effect.fn("McpProjectConfig.entries")(function* (directory: string) {
  return Object.fromEntries(
    (yield* read(directory))
      .filter((document) => document.errors.length === 0)
      .flatMap((document) => Object.entries(servers(document)).map(([name, value]) => [name, select(value)] as const)),
  )
})

/**
 * Creates or updates one MCP server in the profile's own config file. Only the given fields are
 * written, so values the dialog does not edit (environment, headers, `{env:...}` references,
 * comments) stay exactly as the owner wrote them. Returns the file that was written.
 */
export const write = Effect.fn("McpProjectConfig.write")(function* (
  directory: string,
  name: string,
  config: Written,
) {
  return yield* exclusiveTo(
    directory,
    Effect.gen(function* () {
      const documents = yield* read(directory)
      const ambiguity = documents.map((document) => duplicateError(document, name)).find((error) => error !== undefined)
      if (ambiguity) return yield* ambiguity
      const target =
        documents.findLast((document) => Object.hasOwn(servers(document), name)) ??
        documents.find((document) => document.text !== undefined) ??
        documents[0]
      yield* editable(target, name)
      const current = servers(target)[name]
      // jsonc-parser cannot delete a missing path, so only drop keys the entry really has.
      const stale = exclusive[config.type === "local" ? "remote" : "local"].filter(
        (key) => isRecord(current) && Object.hasOwn(current, key),
      )
      const text = [
        ...stale.map((key) => [key, undefined] as const),
        ...Object.entries(config).map(([key, value]) => [key, value] as const),
      ].reduce(
        (result, [key, value]) => applyEdits(result, modify(result, ["mcp", name, key], value, format)),
        target.text ?? "{}",
      )
      yield* save(target.file, text)
      return target.file
    }),
  )
})

// Removes the server from every profile file that defines it; returns the files that changed.
export const remove = Effect.fn("McpProjectConfig.remove")(function* (directory: string, name: string) {
  return yield* exclusiveTo(
    directory,
    Effect.gen(function* () {
      const documents = yield* read(directory)
      const ambiguity = documents.map((document) => duplicateError(document, name)).find((error) => error !== undefined)
      if (ambiguity) return yield* ambiguity
      const defining = documents.filter((document) => Object.hasOwn(servers(document), name))
      yield* Effect.forEach(defining, (document) => editable(document, name))
      yield* Effect.forEach(defining, (document) =>
        save(
          document.file,
          applyEdits(document.text ?? "", modify(document.text ?? "", ["mcp", name], undefined, format)),
        ),
      )
      return defining.map((document) => document.file)
    }),
  )
})

// One writer per profile directory so concurrent saves cannot interleave read-modify-write.
function exclusiveTo<A, E, R>(directory: string, effect: Effect.Effect<A, E, R>) {
  return writers.withLock(path.resolve(directory))(effect)
}

const read = Effect.fnUntraced(function* (directory: string) {
  const fs = yield* FSUtil.Service
  return yield* Effect.forEach(files(directory), (file) =>
    fs.readFileStringSafe(file).pipe(
      Effect.mapError(() => new FileError({ file, message: `Could not read ${file}` })),
      Effect.map((text): Document => {
        if (text === undefined) return { file, errors: [] }
        const errors: ParseError[] = []
        return { file, text, value: parse(text, errors, { allowTrailingComma: true }), errors }
      }),
    ),
  )
})

// Atomic replace next to the real file, so a symlinked config keeps its link.
const save = Effect.fnUntraced(function* (file: string, text: string) {
  const fs = yield* FSUtil.Service
  const real = yield* fs.realPath(file).pipe(Effect.orElseSucceed(() => file))
  const temp = `${real}.${process.pid}-${Date.now()}.tmp`
  yield* Effect.gen(function* () {
    yield* fs.ensureDir(path.dirname(real))
    yield* fs.writeFileString(temp, text)
    yield* fs.rename(temp, real)
  }).pipe(
    Effect.tapError(() => fs.remove(temp).pipe(Effect.ignore)),
    Effect.mapError(
      (error) =>
        new FileError({
          file,
          message:
            "reason" in error && error.reason._tag === "PermissionDenied"
              ? `Permission denied writing ${file}`
              : `Could not write ${file}`,
        }),
    ),
  )
})

// modify() chooses the first matching property, while parse() loads the last. Refuse ambiguous
// mutation paths before any file changes; parsed key values also catch JSON-escaped duplicates.
function duplicateError(document: Document, name: string) {
  let node = document.text === undefined ? undefined : parseTree(document.text, [], { allowTrailingComma: true })
  for (const key of ["mcp", name]) {
    const properties =
      node?.type === "object" ? (node.children?.filter((property) => property.children?.[0]?.value === key) ?? []) : []
    if (properties.length > 1)
      return new FileError({
        file: document.file,
        message: `Cannot edit duplicate property ${JSON.stringify(key)} in ${document.file}`,
      })
    node = properties[0]?.children?.[1]
  }
  const keys = node?.type === "object" ? (node.children?.map((property) => property.children?.[0]?.value) ?? []) : []
  const duplicate = keys.find((key, index) => keys.indexOf(key) !== index)
  if (duplicate !== undefined)
    return new FileError({
      file: document.file,
      message: `Cannot edit duplicate property ${JSON.stringify(duplicate)} in mcp.${name} in ${document.file}`,
    })
}

function editable(document: Document, name: string) {
  const reason = (() => {
    if (document.errors.length > 0)
      return `${document.file} is not valid JSONC (${printParseErrorCode(document.errors[0].error)} at offset ${document.errors[0].offset})`
    if (document.value === undefined) return
    if (!isRecord(document.value)) return `${document.file} must contain a JSON object`
    if (document.value.mcp !== undefined && !isRecord(document.value.mcp))
      return `"mcp" in ${document.file} must be an object`
    const current = servers(document)[name]
    if (current !== undefined && !isRecord(current)) return `"mcp.${name}" in ${document.file} must be an object`
  })()
  if (reason) return Effect.fail(new FileError({ file: document.file, message: reason }))
  return Effect.void
}

function servers(document: Document): Record<string, unknown> {
  if (!isRecord(document.value) || !isRecord(document.value.mcp)) return {}
  return document.value.mcp
}

function select(value: unknown): Entry {
  if (!isRecord(value)) return {}
  return {
    ...(value.type === "local" || value.type === "remote" ? { type: value.type } : {}),
    ...(Array.isArray(value.command) && value.command.every((part) => typeof part === "string")
      ? { command: value.command }
      : {}),
    ...(typeof value.url === "string" ? { url: value.url } : {}),
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

/** A V2 config server in the shape `write` stores. */
export function written(server: ConfigMCP.Local | ConfigMCP.Remote): Written {
  const enabled = server.disabled === undefined ? {} : { enabled: !server.disabled }
  if (server.type === "local")
    return {
      type: "local",
      command: [...server.command],
      ...(server.cwd === undefined ? {} : { cwd: server.cwd }),
      ...(server.environment === undefined ? {} : { environment: server.environment }),
      ...enabled,
    }
  return {
    type: "remote",
    url: server.url,
    ...(server.headers === undefined ? {} : { headers: server.headers }),
    ...enabled,
  }
}

export * as McpProvided from "./provided"

// MCP servers a product module serves in process, such as one per interface open in the MCP Dock. They come and go
// while the process runs, are never written to config, and connect over a transport the module hands out.

import type { Transport } from "@modelcontextprotocol/sdk/shared/transport.js"
import { Context, Effect, Layer } from "effect"
import { makeGlobalNode } from "../effect/app-node"

export type Server = {
  readonly name: string
  // Changes when the server behind the name changes (a new tab, a reloaded document); a new key reconnects it.
  readonly key: string
  readonly connect: () => Transport
}

export interface Interface {
  /**
   * The servers available now. Asked before every provider turn, so it must answer fast and bound its own waits; a
   * failure keeps the servers of the last answer.
   */
  readonly servers: () => Effect.Effect<ReadonlyArray<Server>, unknown>
}

export class Service extends Context.Service<Service, Interface>()("@orchestra/v2/McpProvided") {}

/** Keeps the last answer of `servers` by name and says which names left and which are new or changed since. */
export function tracker(service: Interface) {
  const current = new Map<string, Server>()
  const update = Effect.fnUntraced(function* () {
    const listed = yield* service.servers().pipe(Effect.orElseSucceed(() => undefined))
    if (!listed) return { gone: [], changed: [] }
    const names = new Set(listed.map((server) => server.name))
    const gone = Array.from(current.keys()).filter((name) => !names.has(name))
    const changed = listed.filter((server) => current.get(server.name)?.key !== server.key)
    for (const name of gone) current.delete(name)
    for (const server of changed) current.set(server.name, server)
    return { gone, changed: changed.map((server) => server.name) }
  })
  return { current, update }
}

export const layer = Layer.succeed(Service, Service.of({ servers: () => Effect.succeed([]) }))

/** A product serves its servers by replacing this node (Host.Contribution.replacements). */
export const node = makeGlobalNode({ service: Service, layer, deps: [] })

export * as SkillDiscovery from "./discovery"

import path from "path"
import { Context, Effect, Layer, Schedule, Schema } from "effect"
import { FetchHttpClient, HttpClient, HttpClientRequest, HttpClientResponse } from "effect/unstable/http"
import { FSUtil } from "../fs-util"
import { Global } from "../global"
import { makeGlobalNode } from "../effect/app-node"
import { httpClient } from "../effect/app-node-platform"
import { AbsolutePath } from "../schema"

const skillConcurrency = 4
const fileConcurrency = 8

function isSafeSegment(value: string) {
  return (
    value.length > 0 &&
    value !== "." &&
    value !== ".." &&
    !value.includes("/") &&
    !value.includes("\\") &&
    !value.includes("\0")
  )
}

function isSafeRelativePath(value: string) {
  const segments = value.split("/")
  return (
    value.length > 0 &&
    !value.includes("\\") &&
    !value.includes("\0") &&
    !value.includes("?") &&
    !value.includes("#") &&
    !URL.canParse(value) &&
    !path.posix.isAbsolute(value) &&
    !path.win32.isAbsolute(value) &&
    segments.every((segment) => {
      try {
        const decoded = decodeURIComponent(segment)
        return (
          decoded.length > 0 &&
          decoded !== "." &&
          decoded !== ".." &&
          !decoded.includes("/") &&
          !decoded.includes("\\") &&
          !decoded.includes("\0")
        )
      } catch {
        return false
      }
    })
  )
}

class IndexSkill extends Schema.Class<IndexSkill>("SkillDiscovery.IndexSkill")({
  name: Schema.String,
  version: Schema.optional(Schema.String),
  files: Schema.Array(Schema.String),
}) {}

class Index extends Schema.Class<Index>("SkillDiscovery.Index")({
  skills: Schema.Array(IndexSkill),
}) {}

export interface Interface {
  readonly pull: (url: string) => Effect.Effect<AbsolutePath[]>
}

export class Service extends Context.Service<Service, Interface>()("@orchestra/v2/SkillDiscovery") {}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* FSUtil.Service
    const global = yield* Global.Service
    const http = (yield* HttpClient.HttpClient).pipe(
      HttpClient.retryTransient({
        retryOn: "errors-and-responses",
        times: 2,
        schedule: Schedule.exponential(200).pipe(Schedule.jittered),
      }),
      HttpClient.filterStatusOk,
    )

    const download = Effect.fn("SkillDiscovery.download")(function* (url: string, destination: string) {
      if (yield* fs.exists(destination).pipe(Effect.orDie)) return true
      return yield* HttpClientRequest.get(url).pipe(
        http.execute,
        Effect.flatMap((response) => response.arrayBuffer),
        Effect.flatMap((body) => fs.writeWithDirs(destination, new Uint8Array(body))),
        Effect.as(true),
        Effect.catch((error) =>
          Effect.logError("failed to download skill file", { url, error }).pipe(Effect.as(false)),
        ),
      )
    })

    return Service.of({
      pull: Effect.fn("SkillDiscovery.pull")(function* (url) {
        const base = url.endsWith("/") ? url : `${url}/`
        const source = new URL(base)
        const index = new URL("index.json", source).href
        const data = yield* HttpClientRequest.get(index).pipe(
          HttpClientRequest.acceptJson,
          http.execute,
          Effect.flatMap(HttpClientResponse.schemaBodyJson(Index)),
          Effect.catch((error) =>
            Effect.logError("failed to fetch skill index", { url: index, error }).pipe(Effect.as(undefined)),
          ),
        )
        if (!data) return []

        const sourceRoot = path.resolve(global.cache, "skills", Bun.hash(base).toString(16))
        return yield* Effect.forEach(
          data.skills.flatMap((skill) => {
            if (!isSafeSegment(skill.name)) {
              return []
            }
            if (!skill.files.includes("SKILL.md") && !skill.files.includes(`${skill.name}.md`)) {
              return []
            }

            const root = path.resolve(sourceRoot, skill.name)
            if (!FSUtil.contains(sourceRoot, root) || root === sourceRoot) {
              return []
            }

            const skillUrl = new URL(`${encodeURIComponent(skill.name)}/`, source)
            const versionFile = path.join(root, ".orchestra-version")
            const files = skill.files.map((file) => {
              if (!isSafeRelativePath(file)) return undefined
              let resource: URL
              try {
                resource = new URL(file, skillUrl)
              } catch {
                return undefined
              }
              if (resource.origin !== source.origin) return undefined

              const destination = path.resolve(root, file)
              if (!FSUtil.contains(root, destination) || destination === root) return undefined
              return {
                url: resource.href,
                destination,
                file,
              }
            })
            if (files.some((file) => file === undefined)) {
              return []
            }
            return [{ skill, root, versionFile, files: files as { url: string; destination: string; file: string }[] }]
          }),
          ({ skill, root, versionFile, files }) =>
            Effect.gen(function* () {
              const version = skill.version
              const current =
                version === undefined
                  ? undefined
                  : yield* fs.readFileStringSafe(versionFile).pipe(Effect.catch(() => Effect.succeed(undefined)))
              if (version === undefined || current === version) {
                yield* Effect.forEach(files, (file) => download(file.url, file.destination), {
                  concurrency: fileConcurrency,
                  discard: true,
                })
              } else {
                const token = crypto.randomUUID()
                const staging = `${root}.tmp-${token}`
                const backup = `${root}.old-${token}`
                yield* Effect.gen(function* () {
                  const downloaded = yield* Effect.forEach(
                    files,
                    (file) => download(file.url, path.resolve(staging, file.file)),
                    { concurrency: fileConcurrency },
                  )
                  if (!downloaded.every(Boolean)) return
                  const exists =
                    (yield* fs.exists(path.join(staging, "SKILL.md")).pipe(Effect.orDie)) ||
                    (yield* fs.exists(path.join(staging, `${skill.name}.md`)).pipe(Effect.orDie))
                  if (!exists) return
                  yield* fs.writeFileString(path.join(staging, ".orchestra-version"), version)
                  yield* Effect.uninterruptible(
                    Effect.gen(function* () {
                      const cached = yield* fs.exists(root).pipe(Effect.orDie)
                      if (cached) yield* fs.rename(root, backup)
                      yield* fs.rename(staging, root).pipe(
                        Effect.catch((error) =>
                          Effect.gen(function* () {
                            if (cached) yield* fs.rename(backup, root).pipe(Effect.ignore)
                            return yield* Effect.fail(error)
                          }),
                        ),
                      )
                      if (cached) yield* fs.remove(backup, { recursive: true, force: true }).pipe(Effect.ignore)
                    }),
                  )
                }).pipe(
                  Effect.catch((error) => Effect.logError("failed to refresh skill", { skill: skill.name, error })),
                  Effect.ensuring(fs.remove(staging, { recursive: true, force: true }).pipe(Effect.ignore)),
                )
              }
              const exists =
                (yield* fs.exists(path.join(root, "SKILL.md")).pipe(Effect.orDie)) ||
                (yield* fs.exists(path.join(root, `${skill.name}.md`)).pipe(Effect.orDie))
              return exists ? [AbsolutePath.make(root)] : []
            }),
          { concurrency: skillConcurrency },
        ).pipe(Effect.map((directories) => directories.flat()))
      }),
    })
  }),
)

export const node = makeGlobalNode({ service: Service, layer, deps: [httpClient, FSUtil.node, Global.node] })

export * as SkillFile from "./file"

import path from "path"
import { rmdir } from "fs/promises"
import matter from "gray-matter"
import { Effect, Option, Schema } from "effect"
import { ConfigMarkdown } from "../config/markdown"
import { FSUtil } from "../fs-util"

// New names become directory names and skill tool arguments, so they follow the Agent Skills naming rule.
const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
const NAME_LIMIT = 64
// The project's own skill folders that orchestra reads. Global, configured-path and URL skills stay read-only.
const PROJECT_ROOTS = [".orchestra/skills", ".orchestra/skill", ".claude/skills", ".agents/skills"]
// Atlas owns these skills and verifies them by name; editing them here would bypass that governance.
const GOVERNED_ROOT = ".orchestra/skills/own"

export class WriteError extends Schema.TaggedErrorClass<WriteError>()("SkillWriteError", {
  reason: Schema.Literals(["invalid", "missing", "readonly", "conflict"]),
  message: Schema.String,
}) {}

export type Registered = { readonly name: string; readonly location: string }

export interface SaveInput {
  readonly name: string
  readonly description: string
  readonly content: string
  /** Existing registered skill file to rewrite. Omit to create a project skill. */
  readonly location?: string
  /** Modification time (ms) the caller read; a different time on disk fails with a conflict. */
  readonly mtime?: number
}

export interface Saved {
  readonly name: string
  readonly description: string
  readonly location: string
  readonly content: string
  readonly mtime?: number
}

/** Last modification time in whole milliseconds, the token `SaveInput.mtime` is compared against. */
export const modified = Effect.fn("SkillFile.modified")(function* (file: string) {
  const fs = yield* FSUtil.Service
  const info = yield* fs.stat(file).pipe(Effect.option)
  return Option.getOrUndefined(Option.flatMap(info, (item) => item.mtime))?.getTime()
})

/**
 * Creates `<directory>/.orchestra/skills/<name>/SKILL.md`, or rewrites a registered project skill file in place.
 * Edits keep the other front-matter keys, but the front matter is re-serialized as YAML, so comments and
 * formatting inside it are not preserved. Files are written to a temporary sibling and then linked (create)
 * or renamed (edit) into place, so readers never see a partial file and a symlink at the target is not followed.
 */
export const save = Effect.fn("SkillFile.save")(function* (input: {
  directory: string
  registered: readonly Registered[]
  skill: SaveInput
}) {
  const fs = yield* FSUtil.Service
  const name = input.skill.name.trim()
  const description = input.skill.description.trim()
  const current =
    input.skill.location === undefined
      ? undefined
      : yield* requireFile(input.directory, input.registered, input.skill.location)
  if (!name || name.length > NAME_LIMIT || (name !== current?.name && !NAME.test(name)))
    return yield* new WriteError({
      reason: "invalid",
      message: `Skill names use up to ${NAME_LIMIT} lowercase letters, numbers and single hyphens.`,
    })
  if (!description) return yield* new WriteError({ reason: "invalid", message: "A skill needs a description." })
  if (input.registered.some((skill) => skill.name === name && skill.location !== current?.location))
    return yield* new WriteError({ reason: "conflict", message: `A skill named ${name} is already registered.` })
  if (current && input.skill.mtime !== undefined && (yield* modified(current.location)) !== input.skill.mtime)
    return yield* new WriteError({
      reason: "conflict",
      message: `${current.name} changed on disk after it was read. Reopen it and try again.`,
    })

  const location = current?.location ?? path.join(input.directory, ".orchestra", "skills", name, "SKILL.md")
  if (!current) yield* requireLexical(input.directory, location)
  const existing = current ? yield* fs.readFileStringSafe(location).pipe(Effect.orDie) : undefined
  const data = existing === undefined ? {} : ConfigMarkdown.parseOption(existing)?.data
  const body = input.skill.content.endsWith("\n") ? input.skill.content : `${input.skill.content}\n`
  // The object form keeps a body that itself starts with `---` from being parsed as front matter.
  const text = matter.stringify({ content: body }, { ...data, name, description })
  const folder = path.dirname(location)
  yield* fs.makeDirectory(folder, { recursive: true }).pipe(Effect.orDie)
  const temp = path.join(folder, `.${path.basename(location)}.${crypto.randomUUID()}.tmp`)
  yield* Effect.acquireUseRelease(
    fs.writeFileString(temp, text, { flag: "wx" }).pipe(Effect.orDie),
    () =>
      current
        ? fs.rename(temp, location).pipe(Effect.orDie)
        : fs.link(temp, location).pipe(
            Effect.catchReason("PlatformError", "AlreadyExists", () =>
              Effect.fail(new WriteError({ reason: "conflict", message: `${location} already exists.` })),
            ),
            Effect.catchTag("PlatformError", (error) => Effect.die(error)),
          ),
    () => fs.remove(temp).pipe(Effect.ignore),
  )
  return {
    name,
    description,
    location,
    content: ConfigMarkdown.parse(text).content,
    mtime: yield* modified(location),
  } satisfies Saved
})

/** Deletes a registered project skill file, then its folder when nothing else is left in it. */
export const remove = Effect.fn("SkillFile.remove")(function* (input: {
  directory: string
  registered: readonly Registered[]
  location: string
}) {
  const fs = yield* FSUtil.Service
  const skill = yield* requireFile(input.directory, input.registered, input.location)
  yield* fs.remove(skill.location).pipe(Effect.orDie)
  if (path.basename(skill.location) !== "SKILL.md") return skill
  // rmdir without recursion refuses a folder that still holds references or scripts.
  yield* Effect.tryPromise({ try: () => rmdir(path.dirname(skill.location)), catch: (error) => error }).pipe(
    Effect.catch((error) =>
      error instanceof Error && "code" in error && (error.code === "ENOTEMPTY" || error.code === "EEXIST")
        ? Effect.void
        : Effect.die(error),
    ),
  )
  return skill
})

// Only project skill files the catalog currently registers may change, so the API cannot reach other paths.
const requireFile = Effect.fnUntraced(function* (
  directory: string,
  registered: readonly Registered[],
  location: string,
) {
  const fs = yield* FSUtil.Service
  const skill = registered.find((item) => item.location === location)
  if (!skill) return yield* new WriteError({ reason: "missing", message: `${location} is not a registered skill.` })
  if (!path.isAbsolute(location) || location.startsWith("/builtin/"))
    return yield* new WriteError({ reason: "readonly", message: `${skill.name} is built in and cannot be changed.` })
  const relative = path.relative(directory, location).replaceAll("\\", "/")
  if (relative === GOVERNED_ROOT || relative.startsWith(`${GOVERNED_ROOT}/`))
    return yield* new WriteError({
      reason: "readonly",
      message: `${skill.name} is governed by Atlas and is read-only.`,
    })
  if (path.extname(location) !== ".md" || !PROJECT_ROOTS.some((root) => relative.startsWith(`${root}/`)))
    return yield* new WriteError({
      reason: "readonly",
      message: `${skill.name} is outside this project's skill folders and is read-only here.`,
    })
  if (!(yield* fs.isFile(location)))
    return yield* new WriteError({ reason: "missing", message: `${location} no longer exists on disk.` })
  yield* requireLexical(directory, location)
  return skill
})

// Refuses targets whose nearest existing path resolves elsewhere, so a symlinked folder or file cannot redirect a
// write or delete outside the project. A symlinked project root itself is fine.
const requireLexical = Effect.fnUntraced(function* (directory: string, location: string) {
  const fs = yield* FSUtil.Service
  const root = yield* fs.realPath(directory).pipe(Effect.orDie)
  const existing = yield* nearestExisting(location)
  const real = yield* fs.realPath(existing).pipe(Effect.orDie)
  if (real === path.join(root, path.relative(directory, existing))) return
  return yield* new WriteError({
    reason: "readonly",
    message: `${location} resolves through a symbolic link and cannot be changed.`,
  })
})

const nearestExisting = Effect.fnUntraced(function* (location: string) {
  const fs = yield* FSUtil.Service
  for (const item of ancestors(location)) if (yield* fs.existsSafe(item)) return item
  return path.parse(location).root
})

function ancestors(location: string): string[] {
  const parent = path.dirname(location)
  return parent === location ? [location] : [location, ...ancestors(parent)]
}

export * as PackagedSkills from "./packaged-skills"

import { createHash } from "node:crypto"
import fs from "node:fs/promises"
import path from "node:path"

declare const ORCHESTRA_PACKAGED_SKILLS: unknown

export type Trees = Readonly<Record<string, Readonly<Record<string, string>>>>

export class PackagingError extends Error {
  override name = "PackagedSkillsError"
}

/** Undefined only in source execution. A defined but empty/malformed build must fail. */
export function embedded(): unknown {
  return typeof ORCHESTRA_PACKAGED_SKILLS === "undefined" ? undefined : ORCHESTRA_PACKAGED_SKILLS
}

/** SHA-256 of sorted combined relative paths and their exact UTF-8 content hashes. */
export function digest(trees: unknown) {
  return treeDigest(validate(trees))
}

/**
 * Stable, user-owned cooperative namespace: the mkdir lock serializes cooperating writers.
 * This does not claim immunity to a hostile writer replacing paths during filesystem operations.
 * Old versions are immutable and retained; only our own stage and lock are cleaned up.
 */
export async function materialize(input: {
  cache: string
  version: string
  trees?: unknown
  lockTimeoutMs?: number
}) {
  const trees = input.trees === undefined ? embedded() : input.trees
  if (trees === undefined) return []
  const files = validate(trees)
  const version = input.version.replace(/[^A-Za-z0-9._-]/g, "-")
  if (!version || !/[A-Za-z0-9]/.test(version)) throw new PackagingError("Invalid packaged skill version")
  const timeout = input.lockTimeoutMs ?? 10_000
  if (!Number.isFinite(timeout) || timeout < 0) throw new PackagingError("Invalid packaged skill lock timeout")
  await fs.mkdir(input.cache, { recursive: true })
  const namespace = path.join(await fs.realpath(input.cache), "packaged-skills")
  await fs.mkdir(namespace).catch((cause: unknown) => {
    if (!hasCode(cause, "EEXIST")) throw cause
  })
  await requireDirectory(namespace)
  const target = path.join(
    namespace,
    `${version.slice(0, 60)}-${createHash("sha256").update(input.version, "utf8").digest("hex")}-${treeDigest(files)}`,
  )
  // Published trees are immutable: verified readers need not wait for a writer's leftover lock.
  if (await stat(target)) {
    await verify(target, files)
    return roots(await fs.realpath(target), files)
  }
  const lock = `${target}.lock`
  await acquire(lock, timeout)
  const stage: { path?: string } = {}
  try {
    if (await stat(target)) {
      await verify(target, files)
      return roots(await fs.realpath(target), files)
    }
    stage.path = await fs.mkdtemp(`${target}.stage-`)
    // Sequential writes keep cleanup from racing writes still in flight after a failure.
    for (const file of files) {
      const destination = path.join(stage.path, ...file.path.split("/"))
      await fs.mkdir(path.dirname(destination), { recursive: true })
      await fs.writeFile(destination, file.text, { encoding: "utf8", flag: "wx" })
    }
    await verify(stage.path, files)
    // Refuse an unexpected destination rather than letting rename replace it.
    if (await stat(target)) throw new PackagingError(`Packaged skill destination appeared: ${target}`)
    await fs.rename(stage.path, target)
    stage.path = undefined
    await verify(target, files)
    return roots(await fs.realpath(target), files)
  } finally {
    try {
      if (stage.path) await fs.rm(stage.path, { recursive: true, force: true })
    } finally {
      await fs.rmdir(lock)
    }
  }
}

function validate(trees: unknown) {
  if (!record(trees) || Object.keys(trees).length === 0) throw new PackagingError("Empty or invalid packaged skill trees")
  const files = Object.entries(trees).flatMap(([id, tree]) => {
    if (!/^[a-z]+(?:-[a-z]+)*$/.test(id) || !safeSegment(id) || !record(tree) || Object.keys(tree).length === 0)
      throw new PackagingError(`Invalid packaged skill seat: ${id}`)
    const entries = Object.entries(tree).map(([file, text]) => {
      if (!file.split("/").every(safeSegment)) throw new PackagingError(`Invalid packaged skill path: ${id}/${file}`)
      if (typeof text !== "string" || Buffer.from(text, "utf8").toString("utf8") !== text)
        throw new PackagingError(`Invalid packaged skill UTF-8 text: ${id}/${file}`)
      if (path.posix.basename(file) === "SKILL.md" && !text.trim())
        throw new PackagingError(`Empty packaged SKILL.md: ${id}/${file}`)
      return { path: `${id}/${file}`, text }
    })
    if (!entries.some((file) => path.posix.basename(file.path) === "SKILL.md"))
      throw new PackagingError(`Missing packaged SKILL.md: ${id}`)
    return entries
  }).toSorted((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0)
  const names = new Map<string, string>()
  const directories = new Set<string>()
  files.forEach((file) => {
    file.path.split("/").forEach((_, index, parts) => {
      const name = parts.slice(0, index + 1).join("/")
      const previous = names.get(name.toLowerCase())
      if (previous !== undefined && previous !== name) throw new PackagingError(`Aliased packaged skill path: ${name}`)
      names.set(name.toLowerCase(), name)
      if (index < parts.length - 1) directories.add(name)
    })
  })
  if (files.some((file) => directories.has(file.path))) throw new PackagingError("Packaged skill file/directory conflict")
  return files
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null)
}

function safeSegment(value: string) {
  return /^[A-Za-z0-9._-]+$/.test(value) && value !== "." && value !== ".." && !value.endsWith(".") &&
    !/^(con|prn|aux|nul|com[0-9]|lpt[0-9])(?:\.|$)/i.test(value)
}

function treeDigest(files: readonly { path: string; text: string }[]) {
  const hash = createHash("sha256")
  files.forEach((file) => hash.update(`${file.path}\0${createHash("sha256").update(file.text, "utf8").digest("hex")}\n`))
  return hash.digest("hex")
}

function roots(target: string, files: readonly { path: string }[]) {
  return [...new Set(files.map((file) => file.path.split("/")[0]))].map((id) => path.join(target, id))
}

function hasCode(cause: unknown, code: string) {
  return cause !== null && typeof cause === "object" && "code" in cause && cause.code === code
}

async function stat(file: string) {
  return fs.lstat(file).catch((cause: unknown) => {
    if (hasCode(cause, "ENOENT")) return undefined
    throw cause
  })
}

async function requireDirectory(directory: string) {
  const info = await fs.lstat(directory)
  if (!info.isDirectory() || info.isSymbolicLink()) throw new PackagingError(`Invalid packaged skill directory: ${directory}`)
}

async function acquire(lock: string, timeout: number) {
  const deadline = Date.now() + timeout
  for (;;) {
    const acquired = await fs.mkdir(lock).then(() => true, (cause: unknown) => {
      if (hasCode(cause, "EEXIST")) return false
      // Windows fails mkdir with EPERM while another starter's lock is pending delete.
      if (process.platform === "win32" && hasCode(cause, "EPERM")) return false
      throw cause
    })
    if (acquired) return
    // Its owner may release between our failed mkdir and lstat; disappearance means retry.
    const info = await stat(lock)
    if (info && (!info.isDirectory() || info.isSymbolicLink()))
      throw new PackagingError(`Invalid packaged skill lock: ${lock}`)
    if (Date.now() >= deadline) throw new PackagingError(`Timed out waiting for packaged skill lock: ${lock}`)
    await new Promise((resolve) => setTimeout(resolve, Math.min(25, Math.max(1, deadline - Date.now()))))
  }
}

async function verify(root: string, files: readonly { path: string; text: string }[]) {
  const expected = new Map(files.map((file) => [file.path, Buffer.from(file.text, "utf8")]))
  const directories = new Set(files.flatMap((file) => file.path.split("/").slice(0, -1)
    .map((_, index) => file.path.split("/").slice(0, index + 1).join("/"))))
  const seen = new Set<string>()
  const visit = async (directory: string, relative: string): Promise<void> => {
    await requireDirectory(directory)
    for (const name of await fs.readdir(directory)) {
      const file = relative ? `${relative}/${name}` : name
      const target = path.join(directory, name)
      const info = await fs.lstat(target)
      if (info.isSymbolicLink()) throw new PackagingError(`Symlink in packaged skill tree: ${file}`)
      if (info.isDirectory()) {
        if (!directories.delete(file)) throw new PackagingError(`Unexpected packaged skill directory: ${file}`)
        await visit(target, file)
        continue
      }
      if (!info.isFile() || info.nlink !== 1) throw new PackagingError(`Non-regular or hardlinked packaged skill file: ${file}`)
      const bytes = expected.get(file)
      if (!bytes || !(await fs.readFile(target)).equals(bytes)) throw new PackagingError(`Packaged skill bytes differ: ${file}`)
      seen.add(file)
    }
  }
  await visit(root, "")
  if (seen.size !== expected.size || directories.size > 0) throw new PackagingError(`Incomplete packaged skill tree: ${root}`)
}

export * as CapabilityChildren from "./children"

import { Capability } from "@orchestra/schema/capability"
import { SessionEvent } from "@orchestra/schema/session-event"
import { and, eq, or } from "drizzle-orm"
import { EffectDrizzleQueryError } from "drizzle-orm/effect-core/errors"
import { Cause, DateTime, Effect, Exit, Schema } from "effect"
import { SqlError } from "effect/unstable/sql/SqlError"
import { AgentV2 } from "../agent"
import { Database } from "../database/database"
import { EventV2 } from "../event"
import { Location } from "../location"
import type { ToolOutputStore } from "../tool-output-store"
import type { ToolRegistry } from "../tool/registry"
import type { Tool } from "../tool/tool"
import { CapabilityVendorSchema } from "./catalog/schema"
import { CapabilityInvocation } from "./invocation"
import { CapabilityPolicy } from "./policy"
import { CapabilityChildTable } from "./sql"

export type Dispatcher = {
  readonly settle: (name: string, input: Schema.Json) => Effect.Effect<
    ToolRegistry.Settlement, Capability.Failure | ToolOutputStore.Error
  >
}

export const make = Effect.gen(function* () {
  const location = yield* Location.Service
  const database = yield* Database.Service
  const agents = yield* AgentV2.Service
  const policy = yield* CapabilityPolicy.make
  const events = yield* EventV2.Service

  const dispatcher = Effect.fn("CapabilityChildren.dispatcher")(function* (
    supplied: Tool.Context,
    materialization: ToolRegistry.Materialization,
  ): Effect.fn.Return<Dispatcher, Capability.Failure> {
    const context = Object.freeze({ ...supplied })
    const binding = yield* policy.binding(context)
    const counter = { ordinal: 0 }

    const observe = (proof: CapabilityInvocation.ChildProof, state: typeof CapabilityChildTable.$inferSelect.state) =>
      Effect.gen(function* () {
        // Progress is a bounded live-parent observation. SQL remains authoritative after the root ends.
        const live = yield* policy.binding(context).pipe(Effect.result)
        if (live._tag === "Failure" || live.success !== binding) return
        yield* events.publish(SessionEvent.Tool.Progress, {
          timestamp: yield* DateTime.now,
          sessionID: context.sessionID,
          assistantMessageID: context.assistantMessageID,
          callID: context.toolCallID,
          structured: { capabilityChild: {
            callID: proof.callID, parentCallID: proof.parentCallID, ordinal: proof.ordinal,
            toolName: proof.toolName, state,
          } },
          content: [],
        }, { location })
      })

    return {
      settle: (name, suppliedInput) => Effect.suspend(() => {
        // Allocation belongs to execution, never Effect construction or model input.
        const ordinal = ++counter.ordinal
        return Effect.gen(function* () {
          if (ordinal > 64 || binding.lineage.length >= 8) return yield* failure("quota_exceeded")
          // Same grammar as Tool.validateName, with an exact end assertion (no trailing newline).
          if (typeof name !== "string" || !/^[A-Za-z][A-Za-z0-9_-]{0,63}(?![\s\S])/.test(name))
            return yield* failure("unsupported_operation")
          const input = CapabilityVendorSchema.snapshot(suppliedInput)
          if (input instanceof Capability.Failure) return yield* input
          if (!materialization.definition(name) || !materialization.registrationIdentity(name))
            return yield* failure("stale_descriptor")
          const proof = Object.freeze({
            callID: CapabilityInvocation.childID(binding.invocation, ordinal),
            parentCallID: binding.invocation.callID,
            ordinal, toolName: name,
            requestHash: CapabilityVendorSchema.hash({ name, input }),
          })
          if (!database.inTransaction) return yield* Effect.die("Capability admission requires SQL transaction identity")
          if (yield* database.inTransaction) return yield* failure("invocation_binding_mismatch")

          return yield* Effect.uninterruptibleMask((restore) => Effect.gen(function* () {
            // Same lock order as policy.commit. No leaf, hook, approval, or event publication under locks.
            const row = yield* agents.withPermissions(context.agent, () => database.db.transaction((tx) =>
              Effect.gen(function* () {
                const current = yield* policy.binding(context)
                if (current !== binding) return yield* failure("invocation_binding_mismatch")
                const existing = yield* tx.select().from(CapabilityChildTable).where(or(
                  eq(CapabilityChildTable.id, proof.callID),
                  and(eq(CapabilityChildTable.session_id, context.sessionID),
                    eq(CapabilityChildTable.assistant_message_id, context.assistantMessageID),
                    eq(CapabilityChildTable.parent_call_id, proof.parentCallID),
                    eq(CapabilityChildTable.ordinal, ordinal)),
                )).get()
                if (existing) return yield* failure(
                  existing.id === proof.callID && existing.request_hash === proof.requestHash &&
                  existing.tool_name === name && existing.agent_id === context.agent &&
                  existing.session_id === context.sessionID && existing.assistant_message_id === context.assistantMessageID &&
                  existing.parent_call_id === proof.parentCallID && existing.ordinal === ordinal &&
                  existing.root_call_id === binding.rootInvocation.callID &&
                  existing.root_tool_name === binding.rootToolName && existing.depth === binding.lineage.length + 1
                    ? "outcome_unknown" : "invocation_binding_mismatch",
                )
                return yield* tx.insert(CapabilityChildTable).values({
                  id: proof.callID, session_id: context.sessionID, agent_id: context.agent,
                  assistant_message_id: context.assistantMessageID,
                  root_call_id: binding.rootInvocation.callID, root_tool_name: binding.rootToolName,
                  parent_call_id: proof.parentCallID, ordinal, depth: binding.lineage.length + 1,
                  tool_name: name, request_hash: proof.requestHash, state: "running",
                }).returning().get()
              }), { behavior: "immediate" })).pipe(storageErrors)

            const exit = yield* restore(Effect.gen(function* () {
              yield* observe(proof, "running")
              return yield* CapabilityInvocation.withChildContext(context, proof, materialization.settle({
                sessionID: context.sessionID, agent: context.agent, assistantMessageID: context.assistantMessageID,
                call: { type: "tool-call", id: proof.callID, name, input },
              }))
            })).pipe(Effect.exit)
            const state = Exit.isFailure(exit)
              ? Cause.hasInterrupts(exit.cause) ? "interrupted" : "failed"
              : exit.value.result.type === "error" ? "failed" : "completed"
            // Recording an acquired outcome is a fact, not a fresh effect grant. No root/deny check here.
            const recorded = yield* database.db.update(CapabilityChildTable).set({ state }).where(and(
              eq(CapabilityChildTable.id, row.id), eq(CapabilityChildTable.session_id, row.session_id),
              eq(CapabilityChildTable.agent_id, row.agent_id),
              eq(CapabilityChildTable.assistant_message_id, row.assistant_message_id),
              eq(CapabilityChildTable.root_call_id, row.root_call_id),
              eq(CapabilityChildTable.root_tool_name, row.root_tool_name),
              eq(CapabilityChildTable.parent_call_id, row.parent_call_id), eq(CapabilityChildTable.ordinal, row.ordinal),
              eq(CapabilityChildTable.depth, row.depth), eq(CapabilityChildTable.tool_name, row.tool_name),
              eq(CapabilityChildTable.request_hash, row.request_hash), eq(CapabilityChildTable.state, "running"),
              eq(CapabilityChildTable.time_created, row.time_created),
              eq(CapabilityChildTable.time_updated, row.time_updated),
            )).returning().get().pipe(storageErrors, Effect.flatMap((updated) =>
              updated ? Effect.void : Effect.fail(failure("outcome_unknown"))), Effect.exit)
            if (Exit.isFailure(recorded)) return yield* Effect.failCause(Exit.isFailure(exit)
              ? Cause.combine(exit.cause, recorded.cause) : recorded.cause)
            const observed = yield* restore(observe(proof, state)).pipe(Effect.exit)
            if (Exit.isFailure(exit)) return yield* Effect.failCause(Exit.isFailure(observed)
              ? Cause.combine(exit.cause, observed.cause) : exit.cause)
            return yield* observed.pipe(Effect.andThen(exit))
          }))
        })
      }),
    }
  })

  return { dispatcher }
})

function storageErrors<A, E, R>(effect: Effect.Effect<A, E, R>) {
  return effect.pipe(Effect.catchIf(
    (error): error is Extract<E, SqlError | EffectDrizzleQueryError> =>
      error instanceof SqlError || error instanceof EffectDrizzleQueryError,
    () => Effect.fail(failure("outcome_unknown")),
  ))
}

function failure(code: Capability.Failure["code"]) {
  return new Capability.Failure({ code, message: code === "invocation_binding_mismatch"
    ? "Capability invocation binding does not match" : "Capability child settlement failed" })
}

export * as CapabilityArtifacts from "./index"

import { randomUUID } from "node:crypto"
import { isAbsolute, join } from "node:path"
import { and, desc, eq, lt, sql } from "drizzle-orm"
import { EffectDrizzleQueryError } from "drizzle-orm/effect-core/errors"
import { Cause, Effect, Option, Schema } from "effect"
import { SqlError } from "effect/unstable/sql/SqlError"
import { Capability } from "@orchestra/schema/capability"
import { SessionID } from "@orchestra/schema/session-id"
import { Database } from "../../database/database"
import { Credential } from "../../credential"
import { FSUtil } from "../../fs-util"
import { Global } from "../../global"
import { SessionStore } from "../../session/store"
import type { Tool } from "../../tool/tool"
import { CapabilityPolicy } from "../policy"
import { CapabilityArtifactPinTable, CapabilityArtifactReferenceTable, CapabilityArtifactTable } from "../sql"
import { ArtifactBlobs } from "./blob"
import { Failure, failure } from "./error"
import { matchesMime, validMime } from "./mime"
import { checkSelection, snapshotRequirements } from "./selection"
import type { Requirements } from "./selection"

export { Failure }
export { selectionCredentialHash } from "./selection"
export type { Requirements } from "./selection"
// Mixed SQL Causes retain their typed failures alongside defects or interruption.
export type Error = Failure | Capability.Failure | SqlError | EffectDrizzleQueryError

// Fixture adapters may omit storageID. Persistent DB providers must supply it: object identity cannot survive reopening.
const identities = new WeakMap<Database.Interface["db"], string>()

export type Input = {
  readonly data: Uint8Array
  readonly mime: string
  readonly kind: string
  readonly verification: Capability.Verification
  readonly metadata: Schema.Json
}

export type Options = {
  readonly boundedBytes?: number
  /** Logical committed raw + UTF-8 JSON bytes per placement, not a physical disk/orphan-burst cap. */
  readonly quota?: number
  /** Trusted host fixture override; never accepted through a model-facing input. */
  readonly root?: string
  /** Unreferenced revisions, orphan blobs and staging files survive this many milliseconds. */
  readonly scratchTTL?: number
}

export type Record = typeof CapabilityArtifactTable.$inferSelect
type Transaction = Parameters<Parameters<Database.Interface["db"]["transaction"]>[0]>[0]

/** Shared by the model facade and the operator facade so both resolve the same private blob root and bounds. */
export const storage = Effect.fn("CapabilityArtifacts.storage")(function* (options: Options = {}) {
  const database = yield* Database.Service
  const fs = yield* FSUtil.Service
  const global = yield* Global.Service
  const boundedBytes = options.boundedBytes ?? 16 * 1024 * 1024
  const quota = options.quota ?? 256 * 1024 * 1024
  const scratchTTL = options.scratchTTL ?? 24 * 60 * 60 * 1000
  const storageID = database.storageID ?? databaseIdentity(database.db)
  const root = options.root ?? join(global.data, "capability-artifacts", ArtifactBlobs.hash(storageID))
  if (![boundedBytes, quota, scratchTTL].every((n) => Number.isSafeInteger(n) && n > 0) || !isAbsolute(root))
    return yield* failure("invalid_input", "Artifact store options are invalid")
  return { boundedBytes, quota, scratchTTL, blobs: ArtifactBlobs.make({ root, boundedBytes, storageID, fs }) }
})

export const make = (options: Options = {}) => Effect.gen(function* () {
  const database = yield* Database.Service
  const sessions = yield* SessionStore.Service
  const policy = yield* CapabilityPolicy.make
  const credentials = yield* Effect.serviceOption(Credential.Service)
  const settings = yield* storage(options)
  const boundedBytes = settings.boundedBytes
  const quota = settings.quota
  const scratchTTL = settings.scratchTTL
  const blobs = settings.blobs
  // Repeat persisted identity validation under the storage transaction, without opening an approval queue there.
  const binding = policy.binding

  const authorize = Effect.fn("CapabilityArtifacts.authorize")(function* (
    context: Tool.Context, action: string, resources: readonly string[],
  ) {
    yield* binding(context)
    return yield* policy.authorize(context, { action, resources })
  })

  const resolve = Effect.fn("CapabilityArtifacts.resolve")(function* (
    tx: Transaction, context: Tool.Context, ref: Capability.ArtifactRef,
  ) {
    const issued = yield* binding(context)
    const record = yield* tx.select().from(CapabilityArtifactTable).where(key(ref)).get()
    const reference = yield* tx.select().from(CapabilityArtifactReferenceTable).where(referenceKey(ref, context.sessionID)).get()
    if (!record || !reference) return yield* failure("artifact_not_found", "Artifact reference is unavailable")
    if (!samePlacement(record.owner, issued.owner)) return yield* denied()
    const pinned = yield* tx.select().from(CapabilityArtifactPinTable).where(pinKey(ref, context.sessionID)).get()
    return { record, reference, issued, pinned: reference.pinned || !!pinned }
  })

  const store = Effect.fn("CapabilityArtifacts.store")(function* (
    tx: Transaction, context: Tool.Context, ref: Capability.ArtifactRef, input: Input, required: Requirements,
  ) {
    const issued = yield* binding(context)
    const rows = yield* tx.select().from(CapabilityArtifactTable)
    const used = rows.filter((row) => samePlacement(row.owner, issued.owner))
      .reduce((n, row) => n + row.bytes + jsonBytes(row.metadata), 0)
    if (used + input.data.byteLength + jsonBytes(input.metadata) > quota) return yield* quotaFailure()
    yield* Effect.forEach(required, (requirement) => checkSelection(tx, context, issued.owner, requirement, credentials))
    // Policy holds actor state before the SQLite writer; GC cannot remove publication before insertion.
    const hash = yield* blobs.publish(input.data, input.mime)
    const record: Record = {
      ...ref, owner: issued.owner, producer: issued.invocation, mime: input.mime, kind: input.kind,
      verification: input.verification, metadata: input.metadata, hash, bytes: input.data.byteLength, time_created: Date.now(),
    }
    // Drizzle treats JS null as SQL NULL even in a JSON column. Keep JSON null as the non-null JSON text "null".
    yield* tx.insert(CapabilityArtifactTable).values({ ...record, metadata: sql`${JSON.stringify(input.metadata)}` }).run()
    yield* tx.insert(CapabilityArtifactReferenceTable).values({
      artifact_id: ref.id, revision: ref.revision, session_id: context.sessionID,
    }).run()
    return ref
  })

  const publish = Effect.fn("CapabilityArtifacts.publish")(function* (context: Tool.Context, input: Input, requirements: Requirements = []) {
    const required = snapshotRequirements(requirements)
    if (required instanceof Capability.Failure) return yield* required
    yield* binding(context)
    const value = yield* snapshot(input, boundedBytes)
    const ref = Capability.ArtifactRef.make({ id: Capability.ArtifactID.create(), revision: 0 })
    const permit = yield* authorize(context, "artifact.write", [resource(ref)])
    const native = yield* Effect.forEach(required, (input) => policy.authorize(context, input))
    return yield* policy.commitMany([permit, ...native], (tx) => store(tx, context, ref, value, required))
      .pipe(storageErrors)
  })

  const update = Effect.fn("CapabilityArtifacts.update")(function* (
    context: Tool.Context, expectedRef: Capability.ArtifactRef, input: Input, requirements: Requirements = [],
  ) {
    const required = snapshotRequirements(requirements)
    if (required instanceof Capability.Failure) return yield* required
    const ref = yield* requireRef(expectedRef)
    yield* binding(context)
    const value = yield* snapshot(input, boundedBytes)
    const permit = yield* authorize(context, "artifact.write", [resource(ref)])
    const native = yield* Effect.forEach(required, (input) => policy.authorize(context, input))
    return yield* policy.commitMany([permit, ...native], (tx) => Effect.gen(function* () {
      yield* resolve(tx, context, ref)
      const latest = yield* tx.select().from(CapabilityArtifactTable).where(eq(CapabilityArtifactTable.id, ref.id))
        .orderBy(desc(CapabilityArtifactTable.revision)).get()
      if (!latest || latest.revision !== ref.revision || !Number.isSafeInteger(ref.revision + 1))
        return yield* failure("revision_conflict", "Artifact revision no longer matches")
      return yield* store(tx, context, Capability.ArtifactRef.make({ id: ref.id, revision: ref.revision + 1 }), value, required)
    })).pipe(storageErrors)
  })

  /** Host-only byte access. Model adapters should expose describe, never paths or this result. */
  const read = Effect.fn("CapabilityArtifacts.read")(function* (context: Tool.Context, supplied: Capability.ArtifactRef) {
    const ref = yield* requireRef(supplied)
    const permit = yield* authorize(context, "artifact.read", [resource(ref)])
    return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
      const found = yield* resolve(tx, context, ref)
      return { metadata: found.record, data: yield* blobs.read(
        found.record.hash, found.record.bytes, found.record.mime,
      ) }
    })).pipe(storageErrors)
  })

  const describe = Effect.fn("CapabilityArtifacts.describe")(function* (context: Tool.Context, supplied: Capability.ArtifactRef) {
    const ref = yield* requireRef(supplied)
    const permit = yield* authorize(context, "artifact.read", [resource(ref)])
    return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
      const found = yield* resolve(tx, context, ref)
      yield* blobs.read(found.record.hash, found.record.bytes, found.record.mime)
      // User metadata and producer/owner placement are host-only; arbitrary metadata may contain secrets.
      return {
        id: found.record.id, revision: found.record.revision, mime: found.record.mime, kind: found.record.kind,
        hash: found.record.hash, bytes: found.record.bytes, verification: found.record.verification,
        timeCreated: found.record.time_created, pinned: found.pinned,
      }
    })).pipe(storageErrors)
  })

  const share = Effect.fn("CapabilityArtifacts.share")(function* (
    context: Tool.Context, supplied: Capability.ArtifactRef, targetSessionID: SessionID,
  ) {
    const ref = yield* requireRef(supplied)
    const target = Schema.decodeUnknownOption(SessionID)(targetSessionID)
    if (Option.isNone(target)) return yield* failure("invalid_input", "Artifact target Session is invalid")
    const permit = yield* authorize(context, "artifact.share", [resource(ref), `session:${target.value}`])
    yield* policy.commit(permit, (tx) => Effect.gen(function* () {
      const found = yield* resolve(tx, context, ref)
      const session = yield* sessions.get(target.value)
      if (!session || session.projectID !== found.issued.owner.projectID ||
        session.location.directory !== found.issued.owner.location.directory ||
        session.location.workspaceID !== found.issued.owner.location.workspaceID) return yield* denied()
      yield* tx.insert(CapabilityArtifactReferenceTable).values({
        artifact_id: ref.id, revision: ref.revision, session_id: target.value,
      }).onConflictDoNothing().run()
    })).pipe(storageErrors)
  })

  const pin = Effect.fn("CapabilityArtifacts.pin")(function* (
    context: Tool.Context, supplied: Capability.ArtifactRef, pinned: boolean,
  ) {
    const ref = yield* requireRef(supplied)
    if (typeof pinned !== "boolean") return yield* failure("invalid_input", "Artifact pin is invalid")
    const permit = yield* authorize(context, "artifact.write", [resource(ref)])
    yield* policy.commit(permit, (tx) => Effect.gen(function* () {
      const found = yield* resolve(tx, context, ref)
      if (pinned) yield* tx.insert(CapabilityArtifactPinTable).values({
        artifact_id: ref.id, revision: ref.revision, session_id: context.sessionID, owner: found.issued.owner,
      }).onConflictDoNothing().run()
      if (!pinned) yield* tx.delete(CapabilityArtifactPinTable).where(pinKey(ref, context.sessionID)).run()
      yield* tx.update(CapabilityArtifactReferenceTable).set({ pinned }).where(referenceKey(ref, context.sessionID)).run()
    })).pipe(storageErrors)
  })

  const deleteReference = Effect.fn("CapabilityArtifacts.deleteReference")(function* (
    context: Tool.Context, supplied: Capability.ArtifactRef,
  ) {
    const ref = yield* requireRef(supplied)
    const permit = yield* authorize(context, "artifact.write", [resource(ref)])
    yield* policy.commit(permit, (tx) => Effect.gen(function* () {
      const found = yield* resolve(tx, context, ref)
      if (found.pinned) return yield* failure("reference_pinned", "Artifact reference must be unpinned before deletion")
      yield* tx.delete(CapabilityArtifactReferenceTable).where(referenceKey(ref, context.sessionID)).run()
    })).pipe(storageErrors)
  })

  /** Host-only GC. A linked revision keeps the entire immutable revision chain, including its CAS head. */
  const cleanup = Effect.fn("CapabilityArtifacts.cleanup")(function* () {
    yield* database.db.transaction((tx) => Effect.gen(function* () {
      const cutoff = Date.now() - scratchTTL
      const refs = yield* tx.select().from(CapabilityArtifactReferenceTable)
      const pins = yield* tx.select().from(CapabilityArtifactPinTable)
      const linked = new Set([...refs, ...pins].map((ref) => ref.artifact_id))
      const records = yield* tx.select().from(CapabilityArtifactTable)
      yield* Effect.forEach(records.filter((row) => !linked.has(row.id) && row.time_created < cutoff),
        (row) => tx.delete(CapabilityArtifactTable).where(and(key(row), lt(CapabilityArtifactTable.time_created, cutoff))).run())
      const retained = new Set((yield* tx.select({ hash: CapabilityArtifactTable.hash }).from(CapabilityArtifactTable))
        .map((row) => row.hash))
      yield* blobs.cleanup(retained, cutoff)
    }), { behavior: "immediate" }).pipe(storageErrors,
      Effect.catchTag("PlatformError", () => Effect.fail(failure("artifact_io_failed", "Artifact cleanup failed"))))
  })

  return { publish, update, read, describe, share, pin, deleteReference, cleanup }
})

function storageErrors<A, E, R>(effect: Effect.Effect<A, E, R>) {
  // Mixed Causes retain their SQL Fail reasons, so their original E must also remain in the inferred error channel.
  return Effect.catchCauseIf(effect,
    (cause: Cause.Cause<E>) => cause.reasons.length > 0 && cause.reasons.every((reason) => reason._tag === "Fail" &&
      (reason.error instanceof SqlError || reason.error instanceof EffectDrizzleQueryError)),
    () => Effect.fail(failure("artifact_storage_failed", "Artifact storage transaction failed")),
  )
}

function denied() {
  return new Capability.Failure({ code: "target_denied", message: "Capability action is not authorized" })
}

function quotaFailure() {
  return new Capability.Failure({ code: "quota_exceeded", message: "Artifact byte budget exceeded" })
}

function resource(ref: Capability.ArtifactRef) {
  return `artifact:${ref.id}:${ref.revision}`
}

function key(ref: Capability.ArtifactRef) {
  return and(eq(CapabilityArtifactTable.id, ref.id), eq(CapabilityArtifactTable.revision, ref.revision))
}

function referenceKey(ref: Capability.ArtifactRef, sessionID: SessionID) {
  return and(eq(CapabilityArtifactReferenceTable.artifact_id, ref.id),
    eq(CapabilityArtifactReferenceTable.revision, ref.revision), eq(CapabilityArtifactReferenceTable.session_id, sessionID))
}

function pinKey(ref: Capability.ArtifactRef, sessionID: SessionID) {
  return and(eq(CapabilityArtifactPinTable.artifact_id, ref.id),
    eq(CapabilityArtifactPinTable.revision, ref.revision), eq(CapabilityArtifactPinTable.session_id, sessionID))
}

function databaseIdentity(db: Database.Interface["db"]) {
  const current = identities.get(db)
  if (current) return current
  const id = randomUUID()
  identities.set(db, id)
  return id
}

function samePlacement(left: Capability.Owner, right: Capability.Owner) {
  return left.projectID === right.projectID && left.location.directory === right.location.directory &&
    left.location.workspaceID === right.location.workspaceID
}

function requireRef(input: Capability.ArtifactRef) {
  const ref = Schema.decodeUnknownOption(Capability.ArtifactRef)(input)
  return Option.isSome(ref) ? Effect.succeed(ref.value) : Effect.fail(failure("invalid_input", "Artifact reference is invalid"))
}

function jsonBytes(value: Schema.Json) {
  return new TextEncoder().encode(JSON.stringify(value)).byteLength
}

function snapshot(input: Input, boundedBytes: number) {
  return Effect.try({
    try: () => {
      if (!(input.data instanceof Uint8Array) || !validMime(input.mime) || typeof input.kind !== "string" || !input.kind.trim() ||
        new TextEncoder().encode(input.kind).byteLength > 256 ||
        Option.isNone(Schema.decodeUnknownOption(Capability.Verification)(input.verification)))
        throw failure("invalid_input", "Artifact input is invalid")
      if (input.data.byteLength > boundedBytes) throw quotaFailure()
      // A JSON round trip captures immutable caller data. Non-finite numbers and cycles are rejected, not normalized.
      const metadata = JSON.stringify(input.metadata, (_, value: unknown) => {
        if (typeof value === "number" && !Number.isFinite(value)) throw failure("invalid_input", "Artifact metadata is invalid")
        if (value === undefined || typeof value === "bigint" || typeof value === "function" || typeof value === "symbol")
          throw failure("invalid_input", "Artifact metadata is invalid")
        return value
      })
      if (new TextEncoder().encode(metadata).byteLength > Math.min(boundedBytes, 64 * 1024)) throw quotaFailure()
      const decoded = Schema.decodeUnknownOption(Schema.UnknownFromJsonString)(metadata)
      if (Option.isNone(decoded)) throw failure("invalid_input", "Artifact metadata is invalid")
      const json = Schema.decodeUnknownOption(Schema.Json)(decoded.value)
      if (Option.isNone(json)) throw failure("invalid_input", "Artifact metadata is invalid")
      // Buffer.slice() aliases caller memory; the Uint8Array constructor always copies it.
      const data = new Uint8Array(input.data)
      if (!matchesMime(data, input.mime)) throw failure("invalid_input", "Artifact bytes do not match MIME")
      return { data, mime: input.mime, kind: input.kind, verification: input.verification, metadata: json.value }
    },
    catch: (error) => error instanceof Failure || error instanceof Capability.Failure
      ? error : failure("invalid_input", "Artifact input is invalid"),
  })
}

export * as CapabilityArtifactManagement from "./management"

import { Capability } from "@orchestra/schema/capability"
import { CapabilityArtifactManagement } from "@orchestra/schema/capability-artifact-management"
import { SessionID } from "@orchestra/schema/session-id"
import { and, eq, gt, or, sql } from "drizzle-orm"
import { Effect, Option, Schema } from "effect"
import { Database } from "../../database/database"
import { capture, decode } from "../connection/input"
import type { CapabilityOperatorContract } from "../operator/contract"
import { CapabilityArtifactPinTable, CapabilityArtifactReferenceTable, CapabilityArtifactTable } from "../sql"
import { failure } from "./error"
import { CapabilityArtifacts } from "./index"
import type { CapabilityArtifactManagementContract } from "./management-contract"
import { CapabilityArtifactMutations } from "./management-mutation"
import { ownedBy, pureAuthorityRejection, sessionPlacement, unavailable } from "./management-shared"

// Owner is loaded only for the placement check; producer and user metadata are never selected.
const columns = {
  id: CapabilityArtifactTable.id, revision: CapabilityArtifactTable.revision, owner: CapabilityArtifactTable.owner,
  mime: CapabilityArtifactTable.mime, kind: CapabilityArtifactTable.kind, hash: CapabilityArtifactTable.hash,
  bytes: CapabilityArtifactTable.bytes, verification: CapabilityArtifactTable.verification,
  timeCreated: CapabilityArtifactTable.time_created, flag: CapabilityArtifactReferenceTable.pinned,
  pin: CapabilityArtifactPinTable.session_id,
}

export function make(options: CapabilityArtifactManagementContract.Options) {
  const operators = Object.freeze({ ...options.operators })
  return Effect.gen(function* () {
    const database = yield* Database.Service
    const storage = yield* CapabilityArtifacts.storage(options.artifacts)
    const mutations = yield* CapabilityArtifactMutations.make(options)
    const db = database.db

    const authorize = (target: CapabilityOperatorContract.Target) => operators.require(target).pipe(
      Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())),
    )
    const validate = (binding: CapabilityOperatorContract.Binding, target: CapabilityOperatorContract.Target) =>
      operators.validate(binding, target).pipe(Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())))

    const rows = (sessionID: SessionID) => db.select(columns).from(CapabilityArtifactReferenceTable)
      .innerJoin(CapabilityArtifactTable, and(eq(CapabilityArtifactTable.id, CapabilityArtifactReferenceTable.artifact_id),
        eq(CapabilityArtifactTable.revision, CapabilityArtifactReferenceTable.revision)))
      .leftJoin(CapabilityArtifactPinTable, and(eq(CapabilityArtifactPinTable.artifact_id, CapabilityArtifactReferenceTable.artifact_id),
        eq(CapabilityArtifactPinTable.revision, CapabilityArtifactReferenceTable.revision),
        eq(CapabilityArtifactPinTable.session_id, sessionID)))

    const resolve = Effect.fn("CapabilityArtifactManagement.resolve")(function* (sessionID: SessionID, ref: Capability.ArtifactRef) {
      const placement = yield* sessionPlacement(db, sessionID)
      const target = { action: "artifact.read", placement, resource: { kind: "artifact", id: ref.id } }
      const binding = yield* authorize(target)
      const row = yield* rows(sessionID).where(and(eq(CapabilityArtifactReferenceTable.session_id, sessionID),
        eq(CapabilityArtifactReferenceTable.artifact_id, ref.id), eq(CapabilityArtifactReferenceTable.revision, ref.revision))).get()
      if (!row || !ownedBy(row.owner, placement)) return yield* unavailable()
      return { row, artifact: yield* project(row), binding, target }
    })

    const list: CapabilityArtifactManagementContract.Interface["list"] = (supplied, input) => {
      const captured = capture({ sessionID: supplied, input },
        decode(Schema.Struct({ sessionID: SessionID, input: CapabilityArtifactManagement.ArtifactQuery })))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* failure("invalid_input", "Artifact query is invalid")
        const sessionID = captured.value.sessionID
        const placement = yield* sessionPlacement(db, sessionID)
        const target = { action: "artifact.list", placement, resource: { kind: "session", id: sessionID } }
        const binding = yield* authorize(target)
        const limit = captured.value.input.limit ?? 16
        const after = captured.value.input.after === undefined ? undefined : cursor(captured.value.input.after)
        const found = yield* rows(sessionID).where(and(
          eq(CapabilityArtifactReferenceTable.session_id, sessionID),
          sql`json_extract(${CapabilityArtifactTable.owner}, '$.projectID') = ${placement.projectID}`,
          sql`json_extract(${CapabilityArtifactTable.owner}, '$.location.directory') = ${placement.location.directory}`,
          sql`json_extract(${CapabilityArtifactTable.owner}, '$.location.workspaceID') IS ${placement.location.workspaceID ?? null}`,
          after === undefined ? undefined : or(gt(CapabilityArtifactReferenceTable.artifact_id, after.id),
            and(eq(CapabilityArtifactReferenceTable.artifact_id, after.id), gt(CapabilityArtifactReferenceTable.revision, after.revision))),
        )).orderBy(CapabilityArtifactReferenceTable.artifact_id, CapabilityArtifactReferenceTable.revision).limit(limit + 1).all()
        const items = yield* Effect.forEach(found.slice(0, limit), project)
        yield* validate(binding, target)
        // The cursor names the last returned item only, never the probed extra row.
        const last = found[limit - 1]
        return Object.freeze({ items: Object.freeze(items), coverage: "live" as const,
          ...(found.length > limit ? { after: `${last.id}:${last.revision}` } : {}) })
      })
    }

    const get: CapabilityArtifactManagementContract.Interface["get"] = (sessionID, ref) => {
      const captured = capture({ sessionID, ref }, decode(Schema.Struct({ sessionID: SessionID, ref: Capability.ArtifactRef })))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* failure("invalid_input", "Artifact reference is invalid")
        const found = yield* resolve(captured.value.sessionID, captured.value.ref)
        yield* validate(found.binding, found.target)
        return found.artifact
      })
    }

    const content: CapabilityArtifactManagementContract.Interface["content"] = (sessionID, ref) => {
      const captured = capture({ sessionID, ref }, decode(Schema.Struct({ sessionID: SessionID, ref: Capability.ArtifactRef })))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* failure("invalid_input", "Artifact reference is invalid")
        const found = yield* resolve(captured.value.sessionID, captured.value.ref)
        // ArtifactBlobs.read verifies size, SHA-256 and MIME; any mismatch is artifact_corrupt.
        const data = yield* storage.blobs.read(found.row.hash, found.row.bytes, found.row.mime)
        yield* validate(found.binding, found.target)
        return Object.freeze({ artifact: found.artifact, data })
      })
    }

    return Object.freeze({ list, get, content, ...mutations }) satisfies CapabilityArtifactManagementContract.Interface
  })
}

export type Interface = CapabilityArtifactManagementContract.Interface

function project(row: { id: Capability.ArtifactID; revision: number; mime: string; kind: string; hash: string; bytes: number;
  verification: Capability.Verification; timeCreated: number; flag: boolean; pin: SessionID | null }) {
  const decoded = Schema.decodeUnknownOption(Schema.toType(CapabilityArtifactManagement.Artifact))({
    artifact: { id: row.id, revision: row.revision }, mime: row.mime, kind: row.kind, hash: row.hash, bytes: row.bytes,
    verification: row.verification, timeCreated: row.timeCreated, pinned: row.flag || row.pin !== null,
  })
  return Option.isNone(decoded) ? Effect.fail(unavailable())
    : Effect.succeed(Object.freeze({ ...decoded.value, artifact: Object.freeze(decoded.value.artifact) }))
}

function cursor(value: string) {
  const split = value.lastIndexOf(":")
  return { id: Capability.ArtifactID.make(value.slice(0, split)), revision: Number(value.slice(split + 1)) }
}

export * as CapabilityArtifactMutations from "./management-mutation"

import { Capability } from "@orchestra/schema/capability"
import { CapabilityArtifactManagement } from "@orchestra/schema/capability-artifact-management"
import { SessionID } from "@orchestra/schema/session-id"
import { and, eq } from "drizzle-orm"
import { Effect, Schema } from "effect"
import { Database } from "../../database/database"
import { capture, decode } from "../connection/input"
import type { CapabilityOperatorContract } from "../operator/contract"
import { CapabilityRequest } from "../operator/request"
import type { CapabilityRequestContract } from "../operator/request-contract"
import { CapabilityArtifactPinTable, CapabilityArtifactReferenceTable, CapabilityArtifactTable } from "../sql"
import { failure } from "./error"
import type { CapabilityArtifacts } from "./index"
import type { CapabilityArtifactManagementContract } from "./management-contract"
import { ownedBy, pureAuthorityRejection, sessionPlacement, unavailable } from "./management-shared"

type Transaction = CapabilityRequestContract.Transaction
type Placement = CapabilityOperatorContract.Placement

export const make = (options: CapabilityArtifactManagementContract.Options) => Effect.gen(function* () {
  const operators = Object.freeze({ ...options.operators })
  const database = yield* Database.Service
  const requests = yield* CapabilityRequest.make({ operators })
  const db = database.db

  const authorize = (target: CapabilityOperatorContract.Target) => operators.require(target).pipe(
    Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())))

  const mutation = Effect.fn("CapabilityArtifactMutations.mutation")(function* (action: string,
    value: Readonly<{ sessionID: SessionID; artifact: Capability.ArtifactRef; input: Schema.Json }>,
    write: (tx: Transaction, placement: Placement) => Effect.Effect<Schema.Json, CapabilityArtifacts.Error>, sharedWith?: SessionID,
  ) {
    const placement = yield* sessionPlacement(db, value.sessionID)
    const target = { action, placement, resource: { kind: "artifact", id: value.artifact.id } }
    yield* authorize(target)
    // Share also needs authority over the target Session at its own stored placement; the ledger target stays the artifact.
    // Intentional: target authority runs before replay, so a share retry after the target Session is deleted is unavailable.
    if (sharedWith !== undefined) yield* authorize({ action, placement: yield* sessionPlacement(db, sharedWith),
      resource: { kind: "session", id: sharedWith } })
    // Replay reconciles after the reference is gone, but never across a moved Session or a collected record.
    const verify = (tx: Transaction) => Effect.gen(function* () {
      if (!samePlacement(placement, yield* sessionPlacement(tx, value.sessionID))) return yield* unavailable()
      const row = yield* record(tx, value.artifact)
      if (!row || !ownedBy(row.owner, placement)) return yield* unavailable()
    })
    return yield* requests.commit(target, value, (tx) => write(tx, placement), verify).pipe(
      Effect.withSpan("CapabilityArtifactMutations.commit"),
      Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())))
  })

  const share: CapabilityArtifactManagementContract.Mutations["share"] = (sessionID, artifact, input) => {
    const captured = capture({ sessionID, artifact, input }, payload(CapabilityArtifactManagement.ShareInput))
    return Effect.gen(function* () {
      if (!captured.ok) return yield* invalid()
      const value = captured.value
      return yield* mutation("artifact.share", value, (tx, placement) => Effect.gen(function* () {
        yield* requireReference(tx, value.artifact, value.sessionID)
        if (!samePlacement(placement, yield* sessionPlacement(tx, value.input.targetSessionID))) return yield* unavailable()
        yield* tx.insert(CapabilityArtifactReferenceTable).values({ artifact_id: value.artifact.id,
          revision: value.artifact.revision, session_id: value.input.targetSessionID }).onConflictDoNothing().run()
        return { artifact: value.artifact, targetSessionID: value.input.targetSessionID }
      }), value.input.targetSessionID)
    })
  }

  const pin: CapabilityArtifactManagementContract.Mutations["pin"] = (sessionID, artifact, input) => {
    const captured = capture({ sessionID, artifact, input }, payload(CapabilityArtifactManagement.PinInput))
    return Effect.gen(function* () {
      if (!captured.ok) return yield* invalid()
      const value = captured.value
      const ref = value.artifact
      return yield* mutation("artifact.pin", value, (tx) => Effect.gen(function* () {
        yield* requireReference(tx, ref, value.sessionID)
        // Same SQL as the Core pin. An operator has no issued owner, so the pin row carries the record owner.
        const row = yield* record(tx, ref)
        if (!row) return yield* unavailable()
        if (value.input.pinned) yield* tx.insert(CapabilityArtifactPinTable).values({ artifact_id: ref.id,
          revision: ref.revision, session_id: value.sessionID, owner: row.owner }).onConflictDoNothing().run()
        if (!value.input.pinned) yield* tx.delete(CapabilityArtifactPinTable).where(pinKey(ref, value.sessionID)).run()
        yield* tx.update(CapabilityArtifactReferenceTable).set({ pinned: value.input.pinned })
          .where(referenceKey(ref, value.sessionID)).run()
        return { artifact: ref, pinned: value.input.pinned }
      }))
    })
  }

  const removeReference: CapabilityArtifactManagementContract.Mutations["removeReference"] = (sessionID, artifact) => {
    const captured = capture({ sessionID, artifact, input: null }, payload(Schema.Null))
    return Effect.gen(function* () {
      if (!captured.ok) return yield* invalid()
      const value = captured.value
      const ref = value.artifact
      return yield* mutation("artifact.reference.delete", value, (tx) => Effect.gen(function* () {
        const reference = yield* requireReference(tx, ref, value.sessionID)
        const pinned = yield* tx.select({ sessionID: CapabilityArtifactPinTable.session_id }).from(CapabilityArtifactPinTable)
          .where(pinKey(ref, value.sessionID)).get()
        if (reference.pinned || pinned) return yield* failure("reference_pinned", "Artifact reference must be unpinned before deletion")
        yield* tx.delete(CapabilityArtifactReferenceTable).where(referenceKey(ref, value.sessionID)).run()
        return { artifact: ref, removed: true }
      }))
    })
  }

  return Object.freeze({ share, pin, removeReference }) satisfies CapabilityArtifactManagementContract.Mutations
})

function payload<S extends Schema.Top>(input: S) {
  return decode(Schema.Struct({ sessionID: SessionID, artifact: Capability.ArtifactRef, input }))
}

function record(tx: Transaction, ref: Capability.ArtifactRef) {
  return tx.select({ owner: CapabilityArtifactTable.owner }).from(CapabilityArtifactTable)
    .where(and(eq(CapabilityArtifactTable.id, ref.id), eq(CapabilityArtifactTable.revision, ref.revision))).get()
}

function invalid() {
  return failure("invalid_input", "Artifact management input is invalid")
}

const requireReference = Effect.fn("CapabilityArtifactMutations.reference")(function* (
  tx: Transaction, ref: Capability.ArtifactRef, sessionID: SessionID,
) {
  const row = yield* tx.select({ pinned: CapabilityArtifactReferenceTable.pinned }).from(CapabilityArtifactReferenceTable)
    .where(referenceKey(ref, sessionID)).get()
  if (!row) return yield* unavailable()
  return row
})

function samePlacement(left: Placement, right: Placement) {
  return left.projectID === right.projectID && left.location.directory === right.location.directory &&
    left.location.workspaceID === right.location.workspaceID
}

function referenceKey(ref: Capability.ArtifactRef, sessionID: SessionID) {
  return and(eq(CapabilityArtifactReferenceTable.artifact_id, ref.id),
    eq(CapabilityArtifactReferenceTable.revision, ref.revision), eq(CapabilityArtifactReferenceTable.session_id, sessionID))
}

function pinKey(ref: Capability.ArtifactRef, sessionID: SessionID) {
  return and(eq(CapabilityArtifactPinTable.artifact_id, ref.id),
    eq(CapabilityArtifactPinTable.revision, ref.revision), eq(CapabilityArtifactPinTable.session_id, sessionID))
}

import { Capability } from "@orchestra/schema/capability"
import { AbsolutePath } from "@orchestra/schema/schema"
import type { SessionID } from "@orchestra/schema/session-id"
import { eq } from "drizzle-orm"
import { type Cause, Effect } from "effect"
import type { Database } from "../../database/database"
import { SessionTable } from "../../session/sql"
import type { CapabilityOperatorContract } from "../operator/contract"
import type { CapabilityRequestContract } from "../operator/request-contract"
import { failure } from "./error"

// Missing rows, placement mismatch and pure authority rejection share this one constant: no existence oracle.
export function unavailable() {
  return failure("artifact_unavailable", "Capability artifact is unavailable")
}

export function pureAuthorityRejection<E>(cause: Cause.Cause<E>) {
  return cause.reasons.length > 0 && cause.reasons.every((reason) => reason._tag === "Fail" &&
    reason.error instanceof Capability.Failure && ["invocation_binding_missing", "invocation_binding_mismatch",
      "target_denied", "authentication_required", "authentication_revoked"].includes(reason.error.code))
}

/** The Session is a selector only: placement always comes from its stored row. */
export const sessionPlacement = Effect.fn("CapabilityArtifactManagement.sessionPlacement")(function* (
  tx: CapabilityRequestContract.Transaction | Database.Interface["db"], sessionID: SessionID,
) {
  const row = yield* tx.select({ projectID: SessionTable.project_id, directory: SessionTable.directory,
    workspaceID: SessionTable.workspace_id }).from(SessionTable).where(eq(SessionTable.id, sessionID)).get()
  if (!row) return yield* unavailable()
  const placement: CapabilityOperatorContract.Placement = Object.freeze({ projectID: row.projectID,
    location: Object.freeze({ directory: AbsolutePath.make(row.directory), ...(row.workspaceID == null ? {} : { workspaceID: row.workspaceID }) }) })
  return placement
})

export function ownedBy(owner: Capability.Owner, placement: CapabilityOperatorContract.Placement) {
  return owner.projectID === placement.projectID && owner.location.directory === placement.location.directory &&
    owner.location.workspaceID === placement.location.workspaceID
}

export * as CapabilityConnections from "./index"

import { Agent } from "@orchestra/schema/agent"
import { Capability } from "@orchestra/schema/capability"
import { Integration } from "@orchestra/schema/integration"
import { SessionID } from "@orchestra/schema/session-id"
import { and, eq, isNull } from "drizzle-orm"
import { EffectDrizzleQueryError } from "drizzle-orm/effect-core/errors"
import { Cause, Effect, Option, Schema } from "effect"
import { SqlError } from "effect/unstable/sql/SqlError"
import { Credential } from "../../credential"
import { Database } from "../../database/database"
import { Location } from "../../location"
import { PermissionV2 } from "../../permission"
import type { Tool } from "../../tool/tool"
import { CapabilityPolicy } from "../policy"
import { CapabilityBindingTable, CapabilityConnectionTable, CapabilityTargetTable } from "../sql"
import { CapabilityConnectionStore } from "./store"
import type { CapabilityConnectionStoreContract } from "./store-contract"

export type Error = CapabilityConnectionStoreContract.Error

const Create = Schema.Struct({
  provider: Schema.NonEmptyString,
  integrationID: Integration.ID,
  credentialID: Credential.ID,
  subjectID: Schema.NonEmptyString,
  endpoint: Schema.NonEmptyString,
  scopeHash: Schema.String.check(Schema.isPattern(/^[0-9a-fA-F]{64}(?![\s\S])/)),
})
export type CreateInput = typeof Create.Type

const Target = Schema.Struct({ environment: Schema.NonEmptyString, resource: Schema.Json })
export type TargetInput = typeof Target.Type

const Bind = Schema.Struct({
  target: Capability.TargetRef,
  sessionID: SessionID,
  agentID: Agent.ID,
  actions: Schema.Array(Schema.NonEmptyString),
})
export type BindInput = typeof Bind.Type

const Resolve = Schema.Struct({
  provider: Schema.NonEmptyString,
  connectionID: Schema.optionalKey(Capability.ConnectionID),
  targetID: Schema.optionalKey(Capability.TargetID),
  action: Schema.NonEmptyString,
})
export type ResolveInput = typeof Resolve.Type

const Resolved = Schema.Struct({
  connection: Capability.ConnectionRef,
  target: Capability.TargetRef,
  resource: Schema.Json,
  endpoint: Schema.NonEmptyString,
  credentialID: Credential.ID,
})
/** Host material: never project this object or loadCredential results into model tool output. */
export type Resolution = typeof Resolved.Type
type Transaction = Parameters<Parameters<Database.Interface["db"]["transaction"]>[0]>[0]

/** Location-scoped factory. Management methods are trusted-host boundaries, not model tools. */
export const make = Effect.gen(function* () {
  const database = yield* Database.Service
  const location = yield* Location.Service
  const credentials = yield* Credential.Service
  const permissions = yield* PermissionV2.Service
  const policy = yield* CapabilityPolicy.make
  const store = yield* CapabilityConnectionStore.make
  const placement = { projectID: location.project.id,
    location: { directory: location.directory, workspaceID: location.workspaceID } }
  const db = database.db

  const query = <A, E, R>(effect: Effect.Effect<A, E, R>) => Effect.catchCauseIf(effect,
    (cause: Cause.Cause<E>) => cause.reasons.length > 0 && cause.reasons.every((reason) =>
      reason._tag === "Fail" && (reason.error instanceof SqlError || reason.error instanceof EffectDrizzleQueryError)),
    () => Effect.fail(failure("connection_unavailable")),
  )
  const transaction = <A, E, R>(write: (tx: Transaction) => Effect.Effect<A, E, R>) =>
    query(db.transaction(write, { behavior: "immediate" })).pipe(Effect.withSpan("CapabilityConnections.transaction"))
  const commit = <A, E, R>(permit: CapabilityPolicy.Permit, write: (tx: Transaction) => Effect.Effect<A, E, R>) =>
    query(policy.commit(permit, write))
  const exactCredential = Effect.fn("CapabilityConnections.exactCredential")(function* (
    id: Credential.ID | null, integrationID: Integration.ID,
  ) {
    if (!id) return yield* failure("authentication_required")
    const saved = yield* credentials.get(id)
    if (!saved) return yield* failure("authentication_required")
    if (saved.id !== id || saved.integrationID !== integrationID) return yield* failure("authentication_revoked")
    return saved
  })

  const create = Effect.fn("CapabilityConnections.create")(function* (input: CreateInput) {
    const parsed = Schema.decodeUnknownOption(Create)(input)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    if (!validEndpoint(value.endpoint)) return yield* failure("target_denied")
    // Subject is supplied by an authenticated adapter; no claim of remote qualification is made here.
    return yield* transaction((tx) => Effect.gen(function* () {
      yield* exactCredential(value.credentialID, value.integrationID)
      const row = yield* query(tx.insert(CapabilityConnectionTable).values({
        id: Capability.ConnectionID.create(), project_id: location.project.id,
        directory: location.directory, workspace_id: location.workspaceID,
        provider: value.provider, integration_id: value.integrationID, credential_id: value.credentialID,
        subject_id: value.subjectID, endpoint: new URL(value.endpoint).href,
        scope_hash: value.scopeHash.toLowerCase(), generation: 0, state: "active",
      }).returning().get())
      return CapabilityConnectionStore.connectionRef(row)
    }))
  })

  const createTarget = Effect.fn("CapabilityConnections.createTarget")(function* (
    ref: Capability.ConnectionRef, input: TargetInput,
  ) {
    const parsed = Schema.decodeUnknownOption(Schema.Struct({ ref: Capability.ConnectionRef, input: Target }))({ ref, input })
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    return yield* transaction((tx) => store.createTarget(tx, placement, value.ref, value.input))
  })

  const bind = Effect.fn("CapabilityConnections.bind")(function* (input: BindInput) {
    const parsed = Schema.decodeUnknownOption(Bind)(input)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    if (value.actions.length === 0 || value.actions.some((action) => action !== action.trim())) return yield* failure("target_denied")
    yield* transaction((tx) => store.bind(tx, placement, value))
  })

  const disconnect = Effect.fn("CapabilityConnections.disconnect")(function* (ref: Capability.ConnectionRef) {
    const parsed = Schema.decodeUnknownOption(Capability.ConnectionRef)(ref)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    yield* transaction((tx) => store.disconnect(tx, placement, value))
  })

  const retargetTarget = Effect.fn("CapabilityConnections.retargetTarget")(function* (
    ref: Capability.TargetRef, input: TargetInput,
  ) {
    const parsed = Schema.decodeUnknownOption(Schema.Struct({ ref: Capability.TargetRef, input: Target }))({ ref, input })
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    return yield* transaction((tx) => store.retargetTarget(tx, placement, value.ref, value.input))
  })

  const removeTarget = Effect.fn("CapabilityConnections.removeTarget")(function* (ref: Capability.TargetRef) {
    const parsed = Schema.decodeUnknownOption(Capability.TargetRef)(ref)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    yield* transaction((tx) => store.removeTarget(tx, placement, value))
  })

  const boundRows = (tx: Transaction, context: Tool.Context, input: ResolveInput) => query(tx.select().from(CapabilityBindingTable)
      .innerJoin(CapabilityTargetTable, eq(CapabilityBindingTable.target_id, CapabilityTargetTable.id))
      .innerJoin(CapabilityConnectionTable, eq(CapabilityTargetTable.connection_id, CapabilityConnectionTable.id))
      .where(and(
        eq(CapabilityBindingTable.session_id, context.sessionID), eq(CapabilityBindingTable.agent_id, context.agent),
        eq(CapabilityConnectionTable.project_id, location.project.id), eq(CapabilityConnectionTable.directory, location.directory),
        location.workspaceID ? eq(CapabilityConnectionTable.workspace_id, location.workspaceID) : isNull(CapabilityConnectionTable.workspace_id),
        eq(CapabilityConnectionTable.provider, input.provider), eq(CapabilityConnectionTable.state, "active"),
        input.connectionID ? eq(CapabilityConnectionTable.id, input.connectionID) : undefined,
        input.targetID ? eq(CapabilityTargetTable.id, input.targetID) : undefined,
      )).orderBy(CapabilityTargetTable.id).all())

  const resolve = Effect.fn("CapabilityConnections.resolve")(function* (context: Tool.Context, input: ResolveInput) {
    const supplied = { ...context }
    const parsed = Schema.decodeUnknownOption(Schema.toType(Resolve))(input)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    // ID-specific policy precedes lookup. Discovery never probes rows outside scoped bindings.
    const discovery = yield* policy.authorize(supplied, { action: value.action, resources: [
      value.provider, ...(value.connectionID ? [value.connectionID] : []), ...(value.targetID ? [value.targetID] : []),
    ] })
    const rows = yield* commit(discovery, (tx) => boundRows(tx, supplied, value))
    const candidates = (yield* Effect.forEach(rows.filter((row) =>
      CapabilityConnectionStore.validGeneration(row.capability_connection.generation) && CapabilityConnectionStore.validGeneration(row.capability_target.generation) &&
      (row.capability_binding.actions.includes(value.action) || row.capability_binding.actions.includes("*"))),
    (row) => policy.authorize(supplied, { action: value.action,
      resources: [value.provider, row.capability_connection.id, row.capability_target.id],
    }).pipe(Effect.map((permit) => ({ row, permit })), Effect.catchTag("Capability.Failure", (error) =>
      error.code === "target_denied" ? Effect.succeed(undefined) : Effect.fail(error)),
    ))).filter((candidate) => candidate !== undefined)

    return yield* commit(discovery, (tx) => Effect.gen(function* () {
      const current = yield* boundRows(tx, supplied, value)
      const permitted = (yield* Effect.forEach(candidates, (candidate) => Effect.gen(function* () {
        if (candidate.permit.binding !== discovery.binding) return yield* failure("invocation_binding_mismatch")
        const row = current.find((row) =>
          row.capability_connection.id === candidate.row.capability_connection.id &&
          row.capability_target.id === candidate.row.capability_target.id &&
          row.capability_connection.generation === candidate.row.capability_connection.generation &&
          row.capability_target.generation === candidate.row.capability_target.generation &&
          row.capability_target.environment === candidate.row.capability_target.environment)
        if (!row || (!row.capability_binding.actions.includes(value.action) && !row.capability_binding.actions.includes("*")))
          return undefined
        // Gate and writer are already held. Reassessment is read-only and consumes the original permit.
        if ((yield* permissions.evaluate({ sessionID: supplied.sessionID, agent: supplied.agent,
          action: candidate.permit.action, resources: [...candidate.permit.resources],
        }).pipe(Effect.catchTag("Session.NotFoundError", () => Effect.fail(failure("invocation_binding_mismatch"))))) === "deny") return undefined
        return row
      }))).filter((row) => row !== undefined)
      if (!permitted.length) return yield* failure("connection_unavailable")
      if (permitted.length > 1) return yield* new Capability.Failure({
        code: "ambiguous_target", message: "Capability target selection is ambiguous",
        detail: { choices: permitted.slice(0, 8).map((row) => ({
          connectionID: row.capability_connection.id, targetID: row.capability_target.id,
        })) },
      })
      const selected = permitted[0]
      const saved = yield* exactCredential(selected.capability_connection.credential_id, selected.capability_connection.integration_id)
      return {
        connection: CapabilityConnectionStore.connectionRef(selected.capability_connection), target: CapabilityConnectionStore.targetRef(selected.capability_target),
        resource: selected.capability_target.resource, endpoint: selected.capability_connection.endpoint, credentialID: saved.id,
      } satisfies Resolution
    }))
  })

  const checkBound = Effect.fn("CapabilityConnections.checkBound")(function* (
    tx: Transaction, context: Tool.Context, resolution: Resolution, action: string,
  ) {
    const parent = yield* query(store.connection(tx, placement, resolution.connection))
    const current = yield* query(store.target(tx, placement, resolution.target))
    if (!parent.credential_id) return yield* failure("authentication_required")
    if (current.parent.id !== parent.id || parent.credential_id !== resolution.credentialID ||
      parent.endpoint !== resolution.endpoint || JSON.stringify(current.row.resource) !== JSON.stringify(resolution.resource))
      return yield* failure("target_denied")
    const binding = yield* query(tx.select().from(CapabilityBindingTable).where(and(
      eq(CapabilityBindingTable.target_id, resolution.target.id), eq(CapabilityBindingTable.session_id, context.sessionID),
      eq(CapabilityBindingTable.agent_id, context.agent),
    )).get())
    if (!binding || (!binding.actions.includes(action) && !binding.actions.includes("*"))) return yield* failure("target_denied")
    const saved = yield* exactCredential(parent.credential_id, parent.integration_id)
    return saved.value
  })

  const loadCredential = Effect.fn("CapabilityConnections.loadCredential")(function* (
    context: Tool.Context, resolution: Resolution, action: string,
  ) {
    const supplied = { ...context }
    const parsed = Schema.decodeUnknownOption(Resolved)(resolution)
    if (Option.isNone(parsed)) return yield* failure("target_denied")
    const value = structuredClone(parsed.value)
    const permit = yield* policy.authorize(supplied, { action, resources: [value.connection.provider, value.connection.id, value.target.id] })
    return yield* commit(permit, (tx) => checkBound(tx, supplied, value, action))
  })

  return Object.freeze({ create, createTarget, bind, disconnect, retargetTarget, removeTarget, resolve, loadCredential })
})

export type Interface = Effect.Success<typeof make>

function validEndpoint(endpoint: string) {
  if (endpoint !== endpoint.trim() || endpoint.includes("#") || !URL.canParse(endpoint)) return false
  const url = new URL(endpoint)
  if (url.protocol !== "https:" || url.username || url.password) return false
  // Closed allowlist: arbitrary queries can contain tokens even when their keys look harmless.
  return url.search === "" || url.search === "?codemode=false"
}

function failure(code: "connection_unavailable" | "authentication_required" | "authentication_revoked" | "target_denied" | "stale_descriptor" | "invocation_binding_mismatch") {
  const messages = {
    connection_unavailable: "Capability connection is unavailable",
    authentication_required: "Capability authentication is required",
    authentication_revoked: "Capability authentication is revoked",
    target_denied: "Capability target is not authorized",
    stale_descriptor: "Capability reference is stale",
    invocation_binding_mismatch: "Capability invocation binding does not match",
  }
  return new Capability.Failure({ code, message: messages[code] })
}

export * as CapabilityConnectionManagement from "./management"

import { Agent } from "@orchestra/schema/agent"
import { Capability } from "@orchestra/schema/capability"
import { CapabilityManagement } from "@orchestra/schema/capability-management"
import type { SessionID } from "@orchestra/schema/session-id"
import { and, eq, gt, isNull, sql } from "drizzle-orm"
import { Cause, Effect, Option, Schema } from "effect"
import { Database } from "../../database/database"
import { SessionTable } from "../../session/sql"
import type { CapabilityOperatorContract } from "../operator/contract"
import { CapabilityRequest } from "../operator/request"
import { CapabilityOperatorScope } from "../operator/scope"
import { CapabilityConnectionTable, CapabilityTargetTable } from "../sql"
import type { CapabilityConnectionManagementContract } from "./management-contract"
import type { CapabilityConnectionStoreContract } from "./store-contract"
import { CapabilityConnectionManagementCursor } from "./management-cursor"
import { capture, decode } from "./input"

// Do not load credential identity or host-only connection/target material for management reads.
const connectionColumns = {
  id: CapabilityConnectionTable.id, projectID: CapabilityConnectionTable.project_id,
  directory: CapabilityConnectionTable.directory, workspaceID: CapabilityConnectionTable.workspace_id,
  provider: CapabilityConnectionTable.provider, generation: CapabilityConnectionTable.generation,
  state: CapabilityConnectionTable.state, label: CapabilityConnectionTable.label,
  credential: sql<number>`${CapabilityConnectionTable.credential_id} IS NOT NULL`,
}
const targetColumns = {
  id: CapabilityTargetTable.id, connectionID: CapabilityTargetTable.connection_id,
  generation: CapabilityTargetTable.generation, environment: CapabilityTargetTable.environment,
}

export function make(options: CapabilityConnectionManagementContract.Options) {
  const operators = Object.freeze({ ...options.operators })
  const store = Object.freeze({ ...options.store })
  return Effect.gen(function* () {
    const database = yield* Database.Service
    const requests = yield* CapabilityRequest.make({ operators })
    const cursors = yield* Effect.sync(() => CapabilityConnectionManagementCursor.make())
    const db = database.db

    const parent = Effect.fn("CapabilityConnectionManagement.parent")(function* (
      tx: CapabilityConnectionStoreContract.Transaction | Database.Interface["db"], id: Capability.ConnectionID,
    ) {
      const row = yield* tx.select(connectionColumns).from(CapabilityConnectionTable)
        .where(eq(CapabilityConnectionTable.id, id)).get()
      if (!row) return yield* unavailable()
      return row
    })

    const authorize = (target: CapabilityOperatorContract.Target) => operators.require(target).pipe(
      Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())),
    )

    const actor = Effect.fn("CapabilityConnectionManagement.actor")(function* (
      tx: CapabilityConnectionStoreContract.Transaction | Database.Interface["db"],
      placement: CapabilityOperatorContract.Placement, sessionID: SessionID,
    ) {
      const row = yield* tx.select({ projectID: SessionTable.project_id, directory: SessionTable.directory,
        workspaceID: SessionTable.workspace_id, agent: SessionTable.agent }).from(SessionTable)
        .where(eq(SessionTable.id, sessionID)).get()
      if (!row || !samePlacement(placement, row) || !row.agent || row.agent !== row.agent.trim())
        return yield* unavailable()
      const decoded = Schema.decodeUnknownOption(Schema.toType(Agent.ID))(row.agent)
      if (Option.isNone(decoded)) return yield* unavailable()
      return decoded.value
    })

    const mutation = Effect.fn("CapabilityConnectionManagement.mutation")(function* (
      action: string, ref: Capability.ConnectionRef | Capability.TargetRef, payload: Schema.Json,
      write: (tx: CapabilityConnectionStoreContract.Transaction, placement: CapabilityOperatorContract.Placement,
        agentID?: Agent.ID) => Effect.Effect<Schema.Json, CapabilityConnectionStoreContract.Error>, sessionID?: SessionID,
    ) {
      const targetRef = "connectionID" in ref ? ref : undefined
      if (targetRef) {
        const child = yield* db.select({ connectionID: CapabilityTargetTable.connection_id }).from(CapabilityTargetTable)
          .where(eq(CapabilityTargetTable.id, targetRef.id)).get()
        if (child && child.connectionID !== targetRef.connectionID) return yield* unavailable()
      }
      const row = yield* parent(db, "connectionID" in ref ? ref.connectionID : ref.id)
      const placement = placementOf(row)
      const target: CapabilityOperatorContract.Target = { action, placement,
        resource: { kind: targetRef ? "target" : "connection", id: ref.id } }
      yield* authorize(target)
      const agentID = sessionID === undefined ? undefined : yield* actor(db, placement, sessionID)
      const verify = (tx: CapabilityConnectionStoreContract.Transaction) => Effect.gen(function* () {
        const current = yield* parent(tx, row.id)
        if (!samePlacement(placement, current)) return yield* unavailable()
        // Reconciliation must survive changed generations/state and a deleted target. The fresh Store
        // callback still rejects missing/stale rows. The ledger compares the complete immutable ref.
        if (targetRef) {
          const child = yield* tx.select({ connectionID: CapabilityTargetTable.connection_id }).from(CapabilityTargetTable)
            .where(eq(CapabilityTargetTable.id, targetRef.id)).get()
          if (child && child.connectionID !== current.id) return yield* unavailable()
        }
        if (sessionID !== undefined && (yield* actor(tx, placement, sessionID)) !== agentID)
          return yield* unavailable()
      })
      return yield* requests.commit(target, agentID === undefined ? payload : { input: payload, agentID },
        (tx) => write(tx, placement, agentID), verify).pipe(
          Effect.withSpan("CapabilityConnectionManagement.commit"),
          Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())),
        )
    })

    const list: CapabilityConnectionManagementContract.Interface["list"] = (supplied, input) => {
      const captured = capture({ placement: supplied, input }, (value) => {
        const root = CapabilityOperatorScope.record(value, ["placement", "input"])
        return { placement: CapabilityOperatorScope.placement(root.placement),
          input: decode(CapabilityManagement.ConnectionQuery)(root.input) }
      })
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        const target = { action: "connection.list", placement: value.placement }
        const binding = yield* operators.require(target)
        const limit = value.input.limit ?? 16
        const rows = yield* db.select(connectionColumns).from(CapabilityConnectionTable).where(and(
          eq(CapabilityConnectionTable.project_id, value.placement.projectID),
          eq(CapabilityConnectionTable.directory, value.placement.location.directory),
          value.placement.location.workspaceID === undefined ? isNull(CapabilityConnectionTable.workspace_id)
            : eq(CapabilityConnectionTable.workspace_id, value.placement.location.workspaceID),
          value.input.after === undefined ? undefined : gt(CapabilityConnectionTable.id, value.input.after),
        )).orderBy(CapabilityConnectionTable.id).limit(limit + 1).all()
        const items = yield* Effect.forEach(rows.slice(0, limit), projectConnection)
        yield* operators.validate(binding, target)
        return Object.freeze({ items: Object.freeze(items), coverage: "live" as const,
          ...(rows.length > limit ? { after: rows[limit - 1].id } : {}) })
      })
    }

    const get: CapabilityConnectionManagementContract.Interface["get"] = (id) => {
      const captured = capture(id, decode(Capability.ConnectionID))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const row = yield* parent(db, captured.value)
        const target = { action: "connection.get", placement: placementOf(row), resource: { kind: "connection", id: row.id } }
        const binding = yield* authorize(target)
        const result = yield* projectConnection(row)
        yield* operators.validate(binding, target).pipe(Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())))
        return result
      })
    }

    const targets: CapabilityConnectionManagementContract.Interface["targets"] = (id, input) => {
      const captured = capture({ id, input }, decode(Schema.Struct({ id: Capability.ConnectionID, input: CapabilityManagement.TargetQuery })))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        const row = yield* parent(db, value.id)
        const placement = placementOf(row)
        const target = { action: "connection.targets", placement, resource: { kind: "connection" as const, id: row.id } }
        const binding = yield* authorize(target)
        const after = value.input.after === undefined ? undefined : yield* cursors.open(value.input.after, binding, target)
        const limit = value.input.limit ?? 16
        const rows = yield* db.select(targetColumns).from(CapabilityTargetTable).where(and(
          eq(CapabilityTargetTable.connection_id, row.id),
          after === undefined ? undefined : gt(CapabilityTargetTable.id, after),
        )).orderBy(CapabilityTargetTable.id).limit(limit + 1).all()
        const items = (yield* Effect.forEach(rows.slice(0, limit), (child) => Effect.gen(function* () {
          const scoped = { action: target.action, placement, resource: { kind: "target", id: child.id } }
          const allowed = yield* operators.require(scoped)
          const decoded = Schema.decodeUnknownOption(Schema.toType(Capability.TargetRef))(child)
          if (Option.isNone(decoded)) return yield* unavailable()
          yield* operators.validate(allowed, scoped)
          return Object.freeze({ target: Object.freeze(decoded.value) })
        }).pipe(Effect.catchCauseIf(pureDenial, () => Effect.succeed(undefined))))).filter((item) => item !== undefined)
        yield* operators.validate(binding, target)
        return Object.freeze({ items: Object.freeze(items), coverage: "live" as const,
          ...(rows.length > limit ? { after: yield* cursors.seal(rows[limit - 1].id, binding, target) } : {}) })
      }).pipe(Effect.catchCauseIf(pureAuthorityRejection, () => Effect.fail(unavailable())))
    }

    const disconnect: CapabilityConnectionManagementContract.Interface["disconnect"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.DisconnectInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        return yield* mutation("connection.disconnect", value.connection, value,
          (tx, placement) => store.disconnect(tx, placement, value.connection).pipe(Effect.as(null)))
      })
    }
    const createTarget: CapabilityConnectionManagementContract.Interface["createTarget"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.CreateTargetInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        return yield* mutation("target.create", value.connection, value, (tx, placement) =>
          store.createTarget(tx, placement, value.connection, value.input).pipe(Effect.map((target) => ({ target }))))
      })
    }
    const retargetTarget: CapabilityConnectionManagementContract.Interface["retargetTarget"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.RetargetInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        return yield* mutation("target.retarget", value.target, value, (tx, placement) =>
          store.retargetTarget(tx, placement, value.target, value.input).pipe(Effect.map((target) => ({ target }))))
      })
    }
    const removeTarget: CapabilityConnectionManagementContract.Interface["removeTarget"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.RemoveTargetInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        return yield* mutation("target.remove", value.target, value,
          (tx, placement) => store.removeTarget(tx, placement, value.target).pipe(Effect.as(null)))
      })
    }
    const bind: CapabilityConnectionManagementContract.Interface["bind"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.PutBindingInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        if (value.input.actions.some((action) => action !== action.trim())) return yield* unavailable()
        const actions = [...new Set(value.input.actions)].sort()
        return yield* mutation("binding.put", value.target, { target: value.target,
          input: { sessionID: value.input.sessionID, actions } }, (tx, placement, agentID) => {
          if (agentID === undefined) return Effect.fail(unavailable())
          return store.bind(tx, placement, { target: value.target, sessionID: value.input.sessionID, agentID, actions }).pipe(Effect.as(null))
        }, value.input.sessionID)
      })
    }
    const unbind: CapabilityConnectionManagementContract.Interface["unbind"] = (input) => {
      const captured = capture(input, decode(CapabilityManagement.RemoveBindingInput))
      return Effect.gen(function* () {
        if (!captured.ok) return yield* unavailable()
        const value = captured.value
        return yield* mutation("binding.remove", value.target, value, (tx, placement, agentID) => {
          if (agentID === undefined) return Effect.fail(unavailable())
          return store.unbind(tx, placement, value.target, value.sessionID, agentID).pipe(Effect.as(null))
        }, value.sessionID)
      })
    }
    return Object.freeze({ list, get, targets, disconnect, createTarget, retargetTarget, removeTarget, bind, unbind }) satisfies CapabilityConnectionManagementContract.Interface
  })
}

export type Interface = CapabilityConnectionManagementContract.Interface

function placementOf(row: { projectID: CapabilityOperatorContract.Placement["projectID"];
  directory: CapabilityOperatorContract.Placement["location"]["directory"];
  workspaceID: CapabilityOperatorContract.Placement["location"]["workspaceID"] | null }) {
  return Object.freeze({ projectID: row.projectID, location: Object.freeze({ directory: row.directory,
    ...(row.workspaceID == null ? {} : { workspaceID: row.workspaceID }) }) })
}

function samePlacement(placement: CapabilityOperatorContract.Placement, row: { projectID: string; directory: string; workspaceID?: string | null }) {
  return placement.projectID === row.projectID && placement.location.directory === row.directory &&
    placement.location.workspaceID === (row.workspaceID ?? undefined)
}

function projectConnection(row: { id: Capability.ConnectionID; provider: string; generation: number; label: string;
  state: typeof CapabilityManagement.Connection.Type["state"]; credential: number }) {
  const decoded = Schema.decodeUnknownOption(Schema.toType(CapabilityManagement.Connection))({
    connection: { id: row.id, provider: row.provider, generation: row.generation }, state: row.state,
    credential: row.credential ? "present" : "missing",
    ...(row.label.length > 0 && row.label.length <= 128 ? { label: row.label } : {}),
  })
  return Option.isNone(decoded) ? Effect.fail(unavailable()) : Effect.succeed(Object.freeze({ ...decoded.value,
    connection: Object.freeze(decoded.value.connection) }))
}

function pureDenial(cause: Cause.Cause<CapabilityConnectionStoreContract.Error>) {
  return cause.reasons.length > 0 && cause.reasons.every((reason) => reason._tag === "Fail" &&
    reason.error instanceof Capability.Failure && reason.error.code === "target_denied")
}

function pureAuthorityRejection(cause: Cause.Cause<CapabilityConnectionStoreContract.Error>) {
  return cause.reasons.length > 0 && cause.reasons.every((reason) => reason._tag === "Fail" &&
    reason.error instanceof Capability.Failure && ["invocation_binding_missing", "invocation_binding_mismatch",
      "target_denied", "authentication_required", "authentication_revoked"].includes(reason.error.code))
}

function unavailable() {
  return new Capability.Failure({ code: "connection_unavailable", message: "Capability connection is unavailable" })
}

export * as CapabilityConnectionVerification from "./verify"

import { Capability } from "@orchestra/schema/capability"
import { CapabilitySetup } from "@orchestra/schema/capability-setup"
import { Cause, Context, Effect, Option, Schema } from "effect"
import { createHash } from "node:crypto"
import { types } from "node:util"
import { Failure, request, validateOptions, type Options } from "../channel/http"
import { CapabilityOperatorScope } from "../operator/scope"
import type { CapabilityConnectionSetupContract } from "./setup-contract"
import type { CapabilityVerifierContract } from "./verifiers/contract"
import { CapabilityVerifiers } from "./verifiers/index"

export type { Options } from "../channel/http"

const failure = (code: Capability.ErrorCode) => new Capability.Failure({ code,
  message: "Capability connection verification is unavailable" })

/** Identity only. The setup facade checks its own operator before calling this verifier. */
export const make = (options: Options = {}) => {
  const transport = capture(options, ["fixtureOrigin", "timeoutMs", "maxResponseBytes"], (value) => {
    const decoded = Schema.decodeUnknownOption(Schema.Struct({ fixtureOrigin: Schema.optionalKey(Schema.NonEmptyString),
      timeoutMs: Schema.optionalKey(Schema.Number), maxResponseBytes: Schema.optionalKey(Schema.Number),
    }))(value)
    if (Option.isNone(decoded) || !validateOptions(decoded.value)) throw new Error("Invalid verification options")
    return Object.freeze(decoded.value)
  })
  return Effect.gen(function* () {
    if (!transport.ok) return yield* failure("unsupported_schema")
    const verify: CapabilityConnectionSetupContract.Verifier["verify"] = (input) => {
      // Capture at call time, before scheduling any effects; only this flat data shape is accepted.
      const captured = capture(input, ["provider", "key", "label"], (value) => {
        const decoded = Schema.decodeUnknownOption(CapabilitySetup.Input)(value)
        if (Option.isNone(decoded)) throw new Error("Invalid verification input")
        return Object.freeze(decoded.value)
      })
      return Effect.gen(function* () {
        if (!captured.ok) return yield* failure("unsupported_schema")
        return yield* prove(CapabilityVerifiers.descriptor(captured.value.provider), captured.value.key, transport.value)
      })
    }
    return Object.freeze({ verify }) satisfies CapabilityConnectionSetupContract.Verifier
  })
}

/**
 * Descriptor dispatch. Exported so a test descriptor can prove the shared rules without joining the registry.
 * Expects already-captured input: a trusted descriptor and a plain key string; options are re-validated here.
 */
export function prove(descriptor: CapabilityVerifierContract.Descriptor, key: string, options: Options) {
  return Effect.gen(function* () {
    // Whitespace or control characters could split headers; refused here so no caller of this hook can skip it.
    if (!validateOptions(options) || /[\s\u0000-\u001f\u007f]/.test(key)) return yield* failure("unsupported_schema")
    // Before any network call. A fresh anchored, non-global copy matches the WHOLE key without shared lastIndex state.
    if (descriptor.keyPattern && !new RegExp(`^(?:${descriptor.keyPattern.source})(?![\\s\\S])`,
      descriptor.keyPattern.flags.replace(/[gmy]/g, "")).test(key)) return yield* failure("unsupported_operation")
    // Origin, auth scheme and headers are descriptor-fixed; only the trusted fixture may swap the origin.
    const call: CapabilityVerifierContract.Call = (route) => request(descriptor.origin, descriptor.authorization(key),
      { method: route.method, path: route.path, body: route.body, headers: descriptor.headers }, options).pipe(
      // Map the whole Cause without dropping other failures, defects, interrupts or annotations.
      Effect.catchCause((cause) => Effect.failCause(transportCause(cause))),
    )
    const identified = yield* descriptor.identify(call)
    // Credential-only identify proves validity alone and returns the literal "key"; anything else fails `accepts`.
    const subjectID = descriptor.verification === "verified" ? identified
      : identified === "key" ? CapabilityVerifiers.fingerprint(key) : ""
    if (!CapabilityVerifiers.accepts(descriptor, subjectID, key)) return yield* failure("connection_unavailable")
    // This fingerprint binds identity and exact key, not vendor action entitlement.
    return Object.freeze({ provider: descriptor.provider, endpoint: descriptor.endpoint, subjectID,
      integrationID: descriptor.integrationID,
      scopeHash: createHash("sha256").update(JSON.stringify([descriptor.provider, descriptor.endpoint, subjectID,
        createHash("sha256").update(key).digest("hex")])).digest("hex"),
    }) satisfies CapabilityConnectionSetupContract.Proof
  })
}

/** Pure projection: mixed errors retain identity; repeated reasons and annotations survive normalization. */
export function transportCause(cause: Cause.Cause<Capability.Failure | Failure>) {
  return Cause.fromReasons<Capability.Failure>(cause.reasons.map((reason) => reason._tag === "Fail"
    ? Cause.makeFailReason(reason.error instanceof Failure ? failure(
      reason.error.reason === "http" && (reason.error.status === 401 || reason.error.status === 403)
        ? "authentication_required" : "connection_unavailable",
    ) : reason.error).annotate(Context.makeUnsafe(new Map(reason.annotations))) : reason))
}

/** Reject proxies before reflection, and nested objects before the shared descriptor copier visits them. */
function capture<A>(input: unknown, allowed: readonly string[], parse: (value: unknown) => A) {
  if (!input || typeof input !== "object" || types.isProxy(input)) return { ok: false } as const
  const keys = Reflect.ownKeys(input)
  if (keys.length > allowed.length || keys.some((key) => {
    if (typeof key !== "string" || !allowed.includes(key)) return true
    const descriptor = Object.getOwnPropertyDescriptor(input, key)
    return !descriptor || !("value" in descriptor) || !descriptor.enumerable ||
      (descriptor.value !== null && ["object", "function", "symbol", "bigint"].includes(typeof descriptor.value))
  })) return { ok: false } as const
  return CapabilityOperatorScope.capture(input, parse)
}

export * as CapabilityJobs from "./index"

import { Capability } from "@orchestra/schema/capability"
import { Permission } from "@orchestra/schema/permission"
import { createHash } from "crypto"
import { and, eq, isNull, sql } from "drizzle-orm"
import { Effect, Option, Schema } from "effect"
import { AgentV2 } from "../../agent"
import { Database } from "../../database/database"
import { Location } from "../../location"
import { PermissionV2 } from "../../permission"
import { SessionStore } from "../../session/store"
import type { Tool } from "../../tool/tool"
import { CapabilityInvocation } from "../invocation"
import { CapabilityPolicy } from "../policy"
import {
  CapabilityArtifactReferenceTable, CapabilityArtifactTable, CapabilityBindingTable,
  CapabilityChildTable, CapabilityConnectionTable, CapabilityJobTable, CapabilityTargetTable,
} from "../sql"

const Create = Schema.Struct({
  kind: Capability.JobKind,
  requestHash: Schema.optional(Schema.String.check(Schema.isPattern(/^[0-9a-f]{64}(?![\s\S])/))),
  operation: Schema.String.check(Schema.isPattern(/^[a-z][a-z0-9._:-]{0,127}(?![\s\S])/)),
  // Scoped to producer invocation + operation; another key deliberately creates another subjob.
  creationKey: Schema.optional(Schema.String.check(Schema.isPattern(/^[a-z][a-z0-9-]{0,63}(?![\s\S])/))),
  connection: Schema.optional(Capability.ConnectionRef),
  target: Schema.optional(Capability.TargetRef),
}).annotate({ parseOptions: { onExcessProperty: "error" } })

// Provider text, URLs, credentials and process handles have no projection slot.
export const Observation = Schema.Struct({
  progress: Schema.optional(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))),
  remoteOutcome: Schema.optional(Schema.Literals(["completed", "failed"])),
  materialization: Schema.optional(Schema.Literals(["pending", "complete", "failed"])),
  cancellation: Schema.optional(Schema.Literals(["requested", "confirmed", "unsupported"])),
  artifactRefs: Schema.optional(Schema.Array(Capability.ArtifactRef)),
}).annotate({ parseOptions: { onExcessProperty: "error" } })
export type Observation = typeof Observation.Type
export type CreateInput = typeof Create.Type
export type TransitionInput = {
  expectedGeneration: number
  state: Capability.JobState
  providerID?: string
  observation: Schema.Json
}
export type Receipt = {
  ref: Capability.JobRef
  generation: number
  kind: Capability.JobKind
  state: Capability.JobState
  observation: Observation
}
/** Trusted host only: exact persisted producer, never an invented Tool.Context or execution grant. */
export type ProducerProof = {
  owner: Capability.Owner
  producer: Capability.InvocationRef
  rootToolName: string
}
const Proof = Schema.Struct({ owner: Schema.toType(Capability.Owner), producer: Capability.InvocationRef,
  rootToolName: Schema.NonEmptyString })
const ChildProof = Schema.Struct({
  callID: Schema.String.check(Schema.isPattern(/^child_[0-9a-f]{64}(?![\s\S])/)),
  parentCallID: Schema.NonEmptyString,
  ordinal: Schema.Number.check(Schema.isInt(), Schema.isBetween({ minimum: 1, maximum: 64 })),
  toolName: Schema.String.check(Schema.isPattern(/^[A-Za-z][A-Za-z0-9_-]{0,63}(?![\s\S])/)),
  requestHash: Schema.String.check(Schema.isPattern(/^[0-9a-f]{64}(?![\s\S])/)),
}).annotate({ parseOptions: { onExcessProperty: "error" } })
const Stored = Schema.Struct({ rootToolName: Schema.NonEmptyString,
  rootInvocation: Schema.optional(Capability.InvocationRef),
  lineage: Schema.optional(Schema.Array(ChildProof).check(Schema.isMaxLength(8))), effectiveRules: Permission.Ruleset,
  nativeDenyFloor: Permission.Ruleset, data: Observation,
  // Set by the first transferHost: provenance stays with the producer while `owner` names the current holder.
  producerOwner: Schema.optional(Schema.toType(Capability.Owner)) })
type Row = typeof CapabilityJobTable.$inferSelect
type Writer = Pick<Database.Interface["db"], "select" | "insert" | "update">
type FixedTransition = Omit<TransitionInput, "observation"> & { observation: Observation }

/** Durable metadata only: constructing or replaying this service never dispatches work. */
export const make = Effect.gen(function* () {
  const database = yield* Database.Service
  const location = yield* Location.Service
  const sessions = yield* SessionStore.Service
  const permissions = yield* PermissionV2.Service
  const agents = yield* AgentV2.Service
  const policy = yield* CapabilityPolicy.make
  const placement = { projectID: location.project.id,
    location: Location.Ref.make({ directory: location.directory, workspaceID: location.workspaceID }) }

  const load = Effect.fn("CapabilityJobs.load")(function* (writer: Writer, ref: Capability.JobRef) {
    const row = yield* writer.select().from(CapabilityJobTable)
      .where(eq(CapabilityJobTable.id, ref.id)).get().pipe(Effect.orDie)
    if (!row) return yield* failure("stale_descriptor")
    return row
  })

  const refs = Effect.fn("CapabilityJobs.refs")(function* (writer: Writer, row: Pick<Row, "connection" | "target" | "owner" | "operation">) {
    if (row.target && (!row.connection || row.target.connectionID !== row.connection.id))
      return yield* failure("stale_descriptor")
    if (row.connection) {
      const connection = yield* writer.select().from(CapabilityConnectionTable)
        .where(eq(CapabilityConnectionTable.id, row.connection.id)).get().pipe(Effect.orDie)
      if (!connection || connection.generation !== row.connection.generation ||
        connection.provider !== row.connection.provider || connection.state !== "active" ||
        connection.project_id !== row.owner.projectID || connection.directory !== row.owner.location.directory ||
        (connection.workspace_id ?? undefined) !== row.owner.location.workspaceID)
        return yield* failure("connection_unavailable")
    }
    if (row.target) {
      const target = yield* writer.select().from(CapabilityTargetTable)
        .where(eq(CapabilityTargetTable.id, row.target.id)).get().pipe(Effect.orDie)
      if (!target || target.generation !== row.target.generation || target.connection_id !== row.target.connectionID ||
        target.environment !== row.target.environment) return yield* failure("stale_descriptor")
      const binding = yield* writer.select().from(CapabilityBindingTable).where(and(
        eq(CapabilityBindingTable.target_id, target.id), eq(CapabilityBindingTable.session_id, row.owner.sessionID),
        eq(CapabilityBindingTable.agent_id, row.owner.agentID),
      )).get().pipe(Effect.orDie)
      if (!binding || (!binding.actions.includes("*") && !binding.actions.includes(row.operation)))
        return yield* failure("target_denied")
    }
  })

  const authorize = Effect.fn("CapabilityJobs.authorize")(function* (context: Tool.Context, row: Row, action: string) {
    const binding = yield* CapabilityInvocation.require(context, placement)
    if (!sameOwner(binding.owner, row.owner)) return yield* failure("target_denied")
    return yield* policy.authorize(context, { action, resources: resources(row) })
  })

  const host = Effect.fn("CapabilityJobs.host")(function* (writer: Writer, proof: ProducerProof, row: Row, read: boolean) {
    const stored = yield* Schema.decodeUnknownEffect(Stored)(row.observation).pipe(Effect.orDie)
    const producer = stored.producerOwner ?? row.owner
    if (!sameOwner(proof.owner, row.owner) || !sameInvocation(proof.producer, row.invocation) ||
      proof.rootToolName !== stored.rootToolName || row.owner.projectID !== placement.projectID ||
      row.owner.location.directory !== placement.location.directory ||
      row.owner.location.workspaceID !== placement.location.workspaceID || !samePlacement(producer, row.owner))
      return yield* failure("target_denied")
    // Legacy direct producers have no lineage. Missing provenance never adopts a child as a root.
    const root = stored.rootInvocation ?? row.invocation
    const lineage = stored.lineage ?? []
    if (root.sessionID !== producer.sessionID || root.agentID !== producer.agentID ||
      row.invocation.sessionID !== producer.sessionID || row.invocation.agentID !== producer.agentID ||
      root.assistantMessageID !== row.invocation.assistantMessageID ||
      (lineage.length === 0 ? !sameInvocation(root, row.invocation) : !stored.rootInvocation ||
        lineage.at(-1)?.callID !== row.invocation.callID)) return yield* failure("target_denied")
    const session = yield* sessions.get(root.sessionID)
    const message = yield* sessions.message(root.assistantMessageID)
    if (!session || session.id !== producer.sessionID || session.projectID !== row.owner.projectID ||
      session.location.directory !== row.owner.location.directory || session.location.workspaceID !== row.owner.location.workspaceID ||
      !message || message.sessionID !== producer.sessionID || message.message.id !== root.assistantMessageID ||
      message.message.type !== "assistant" ||
      message.message.agent !== producer.agentID || !message.message.content.some((part) =>
        part.type === "tool" && part.id === root.callID && part.name === stored.rootToolName))
      return yield* failure("target_denied")
    yield* Effect.forEach(lineage, (proof, index) => Effect.gen(function* () {
      const parentCallID = index === 0 ? root.callID : lineage[index - 1]?.callID
      if (proof.parentCallID !== parentCallID ||
        proof.callID !== CapabilityInvocation.childID({ ...root, callID: proof.parentCallID }, proof.ordinal))
        return yield* failure("target_denied")
      const child = yield* writer.select().from(CapabilityChildTable)
        .where(eq(CapabilityChildTable.id, proof.callID)).get().pipe(Effect.orDie)
      if (!child || child.id !== proof.callID || child.session_id !== producer.sessionID ||
        child.agent_id !== producer.agentID || child.assistant_message_id !== root.assistantMessageID ||
        child.root_call_id !== root.callID || child.root_tool_name !== stored.rootToolName ||
        child.parent_call_id !== proof.parentCallID || child.ordinal !== proof.ordinal || child.depth !== index + 1 ||
        child.tool_name !== proof.toolName || child.request_hash !== proof.requestHash ||
        !["running", "completed", "failed", "interrupted"].includes(child.state)) return yield* failure("target_denied")
    }), { discard: true })
    // Already-acquired facts need provenance, not fresh permission to perform external effects.
    if (!read) return
    if (resources(row).some((resource) =>
      PermissionV2.evaluate("read", resource, stored.nativeDenyFloor.filter((rule) => rule.effect === "deny")).effect === "deny" ||
      PermissionV2.evaluate("read", resource, stored.effectiveRules).effect !== "allow"))
      return yield* failure("target_denied")
    const current = yield* permissions.evaluate({ sessionID: row.owner.sessionID, agent: row.owner.agentID,
      action: "read", resources: resources(row) }).pipe(
        Effect.catchTag("Session.NotFoundError", () => Effect.fail(failure("target_denied"))),
      )
    if (current !== "allow") return yield* failure("target_denied")
  })

  const update = Effect.fn("CapabilityJobs.update")(function* (writer: Writer, row: Row, input: FixedTransition, lost = false) {
    if (row.generation !== input.expectedGeneration || row.generation >= Number.MAX_SAFE_INTEGER)
      return yield* failure("stale_descriptor")
    if (!allowed(row.state, input.state, lost)) return yield* failure("unsupported_operation")
    if (input.providerID !== undefined && (row.kind !== "provider" ||
      (row.provider_id !== null && row.provider_id !== input.providerID))) return yield* failure("outcome_unknown")
    const providerID = input.providerID ?? row.provider_id
    if (row.kind === "provider" && ["submitted", "running", "completed"].includes(input.state) && !providerID)
      return yield* failure("outcome_unknown")
    const observation = input.observation
    if (input.state === "cancel-requested" && observation.cancellation !== "requested" &&
      !(row.state === "cancel-requested" && observation.cancellation === "unsupported"))
      return yield* failure("unsupported_operation")
    if (input.state === "cancelled" && row.state !== "intent" && observation.cancellation !== "confirmed")
      return yield* failure("unsupported_operation")
    if ((observation.cancellation === "confirmed" && input.state !== "cancelled") ||
      (observation.cancellation === "requested" && input.state !== "cancel-requested") ||
      (row.kind === "provider" && row.state !== "intent" && input.state === "cancelled" && !providerID))
      return yield* failure("unsupported_operation")
    const stored = yield* Schema.decodeUnknownEffect(Stored)(row.observation).pipe(Effect.orDie)
    if ((stored.data.remoteOutcome !== undefined && observation.remoteOutcome !== stored.data.remoteOutcome) ||
      (observation.remoteOutcome !== undefined && input.state !== observation.remoteOutcome) ||
      (observation.materialization !== undefined && input.state !== "completed"))
      return yield* failure("unsupported_operation")
    yield* Effect.forEach(observation.artifactRefs ?? [], (ref) => Effect.gen(function* () {
      const artifact = yield* writer.select().from(CapabilityArtifactTable).where(and(
        eq(CapabilityArtifactTable.id, ref.id), eq(CapabilityArtifactTable.revision, ref.revision),
      )).get().pipe(Effect.orDie)
      const retained = yield* writer.select().from(CapabilityArtifactReferenceTable).where(and(
        eq(CapabilityArtifactReferenceTable.artifact_id, ref.id), eq(CapabilityArtifactReferenceTable.revision, ref.revision),
        eq(CapabilityArtifactReferenceTable.session_id, row.owner.sessionID),
      )).get().pipe(Effect.orDie)
      // Sharing is Session retention within project/placement, not creator Session/actor equality.
      if (!artifact || !retained || !samePlacement(artifact.owner, row.owner)) return yield* failure("target_denied")
    }))
    const next = yield* writer.update(CapabilityJobTable).set({
      state: input.state, provider_id: providerID, observation: { ...stored, data: observation },
      generation: row.generation + 1, time_updated: Date.now(),
    }).where(and(eq(CapabilityJobTable.id, row.id), eq(CapabilityJobTable.generation, input.expectedGeneration)))
      .returning().get().pipe(Effect.orDie)
    if (!next) return yield* failure("stale_descriptor")
    return yield* receipt(next)
  })

  const admit = Effect.fn("CapabilityJobs.admit")(function* (supplied: Tool.Context, input: CreateInput) {
      const decoded = Schema.decodeUnknownOption(Create)(input)
      if (Option.isNone(decoded) || !decoded.value.requestHash) return yield* failure("unsupported_schema")
      const fixed = Object.freeze({ ...decoded.value,
        ...(decoded.value.connection ? { connection: Object.freeze({ ...decoded.value.connection }) } : {}),
        ...(decoded.value.target ? { target: Object.freeze({ ...decoded.value.target }) } : {}),
      })
      const context = Object.freeze({ ...supplied })
      const binding = yield* CapabilityInvocation.require(context, placement)
      const observation = Object.freeze({ rootToolName: binding.rootToolName,
        rootInvocation: Object.freeze({ ...binding.rootInvocation }),
        lineage: Object.freeze(binding.lineage.map((proof) => Object.freeze({ ...proof }))),
        effectiveRules: binding.effectiveRules, nativeDenyFloor: binding.nativeDenyFloor, data: Object.freeze({}) })
      // Policy/provenance has its own 16 KiB budget; model observation retains an independent 4 KiB budget.
      if (!boundedJson(observation, 16384, 1024)) return yield* failure("quota_exceeded")
      const creationKey = createHash("sha256").update(JSON.stringify([
        binding.invocation.sessionID, binding.invocation.agentID, binding.invocation.assistantMessageID,
        binding.invocation.callID, fixed.operation, fixed.creationKey ?? "primary",
      ])).digest("hex")
      const permit = yield* policy.authorize(context, { action: "effect", resources: resources(fixed) })
      return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
        const keyed = yield* tx.select().from(CapabilityJobTable)
          .where(eq(CapabilityJobTable.creation_key, creationKey)).get().pipe(Effect.orDie)
        const legacy = keyed || (fixed.creationKey ?? "primary") !== "primary" ? []
          : yield* tx.select().from(CapabilityJobTable).where(and(
            isNull(CapabilityJobTable.creation_key), eq(CapabilityJobTable.operation, fixed.operation),
            sql`json_extract(${CapabilityJobTable.invocation}, '$.sessionID') = ${binding.invocation.sessionID}`,
            sql`json_extract(${CapabilityJobTable.invocation}, '$.agentID') = ${binding.invocation.agentID}`,
            sql`json_extract(${CapabilityJobTable.invocation}, '$.assistantMessageID') = ${binding.invocation.assistantMessageID}`,
            sql`json_extract(${CapabilityJobTable.invocation}, '$.callID') = ${binding.invocation.callID}`,
          )).limit(2).all().pipe(Effect.orDie)
        if (legacy.length > 1) return yield* failure("outcome_unknown")
        const existing = keyed ?? legacy[0]
        if (existing) {
          const stored = yield* Schema.decodeUnknownEffect(Stored)(existing.observation).pipe(Effect.orDie)
          if (!sameOwner(existing.owner, binding.owner) || !sameInvocation(existing.invocation, binding.invocation) ||
            existing.kind !== fixed.kind || existing.operation !== fixed.operation || !sameRefs(existing, fixed) ||
            stored.rootToolName !== binding.rootToolName || existing.request_hash !== (fixed.requestHash ?? null) ||
            !sameInvocation(stored.rootInvocation ?? existing.invocation, observation.rootInvocation) ||
            !sameLineage(stored.lineage ?? [], observation.lineage))
            return yield* failure("outcome_unknown")
          if (existing.creation_key === null) yield* tx.update(CapabilityJobTable).set({ creation_key: creationKey })
            .where(eq(CapabilityJobTable.id, existing.id)).run().pipe(Effect.orDie)
          return { ref: { id: existing.id }, reused: true }
        }
        yield* refs(tx, { ...fixed, owner: binding.owner, connection: fixed.connection ?? null, target: fixed.target ?? null })
        const ref = { id: Capability.JobID.create() }
        yield* tx.insert(CapabilityJobTable).values({ id: ref.id, owner: binding.owner, invocation: binding.invocation,
          kind: fixed.kind, operation: fixed.operation, connection: fixed.connection, target: fixed.target,
          creation_key: creationKey, request_hash: fixed.requestHash, state: "intent", observation,
        }).run().pipe(Effect.orDie)
        return { ref, reused: false }
      })).pipe(Effect.catchTag("SqlError", Effect.die))
    })
  return {
    admit,
    create: (context: Tool.Context, input: CreateInput) => Effect.suspend(() => {
      const decoded = Schema.decodeUnknownOption(Create)(input)
      if (Option.isNone(decoded)) return Effect.fail(failure("unsupported_schema"))
      const fixed = structuredClone(decoded.value)
      return admit({ ...context }, { ...fixed,
        requestHash: fixed.requestHash ?? createHash("sha256").update(JSON.stringify([
          fixed.kind, fixed.operation, fixed.creationKey ?? "primary",
          fixed.connection ? [fixed.connection.id, fixed.connection.provider, fixed.connection.generation] : null,
          fixed.target ? [fixed.target.id, fixed.target.connectionID, fixed.target.generation, fixed.target.environment] : null,
        ])).digest("hex"),
      }).pipe(Effect.map((result) => result.ref))
    }),
    read: Effect.fn("CapabilityJobs.read")(function* (supplied: Tool.Context, suppliedRef: Capability.JobRef) {
      const ref = fixedRef(suppliedRef)
      if (ref instanceof Capability.Failure) return yield* ref
      const context = Object.freeze({ ...supplied })
      const row = yield* load(database.db, ref)
      const permit = yield* authorize(context, row, "read")
      return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        if (!sameOwner(current.owner, permit.binding.owner)) return yield* failure("target_denied")
        return yield* receipt(current)
      })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
    transition: Effect.fn("CapabilityJobs.transition")(function* (
      supplied: Tool.Context, suppliedRef: Capability.JobRef, input: TransitionInput,
    ) {
      // All caller-owned transition data is parsed/copied before the first service/DB/permission yield.
      const fixed = fixedTransition(input)
      const ref = fixedRef(suppliedRef)
      const context = Object.freeze({ ...supplied })
      if (fixed instanceof Capability.Failure) return yield* fixed
      if (ref instanceof Capability.Failure) return yield* ref
      const row = yield* load(database.db, ref)
      const permit = yield* authorize(context, row, "effect")
      if (!sameInvocation(permit.binding.invocation, row.invocation)) return yield* failure("target_denied")
      return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        if (!sameOwner(current.owner, permit.binding.owner) || !sameInvocation(current.invocation, permit.binding.invocation))
          return yield* failure("target_denied")
        if (current.kind !== row.kind || current.operation !== row.operation || !sameRefs(current, row))
          return yield* failure("stale_descriptor")
        yield* refs(tx, current)
        return yield* update(tx, current, fixed)
      })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
    observeHost: Effect.fn("CapabilityJobs.observeHost")(function* (
      suppliedProof: ProducerProof, suppliedRef: Capability.JobRef, input: TransitionInput,
    ) {
      const fixed = fixedTransition(input)
      const proof = fixedProof(suppliedProof)
      const ref = fixedRef(suppliedRef)
      if (fixed instanceof Capability.Failure) return yield* fixed
      if (proof instanceof Capability.Failure) return yield* proof
      if (ref instanceof Capability.Failure) return yield* ref
      // No poll, network, cancel or dispatch. Callers separately authorize acquiring external facts.
      return yield* agents.withPermissions(proof.owner.agentID, () => database.db.transaction((tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        yield* host(tx, proof, current, false)
        if (current.state === "intent" || fixed.state === "submitting") return yield* failure("unsupported_operation")
        return yield* update(tx, current, fixed)
      }), { behavior: "immediate" })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
    readHost: Effect.fn("CapabilityJobs.readHost")(function* (suppliedProof: ProducerProof, suppliedRef: Capability.JobRef) {
      const proof = fixedProof(suppliedProof)
      const ref = fixedRef(suppliedRef)
      if (proof instanceof Capability.Failure) return yield* proof
      if (ref instanceof Capability.Failure) return yield* ref
      return yield* agents.withPermissions(proof.owner.agentID, () => database.db.transaction((tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        yield* host(tx, proof, current, true)
        return { receipt: yield* receipt(current), providerID: current.provider_id ?? undefined }
      }), { behavior: "immediate" })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
    markLostHost: Effect.fn("CapabilityJobs.markLostHost")(function* (
      suppliedProof: ProducerProof, suppliedRef: Capability.JobRef,
      // Trusted startup host must check actual owner absence; restart alone is not evidence.
      input: { expectedGeneration: number; evidence: "startup-owner-absent" },
    ) {
      const fixed = fixedTransition({ expectedGeneration: input.expectedGeneration, state: "lost", observation: {} })
      const evidence = input.evidence
      const proof = fixedProof(suppliedProof)
      const ref = fixedRef(suppliedRef)
      if (fixed instanceof Capability.Failure) return yield* fixed
      if (proof instanceof Capability.Failure) return yield* proof
      if (ref instanceof Capability.Failure) return yield* ref
      return yield* agents.withPermissions(proof.owner.agentID, () => database.db.transaction((tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        yield* host(tx, proof, current, false)
        if (current.kind !== "local-process" || evidence !== "startup-owner-absent") return yield* failure("unsupported_operation")
        return yield* update(tx, current, fixed, true)
      }), { behavior: "immediate" })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
    transferHost: Effect.fn("CapabilityJobs.transferHost")(function* (
      suppliedProof: ProducerProof, suppliedRef: Capability.JobRef,
      // Trusted host only: the caller has already proven the destination is the live parent Session.
      input: { expectedGeneration: number; owner: Capability.Owner },
    ) {
      const expectedGeneration = input.expectedGeneration
      const decoded = Schema.decodeUnknownOption(Schema.toType(Capability.Owner))(input.owner)
      const proof = fixedProof(suppliedProof)
      const ref = fixedRef(suppliedRef)
      if (!Number.isSafeInteger(expectedGeneration) || expectedGeneration < 0) return yield* failure("stale_descriptor")
      if (Option.isNone(decoded)) return yield* failure("target_denied")
      if (proof instanceof Capability.Failure) return yield* proof
      if (ref instanceof Capability.Failure) return yield* ref
      const owner = Object.freeze({ ...decoded.value, location: Object.freeze({ ...decoded.value.location }) })
      return yield* agents.withPermissions(proof.owner.agentID, () => database.db.transaction((tx) => Effect.gen(function* () {
        const current = yield* load(tx, ref)
        yield* host(tx, proof, current, false)
        if (current.kind !== "local-process" || current.state !== "running") return yield* failure("unsupported_operation")
        if (!samePlacement(owner, current.owner) || owner.sessionID === current.owner.sessionID)
          return yield* failure("target_denied")
        if (current.generation !== expectedGeneration || current.generation >= Number.MAX_SAFE_INTEGER)
          return yield* failure("stale_descriptor")
        const session = yield* sessions.get(owner.sessionID)
        if (!session || session.projectID !== owner.projectID || session.location.directory !== owner.location.directory ||
          session.location.workspaceID !== owner.location.workspaceID) return yield* failure("target_denied")
        const stored = yield* Schema.decodeUnknownEffect(Stored)(current.observation).pipe(Effect.orDie)
        const next = yield* tx.update(CapabilityJobTable).set({ owner,
          observation: { ...stored, producerOwner: stored.producerOwner ?? current.owner },
          generation: current.generation + 1, time_updated: Date.now(),
        }).where(and(eq(CapabilityJobTable.id, current.id), eq(CapabilityJobTable.generation, expectedGeneration)))
          .returning().get().pipe(Effect.orDie)
        if (!next) return yield* failure("stale_descriptor")
        return yield* receipt(next)
      }), { behavior: "immediate" })).pipe(Effect.catchTag("SqlError", Effect.die))
    }),
  }
})

/**
 * Trusted host only (startup sweep): rebuilds the host proof for a stored row's current owner, None when the
 * persisted provenance does not decode. host() then acts as a provenance-consistency check for such callers, not as
 * proof that the caller holds the producer invocation. Do not widen its use.
 */
export function proofFromRow(row: Row): Option.Option<ProducerProof> {
  return Schema.decodeUnknownOption(Stored)(row.observation).pipe(Option.map((stored) =>
    ({ owner: row.owner, producer: row.invocation, rootToolName: stored.rootToolName })))
}

function fixedTransition(input: TransitionInput): FixedTransition | Capability.Failure {
  const state = input.state
  const expectedGeneration = input.expectedGeneration
  const providerID = input.providerID
  const observation = input.observation
  if (!Number.isSafeInteger(expectedGeneration) || expectedGeneration < 0) return failure("stale_descriptor")
  if (Option.isNone(Schema.decodeUnknownOption(Capability.JobState)(state))) return failure("unsupported_operation")
  if (providerID !== undefined && (typeof providerID !== "string" || providerID.length > 256 ||
    !/^[0-9A-Za-z._:-]{1,256}(?![\s\S])/.test(providerID))) return failure("outcome_unknown")
  if (!boundedJson(observation)) return failure("quota_exceeded")
  const snapshot = copyJson(observation)
  if (snapshot instanceof Capability.Failure) return snapshot
  if (!boundedJson(snapshot)) return failure("quota_exceeded")
  const decoded = Schema.decodeUnknownOption(Observation)(snapshot)
  if (Option.isNone(decoded)) return failure("unsupported_schema")
  return Object.freeze({ state, expectedGeneration, providerID, observation: Object.freeze({ ...decoded.value,
    ...(decoded.value.artifactRefs ? { artifactRefs: Object.freeze(decoded.value.artifactRefs.map((ref) => Object.freeze({ ...ref }))) } : {}),
  }) })
}

function fixedRef(ref: Capability.JobRef) {
  const decoded = Schema.decodeUnknownOption(Capability.JobRef)(ref)
  return Option.isNone(decoded) ? failure("stale_descriptor") : Object.freeze({ ...decoded.value })
}

function fixedProof(proof: ProducerProof) {
  const decoded = Schema.decodeUnknownOption(Proof)(proof)
  if (Option.isNone(decoded)) return failure("target_denied")
  return Object.freeze({ rootToolName: decoded.value.rootToolName, producer: Object.freeze({ ...decoded.value.producer }),
    owner: Object.freeze({ ...decoded.value.owner, location: Object.freeze({ ...decoded.value.owner.location }) }) })
}

function resources(row: { operation: string; connection?: Capability.ConnectionRef | null; target?: Capability.TargetRef | null }) {
  return [`capability:job:${row.operation}`, ...(row.connection ? [`capability:connection:${row.connection.id}`] : []),
    ...(row.target ? [`capability:target:${row.target.id}`] : [])]
}

function samePlacement(left: Capability.Owner, right: Capability.Owner) {
  return left.projectID === right.projectID && left.location.directory === right.location.directory &&
    left.location.workspaceID === right.location.workspaceID
}

function sameOwner(left: Capability.Owner, right: Capability.Owner) {
  return samePlacement(left, right) && left.sessionID === right.sessionID && left.agentID === right.agentID
}

function sameInvocation(left: Capability.InvocationRef, right: Capability.InvocationRef) {
  return left.sessionID === right.sessionID && left.agentID === right.agentID &&
    left.assistantMessageID === right.assistantMessageID && left.callID === right.callID
}

function sameLineage(left: readonly CapabilityInvocation.ChildProof[], right: readonly CapabilityInvocation.ChildProof[]) {
  return left.length === right.length && left.every((proof, index) => {
    const other = right[index]
    return other !== undefined && proof.callID === other.callID && proof.parentCallID === other.parentCallID &&
      proof.ordinal === other.ordinal && proof.toolName === other.toolName && proof.requestHash === other.requestHash
  })
}

function sameRefs(left: { connection?: Capability.ConnectionRef | null; target?: Capability.TargetRef | null },
  right: { connection?: Capability.ConnectionRef | null; target?: Capability.TargetRef | null }) {
  return (left.connection?.id === right.connection?.id && left.connection?.provider === right.connection?.provider &&
    left.connection?.generation === right.connection?.generation && left.target?.id === right.target?.id &&
    left.target?.connectionID === right.target?.connectionID && left.target?.generation === right.target?.generation &&
    left.target?.environment === right.target?.environment)
}

function allowed(from: string, to: Capability.JobState, lost: boolean) {
  if (to === "lost") return lost && ["submitting", "submitted", "running", "cancel-requested", "unknown"].includes(from)
  if (from === to) return from !== "intent" && from !== "submitting"
  if (from === "intent") return ["submitting", "cancelled"].includes(to)
  if (from === "submitting") return ["submitted", "running", "completed", "failed", "unknown", "cancel-requested"].includes(to)
  if (from === "submitted") return ["running", "completed", "failed", "unknown", "cancel-requested"].includes(to)
  if (from === "running") return ["completed", "failed", "unknown", "cancel-requested"].includes(to)
  if (from === "unknown") return ["submitted", "running", "completed", "failed", "cancel-requested"].includes(to)
  if (from === "cancel-requested") return ["cancelled", "completed", "failed", "unknown"].includes(to)
  return false
}

function failure(code: Capability.ErrorCode) {
  return new Capability.Failure({ code, message: "Job unavailable" })
}

function receipt(row: Row) {
  return Effect.gen(function* () {
    const state = yield* Schema.decodeUnknownEffect(Capability.JobState)(row.state).pipe(Effect.orDie)
    const stored = yield* Schema.decodeUnknownEffect(Stored)(row.observation).pipe(Effect.orDie)
    return { ref: { id: row.id }, generation: row.generation, kind: row.kind, state, observation: stored.data } satisfies Receipt
  })
}

function copyJson(value: unknown): Schema.Json | Capability.Failure {
  const budget = { nodes: 0 }
  const copy = (item: unknown, depth: number): Schema.Json | Capability.Failure => {
    budget.nodes++
    if (depth > 8 || budget.nodes > 256) return failure("quota_exceeded")
    if (item === null || typeof item === "boolean") return item
    if (typeof item === "number") return Number.isFinite(item) ? item : failure("quota_exceeded")
    if (typeof item === "string") return item.length <= 4096 ? item : failure("quota_exceeded")
    if (typeof item !== "object") return failure("quota_exceeded")
    if (Array.isArray(item)) {
      // Numeric data descriptors only: never call caller map/slice, constructor or species hooks.
      const length: unknown = Object.getOwnPropertyDescriptor(item, "length")?.value
      if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0 || length > 256 - budget.nodes)
        return failure("quota_exceeded")
      const result: Schema.Json[] = []
      for (let index = 0; index < length; index++) {
        const descriptor = Object.getOwnPropertyDescriptor(item, String(index))
        if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) return failure("quota_exceeded")
        const child = copy(descriptor.value, depth + 1)
        if (child instanceof Capability.Failure) return child
        Object.defineProperty(result, String(index), { value: child, enumerable: true })
      }
      return Object.freeze(result)
    }
    const result: { [key: string]: Schema.Json } = {}
    for (const key in item) {
      if (!Object.hasOwn(item, key)) continue
      if (budget.nodes >= 256 || key.length > 4096) return failure("quota_exceeded")
      const descriptor = Object.getOwnPropertyDescriptor(item, key)
      if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) return failure("quota_exceeded")
      const child = copy(descriptor.value, depth + 1)
      if (child instanceof Capability.Failure) return child
      Object.defineProperty(result, key, { value: child, enumerable: true })
    }
    return Object.freeze(result)
  }
  return copy(value, 0)
}

function boundedJson(value: unknown, bytes = 4096, nodes = 256) {
  const seen = new Set<object>()
  const budget = { nodes: 0, bytes: 0 }
  const valid = (item: unknown, depth: number): boolean => {
    budget.nodes++
    if (depth > 8 || budget.nodes > nodes) return false
    if (item === null || typeof item === "boolean") return true
    if (typeof item === "number") return Number.isFinite(item)
    if (typeof item === "string") {
      if (item.length > bytes - budget.bytes) return false
      budget.bytes += new TextEncoder().encode(item).byteLength
      return budget.bytes <= bytes
    }
    if (typeof item !== "object" || seen.has(item)) return false
    const length = Array.isArray(item) ? item.length : undefined
    // Giant arrays fail before enumeration; no custom serialization hooks enter the JSON boundary.
    if (length !== undefined && length > nodes - budget.nodes) return false
    const prototype = Object.getPrototypeOf(item)
    if (length !== undefined ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null)
      return false
    if (Object.hasOwn(item, "toJSON")) return false
    seen.add(item)
    const visited = { keys: 0 }
    // Stop per-key work at the budget; do not first materialize a wide object's complete descriptor map.
    for (const key in item) {
      if (!Object.hasOwn(item, key)) continue
      if (budget.nodes >= nodes || key.length > bytes - budget.bytes) return false
      if (length !== undefined && (!/^(0|[1-9][0-9]*)$/.test(key) || Number(key) >= length)) return false
      const descriptor = Object.getOwnPropertyDescriptor(item, key)
      if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) return false
      budget.bytes += new TextEncoder().encode(key).byteLength
      if (budget.bytes > bytes || !valid(descriptor.value, depth + 1)) return false
      visited.keys++
    }
    seen.delete(item)
    return length === undefined || visited.keys === length
  }
  return valid(value, 0) && new TextEncoder().encode(JSON.stringify(value)).byteLength <= bytes
}

