  provider: Schema.NonEmptyString,
  connectionID: Schema.optionalKey(Capability.ConnectionID),
  targetID: Schema.optionalKey(Capability.TargetID),
  cursor: Schema.optionalKey(Schema.NonEmptyString),
  limit: Schema.optionalKey(Schema.Int.check(Schema.isGreaterThan(0))),
})
type Transaction = Parameters<Parameters<Database.Interface["db"]["transaction"]>[0]>[0]
type Envelope = Readonly<{
  tools: readonly Readonly<{ name: string; summary: string; source: VendorTool }>[]
  catalogGeneration: number
  coverage: "complete" | "partial"
}>
type DisclosureDecision = Readonly<{ tool: Envelope["tools"][number]; approved: boolean }>
type Visibility = readonly Readonly<{
  tool: Envelope["tools"][number]
  allowed: boolean
  effect: "allow" | "ask" | "deny"
  configured: "allow" | "ask" | "deny"
}>[]

export function make(options: Options) {
  return Effect.gen(function* () {
    const location = yield* Location.Service
    const connections = yield* CapabilityConnections.make
    const policy = yield* CapabilityPolicy.make
    const registry = yield* ToolRegistry.Service
    const permissions = yield* PermissionV2.Service
    const maxEntries = options.maxEntries ?? 512
    const ttlMillis = options.ttlMillis ?? 60000
    const maxTools = options.maxTools ?? 256
    const maxCatalogBytes = options.maxCatalogBytes ?? 4194304
    const maxLimit = options.maxLimit ?? 32
    const now = options.now ?? Date.now
    const source = options.source
    if ([maxEntries, maxTools, maxCatalogBytes, maxLimit].some((value) => !Number.isSafeInteger(value) || value <= 0) ||
      !Number.isFinite(ttlMillis) || ttlMillis <= 0) return yield* Effect.die(new RangeError("Invalid discovery bounds"))
    const descriptors = options.descriptors ?? (yield* CapabilityDescriptors.make({ maxEntries, ttlMillis, now }))
    const cursors = yield* CapabilityCursors.make({ maxEntries, ttlMillis, now })
    const locators = new Map<Capability.DescriptorID, Readonly<{
      provider: string; name: string; owner: Capability.Owner; ref: Capability.DescriptorRef; expiresAt: number; canonicalIdentity: object
    }>>()
    const validators = new Map<string, { value: CapabilityVendorSchema.Validator | Capability.Failure; expiresAt: number }>()
    const compilation = Semaphore.makeUnsafe(1)
    const placement = { projectID: location.project.id,
      location: Location.Ref.make({ directory: location.directory, workspaceID: location.workspaceID }) }

    const identity = (provider: string, materialization: ToolRegistry.Materialization) => {
      const canonicalName = `platform_${provider}`
      const captured = materialization.registrationIdentity(canonicalName)
      if (!captured || registry.currentRegistrationIdentity(canonicalName) !== captured) return failure("stale_descriptor")
      return { canonicalName, canonicalIdentity: captured }
    }
    const acquire = Effect.fn("CapabilityDiscovery.acquire")(function* (
      context: Tool.Context, input: Omit<FindInput, "query" | "cursor" | "limit">, materialization: ToolRegistry.Materialization,
    ) {
      // Missing frame and persisted-root failures precede selection, registry probing and acquisition.
      const binding = yield* CapabilityInvocation.require(context, placement)
      yield* policy.assert(context, { action: disclosureAction, resources: resources(input) })
      const canonical = identity(input.provider, materialization)
      if (canonical instanceof Capability.Failure) return yield* canonical
      const resolution = yield* connections.resolve(context, { ...input, action: disclosureAction })
      const credential = yield* connections.loadCredential(context, resolution, disclosureAction)
      const listed = yield* source.listTools(Object.freeze(structuredClone({ ...resolution, owner: binding.owner, credential }))).pipe(
        Effect.mapError(() => failure("acquisition_failed")),
      )
      const catalog = boundedEnvelope(listed, maxTools, maxCatalogBytes)
      if (catalog instanceof Capability.Failure) return yield* catalog
      // No cache can assert a current remote generation. Re-list each disclosure; cache only validators.
      yield* connections.loadCredential(context, resolution, disclosureAction)
      const current = identity(input.provider, materialization)
      if (current instanceof Capability.Failure) return yield* current
      return { binding, canonical, resolution, catalog }
    })
    const visibility = Effect.fnUntraced(function* (
      context: Tool.Context, binding: CapabilityInvocation.Binding, decisions: readonly DisclosureDecision[],
      selection: { provider: string; connectionID: Capability.ConnectionID; targetID: Capability.TargetID },
    ) {
      return yield* Effect.forEach(decisions, (decision) => Effect.gen(function* () {
        const selected = [...resources(selection), operationResource(selection.provider, decision.tool.name)]
        const captured = selected.map((resource) => PermissionV2.evaluate(disclosureAction, resource,
          binding.nativeDenyFloor.filter((rule) => rule.effect === "deny")).effect === "deny" ? "deny"
          : PermissionV2.evaluate(disclosureAction, resource, binding.effectiveRules).effect)
        const current = yield* permissions.evaluate({ sessionID: context.sessionID, agent: context.agent,
          action: disclosureAction, resources: selected }).pipe(
          Effect.catchTag("Session.NotFoundError", () => Effect.fail(failure("invocation_binding_mismatch"))),
        )
        const effect = captured.includes("deny") || current === "deny" ? "deny" as const
          : current === "ask" || captured.includes("ask") ? "ask" as const : "allow" as const
        return { tool: decision.tool, allowed: decision.approved && effect !== "deny", effect, configured: current }
      }))
    })
    const visibleCatalog = Effect.fnUntraced(function* (
      context: Tool.Context, binding: CapabilityInvocation.Binding, envelope: Envelope,
      resolution: CapabilityConnections.Resolution,
    ) {
      const selection = { provider: resolution.connection.provider, connectionID: resolution.connection.id, targetID: resolution.target.id }
      const permit = yield* policy.authorize(context, { action: disclosureAction, resources: [disclosureAction, ...resources(selection)] })
      // Finish every approval before consulting any individual schema. A declined ask is a per-call
      // decision, not a configured deny, and must never be resurrected by read-only reassessment.
      const decisions = yield* Effect.forEach(envelope.tools, (tool) => policy.assert(context, {
        action: disclosureAction, resources: [...resources(selection), operationResource(selection.provider, tool.name)],
      }).pipe(Effect.as(true), Effect.catchTag("Capability.Failure", (error) =>
        error.code === "target_denied" ? Effect.succeed(false) : Effect.fail(error)),
        Effect.map((approved) => ({ tool, approved })),
      ))
      return yield* policy.commit(permit, (tx) => Effect.gen(function* () {
        yield* checkSelection(tx, context, binding.owner, resolution)
        const current = yield* visibility(context, binding, decisions, selection)
        // Actor/private-root gate holds reassessment and schema copying in one stable transition.
        // Revocation while another operation waited for approval cannot become a schema oracle.
        const tools = current.filter((item) => item.allowed).map((item): VendorTool | Capability.Failure => {
          const inputSchema = CapabilityVendorSchema.snapshot(item.tool.source.inputSchema)
          const outputSchema = item.tool.source.outputSchema === undefined ? undefined : CapabilityVendorSchema.snapshot(item.tool.source.outputSchema)
          if (inputSchema instanceof Capability.Failure || outputSchema instanceof Capability.Failure) return failure("unsupported_schema")
          return Object.freeze({ name: item.tool.name, summary: item.tool.summary, inputSchema,
            ...(outputSchema === undefined ? {} : { outputSchema }) })
        })
        const error = tools.find((tool) => tool instanceof Capability.Failure)
        if (error instanceof Capability.Failure) return yield* error
        const visible = tools.filter((tool): tool is VendorTool => !(tool instanceof Capability.Failure))
        return { permit, decisions, tools: visible, visibilityHash: visibilityHash(binding, current), catalogHash: CapabilityVendorSchema.hash({
          generation: envelope.catalogGeneration, coverage: envelope.coverage,
          tools: visible.map((tool) => ({ name: tool.name, summary: tool.summary, inputSchema: tool.inputSchema,
            ...(tool.outputSchema === undefined ? {} : { outputSchema: tool.outputSchema }) })),
        }) }
      })).pipe(Effect.catchTag("SqlError", () => Effect.fail(failure("connection_unavailable"))))
    })
    const compile = Effect.fnUntraced(function* (tool: VendorTool) {
      const time = now()
      if (!Number.isFinite(time) || !Number.isFinite(time + ttlMillis)) return yield* failure("stale_descriptor")
      Array.from(validators).forEach(([key, value]) => { if (value.expiresAt <= time) validators.delete(key) })
      const key = CapabilityVendorSchema.hash({ input: tool.inputSchema, output: tool.outputSchema ?? null,
        outputPresent: tool.outputSchema !== undefined })
      const cached = validators.get(key)
      if (cached) return cached.value
      if (validators.size >= maxEntries) return yield* failure("quota_exceeded")
      const value = yield* CapabilityVendorSchema.compile(tool.inputSchema, tool.outputSchema).pipe(
        Effect.catchTag("Capability.Failure", (error) => Effect.succeed(error)),
      )
      validators.set(key, { value, expiresAt: time + ttlMillis })
      return value
    }, compilation.withPermit)

    const find = Effect.fn("CapabilityDiscovery.find")(function* (
      context: Tool.Context, input: FindInput, materialization: ToolRegistry.Materialization,
    ): Effect.fn.Return<Page, CapabilityConnections.Error> {
      const supplied = { ...context }
      const binding = yield* CapabilityInvocation.require(supplied, placement)
      // Validate the durable root before inspecting caller-controlled selectors.
      yield* policy.assert(supplied, { action: disclosureAction, resources: [disclosureAction] })
      const parsed = Schema.decodeUnknownOption(Schema.toType(Find))(input)
      if (Option.isNone(parsed)) return yield* failure("unsupported_operation")
      const provider = normalizeProvider(parsed.value.provider)
      if (!provider) return yield* failure("unsupported_operation")
      const value = { ...parsed.value, provider, limit: parsed.value.limit ?? maxLimit }
      if (value.query.length > 1024 || value.limit > maxLimit || (value.cursor?.length ?? 0) > 128)
        return yield* failure("unsupported_operation")
      const preflight: CapabilityCursors.PreflightScope = {
        owner: binding.owner, query: value.query, provider: value.provider, limit: value.limit,
        requestedConnectionID: value.connectionID, requestedTargetID: value.targetID,
      }
      if (value.cursor !== undefined) yield* cursors.preflight(value.cursor, preflight)
      const acquired = yield* acquire(supplied, value, materialization)
      const selection = { provider: value.provider, connectionID: acquired.resolution.connection.id,
        targetID: acquired.resolution.target.id }
      const visible = yield* visibleCatalog(supplied, binding, acquired.catalog, acquired.resolution)
      const scope: CapabilityCursors.Scope = {
        ...preflight, ...selection,
        connectionGeneration: acquired.resolution.connection.generation, targetGeneration: acquired.resolution.target.generation,
        catalogGeneration: acquired.catalog.catalogGeneration, catalogHash: visible.catalogHash, visibilityHash: visible.visibilityHash,
        canonicalIdentity: acquired.canonical.canonicalIdentity,
      }
      const offset = value.cursor === undefined ? 0 : yield* cursors.read(value.cursor, scope)
      const matches = visible.tools.filter((tool) => `${tool.name}\n${tool.summary}`.toLowerCase().includes(value.query.toLowerCase()))
      const page = yield* Effect.forEach(matches.slice(offset, offset + value.limit), (tool) => Effect.gen(function* () {
        const validator = yield* compile(tool)
        return { tool, validator }
      }))
      const plan = page.flatMap((item) => item.validator instanceof Capability.Failure ? [] : [{
        owner: binding.owner, ...acquired.canonical,
        connectionID: scope.connectionID, targetID: scope.targetID,
        connectionGeneration: scope.connectionGeneration, targetGeneration: scope.targetGeneration,
        catalogGeneration: scope.catalogGeneration, schemaHash: item.validator.schemaHash,
        inputSchema: item.validator.inputSchema, outputSchema: item.validator.outputSchema, operationID: item.tool.name,
      }])
      const pending: { records: readonly CapabilityDescriptors.DescriptorRecord[]; cursor?: string; cancelled: boolean } = {
        records: [], cancelled: false,
      }
      return yield* Effect.uninterruptibleMask((restore) => Effect.gen(function* () {
        // Reserve actual cursor capacity before descriptor issuance. Pending token remains host-only.
        const cursor = offset + page.length < matches.length ? yield* cursors.issue(scope, offset + page.length) : undefined
        pending.cursor = cursor
        return yield* restore(Effect.gen(function* () {
          const operations = yield* policy.commit(visible.permit, (tx) => Effect.gen(function* () {
            yield* checkSelection(tx, supplied, binding.owner, acquired.resolution)
            const current = yield* visibility(supplied, binding, visible.decisions, selection)
            if (visibilityHash(binding, current) !== scope.visibilityHash) return yield* failure("stale_descriptor")
            const canonical = identity(value.provider, materialization)
            if (canonical instanceof Capability.Failure) return yield* canonical
            const time = now()
            Array.from(locators).forEach(([id, value]) => { if (value.expiresAt <= time) locators.delete(id) })
            if (locators.size + plan.length > maxEntries)
              return yield* failure("quota_exceeded")
            // Mask only admission and capture: injected asynchronous stores must deliver their committed
            // tuple before interruption can start rollback. Shared store owns actual batch capacity.
            yield* descriptors.issueBatch(plan).pipe(Effect.tap((records) => Effect.sync(() => {
              pending.records = records
            })), Effect.uninterruptible)
            const currentIdentity = identity(value.provider, materialization)
            if (currentIdentity instanceof Capability.Failure) return yield* currentIdentity
            if (pending.records.length !== plan.length || new Set(pending.records.map((record) => record.operationID)).size !== plan.length ||
              pending.records.some((record) => !CapabilityCursors.sameOwner(record.owner, binding.owner) ||
                record.canonicalIdentity !== acquired.canonical.canonicalIdentity || record.canonicalName !== acquired.canonical.canonicalName ||
                record.connectionGeneration !== scope.connectionGeneration || record.targetGeneration !== scope.targetGeneration ||
                record.ref.connectionID !== scope.connectionID || record.ref.targetID !== scope.targetID ||
                record.ref.catalogGeneration !== scope.catalogGeneration ||
                !plan.some((input) => input.operationID === record.operationID && input.schemaHash === record.ref.schemaHash)))
              return yield* failure("stale_descriptor")
            const operations = page.map((item): Operation | Capability.Failure => {
              if (item.validator instanceof Capability.Failure) return {
                name: item.tool.name, summary: item.tool.summary, readiness: "unsupported",
                coverage: { input: "unsupported", output: "unsupported" },
              }
              const record = pending.records.find((record) => record.operationID === item.tool.name)
              if (!record) return failure("stale_descriptor")
              return { name: record.operationID, summary: item.tool.summary, readiness: "ready",
                coverage: item.validator.coverage, ref: record.ref }
            })
            const error = operations.find((operation) => operation instanceof Capability.Failure)
            if (error instanceof Capability.Failure) return yield* error
            return operations.filter((operation): operation is Operation => !(operation instanceof Capability.Failure))
          })).pipe(Effect.catchTag("SqlError", () => Effect.fail(failure("connection_unavailable"))))
          if (cursor !== undefined) yield* cursors.preflight(cursor, preflight)
          // SQLite COMMIT and injected Store calls may yield. Check current token outside that boundary,
          // then publish locators and return in one synchronous transition. This is not a liveness lease.
          return yield* Effect.suspend(() => {
            const currentIdentity = identity(value.provider, materialization)
            if (currentIdentity instanceof Capability.Failure) return Effect.fail(currentIdentity)
            const time = now()
            // A synchronous host callback can request interruption and run rollback reentrantly.
            // Never republish locators after that cleanup, even if this callback resumes afterward.
            if (pending.cancelled) return Effect.interrupt
            if (!Number.isFinite(time) || pending.records.some((record) => record.expiresAt <= time))
              return Effect.fail(failure("stale_descriptor"))
            Array.from(locators).forEach(([id, value]) => { if (value.expiresAt <= time) locators.delete(id) })
            if (locators.size + pending.records.length > maxEntries) return Effect.fail(failure("quota_exceeded"))
            pending.records.forEach((record) => locators.set(record.ref.id, Object.freeze({
              provider: value.provider, name: record.operationID, owner: record.owner, ref: record.ref, expiresAt: record.expiresAt,
              canonicalIdentity: record.canonicalIdentity,
            })))
            return Effect.succeed({ operations, coverage: acquired.catalog.coverage, catalogGeneration: acquired.catalog.catalogGeneration,
              ...(cursor === undefined ? {} : { cursor }) })
          })
        }))
      })).pipe(Effect.onExit((exit) => Exit.isFailure(exit) ? Effect.gen(function* () {
        // This observer encloses the mask itself, including interruption delivered at restoration.
        pending.cancelled = true
        if (pending.cursor !== undefined) yield* cursors.remove(pending.cursor)
        yield* Effect.forEach(pending.records, (record) => descriptors.remove(record.ref), { discard: true })
        pending.records.forEach((record) => locators.delete(record.ref.id))
      }) : Effect.void))
    })

    const describe = Effect.fn("CapabilityDiscovery.describe")(function* (
      context: Tool.Context, ref: Capability.DescriptorRef, materialization: ToolRegistry.Materialization,
    ): Effect.fn.Return<Description, CapabilityConnections.Error> {
      const supplied = { ...context }
      const binding = yield* CapabilityInvocation.require(supplied, placement)
      yield* policy.assert(supplied, { action: disclosureAction, resources: [disclosureAction] })
      const parsed = Schema.decodeUnknownOption(Capability.DescriptorRef)(ref)
      if (Option.isNone(parsed)) return yield* failure("stale_descriptor")
      const value = { ...parsed.value }
      const locator = locators.get(value.id)
      const time = now()
      if (!locator || !Number.isFinite(time) || locator.expiresAt <= time ||
        !CapabilityCursors.sameOwner(locator.owner, binding.owner) || !sameRef(locator.ref, value))
        return yield* failure("stale_descriptor")
      yield* policy.assert(supplied, { action: disclosureAction, resources: [disclosureAction, value.connectionID, value.targetID] })
      yield* policy.assert(supplied, { action: disclosureAction, resources: [operationResource(locator.provider, locator.name)] })
      const acquired = yield* acquire(supplied, { provider: locator.provider, connectionID: value.connectionID,
        targetID: value.targetID }, materialization)
      const visible = yield* visibleCatalog(supplied, binding,
        { ...acquired.catalog, tools: acquired.catalog.tools.filter((tool) => tool.name === locator.name) }, acquired.resolution)
      const tool = visible.tools.find((tool) => tool.name === locator.name)
      if (!tool) return yield* failure("stale_descriptor")
      const validator = yield* compile(tool)
      if (validator instanceof Capability.Failure) return yield* validator
      const permit = yield* policy.authorize(supplied, { action: disclosureAction,
        resources: [...resources({ provider: locator.provider, connectionID: value.connectionID, targetID: value.targetID }),
          operationResource(locator.provider, locator.name)],
      })
      const description = yield* policy.commit(permit, (tx) => Effect.gen(function* () {
        yield* checkSelection(tx, supplied, binding.owner, acquired.resolution)
        const canonical = identity(locator.provider, materialization)
        if (canonical instanceof Capability.Failure) return yield* canonical
        const record = yield* descriptors.read(value, {
          owner: binding.owner, connectionGeneration: acquired.resolution.connection.generation,
          targetGeneration: acquired.resolution.target.generation, canonicalIdentity: acquired.canonical.canonicalIdentity,
          catalogGeneration: acquired.catalog.catalogGeneration, schemaHash: validator.schemaHash,
        })
        const currentIdentity = identity(locator.provider, materialization)
        if (currentIdentity instanceof Capability.Failure) return yield* currentIdentity
        return { ref: record.ref, name: record.operationID, summary: tool.summary, readiness: "ready" as const,
          coverage: validator.coverage, inputSchema: record.inputSchema,
          ...(record.outputSchema === undefined ? {} : { outputSchema: record.outputSchema }) }
      })).pipe(Effect.catchTag("SqlError", () => Effect.fail(failure("connection_unavailable"))))
      return yield* Effect.suspend(() => {
        const currentIdentity = identity(locator.provider, materialization)
        if (currentIdentity instanceof Capability.Failure) return Effect.fail(currentIdentity)
        const time = now()
        return !Number.isFinite(time) || locator.expiresAt <= time ? Effect.fail(failure("stale_descriptor")) : Effect.succeed(description)
      })
    })
    // Host routing metadata only; the leaf must re-list and validate current selection/schema before execution.
    const locate = Effect.fn("CapabilityDiscovery.locate")(function* (
      context: Tool.Context, ref: Capability.DescriptorRef, materialization: ToolRegistry.Materialization,
    ): Effect.fn.Return<Readonly<{ provider: string; canonicalName: string; name: string }>, Capability.Failure> {
      const supplied = { ...context }
      const binding = yield* CapabilityInvocation.require(supplied, placement)
      yield* policy.assert(supplied, { action: disclosureAction, resources: [disclosureAction] })
      const parsed = Schema.decodeUnknownOption(Capability.DescriptorRef)(ref)
      if (Option.isNone(parsed)) return yield* failure("stale_descriptor")
      const value = { ...parsed.value }
      const locator = locators.get(value.id)
      const time = now()
      if (!locator || !Number.isFinite(time) || locator.expiresAt <= time ||
        !CapabilityCursors.sameOwner(locator.owner, binding.owner) || !sameRef(locator.ref, value))
        return yield* failure("stale_descriptor")
      const permit = yield* policy.authorize(supplied, { action: disclosureAction,
        resources: [disclosureAction, ...resources({ provider: locator.provider,
          connectionID: value.connectionID, targetID: value.targetID }), operationResource(locator.provider, locator.name)],
      })
      yield* policy.commit(permit, () => Effect.void).pipe(
        Effect.catchTag("SqlError", () => Effect.fail(failure("connection_unavailable"))),
      )
      return yield* Effect.suspend(() => {
        const canonical = identity(locator.provider, materialization)
        if (canonical instanceof Capability.Failure) return Effect.fail(canonical)
        const time = now()
        if (!Number.isFinite(time) || locator.expiresAt <= time || locators.get(value.id) !== locator ||
          canonical.canonicalIdentity !== locator.canonicalIdentity) return Effect.fail(failure("stale_descriptor"))
        return Effect.succeed(Object.freeze({ provider: locator.provider, canonicalName: canonical.canonicalName, name: locator.name }))
      })
    })
    // Host-only current metadata check, not a grant or execution lease. Callers must already hold scope approval.
    const validateCurrent = Effect.fn("CapabilityDiscovery.validateCurrent")(function* (
      context: Tool.Context, ref: Capability.DescriptorRef, materialization: ToolRegistry.Materialization,
      scope: Readonly<{ connectionGeneration: number; targetGeneration: number; catalogGeneration: number; schemaHash: string }>,
    ): Effect.fn.Return<void, Capability.Failure> {
      const supplied = { ...context }
      const binding = yield* policy.binding(supplied)
      const parsed = Schema.decodeUnknownOption(Capability.DescriptorRef)(ref)
      if (Option.isNone(parsed)) return yield* failure("stale_descriptor")
      const value = { ...parsed.value }
      const currentScope = { ...scope }
      const locator = locators.get(value.id)
      const time = now()
      if (!locator || !Number.isFinite(time) || locator.expiresAt <= time ||
        !CapabilityCursors.sameOwner(locator.owner, binding.owner) || !sameRef(locator.ref, value))
        return yield* failure("stale_descriptor")
      const canonical = identity(locator.provider, materialization)
      if (canonical instanceof Capability.Failure) return yield* canonical
      if (canonical.canonicalIdentity !== locator.canonicalIdentity) return yield* failure("stale_descriptor")
      const record = yield* descriptors.read(value, { ...currentScope, owner: binding.owner, canonicalIdentity: canonical.canonicalIdentity })
      if (!sameRef(record.ref, value) || !CapabilityCursors.sameOwner(record.owner, binding.owner) ||
        record.operationID !== locator.name || record.canonicalName !== canonical.canonicalName ||
        record.canonicalIdentity !== canonical.canonicalIdentity) return yield* failure("stale_descriptor")
      if ((yield* policy.binding(supplied)) !== binding) return yield* failure("invocation_binding_mismatch")
      return yield* Effect.suspend(() => {
        const current = identity(locator.provider, materialization)
        if (current instanceof Capability.Failure) return Effect.fail(current)
        const time = now()
        return !Number.isFinite(time) || locator.expiresAt <= time || record.expiresAt <= time ||
          locators.get(value.id) !== locator || current.canonicalIdentity !== canonical.canonicalIdentity
          ? Effect.fail(failure("stale_descriptor")) : Effect.void
      })
    })
    return { find, describe, locate, validateCurrent }
  })
}

export type Interface = Effect.Success<ReturnType<typeof make>>

function normalizeProvider(value: string) {
  const normalized = value.trim().toLowerCase().replaceAll("-", "_")
  return /^[a-z][a-z0-9_]{0,63}$/.test(normalized) ? normalized : undefined
}

function resources(input: { provider: string; connectionID?: Capability.ConnectionID; targetID?: Capability.TargetID }) {
  return [input.provider, ...(input.connectionID ? [input.connectionID] : []), ...(input.targetID ? [input.targetID] : [])]
}

function operationResource(provider: string, name: string) {
  return `${provider}:${name}`
}

function boundedEnvelope(list: VendorList, maxTools: number, maxBytes: number): Envelope | Capability.Failure {
  if (!list || !Array.isArray(list.tools) || list.tools.length > maxTools ||
    !Number.isSafeInteger(list.catalogGeneration) || list.catalogGeneration < 0 ||
    (list.coverage !== "complete" && list.coverage !== "partial")) return failure("acquisition_failed")
  if (!Number.isSafeInteger(list.byteLength) || list.byteLength < 0) return failure("acquisition_failed")
  if (list.byteLength > maxBytes) return failure("quota_exceeded")
  const names = new Set<string>()
  const tools = list.tools.map((tool): Envelope["tools"][number] | Capability.Failure => {
    if (!tool || typeof tool.name !== "string" || !tool.name.trim() || tool.name.length > 256 || names.has(tool.name) ||
      typeof tool.summary !== "string" || tool.summary.length > 2048) return failure("acquisition_failed")
    names.add(tool.name)
    return Object.freeze({ name: tool.name, summary: tool.summary, source: tool })
  })
  const error = tools.find((tool) => tool instanceof Capability.Failure)
  if (error instanceof Capability.Failure) return error
  return { tools: tools.filter((tool): tool is Envelope["tools"][number] => !(tool instanceof Capability.Failure)),
    catalogGeneration: list.catalogGeneration, coverage: list.coverage }
}

function sameRef(left: Capability.DescriptorRef, right: Capability.DescriptorRef) {
  return left.id === right.id && left.schemaHash === right.schemaHash && left.catalogGeneration === right.catalogGeneration &&
    left.connectionID === right.connectionID && left.targetID === right.targetID
}

function visibilityHash(binding: CapabilityInvocation.Binding, visible: Visibility) {
  const rules = (rules: PermissionV2.Ruleset) => rules.map((rule) => ({ action: rule.action, resource: rule.resource, effect: rule.effect }))
  return CapabilityVendorSchema.hash({ captured: rules(binding.effectiveRules), nativeFloor: rules(binding.nativeDenyFloor),
    configured: visible.map((item) => ({ name: item.tool.name, effect: item.configured })),
    visible: visible.filter((item) => item.allowed).map((item) => ({ name: item.tool.name, effect: item.effect })) })
}

// Recheck authoritative selection in the disclosure commit, closing retarget/binding races after transport.
function checkSelection(tx: Transaction, context: Tool.Context, owner: Capability.Owner, resolution: CapabilityConnections.Resolution) {
  return Effect.gen(function* () {
    const connection = yield* tx.select().from(CapabilityConnectionTable)
      .where(eq(CapabilityConnectionTable.id, resolution.connection.id)).get()
    const target = yield* tx.select().from(CapabilityTargetTable).where(eq(CapabilityTargetTable.id, resolution.target.id)).get()
    const binding = yield* tx.select().from(CapabilityBindingTable).where(and(
      eq(CapabilityBindingTable.target_id, resolution.target.id), eq(CapabilityBindingTable.session_id, context.sessionID),
      eq(CapabilityBindingTable.agent_id, context.agent),
    )).get()
    if (!connection || !target || connection.state !== "active" || connection.generation !== resolution.connection.generation ||
      connection.project_id !== owner.projectID || connection.directory !== owner.location.directory ||
      (connection.workspace_id ?? undefined) !== owner.location.workspaceID || connection.provider !== resolution.connection.provider ||
      target.generation !== resolution.target.generation || target.connection_id !== connection.id ||
      connection.credential_id !== resolution.credentialID || connection.endpoint !== resolution.endpoint ||
      CapabilityVendorSchema.hash(target.resource) !== CapabilityVendorSchema.hash(resolution.resource) ||
      target.environment !== resolution.target.environment || !binding ||
      (!binding.actions.includes(disclosureAction) && !binding.actions.includes("*"))) return yield* failure("stale_descriptor")
  }).pipe(Effect.mapError((error) => error instanceof Capability.Failure ? error : failure("connection_unavailable")))
}

function failure(code: Capability.ErrorCode) {
  return new Capability.Failure({ code, message: "Capability discovery unavailable" })
}

export * as CapabilityDescriptors from "./descriptors"

import { Effect, Option, Schema } from "effect"
import { Capability } from "@orchestra/schema/capability"

// Store callers pass decoded host values; the public codec remains the strict wire boundary.
const OwnerInput = Schema.toType(Capability.Owner)

export type DescriptorRecord = Readonly<{
  ref: Capability.DescriptorRef
  owner: Capability.Owner
  connectionGeneration: number
  targetGeneration: number
  canonicalName: string
  canonicalIdentity: object
  inputSchema: Schema.Json
  outputSchema?: Schema.Json
  operationID: string
  issuedAt: number
  expiresAt: number
}>
export type IssueInput = Omit<DescriptorRecord, "ref" | "issuedAt" | "expiresAt"> & Omit<Capability.DescriptorRef, "id">
export type ReadScope = Pick<
  DescriptorRecord,
  "owner" | "connectionGeneration" | "targetGeneration" | "canonicalIdentity"
> &
  Pick<Capability.DescriptorRef, "catalogGeneration" | "schemaHash">
export type Store = {
  issue: (input: IssueInput) => Effect.Effect<DescriptorRecord, Capability.Failure>
  issueBatch: (inputs: readonly IssueInput[]) => Effect.Effect<readonly DescriptorRecord[], Capability.Failure>
  remove: (ref: Capability.DescriptorRef) => Effect.Effect<void>
  read: (ref: Capability.DescriptorRef, scope: ReadScope) => Effect.Effect<DescriptorRecord, Capability.Failure>
  reissue: (
    ref: Capability.DescriptorRef,
    oldScope: ReadScope,
    newOwner: Capability.Owner,
  ) => Effect.Effect<DescriptorRecord, Capability.Failure>
  invalidateConnection: (connectionID: Capability.ConnectionID) => Effect.Effect<void>
  clear: () => Effect.Effect<void>
}

/** Metadata only. Callers must authorize disclosure before read, and authorize narrowing before reissue.
 * Identity and cross-scope checks are not grants. canonicalIdentity is a private registration token,
 * never serialized; callers must supply current generations and identity from their authoritative source.
 */
export function make(options: { maxEntries: number; ttlMillis: number; now: () => number }): Effect.Effect<Store> {
  return Effect.sync(() => {
    const maxEntries = options.maxEntries
    const ttlMillis = options.ttlMillis
    const now = options.now
    if (!Number.isSafeInteger(maxEntries) || maxEntries <= 0 || !Number.isFinite(ttlMillis) || ttlMillis <= 0)
      throw new RangeError("Descriptor bounds must be positive; maxEntries must be a safe integer")
    const records = new Map<Capability.DescriptorID, DescriptorRecord>()
    const check = (ref: Capability.DescriptorRef, scope: ReadScope) => {
      const record = records.get(ref.id)
      const currentTime = now()
      if (!record || !Number.isFinite(currentTime) || record.expiresAt <= currentTime)
        return failure("stale_descriptor")
      if (
        !sameLocation(record.owner, scope.owner) ||
        record.owner.projectID !== scope.owner.projectID ||
        record.owner.sessionID !== scope.owner.sessionID ||
        record.owner.agentID !== scope.owner.agentID
      )
        return failure("target_denied")
      if (
        Option.isNone(Schema.decodeUnknownOption(Capability.DescriptorRef)(ref)) ||
        ref.schemaHash !== record.ref.schemaHash ||
        ref.catalogGeneration !== record.ref.catalogGeneration ||
        ref.connectionID !== record.ref.connectionID ||
        ref.targetID !== record.ref.targetID ||
        scope.schemaHash !== record.ref.schemaHash ||
        scope.catalogGeneration !== record.ref.catalogGeneration ||
        scope.connectionGeneration !== record.connectionGeneration ||
        scope.targetGeneration !== record.targetGeneration ||
        scope.canonicalIdentity !== record.canonicalIdentity
      )
        return failure("stale_descriptor")
      return record
    }
    // Synchronous state transition: no Effect may separate validation from insertion.
    const create = (input: IssueInput, storage = records): DescriptorRecord | Capability.Failure => {
      const issuedAt = now()
      const expiresAt = issuedAt + ttlMillis
      if (!Number.isFinite(issuedAt) || !Number.isFinite(expiresAt)) return failure("stale_descriptor")
      Array.from(storage.entries()).forEach(([id, record]) => {
        if (record.expiresAt <= issuedAt) storage.delete(id)
      })
      if (storage.size >= maxEntries) return failure("quota_exceeded")
      const ref = Schema.decodeUnknownOption(Capability.DescriptorRef)({
        id: Capability.DescriptorID.create(),
        schemaHash: input.schemaHash,
        catalogGeneration: input.catalogGeneration,
        connectionID: input.connectionID,
        targetID: input.targetID,
      })
      const owner = Schema.decodeUnknownOption(OwnerInput)(input.owner)
      if (
        Option.isNone(ref) ||
        Option.isNone(owner) ||
        [input.connectionGeneration, input.targetGeneration].some((x) => !Number.isSafeInteger(x) || x < 0) ||
        typeof input.canonicalIdentity !== "object" ||
        input.canonicalIdentity === null ||
        typeof input.canonicalName !== "string" ||
        !input.canonicalName ||
        typeof input.operationID !== "string" ||
        !input.operationID
      )
        return failure("stale_descriptor")
      if (
        Option.isNone(Schema.decodeUnknownOption(Schema.Json)(input.inputSchema)) ||
        (input.outputSchema !== undefined && Option.isNone(Schema.decodeUnknownOption(Schema.Json)(input.outputSchema)))
      )
        return failure("unsupported_schema")
      const record = {
        ref: Object.freeze(ref.value),
        owner: Object.freeze({ ...owner.value, location: Object.freeze({ ...owner.value.location }) }),
        connectionGeneration: input.connectionGeneration,
        targetGeneration: input.targetGeneration,
        canonicalName: input.canonicalName,
        canonicalIdentity: input.canonicalIdentity,
        inputSchema: snapshot(input.inputSchema),
        ...(input.outputSchema === undefined ? {} : { outputSchema: snapshot(input.outputSchema) }),
        operationID: input.operationID,
        issuedAt,
        expiresAt,
      }
      Object.defineProperty(record, "canonicalIdentity", { enumerable: false })
      Object.freeze(record)
      storage.set(record.ref.id, record)
      return record
    }
    return {
      issueBatch: (inputs) => Effect.suspend(() => {
        if (inputs.length > maxEntries) return Effect.fail(failure("quota_exceeded"))
        const staged = new Map(records)
        const issued = inputs.map((input) => create(input, staged))
        const failed = issued.find((record) => record instanceof Capability.Failure)
        if (failed instanceof Capability.Failure) {
          return Effect.fail(failed)
        }
        records.clear()
        staged.forEach((record, id) => records.set(id, record))
        return Effect.succeed(issued.filter((record): record is DescriptorRecord => !(record instanceof Capability.Failure)))
      }),
      remove: (ref) => Effect.sync(() => {
        const record = records.get(ref.id)
        if (record && ref.connectionID === record.ref.connectionID && ref.targetID === record.ref.targetID &&
          ref.catalogGeneration === record.ref.catalogGeneration && ref.schemaHash === record.ref.schemaHash)
          records.delete(ref.id)
      }),
      issue: (input) =>
        Effect.suspend(() => {
          const record = create(input)
          return record instanceof Capability.Failure ? Effect.fail(record) : Effect.succeed(record)
        }),
      read: (ref, scope) =>
        Effect.suspend(() => {
          const record = check(ref, scope)
          return record instanceof Capability.Failure ? Effect.fail(record) : Effect.succeed(record)
        }),
      reissue: (ref, oldScope, newOwner) =>
        Effect.suspend(() => {
          const previous = check(ref, oldScope)
          if (previous instanceof Capability.Failure) return Effect.fail(previous)
          const owner = Schema.decodeUnknownOption(OwnerInput)(newOwner)
          if (
            Option.isNone(owner) ||
            owner.value.projectID !== previous.owner.projectID ||
            !sameLocation(owner.value, previous.owner)
          )
            return Effect.fail(failure("target_denied"))
          // Trusted caller supplies the explicitly authorized new Session/actor; no grant is retained.
          const record = create({
            ...previous,
            ...previous.ref,
            canonicalIdentity: previous.canonicalIdentity,
            owner: owner.value,
          })
          return record instanceof Capability.Failure ? Effect.fail(record) : Effect.succeed(record)
        }),
      invalidateConnection: (connectionID) =>
        Effect.sync(() => {
          Array.from(records.entries()).forEach(([id, record]) => {
            if (record.ref.connectionID === connectionID) records.delete(id)
          })
        }),
      clear: () => Effect.sync(() => records.clear()),
    }
  })
}

function sameLocation(left: Capability.Owner, right: Capability.Owner) {
  return (
    left.location.directory === right.location.directory && left.location.workspaceID === right.location.workspaceID
  )
}

function failure(code: Capability.ErrorCode) {
  return new Capability.Failure({ code, message: "Descriptor unavailable" })
}

function snapshot(value: Schema.Json): Schema.Json {
  if (value === null || typeof value !== "object") return value
  if (Array.isArray(value)) return Object.freeze(value.map(snapshot))
  return Object.freeze(Object.fromEntries(Object.entries(value).map(([key, item]) => [key, snapshot(item)])))
}

export * as CapabilityVendorSchema from "./schema"

import { createHash } from "node:crypto"
import type { Options, ValidateFunction } from "ajv"
import type { FormatName } from "ajv-formats"
import { Effect, Schema } from "effect"
import { Capability } from "@orchestra/schema/capability"

export const bounds = Object.freeze({ maxNodes: 4096, maxDepth: 64, maxBytes: 262144 })
// Explicit validation formats only. Annotation-only formats (password/binary) are not validators.
export const formats: readonly FormatName[] = Object.freeze([
  "date", "time", "date-time", "duration", "uri", "uri-reference", "uri-template", "email", "hostname",
  "ipv4", "ipv6", "regex", "uuid", "json-pointer", "json-pointer-uri-fragment", "relative-json-pointer",
])
export type Coverage = Readonly<{ input: "validated"; output: "validated" | "unvalidated" }>
export type Validation =
  | Readonly<{ valid: true; value: Schema.Json; coverage: "validated" | "unvalidated" }>
  | Readonly<{ valid: false; failure: Capability.Failure }>
export type Validator = Readonly<{
  schemaHash: string
  inputSchema: Schema.Json
  outputSchema?: Schema.Json
  coverage: Coverage
  validateInput: (value: unknown) => Validation
  validateOutput: (value: unknown) => Validation
}>

/** The only heavy boundary: no Ajv import or compilation during module/service construction.
 * Canonical leaves must check validateInput before dispatch and validateOutput before projection.
 */
export const compile = Effect.fn("CapabilityVendorSchema.compile")(function* (
  inputSchema: Schema.Json,
  outputSchema?: Schema.Json,
): Effect.fn.Return<Validator, Capability.Failure> {
  const input = snapshot(inputSchema)
  if (input instanceof Capability.Failure) return yield* input
  const output = outputSchema === undefined ? undefined : snapshot(outputSchema)
  if (output instanceof Capability.Failure) return yield* output
  const inputDialect = dialect(input)
  const outputDialect = output === undefined ? undefined : dialect(output)
  if (inputDialect instanceof Capability.Failure) return yield* inputDialect
  if (outputDialect instanceof Capability.Failure) return yield* outputDialect
  const options: Options = {
    strict: true, allowUnionTypes: true, coerceTypes: false, useDefaults: false, removeAdditional: false,
    validateFormats: true, allErrors: false, ownProperties: true, logger: false,
  }
  const { default: addFormats } = yield* Effect.tryPromise({
    try: () => import("ajv-formats"), catch: unsupported,
  })
  const build = Effect.fnUntraced(function* (schema: Schema.Json, draft: Draft) {
    const engine = yield* Effect.tryPromise({
      try: async () => {
        if (draft === "2020-12") {
          const { Ajv2020 } = await import("ajv/dist/2020.js")
          return new Ajv2020(options)
        }
        if (draft === "2019-09") {
          const { Ajv2019 } = await import("ajv/dist/2019.js")
          return new Ajv2019(options)
        }
        const { Ajv } = await import("ajv")
        return new Ajv(options)
      }, catch: unsupported,
    })
    return yield* Effect.try({
      try: () => {
        addFormats(engine, { formats: [...formats], mode: "full", keywords: false })
        const checked = requireSchema(schema, engine)
        return engine.compile<Schema.Json>(checked)
      }, catch: unsupported,
    })
  })
  const validateInput = yield* build(input, inputDialect)
  const validateOutput = output === undefined || outputDialect === undefined ? undefined : yield* build(output, outputDialect)
  return Object.freeze({
    schemaHash: hash({ input, output: output ?? null, outputPresent: output !== undefined }),
    inputSchema: input,
    ...(output === undefined ? {} : { outputSchema: output }),
    coverage: Object.freeze({ input: "validated", output: output === undefined ? "unvalidated" : "validated" }),
    validateInput: (value: unknown) => validate(value, validateInput),
    validateOutput: (value: unknown) => validate(value, validateOutput),
  })
})

type Draft = "07" | "2019-09" | "2020-12"

function dialect(schema: Schema.Json): Draft | Capability.Failure {
  if (typeof schema === "boolean") return "07"
  if (!schema || typeof schema !== "object" || isArray(schema)) return unsupported()
  if (schema.$schema === undefined || schema.$schema === "http://json-schema.org/draft-07/schema#" ||
    schema.$schema === "https://json-schema.org/draft-07/schema#") return "07"
  if (schema.$schema === "https://json-schema.org/draft/2019-09/schema") return "2019-09"
  if (schema.$schema === "https://json-schema.org/draft/2020-12/schema") return "2020-12"
  return unsupported()
}

// Ajv strictSchema rejects active unknown keywords. Inspect every schema position too: unused $defs
// must not conceal unsupported keywords, formats, async validation or external reference acquisition.
function requireSchema(schema: Schema.Json, engine: { RULES: { keywords: { [name: string]: boolean | undefined } } }): boolean | Record<string, Schema.Json> {
  if (typeof schema === "boolean") return schema
  if (!schema || typeof schema !== "object" || isArray(schema)) throw unsupported()
  Object.entries(schema).forEach(([key, value]) => {
    if (!engine.RULES.keywords[key]) throw unsupported()
    if (key === "$async" || key === "$vocabulary") throw unsupported()
    if (["$ref", "$dynamicRef", "$recursiveRef"].includes(key) &&
      (typeof value !== "string" || !value.startsWith("#"))) throw unsupported()
    if (key === "format" && (typeof value !== "string" || !formats.some((format) => format === value))) throw unsupported()
    if (key === "$schema" && dialect(schema) instanceof Capability.Failure) throw unsupported()
    if (["properties", "patternProperties", "$defs", "definitions", "dependentSchemas"].includes(key)) {
      if (!value || typeof value !== "object" || isArray(value)) throw unsupported()
      Object.values(value).forEach((child) => requireSchema(child, engine))
    }
    if (["allOf", "anyOf", "oneOf", "prefixItems"].includes(key)) {
      if (!isArray(value)) throw unsupported()
      value.forEach((child) => requireSchema(child, engine))
    }
    if (["not", "if", "then", "else", "contains", "propertyNames", "additionalProperties", "unevaluatedProperties",
      "additionalItems", "unevaluatedItems", "items"].includes(key)) {
      if (key === "items" && isArray(value)) value.forEach((child) => requireSchema(child, engine))
      else requireSchema(value, engine)
    }
    if (key === "dependencies" && value && typeof value === "object" && !isArray(value))
      Object.values(value).filter((child) => !isArray(child)).forEach((child) => requireSchema(child, engine))
  })
  return schema
}

function validate(value: unknown, validator?: ValidateFunction<Schema.Json>): Validation {
  const json = snapshot(value)
  if (json instanceof Capability.Failure || (validator && !validator(json))) return {
    valid: false, failure: new Capability.Failure({ code: "unsupported_schema", message: "Vendor value does not match supported schema" }),
  }
  return { valid: true, value: json, coverage: validator ? "validated" : "unvalidated" }
}

/** Bounded JSON copy before recursive schema parsing or serialization. Reject cycles/non-JSON values. */
export function snapshot(value: unknown): Schema.Json | Capability.Failure {
  const budget = { nodes: 0, bytes: 0 }
  const path = new WeakSet<object>()
  const copy = (value: unknown, depth: number): Schema.Json | Capability.Failure => {
    budget.nodes++
    if (depth > bounds.maxDepth || budget.nodes > bounds.maxNodes) return unsupported()
    if (value === null || typeof value === "boolean") return value
    if (typeof value === "number") return Number.isFinite(value) ? value : unsupported()
    if (typeof value === "string") {
      budget.bytes += Buffer.byteLength(value)
      return budget.bytes > bounds.maxBytes ? unsupported() : value
    }
    if (typeof value !== "object" || path.has(value)) return unsupported()
    if (!Array.isArray(value) && Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null)
      return unsupported()
    path.add(value)
    const entries = Object.entries(value)
    if (entries.length > bounds.maxNodes - budget.nodes) return unsupported()
    if (Array.isArray(value) && (entries.length !== value.length || entries.some(([key], index) => key !== String(index))))
      return unsupported()
    const result: Schema.Json = Array.isArray(value) ? [] : {}
    const error = entries.some(([key, item]) => {
      budget.bytes += Buffer.byteLength(key)
      if (budget.bytes > bounds.maxBytes) return true
      const child = copy(item, depth + 1)
      if (child instanceof Capability.Failure) return true
      Object.defineProperty(result, key, { value: child, enumerable: true, configurable: false, writable: false })
      return false
    })
    path.delete(value)
    return error ? unsupported() : Object.freeze(result)
  }
  const result = copy(value, 0)
  if (result instanceof Capability.Failure) return result
  return Buffer.byteLength(JSON.stringify(result)) > bounds.maxBytes ? unsupported() : result
}

export function hash(value: Schema.Json): string {
  const canonical = (value: Schema.Json): string => {
    if (!value || typeof value !== "object") return JSON.stringify(value)
    if (isArray(value)) return `[${value.map(canonical).join(",")}]`
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(",")}}`
  }
  return createHash("sha256").update(canonical(value)).digest("hex")
}

function isArray(value: Schema.Json): value is Schema.JsonArray {
  return Array.isArray(value)
}

function unsupported() {
  return new Capability.Failure({ code: "unsupported_schema", message: "Vendor schema is unsupported" })
}

export * as CapabilityServiceProjection from "./projection"

import { Capability } from "@orchestra/schema/capability"
import type { Credential } from "@orchestra/schema/credential"
import { Cause, Context, Effect, Exit } from "effect"
import { EffectDrizzleQueryError } from "drizzle-orm/effect-core/errors"
import { SqlError } from "effect/unstable/sql/SqlError"
import { CapabilityArtifacts } from "../../artifact/index"
import type { CapabilityConnections } from "../../connection/index"
import type { Tool } from "../../../tool/tool"
import type { CapabilityVendorSchema } from "../../catalog/schema"
import type { CapabilityJobs } from "../../job/index"
import type { CapabilityMcp } from "../../mcp/index"
import type { CapabilityServiceContract } from "../contract"
import type { CapabilityServiceSchema } from "../schema"
import { CapabilityServiceData } from "./data"

export function partial(receipt: CapabilityJobs.Receipt, output: "validated" | "unvalidated" | "failed", unresolved: string[],
  redacted = false): CapabilityServiceSchema.CallOutput {
  return { result: { status: "partial", receipt: receipt.ref.id, summary: "Service response requires reconciliation",
    completedEffects: receipt.observation.remoteOutcome === "completed" ? ["provider-acknowledged"] : [],
    unresolvedEffects: unresolved, artifactRefs: receipt.observation.artifactRefs ?? [] },
    validation: { input: "validated", output }, redacted }
}

export function replay(receipt: CapabilityJobs.Receipt): CapabilityServiceSchema.CallOutput {
  if (receipt.state === "completed") return partial(receipt, "unvalidated", ["output-unavailable"])
  if (receipt.state === "failed") return partial(receipt, "unvalidated", ["provider-reported-error"])
  return { result: { status: "unknown", receipt: receipt.ref.id, summary: "Service call outcome unknown" },
    validation: { input: "validated", output: "unvalidated" }, redacted: false }
}

/** Known ACK is already durable. Expected validation/publication failures only affect materialization. */
export const project = Effect.fn("CapabilityServiceExecution.project")(function* (input: {
  options: CapabilityServiceContract.Options
  context: Tool.Context
  proof: CapabilityJobs.ProducerProof
  receipt: CapabilityJobs.Receipt
  response: CapabilityMcp.CallResult
  validator: CapabilityVendorSchema.Validator
  credential: Credential.Value
  resolution: CapabilityConnections.Resolution
  endpoint: string
  resources: readonly string[]
  revalidate: Effect.Effect<void, Capability.Failure>
  disclose: Effect.Effect<void, Capability.Failure>
}): Effect.fn.Return<CapabilityServiceSchema.CallOutput, Capability.Failure> {
  const raw = CapabilityServiceData.snapshot(input.response)
  const validation = input.validator.outputSchema === undefined
    ? !(raw instanceof Capability.Failure) : input.response.structuredContent !== undefined &&
      input.validator.validateOutput(input.response.structuredContent).valid
  const output = validation ? input.validator.coverage.output : "failed"
  const observe = (observation: CapabilityJobs.Observation) => input.options.jobs.observeHost(input.proof, input.receipt.ref, {
    expectedGeneration: input.receipt.generation, state: input.receipt.state,
    observation: { remoteOutcome: input.response.isError ? "failed" : "completed", ...observation },
  })
  if (!validation || raw instanceof Capability.Failure) {
    const receipt = yield* observe(input.response.isError ? {} : { materialization: "failed" })
    return partial(receipt, "failed", ["output-validation", ...(input.response.isError ? ["provider-reported-error"] : [])])
  }
  const projected = CapabilityServiceData.redact(raw, input.credential, input.endpoint)
  const serialized = JSON.stringify(projected.data)
  const resource = CapabilityServiceData.snapshot(input.resolution.resource)
  if (resource instanceof Capability.Failure) {
    const receipt = yield* observe(input.response.isError ? {} : { materialization: "failed" })
    return partial(receipt, output, ["output-materialization"], projected.redacted)
  }
  // Host-only condition captured before the publication's approval wait; never part of provider data or metadata.
  const selection = Object.freeze({ resolution: Object.freeze({ ...input.resolution, resource,
    connection: Object.freeze({ ...input.resolution.connection }), target: Object.freeze({ ...input.resolution.target }),
  }), credentialHash: CapabilityArtifacts.selectionCredentialHash(input.credential) })
  const published = yield* Effect.gen(function* () {
    yield* input.revalidate
    if (Buffer.byteLength(serialized) <= 8192) return []
    const ref = yield* input.options.artifacts.publish(input.context, {
      data: new TextEncoder().encode(serialized), mime: "application/json", kind: "service-response",
      verification: "acknowledged", metadata: {},
    }, [{ action: "service_call", resources: input.resources, selection }])
    return [ref]
  }).pipe(Effect.exit)
  if (Exit.isFailure(published)) {
    if (!expected(published.cause)) return yield* fatal(published.cause)
    const receipt = yield* observe(input.response.isError ? {} : { materialization: "failed" })
    return partial(receipt, output, ["output-materialization", ...(input.response.isError ? ["provider-reported-error"] : [])], projected.redacted)
  }
  const receipt = yield* observe({ artifactRefs: published.value,
    ...(input.response.isError ? {} : { materialization: "complete" as const }) })
  const result: Capability.Result = input.response.isError
    ? partial(receipt, output, ["provider-reported-error"], projected.redacted).result
    : { status: "completed", receipt: receipt.ref.id, summary: "Service response acknowledged",
      artifactRefs: published.value, verification: "acknowledged" }
  if (published.value.length > 0) return { result, validation: { input: "validated", output }, redacted: projected.redacted }
  // Persistence and all potential permission waits precede the final inline disclosure fence.
  const disclosed = yield* input.disclose.pipe(Effect.exit)
  if (Exit.isFailure(disclosed)) {
    if (!expected(disclosed.cause)) return yield* fatal(disclosed.cause)
    return partial(receipt, output, ["output-disclosure"], projected.redacted)
  }
  return { result, validation: { input: "validated", output }, redacted: projected.redacted, data: projected.data }
})

function expected(cause: Cause.Cause<unknown>) {
  return cause.reasons.length > 0 && cause.reasons.every((reason) => reason._tag === "Fail" &&
    (reason.error instanceof Capability.Failure || reason.error instanceof CapabilityArtifacts.Failure))
}

/** beta83 typed-error combinators extract one Fail. Promote per reason before leaving the business contract. */
export function fatal(cause: Cause.Cause<unknown>) {
  return Effect.failCause(Cause.fromReasons<never>(cause.reasons.map((reason) => {
    if (reason._tag === "Interrupt") return reason
    const error = reason._tag === "Fail" ? reason.error : reason.defect
    const sql = error instanceof SqlError || error instanceof EffectDrizzleQueryError
    if (reason._tag === "Die" && !sql) return reason
    return Cause.makeDieReason(sql ? CapabilityServiceData.failure("connection_unavailable") : error)
      .annotate(Context.makeUnsafe(new Map(reason.annotations)))
  })))
}

export * as CapabilityServiceData from "./data"

import { Capability } from "@orchestra/schema/capability"
import type { Credential } from "@orchestra/schema/credential"
import { Option, Schema } from "effect"
import { CapabilityVendorSchema } from "../../catalog/schema"
import { CapabilityServiceSchema } from "../schema"

const Envelope = Schema.Struct({ provider: Schema.String, input: CapabilityServiceSchema.CallInput,
  context: Schema.Struct({ sessionID: Capability.InvocationRef.fields.sessionID, agent: Capability.InvocationRef.fields.agentID,
    assistantMessageID: Capability.InvocationRef.fields.assistantMessageID, toolCallID: Schema.NonEmptyString }),
})
const providers = new Set(["cloudflare", "supabase", "vercel", "neon", "railway", "sentry", "grafana", "globalping",
  "linear", "stripe", "netlify", "prisma_postgres"])

/** Descriptor-only traversal before VendorSchema.snapshot: that shared copier reads enumerable values. */
export function snapshot(value: unknown): Schema.Json | Capability.Failure {
  const seen = new Set<object>()
  const budget = { nodes: 0, bytes: 0 }
  const copy = (value: unknown, depth: number): Schema.Json | Capability.Failure => {
    if (++budget.nodes > 4096 || depth > 64) return failure("quota_exceeded")
    if (value === null || typeof value === "boolean") return value
    if (typeof value === "number") return Number.isFinite(value) ? value : failure("unsupported_schema")
    if (typeof value === "string") {
      budget.bytes += Buffer.byteLength(value)
      return budget.bytes <= 262144 ? value : failure("quota_exceeded")
    }
    if (typeof value !== "object" || seen.has(value)) return failure("unsupported_schema")
    if (Object.getPrototypeOf(value) !== (Array.isArray(value) ? Array.prototype : Object.prototype) &&
      (Array.isArray(value) || Object.getPrototypeOf(value) !== null)) return failure("unsupported_schema")
    const serializer = Object.getOwnPropertyDescriptor(value, "toJSON")
    if (serializer && (!("value" in serializer) || typeof serializer.value === "function")) return failure("unsupported_schema")
    const keys = Object.keys(value)
    if (keys.length > 4096 - budget.nodes || Array.isArray(value) &&
      (keys.length !== value.length || keys.some((key, index) => key !== String(index)))) return failure("quota_exceeded")
    seen.add(value)
    const result: Schema.Json = Array.isArray(value) ? [] : {}
    const rejected: { failure?: Capability.Failure } = {}
    const invalid = keys.some((key) => {
      const property = Object.getOwnPropertyDescriptor(value, key)
      if (!property || !("value" in property)) return true
      budget.bytes += Buffer.byteLength(key)
      if (budget.bytes > 262144) { rejected.failure = failure("quota_exceeded"); return true }
      const child = copy(property.value, depth + 1)
      if (child instanceof Capability.Failure) { rejected.failure = child; return true }
      Object.defineProperty(result, key, { value: child, enumerable: true })
      return false
    })
    seen.delete(value)
    return rejected.failure ?? (invalid ? failure("unsupported_schema") : Object.freeze(result))
  }
  const copied = copy(value, 0)
  return copied instanceof Capability.Failure ? copied : CapabilityVendorSchema.snapshot(copied)
}

export function input(value: { readonly provider: string; readonly input: unknown; readonly context: object }) {
  // The registry Context also carries the turn's optional model (often an explicit undefined, which no JSON snapshot
  // admits). Copy only the invocation identity, from own data properties, so no caller accessor runs.
  const fields = Object.keys(Envelope.fields.context.fields).map((key) => [key, Object.getOwnPropertyDescriptor(value.context, key)] as const)
  if (fields.some(([, property]) => property && !("value" in property))) return failure("unsupported_schema")
  const context = Object.fromEntries(fields.flatMap(([key, property]) => property ? [[key, property.value]] : []))
  const fixed = snapshot({ provider: value.provider, input: value.input, context })
  if (fixed instanceof Capability.Failure) return fixed
  const decoded = Schema.decodeUnknownOption(Envelope)(fixed)
  if (Option.isNone(decoded)) return failure("unsupported_schema")
  const provider = decoded.value.provider.trim().toLowerCase().replaceAll("-", "_")
  if (!providers.has(provider)) return failure("unsupported_operation")
  return { ...decoded.value, provider, context: Object.freeze(decoded.value.context) }
}

export function object(value: Schema.Json): value is Schema.JsonObject {
  return value !== null && typeof value === "object" && !Array.isArray(value)
}

/** Explicit host argument profile only; endpoint, headers and inferred semantic fields grant nothing. */
export function argumentsFor(supplied: Schema.Json, resource: Schema.Json) {
  const selected = snapshot(resource)
  if (selected instanceof Capability.Failure) return selected
  if (!object(supplied) || !object(selected) || Object.keys(selected).some((key) => key !== "arguments") ||
    (selected.arguments !== undefined && !object(selected.arguments))) return failure("target_denied")
  const bound = selected.arguments === undefined ? {} : selected.arguments
  if (!object(bound)) return failure("target_denied")
  if (Object.keys(bound).some((key) => Object.hasOwn(supplied, key) &&
    CapabilityVendorSchema.hash(supplied[key]) !== CapabilityVendorSchema.hash(bound[key]))) return failure("target_denied")
  return snapshot({ ...supplied, ...bound })
}

export function credentialIdentity(value: Credential.Value) {
  return value.type === "key" ? JSON.stringify([value.type, value.key])
    : JSON.stringify([value.type, value.methodID, value.access, value.refresh, value.expires])
}

export function credentialFailure(value: Credential.Value) {
  const token = value.type === "key" ? value.key : value.access
  return !token || token.length > 16384 || !/^[\x21-\x7e]+(?![\s\S])/.test(token) ||
    value.type === "oauth" && (!Number.isSafeInteger(value.expires) || value.expires <= Date.now())
    ? failure("authentication_required") : undefined
}

/** Validate raw vendor data first. Projection intentionally need not satisfy the vendor schema after redaction. */
export function redact(value: Schema.Json, credential: Credential.Value, endpoint: string) {
  const secrets = (credential.type === "key" ? [credential.key] : [credential.access, credential.refresh])
    .concat(endpoint).filter((value) => value.length > 0).sort((a, b) => b.length - a.length)
  const state = { redacted: false }
  const text = (value: string) => secrets.reduce((value, secret) => {
    if (value.includes(secret)) state.redacted = true
    return value.replaceAll(secret, "[REDACTED]")
  }, value)
  const hidden = new Set(["headers", "authorization", "credential", "credentials", "scopes", "endpoint", "sessionID",
    "session_id", "mcp-session-id", "proof", "rules", "effectiveRules", "nativeDenyFloor", "_meta"])
  const copy = (value: Schema.Json): Schema.Json => {
    if (typeof value === "string") return text(value)
    if (!value || typeof value !== "object") return value
    if (Array.isArray(value)) return value.map(copy)
    if (!object(value)) return null
    return Object.fromEntries(Object.entries(value).flatMap(([key, item]) => {
      if (hidden.has(key) || (value.type === "image" || value.type === "audio") && key === "data" || key === "blob") {
        state.redacted = true
        return []
      }
      return [[text(key), copy(item)]]
    }))
  }
  const data = copy(value)
  return { data, redacted: state.redacted }
}

export function failure(code: Capability.Failure["code"]) {
  return new Capability.Failure({ code, message: "Service call unavailable" })
}

export * as ArtifactBlobs from "./blob"

import { createHash } from "node:crypto"
import { constants, type BigIntStats } from "node:fs"
import { lstat, mkdir, open, realpath, type FileHandle } from "node:fs/promises"
import { dirname, join, resolve } from "node:path"
import { Effect, Ref } from "effect"
import type { FSUtil } from "../../fs-util"
import { Failure, failure } from "./error"
import { matchesMime } from "./mime"

export function hash(data: Uint8Array | string) {
  return createHash("sha256").update(data).digest("hex")
}

/**
 * No model/worker-selected paths: private canonical roots and checked file lifetimes limit their authority.
 * Lifetimes retain root/staging identity and stop on observed legitimate host replacement. Node path APIs
 * cannot anchor every directory-relative syscall, so check-to-syscall races remain; postchecks do not prove
 * absolute confinement against a malicious same-UID host. Reads still bind no-follow, bounded I/O to one FD.
 */
export function make(input: { root: string; boundedBytes: number; storageID: string; fs: FSUtil.Interface }) {
  const root = resolve(input.root)
  const identity = new TextEncoder().encode(hash(input.storageID))
  const io = <A>(body: () => Promise<A>) => Effect.tryPromise({
    try: body,
    catch: (error) => error instanceof Failure ? error : failure("artifact_io_failed", "Artifact filesystem operation failed"),
  })
  const rootInfo = () => directory(root, true)
  const claimedRoot = async (create: boolean) => {
    if (create) await ensureDirectory(root)
    const info = await rootInfo()
    if (create) await withFile(join(root, ".store"), writeFlags(), 0o600, async (file) => {
      await file.writeFile(identity)
      await file.chmod(0o400)
      await file.sync()
    }).catch((error: unknown) => {
      if (!hasCode(error, "EEXIST")) throw error
    })
    const marker = await readBytes(join(root, ".store"), identity.length, info, 1, identity.length)
    if (!marker.every((byte, index) => byte === identity[index]))
      throw failure("artifact_io_failed", "Artifact root belongs to another database")
    return info
  }

  const read = Effect.fn("ArtifactBlobs.read")(function* (
    digest: string, bytes: number, mime: string,
  ): Effect.fn.Return<Uint8Array, Failure> {
    if (!/^[0-9a-f]{64}(?![\s\S])/.test(digest) || !Number.isSafeInteger(bytes) || bytes < 0 || bytes > input.boundedBytes)
      return yield* failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
    const data = yield* io(async () => readBytes(join(root, digest), bytes, await claimedRoot(false), 1)).pipe(
      Effect.mapError(() => failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")),
    )
    if (hash(data) !== digest || !matchesMime(data, mime))
      return yield* failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
    return data
  })

  const publish = Effect.fn("ArtifactBlobs.publish")(function* (data: Uint8Array, mime: string) {
    if (data.byteLength > input.boundedBytes)
      return yield* failure("invalid_input", "Artifact blob exceeds byte bound")
    const digest = hash(data)
    const info = yield* io(() => claimedRoot(true))
    const cleanupFailure = yield* Ref.make<Failure | undefined>(undefined)
    yield* Effect.scoped(Effect.gen(function* () {
      const staging = yield* Effect.acquireRelease(
        Effect.gen(function* () {
          yield* io(() => unchangedRoot(info))
          const path = yield* input.fs.makeTempDirectory({ directory: root, prefix: "stage-" })
          const stat = yield* io(async () => {
            await unchangedRoot(info)
            return directory(path, true)
          })
          return { path, stat }
        }),
        // Finalizers cannot fail typed. Retain the failure so successful body verification cannot erase identity loss.
        (staging) => removeChecked(staging.path, staging.stat, info, true).pipe(Effect.catch((error) =>
          Ref.set(cleanupFailure, error instanceof Failure ? error
            : failure("artifact_io_failed", "Artifact scratch cleanup failed")),
        )),
      )
      const path = join(staging.path, "blob")
      yield* io(async () => {
        await unchangedRoot(info)
        if (!sameFile(staging.stat, await directory(staging.path, true)))
          throw failure("artifact_io_failed", "Artifact staging directory changed during access")
        await withFile(path, writeFlags(), 0o600, async (file) => {
          regular(await file.stat({ bigint: true }), false, 1)
          await file.writeFile(data)
          await file.chmod(0o400)
          await file.sync()
        })
        const verified = await readBytes(path, data.byteLength, info, 1)
        if (hash(verified) !== digest || !matchesMime(verified, mime))
          throw failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
      })
      yield* input.fs.link(path, join(root, digest)).pipe(Effect.catchIf(
        (error) => error.reason._tag === "AlreadyExists", () => Effect.void,
      ))
      const linked = yield* io(async () => readBytes(join(root, digest), data.byteLength, info, 2))
      if (hash(linked) !== digest || !matchesMime(linked, mime))
        return yield* failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
    })).pipe(Effect.catchTag("PlatformError", () => Effect.fail(failure("artifact_io_failed", "Artifact blob publication failed"))))
    const failed = yield* Ref.get(cleanupFailure)
    if (failed) return yield* failed
    // Final verification belongs to the original root lifetime, never a freshly adopted replacement root.
    const final = yield* io(() => readBytes(join(root, digest), data.byteLength, info, 1))
    if (hash(final) !== digest || !matchesMime(final, mime))
      return yield* failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
    return digest
  })

  const cleanup = Effect.fn("ArtifactBlobs.cleanup")(function* (retained: ReadonlySet<string>, cutoff: number) {
    const info = yield* io(() => claimedRoot(false)).pipe(Effect.catchIf(
      (error) => error.code === "artifact_io_failed", () => Effect.succeed(undefined),
    ))
    if (!info) {
      // Missing roots are normal before first publication; an existing unsafe root is a named failure.
      const absent = yield* io(() => lstat(root, { bigint: true }).then(() => false, (error: unknown) => {
        if (hasCode(error, "ENOENT")) return true
        throw error
      }))
      if (absent) return
      return yield* failure("artifact_io_failed", "Artifact cleanup root is unavailable")
    }
    const names = yield* input.fs.readDirectory(root)
    yield* Effect.forEach(names.filter((name) => !retained.has(name) &&
      (/^[0-9a-f]{64}(?![\s\S])/.test(name) || /^stage-[a-zA-Z0-9_-]+(?![\s\S])/.test(name))),
    (name) => Effect.gen(function* () {
      const path = join(root, name)
      const stat = yield* io(async () => {
        await unchangedRoot(info)
        const current = await lstat(path, { bigint: true })
        if (current.isSymbolicLink()) throw failure("artifact_io_failed", "Artifact cleanup entry is unsafe")
        return current
      })
      if (stat.mtimeMs < BigInt(cutoff)) yield* removeChecked(path, stat, info, name.startsWith("stage-"))
    }))
    yield* io(() => unchangedRoot(info))
  })

  async function unchangedRoot(info: BigIntStats) {
    if (!sameFile(info, await rootInfo())) throw failure("artifact_io_failed", "Artifact root changed during access")
  }

  const removeChecked = Effect.fn("ArtifactBlobs.removeChecked")(function* (
    path: string, expected: BigIntStats, rootStat: BigIntStats, recursive: boolean,
  ) {
    yield* io(async () => {
      await unchangedRoot(rootStat)
      const current = await lstat(path, { bigint: true })
      if (current.isSymbolicLink() || !sameFile(expected, current) || current.isDirectory() !== expected.isDirectory())
        throw failure("artifact_io_failed", "Artifact cleanup entry identity changed")
      if (current.isDirectory()) await directory(path, false)
      await unchangedRoot(rootStat)
    })
    yield* input.fs.remove(path, { recursive })
  })

  async function readBytes(path: string, bytes: number, rootStat: BigIntStats, links: number, limit = input.boundedBytes) {
    if (!Number.isSafeInteger(bytes) || bytes < 0 || bytes > limit)
      throw failure("artifact_corrupt", "Artifact blob exceeds read bound")
    await unchangedRoot(rootStat)
    const before = await lstat(path, { bigint: true })
    regular(before, true, links)
    return withFile(path, readFlags(), undefined, async (file) => {
      const opened = await file.stat({ bigint: true })
      regular(opened, true, links)
      if (!sameFile(before, opened) || opened.size !== BigInt(bytes))
        throw failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
      const data = new Uint8Array(bytes)
      let offset = 0
      while (offset < bytes) {
        const chunk = await file.read(data, offset, Math.min(64 * 1024, bytes - offset), offset)
        if (chunk.bytesRead === 0) throw failure("artifact_corrupt", "Artifact blob is unavailable or corrupt")
        offset += chunk.bytesRead
      }
      const after = await file.stat({ bigint: true })
      if (after.size !== BigInt(bytes) || after.mtimeNs !== opened.mtimeNs || after.ctimeNs !== opened.ctimeNs ||
        !sameFile(after, await lstat(path, { bigint: true }))) throw failure("artifact_corrupt", "Artifact blob changed during access")
      await unchangedRoot(rootStat)
      return data
    })
  }

  return { read, publish, cleanup }
}

async function ensureDirectory(path: string): Promise<void> {
  const existing = await lstat(path, { bigint: true }).catch((error: unknown) => {
    if (hasCode(error, "ENOENT")) return undefined
    throw error
  })
  if (existing) {
    if (!existing.isDirectory() || existing.isSymbolicLink() || await realpath(path) !== path)
      throw failure("artifact_io_failed", "Artifact root is not a canonical directory")
    return
  }
  await ensureDirectory(dirname(path))
  await mkdir(path, { mode: 0o700 }).catch((error: unknown) => {
    if (!hasCode(error, "EEXIST")) throw error
  })
  await directory(path, true)
}

async function directory(path: string, privateMode: boolean) {
  const info = await lstat(path, { bigint: true })
  if (!info.isDirectory() || info.isSymbolicLink() || await realpath(path) !== path ||
    (privateMode && process.platform !== "win32" && (info.mode & 0o777n) !== 0o700n) || !owned(info))
    throw failure("artifact_io_failed", "Artifact root is not a private canonical directory")
  return info
}

function regular(info: BigIntStats, readonly: boolean, links: number) {
  if (!info.isFile() || info.isSymbolicLink() || !owned(info) || info.nlink > BigInt(links) ||
    (process.platform !== "win32" && (info.mode & 0o777n) !== (readonly ? 0o400n : 0o600n)) ||
    (process.platform === "win32" && readonly && (info.mode & 0o222n) !== 0n))
    throw failure("artifact_corrupt", "Artifact blob is not a private regular file")
}

function owned(info: BigIntStats) {
  return typeof process.getuid !== "function" || info.uid === BigInt(process.getuid())
}

function sameFile(left: BigIntStats, right: BigIntStats) {
  if (left.ino !== 0n || right.ino !== 0n) return left.dev === right.dev && left.ino === right.ino
  // Some Windows filesystems omit inode IDs. Bind path/descriptor creation identity and file state instead.
  return left.dev === right.dev && left.birthtimeNs === right.birthtimeNs && left.mode === right.mode &&
    left.uid === right.uid && left.isDirectory() === right.isDirectory() &&
    (left.isDirectory() || (left.size === right.size && left.ctimeNs === right.ctimeNs))
}

function hasCode(error: unknown, code: string) {
  return typeof error === "object" && error !== null && "code" in error && error.code === code
}

function readFlags() {
  return constants.O_RDONLY | (process.platform === "win32" ? 0 : (constants.O_NOFOLLOW ?? 0) | constants.O_NONBLOCK)
}

function writeFlags() {
  return constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0)
}

async function withFile<A>(path: string, flags: number, mode: number | undefined, body: (file: FileHandle) => Promise<A>) {
  const file = await open(path, flags, mode)
  try {
    return await body(file)
  } finally {
    await file.close()
  }
}

export * as CapabilityOperator from "./index"

import { Capability } from "@orchestra/schema/capability"
import { Context, Effect } from "effect"
import { createHash, randomBytes } from "node:crypto"
import type { CapabilityOperatorContract } from "./contract"
import { CapabilityOperatorScope } from "./scope"

const issued = Symbol("CapabilityOperator.issued")
type Frame = CapabilityOperatorContract.Binding & { readonly [issued]: true }
type Entry = {
  readonly scope: CapabilityOperatorContract.GrantScope
  readonly scopeHash: string
  readonly origin: CapabilityOperatorContract.Origin
  readonly expires: number
  readonly digest?: string
  revoked: boolean
}
const Current = Context.Reference<Frame | undefined>("@orchestra/core/CapabilityOperator", {
  defaultValue: () => undefined,
})

export const make: CapabilityOperatorContract.Factory = (options) => {
  const captured = CapabilityOperatorScope.capture(options, CapabilityOperatorScope.options, true)
  return Effect.gen(function* () {
    if (!captured.ok) return yield* failure("target_denied")
    const input = captured.value
    const authorities = new WeakMap<CapabilityOperatorContract.Authority, Entry>()
    const frames = new WeakSet<Frame>()
    const bindings = new WeakSet<CapabilityOperatorContract.Binding>()
    const tokens = new Map<string, CapabilityOperatorContract.Authority>()
    const lifetime = { closed: false }

    function mint(entry: Entry) {
      // The frozen contract hides its brand. This is the only bridge from private minted objects.
      const authority = Object.freeze({ [issued]: true }) as unknown as CapabilityOperatorContract.Authority
      authorities.set(authority, entry)
      return authority
    }

    function active(authority: CapabilityOperatorContract.Authority, now: number) {
      const entry = authorities.get(authority)
      return !lifetime.closed && validTime(now) && entry && !entry.revoked && now < entry.expires ? entry : undefined
    }

    const configured = mint({ scope: input.scope, scopeHash: CapabilityOperatorScope.hash(input.scope),
      origin: "configured-auth", expires: Infinity, revoked: false })
    if (!validTime(input.now())) return yield* failure("target_denied")
    yield* Effect.addFinalizer(() => Effect.sync(() => {
      lifetime.closed = true
      tokens.clear()
    }))

    const issue: CapabilityOperatorContract.Interface["issue"] = (supplied) => {
      const captured = CapabilityOperatorScope.capture(supplied, (value) => {
        const options = CapabilityOperatorScope.record(value, ["origin", "scope", "ttlMillis"])
        if (options.origin !== "desktop" && options.origin !== "cli" && options.origin !== "sdk")
          throw new Error("Invalid operator data")
        return { origin: options.origin, scope: options.scope === undefined ? input.scope : CapabilityOperatorScope.grant(options.scope),
          ttlMillis: options.ttlMillis === undefined ? input.ttlMillis : CapabilityOperatorScope.positive(options.ttlMillis) } as const
      })
      return Effect.suspend(() => {
        if (!captured.ok || !CapabilityOperatorScope.subset(captured.value.scope, input.scope))
          return Effect.fail(failure("target_denied"))
        const now = input.now()
        if (lifetime.closed || !validTime(now)) return Effect.fail(failure("authentication_required"))
        const expires = now + captured.value.ttlMillis
        if (!Number.isFinite(expires) || expires > Number.MAX_SAFE_INTEGER || expires <= now)
          return Effect.fail(failure("target_denied"))
        tokens.forEach((authority, digest) => {
          if (!active(authority, now)) tokens.delete(digest)
        })
        if (tokens.size >= input.maxCapabilities) return Effect.fail(failure("quota_exceeded"))
        const bearer = randomBytes(32).toString("base64url")
        const digest = tokenHash(bearer)
        const authority = mint({ scope: captured.value.scope, scopeHash: CapabilityOperatorScope.hash(captured.value.scope),
          origin: captured.value.origin, expires, digest, revoked: false })
        tokens.set(digest, authority)
        return Effect.succeed(Object.freeze({ bearer, authority }))
      })
    }

    const authenticate: CapabilityOperatorContract.Interface["authenticate"] = (bearer) => Effect.suspend(() => {
      if (typeof bearer !== "string" || !/^[A-Za-z0-9_-]{43}(?![\s\S])/.test(bearer))
        return Effect.fail(failure("authentication_required"))
      const authority = tokens.get(tokenHash(bearer))
      if (!authority || !active(authority, input.now())) return Effect.fail(failure("authentication_required"))
      return Effect.succeed(authority)
    })

    const revoke: CapabilityOperatorContract.Interface["revoke"] = (authority) => Effect.suspend(() => {
      const entry = authorities.get(authority)
      if (lifetime.closed || !entry) return Effect.fail(failure("authentication_required"))
      entry.revoked = true
      if (entry.digest !== undefined) tokens.delete(entry.digest)
      return Effect.void
    })

    const withRequest = <A, E, R>(authority: CapabilityOperatorContract.Authority,
      supplied: Readonly<{ requestID: string; idempotencyKey?: string }>, effect: Effect.Effect<A, E, R>) => {
      const captured = CapabilityOperatorScope.capture(supplied, CapabilityOperatorScope.request)
      return Effect.suspend<A, E | Capability.Failure, R>(() => {
        if (!captured.ok) return Effect.fail(failure("invocation_binding_mismatch"))
        const entry = active(authority, input.now())
        if (!entry) return Effect.fail(failure("authentication_required"))
        const frame: Frame = Object.freeze({ [issued]: true as const, authority, principal: input.principal,
          origin: entry.origin, scopeHash: entry.scopeHash, ...captured.value })
        frames.add(frame)
        return Effect.provideService(effect, Current, frame)
      })
    }

    const require: CapabilityOperatorContract.Interface["require"] = (target) => {
      const captured = CapabilityOperatorScope.capture(target, CapabilityOperatorScope.target)
      return Effect.gen(function* () {
        const frame = yield* Current
        if (frame === undefined) return yield* failure("invocation_binding_missing")
        if (!frames.has(frame) || frame[issued] !== true) return yield* failure("invocation_binding_mismatch")
        const entry = active(frame.authority, input.now())
        if (!entry) return yield* failure("authentication_required")
        if (!captured.ok || !CapabilityOperatorScope.allows(entry.scope, captured.value))
          return yield* failure("target_denied")
        bindings.add(frame)
        return frame
      })
    }

    const validate: CapabilityOperatorContract.Interface["validate"] = (binding, target) => {
      const captured = CapabilityOperatorScope.capture(target, CapabilityOperatorScope.target)
      return Effect.gen(function* () {
        const frame = yield* Current
        if (frame === undefined) return yield* failure("invocation_binding_missing")
        if (frame !== binding || !frames.has(frame) || !bindings.has(binding) || frame[issued] !== true)
          return yield* failure("invocation_binding_mismatch")
        const entry = active(frame.authority, input.now())
        if (!entry) return yield* failure("authentication_required")
        if (!captured.ok || !CapabilityOperatorScope.allows(entry.scope, captured.value))
          return yield* failure("target_denied")
      })
    }

    return Object.freeze({ configured, issue, authenticate, revoke, withRequest, require, validate })
  })
}

function validTime(now: number) {
  return typeof now === "number" && Number.isFinite(now) && now >= 0 && now <= Number.MAX_SAFE_INTEGER
}

function tokenHash(bearer: string) {
  return createHash("sha256").update(bearer).digest("hex")
}

function failure(code: Capability.ErrorCode) {
  return new Capability.Failure({ code, message: code === "target_denied" ? "Capability action is not authorized" :
    code === "quota_exceeded" ? "Capability quota is exhausted" :
    code === "invocation_binding_missing" ? "Capability invocation binding is missing" :
    code === "invocation_binding_mismatch" ? "Capability invocation binding does not match" : "Capability authentication is required" })
}

export * as CapabilityOperatorScope from "./scope"

import { Location } from "@orchestra/schema/location"
import { Project } from "@orchestra/schema/project"
import { Option, Schema } from "effect"
import { createHash } from "node:crypto"
import type { CapabilityOperatorContract } from "./contract"

const Placement = Schema.Struct({ projectID: Project.ID, location: Location.Ref })
const actionPattern = /^[a-z][a-z0-9_.-]{0,63}(?![\s\S])/

/** Copy data descriptors before effects run. Accessors and custom serializers never execute. */
export function capture<A>(input: unknown, parse: (value: unknown) => A, allowClock = false):
  { readonly ok: true; readonly value: A } | { readonly ok: false } {
  try {
    const budget = { nodes: 0, bytes: 0 }
    const value = copy(input, budget, 0, allowClock)
    // Only the copied root clock is metadata. Its serialization hooks must never run.
    const data = allowClock && value !== null && typeof value === "object" && !Array.isArray(value)
      ? Object.fromEntries(Object.entries(value).filter(([key, value]) => key !== "now" || typeof value !== "function"))
      : value
    if (Buffer.byteLength(JSON.stringify(data), "utf8") > 65536) throw new Error("Invalid operator data")
    return { ok: true, value: parse(value) }
  } catch {
    // Reflection can throw for hostile proxies. No caller data escapes this parsing boundary.
    return { ok: false }
  }
}

function copy(value: unknown, budget: { nodes: number; bytes: number }, depth: number, allowClock: boolean): unknown {
  budget.nodes += 1
  if (depth > 64 || budget.nodes > 2048) throw new Error("Invalid operator data")
  if (typeof value === "string") {
    budget.bytes += Buffer.byteLength(JSON.stringify(value), "utf8")
    if (budget.bytes > 65536) throw new Error("Invalid operator data")
    return value
  }
  if (value === undefined || value === null || typeof value === "boolean" || typeof value === "number") return value
  if (typeof value !== "object") throw new Error("Invalid operator data")
  const prototype = Object.getPrototypeOf(value)
  const array = Array.isArray(value)
  if (prototype !== (array ? Array.prototype : Object.prototype) && prototype !== null)
    throw new Error("Invalid operator data")
  const keys = Reflect.ownKeys(value)
  if (keys.length > 2048) throw new Error("Invalid operator data")
  const entries = keys.filter((key) => !(array && key === "length")).map((key) => {
    if (typeof key !== "string") throw new Error("Invalid operator data")
    const descriptor = Object.getOwnPropertyDescriptor(value, key)
    if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) throw new Error("Invalid operator data")
    if (allowClock && !array && depth === 0 && key === "now" && typeof descriptor.value === "function")
      return [key, descriptor.value] as const
    if (!array) budget.bytes += Buffer.byteLength(JSON.stringify(key), "utf8") + 1
    if (budget.bytes > 65536) throw new Error("Invalid operator data")
    return [key, copy(descriptor.value, budget, depth + 1, allowClock)] as const
  })
  if (!array) return Object.freeze(Object.fromEntries(entries))
  const length = Object.getOwnPropertyDescriptor(value, "length")?.value
  if (!Number.isSafeInteger(length) || length < 0 || length > 2048 || entries.length !== length ||
    entries.some(([key], index) => key !== String(index))) throw new Error("Invalid operator data")
  return Object.freeze(entries.map((entry) => entry[1]))
}

export function record(value: unknown, keys: readonly string[]): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) ||
    Object.keys(value).some((key) => !keys.includes(key))) throw new Error("Invalid operator data")
  return value as Record<string, unknown>
}

export function text(value: unknown, max = 65536): string {
  if (typeof value !== "string" || value.length === 0 || Buffer.byteLength(value, "utf8") > max)
    throw new Error("Invalid operator data")
  return value
}

export function positive(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0 || value > Number.MAX_SAFE_INTEGER)
    throw new Error("Invalid operator data")
  return value
}

export function options(value: unknown) {
  const input = record(value, ["principal", "scope", "now", "ttlMillis", "maxCapabilities"])
  const principal = text(input.principal, 256)
  const scope = grant(input.scope)
  const ttlMillis = input.ttlMillis === undefined ? 3600000 : positive(input.ttlMillis)
  const maxCapabilities = input.maxCapabilities === undefined ? 128 : positive(input.maxCapabilities)
  if (!Number.isSafeInteger(maxCapabilities) || (input.now !== undefined && typeof input.now !== "function"))
    throw new Error("Invalid operator data")
  // The host clock is the sole callable input; descriptor copying preserves its identity.
  const now = input.now === undefined ? Date.now : input.now as () => number
  return { principal, scope, ttlMillis, maxCapabilities, now }
}

function list<A>(value: unknown, max: number, parse: (value: unknown) => A, key: (value: A) => string): readonly A[] {
  if (!Array.isArray(value) || value.length > max) throw new Error("Invalid operator data")
  const result = value.map(parse).sort((left, right) => key(left) < key(right) ? -1 : key(left) > key(right) ? 1 : 0)
  if (new Set(result.map(key)).size !== result.length) throw new Error("Invalid operator data")
  return Object.freeze(result)
}

export function placement(value: unknown): CapabilityOperatorContract.Placement {
  const input = record(value, ["projectID", "location"])
  text(input.projectID)
  const location = record(input.location, ["directory", "workspaceID"])
  text(location.directory)
  if (location.workspaceID !== undefined) text(location.workspaceID)
  const decoded = Schema.decodeUnknownOption(Schema.toType(Placement))(input)
  if (Option.isNone(decoded)) throw new Error("Invalid operator data")
  return Object.freeze({ projectID: decoded.value.projectID, location: Object.freeze({ ...decoded.value.location }) })
}

export function resource(value: unknown): CapabilityOperatorContract.Resource {
  const input = record(value, ["kind", "id"])
  return Object.freeze({ kind: text(input.kind), id: text(input.id) })
}

export function action(value: unknown): string {
  if (typeof value !== "string" || !actionPattern.test(value)) throw new Error("Invalid operator data")
  return value
}

export function placementKey(value: CapabilityOperatorContract.Placement) {
  return JSON.stringify([value.projectID, value.location.directory, value.location.workspaceID ?? null])
}

function resourceKey(value: CapabilityOperatorContract.Resource) {
  return JSON.stringify([value.kind, value.id])
}

export function grant(value: unknown): CapabilityOperatorContract.GrantScope {
  const input = record(value, ["placements", "actions", "resources"])
  const placements = input.placements === "instance" ? "instance" : list(input.placements, 64, placement, placementKey)
  const actions = list(input.actions, 32, (value) => value === "*" ? "*" : action(value), (value) => value)
  if (actions.includes("*") && actions.length !== 1) throw new Error("Invalid operator data")
  const resources = input.resources === undefined ? undefined : list(input.resources, 64, resource, resourceKey)
  return Object.freeze({ placements, actions, ...(resources === undefined ? {} : { resources }) })
}

export function subset(child: CapabilityOperatorContract.GrantScope, root: CapabilityOperatorContract.GrantScope) {
  return (root.actions.includes("*") || child.actions.every((action) => root.actions.includes(action))) &&
    (root.placements === "instance" || (child.placements !== "instance" &&
      child.placements.every((placement) => root.placements !== "instance" &&
        root.placements.some((allowed) => placementKey(allowed) === placementKey(placement))))) &&
    (root.resources === undefined || (child.resources !== undefined &&
      child.resources.every((resource) => root.resources?.some((allowed) => resourceKey(allowed) === resourceKey(resource)))))
}

export function target(value: unknown): CapabilityOperatorContract.Target {
  const input = record(value, ["action", "placement", "resource"])
  return Object.freeze({ action: action(input.action), placement: placement(input.placement),
    ...(input.resource === undefined ? {} : { resource: resource(input.resource) }) })
}

export function allows(scope: CapabilityOperatorContract.GrantScope, target: CapabilityOperatorContract.Target) {
  const resource = target.resource
  return (scope.actions.includes("*") || scope.actions.includes(target.action)) &&
    (scope.placements === "instance" || scope.placements.some((allowed) => placementKey(allowed) === placementKey(target.placement))) &&
    (scope.resources === undefined || (resource !== undefined &&
      scope.resources.some((allowed) => resourceKey(allowed) === resourceKey(resource))))
}

export function hash(scope: CapabilityOperatorContract.GrantScope) {
  return createHash("sha256").update(JSON.stringify(scope)).digest("hex")
}

export function request(value: unknown) {
  const input = record(value, ["requestID", "idempotencyKey"])
  const requestID = text(input.requestID, 128)
  if (!/^[\x21-\x7e]{1,128}(?![\s\S])/.test(requestID)) throw new Error("Invalid operator data")
  if (input.idempotencyKey === undefined) return Object.freeze({ requestID })
  const idempotencyKey = text(input.idempotencyKey, 128)
  if (!/^[A-Za-z0-9_-]{1,128}(?![\s\S])/.test(idempotencyKey)) throw new Error("Invalid operator data")
  return Object.freeze({ requestID, idempotencyKey })
}

import { NodeFileSystem } from "@effect/platform-node"
import { dirname, isAbsolute, join, relative, resolve as pathResolve, sep } from "path"
import { realpathSync } from "fs"
import * as NFS from "fs/promises"
import { lookup } from "mime-types"
import { Context, Effect, FileSystem, Layer, Schema } from "effect"
import { systemError, type PlatformError } from "effect/PlatformError"
import { Glob } from "./util/glob"
import { PhysicalPath } from "./util/physical-path"
import { serviceUse } from "./effect/service-use"
import { makeGlobalNode } from "./effect/app-node"
import { filesystem } from "./effect/app-node-platform"

export namespace FSUtil {
  export class FileSystemError extends Schema.TaggedErrorClass<FileSystemError>()("FileSystemError", {
    method: Schema.String,
    cause: Schema.optional(Schema.Defect()),
  }) {
    override get message() {
      const detail = this.cause instanceof Error ? this.cause.message : this.cause && String(this.cause)
      return `Filesystem operation failed: ${this.method}${detail ? `: ${detail}` : ""}`
    }
  }

  export type Error = PlatformError | FileSystemError

  export interface DirEntry {
    readonly name: string
    readonly type: "file" | "directory" | "symlink" | "other"
  }

  export interface Interface extends FileSystem.FileSystem {
    readonly isDir: (path: string) => Effect.Effect<boolean>
    readonly isFile: (path: string) => Effect.Effect<boolean>
    readonly existsSafe: (path: string) => Effect.Effect<boolean>
    readonly readFileStringSafe: (path: string) => Effect.Effect<string | undefined, Error>
    readonly readJson: (path: string) => Effect.Effect<unknown, Error>
    readonly writeJson: (path: string, data: unknown, mode?: number) => Effect.Effect<void, Error>
    readonly ensureDir: (path: string) => Effect.Effect<void, Error>
    /** Writes through a temp file in the same directory and renames it over `path`, so readers never see a partial file. */
    readonly writeAtomic: (path: string, content: string, mode?: number) => Effect.Effect<void, Error>
    readonly writeWithDirs: (path: string, content: string | Uint8Array, mode?: number) => Effect.Effect<void, Error>
    /** Write to a path already resolved to its real location, refusing any link found there at write time. */
    readonly writePhysical: (
      path: string,
      content: string | Uint8Array,
      options?: { exclusive?: boolean },
    ) => Effect.Effect<void, Error>
    readonly readDirectoryEntries: (path: string) => Effect.Effect<DirEntry[], Error>
    readonly resolve: (path: string) => Effect.Effect<string>
    readonly findUp: (target: string, start: string, stop?: string) => Effect.Effect<string[], Error>
    readonly up: (options: { targets: string[]; start: string; stop?: string }) => Effect.Effect<string[], Error>
    readonly globUp: (pattern: string, start: string, stop?: string) => Effect.Effect<string[], Error>
    readonly glob: (pattern: string, options?: Glob.Options) => Effect.Effect<string[], Error>
    readonly globMatch: (pattern: string, filepath: string) => boolean
  }

  export class Service extends Context.Service<Service, Interface>()("@orchestra/FileSystem") {}

  export const use = serviceUse(Service)

  const layer = Layer.effect(
    Service,
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem

      const existsSafe = Effect.fn("FileSystem.existsSafe")(function* (path: string) {
        return yield* fs.exists(path).pipe(Effect.orElseSucceed(() => false))
      })

      const readFileStringSafe = Effect.fn("FileSystem.readFileStringSafe")(function* (path: string) {
        return yield* fs.readFileString(path).pipe(
          Effect.catchReason("PlatformError", "NotFound", () => Effect.succeed(undefined)),
          Effect.catchReason("PlatformError", "PermissionDenied", () => Effect.succeed(undefined)),
        )
      })

      const isDir = Effect.fn("FileSystem.isDir")(function* (path: string) {
        const info = yield* fs.stat(path).pipe(Effect.catch(() => Effect.void))
        return info?.type === "Directory"
      })

      const isFile = Effect.fn("FileSystem.isFile")(function* (path: string) {
        const info = yield* fs.stat(path).pipe(Effect.catch(() => Effect.void))
        return info?.type === "File"
      })

      const readDirectoryEntries = Effect.fn("FileSystem.readDirectoryEntries")(function* (dirPath: string) {
        return yield* Effect.tryPromise({
          try: async () => {
            const entries = await NFS.readdir(dirPath, { withFileTypes: true })
            return entries.map(
              (e): DirEntry => ({
                name: e.name,
                type: e.isDirectory() ? "directory" : e.isSymbolicLink() ? "symlink" : e.isFile() ? "file" : "other",
              }),
            )
          },
          catch: (cause) => new FileSystemError({ method: "readDirectoryEntries", cause }),
        })
      })

      const resolve = Effect.fn("FileSystem.resolve")(function* (path: string) {
        const resolved = pathResolve(windowsPath(path))
        return yield* fs.realPath(resolved).pipe(
          Effect.catchReason("PlatformError", "NotFound", () => Effect.succeed(resolved)),
          Effect.orDie,
        )
      })

      const readJson = Effect.fn("FileSystem.readJson")(function* (path: string) {
        const text = yield* fs.readFileString(path)
        return yield* Effect.try({
          try: () => JSON.parse(text),
          catch: (cause) => new FileSystemError({ method: "readJson", cause }),
        })
      })

      const writeAtomic = Effect.fn("FileSystem.writeAtomic")(function* (path: string, content: string, mode?: number) {
        // Write to the real file when the path is a symlink, so the link survives the rename.
        const target = yield* fs.realPath(path).pipe(Effect.catchReason("PlatformError", "NotFound", () => Effect.succeed(path)))
        const temp = `${target}.${process.pid}.${Date.now()}.tmp`
        yield* fs.writeFileString(temp, content).pipe(
          Effect.andThen(mode ? fs.chmod(temp, mode) : Effect.void),
          Effect.andThen(fs.rename(temp, target)),
          Effect.tapError(() => fs.remove(temp, { force: true }).pipe(Effect.ignore)),
        )
      })

      const writeJson = Effect.fn("FileSystem.writeJson")(function* (path: string, data: unknown, mode?: number) {
        yield* writeAtomic(path, JSON.stringify(data, null, 2), mode)
      })

      const ensureDir = Effect.fn("FileSystem.ensureDir")(function* (path: string) {
        yield* fs.makeDirectory(path, { recursive: true }).pipe(
          // Bun on Windows can throw EEXIST here despite recursive mode.
          // https://github.com/oven-sh/bun/issues/21901
          Effect.catchIf(
            (error) => error.reason._tag === "AlreadyExists",
            (error) => isDir(path).pipe(Effect.flatMap((exists) => (exists ? Effect.void : Effect.fail(error)))),
          ),
        )
      })

      const writeWithDirs = Effect.fn("FileSystem.writeWithDirs")(function* (
        path: string,
        content: string | Uint8Array,
        mode?: number,
      ) {
        const write = typeof content === "string" ? fs.writeFileString(path, content) : fs.writeFile(path, content)

        yield* write.pipe(
          Effect.catchIf(
            (e) => e.reason._tag === "NotFound",
            () =>
              Effect.gen(function* () {
                yield* fs.makeDirectory(dirname(path), { recursive: true })
                yield* write
              }),
          ),
        )
        if (mode) yield* fs.chmod(path, mode)
      })

      const writePhysical = Effect.fn("FileSystem.writePhysical")(function* (
        path: string,
        content: string | Uint8Array,
        options?: { exclusive?: boolean },
      ) {
        yield* Effect.tryPromise({
          try: () => PhysicalPath.writePhysical(path, content, options),
          catch: (cause) =>
            systemError({
              _tag: cause instanceof Error && "code" in cause && cause.code === "EEXIST" ? "AlreadyExists" : "Unknown",
              module: "FileSystem",
              method: "writePhysical",
              pathOrDescriptor: path,
              cause,
            }),
        })
      })

      const glob = Effect.fn("FileSystem.glob")(function* (pattern: string, options?: Glob.Options) {
        return yield* Effect.tryPromise({
          try: () => Glob.scan(pattern, options),
          catch: (cause) => new FileSystemError({ method: "glob", cause }),
        })
      })

      const findUp = Effect.fn("FileSystem.findUp")(function* (target: string, start: string, stop?: string) {
        const result: string[] = []
        let current = start
        while (true) {
          const search = join(current, target)
          if (yield* fs.exists(search)) result.push(search)
          if (stop === current) break
          const parent = dirname(current)
          if (parent === current) break
          current = parent
        }
        return result
      })

      const up = Effect.fn("FileSystem.up")(function* (options: { targets: string[]; start: string; stop?: string }) {
        const result: string[] = []
        let current = options.start
        while (true) {
          for (const target of options.targets) {
            const search = join(current, target)
            if (yield* fs.exists(search)) result.push(search)
          }
          if (options.stop === current) break
          const parent = dirname(current)
          if (parent === current) break
          current = parent
        }
        return result
      })

      const globUp = Effect.fn("FileSystem.globUp")(function* (pattern: string, start: string, stop?: string) {
        const result: string[] = []
        let current = start
        while (true) {
          const matches = yield* glob(pattern, { cwd: current, absolute: true, include: "file", dot: true }).pipe(
            Effect.catch(() => Effect.succeed([] as string[])),
          )
          result.push(...matches)
          if (stop === current) break
          const parent = dirname(current)
          if (parent === current) break
          current = parent
        }
        return result
      })

      return Service.of({
        ...fs,
        existsSafe,
        readFileStringSafe,
        isDir,
        isFile,
        readDirectoryEntries,
        resolve,
        readJson,
        writeJson,
        writeAtomic,
        ensureDir,
        writeWithDirs,
        writePhysical,
        findUp,
        up,
        globUp,
        glob,
        globMatch: Glob.match,
      })
    }),
  )

  export const node = makeGlobalNode({ service: Service, layer: layer, deps: [filesystem] })

  // Pure helpers that don't need Effect (path manipulation, sync operations)
  export function mimeType(p: string): string {
    return lookup(p) || "application/octet-stream"
  }

  export function normalizePath(p: string): string {
    if (process.platform !== "win32") return p
    const resolved = pathResolve(windowsPath(p))
    try {
      return realpathSync.native(resolved)
    } catch {
      return resolved
    }
  }

  export function normalizePathPattern(p: string): string {
    if (process.platform !== "win32") return p
    if (p === "*") return p
    const match = p.match(/^(.*)[\\/]\*$/)
    if (!match) return normalizePath(p)
    const dir = /^[A-Za-z]:$/.test(match[1]) ? match[1] + "\\" : match[1]
    return join(normalizePath(dir), "*")
  }

  export function resolve(p: string): string {
    const resolved = pathResolve(windowsPath(p))
    try {
      return normalizePath(realpathSync(resolved))
    } catch (e: any) {
      if (e?.code === "ENOENT") return normalizePath(resolved)
      throw e
    }
  }

  export function windowsPath(p: string): string {
    if (process.platform !== "win32") return p
    return p
      .replace(/^\/([a-zA-Z]):(?:[\\/]|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/cygdrive\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/mnt\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
  }

  export function overlaps(a: string, b: string) {
    return contains(a, b) || contains(b, a)
  }

  export function contains(parent: string, child: string) {
    const result = relative(parent, child)
    return result === "" || (!isAbsolute(result) && result !== ".." && !result.startsWith(`..${sep}`))
  }
}

export * as PhysicalPath from "./physical-path"

import path from "path"
import fs, { type FileHandle } from "fs/promises"
import { constants } from "fs"

const MAX_LINKS = 40

/**
 * The real location of `target`: every symlink or junction in it is followed, including a dangling final link
 * (a write would create its target) and the nearest existing ancestor of a path that does not exist yet.
 */
export async function physicalPath(target: string, depth = 0): Promise<string> {
  if (depth > MAX_LINKS) throw new Error(`Too many symbolic links: ${target}`)
  const real = await fs.realpath(target).catch((error: NodeJS.ErrnoException) => {
    if (error.code === "ENOENT" || error.code === "ENOTDIR") return undefined
    throw error
  })
  if (real) return real
  const parent = path.dirname(target)
  if (parent === target) return target
  const base = await physicalPath(parent, depth + 1)
  const link = await fs.readlink(target).catch(() => undefined)
  if (link === undefined) return path.join(base, path.basename(target))
  return physicalPath(path.resolve(base, link), depth + 1)
}

/**
 * Write `content` to a path already resolved by `physicalPath` and judged by the permission checks. A symlink put
 * there afterwards, or in one of its parents, is refused instead of followed, and nothing is truncated before that
 * is known. `exclusive` refuses a target that already exists.
 *
 * There is no `openat` here, so a parent swapped for a link exactly while the file is opened can still leave a new,
 * empty file where that link points; the checks after the open make sure nothing is written to it.
 */
export async function writePhysical(target: string, content: string | Uint8Array, options?: { exclusive?: boolean }) {
  await fs.mkdir(path.dirname(target), { recursive: true })
  // O_NOFOLLOW does not exist on Windows; the checks after the open cover a final-component swap there.
  const handle = await fs.open(
    target,
    constants.O_WRONLY | constants.O_CREAT | (options?.exclusive ? constants.O_EXCL : 0) | (constants.O_NOFOLLOW ?? 0),
    0o666,
  )
  await opensAt(handle, target)
    .then(async (same) => {
      if (!same) throw new Error(`Refusing to write through a changed link: ${target}`)
      await handle.truncate(0)
      await handle.writeFile(content)
    })
    .finally(() => handle.close())
}

// Whether the opened file is the one at `target`, reached with no link on the way. On Linux the descriptor names its
// own path. Elsewhere the path is checked first and its file then matched to the descriptor, so a parent swapped and
// swapped back around the open is caught; the path check must come before the identity check for that.
async function opensAt(handle: FileHandle, target: string) {
  if (process.platform === "linux") {
    const own = await fs.readlink(`/proc/self/fd/${handle.fd}`).catch(() => undefined)
    if (own !== undefined) return own === target
  }
  if ((await fs.realpath(target).catch(() => undefined)) !== target) return false
  const named = await fs.lstat(target, { bigint: true }).catch(() => undefined)
  const opened = await handle.stat({ bigint: true })
  return named !== undefined && named.dev === opened.dev && named.ino === opened.ino
}

export * as CapabilityMedia from "./index"

import { Buffer } from "node:buffer"
import { createHash } from "node:crypto"
import { Capability } from "@orchestra/schema/capability"
import { Permission } from "@orchestra/schema/permission"
import { and, eq } from "drizzle-orm"
import { Cause, Context, Effect, Exit, Option, Schema } from "effect"
import { AgentV2 } from "../../agent"
import { Credential } from "../../credential"
import { Database } from "../../database/database"
import { Location } from "../../location"
import { PermissionV2 } from "../../permission"
import { Tool } from "../../tool/tool"
import { CapabilityArtifacts } from "../artifact"
import { CapabilityConnections } from "../connection"
import { CapabilityInvocation } from "../invocation"
import { CapabilityJobs } from "../job"
import { CapabilityPolicy } from "../policy"
import { CapabilityBindingTable, CapabilityConnectionTable, CapabilityJobTable, CapabilityTargetTable } from "../sql"
import { base64, dataURL, defaults, image, json, jsonBody, multipart, request, type Budgets } from "./http"
import { failure, ImageInput, ObserveInput, TargetResource, validateImage, validateVideo, VideoInput } from "./schema"

export { ImageInput, VideoInput, TargetResource }

export type Options = {
  /** Trusted host override of transport ONLY. Stored connections still require fixed production endpoint. */
  fixtureOrigin?: string
  budgets?: Partial<Budgets>
  artifacts?: CapabilityArtifacts.Options
}
export type Observe = {
  proof: CapabilityJobs.ProducerProof
  jobRef: Capability.JobRef
  operation: "observe" | "materialize" | "cancel"
  /** Actual active invocation, with its host-issued frame in scope; never a synthesized producer Context. */
  liveRoot?: Tool.Context
}

const endpoints = { openai: "https://api.openai.com/v1", runway: "https://api.dev.runwayml.com" }
const Submitted = Schema.Struct({ id: Schema.String.check(Schema.isPattern(/^[0-9A-Za-z][0-9A-Za-z._:-]{0,255}(?![\s\S])/)) })
const Images = Schema.Struct({ data: Schema.Array(Schema.Struct({ b64_json: Schema.String })).check(Schema.isMinLength(1), Schema.isMaxLength(4)) })
const Task = Schema.Struct({ id: Schema.String, status: Schema.Literals(["PENDING", "RUNNING", "THROTTLED", "SUCCEEDED", "FAILED", "CANCELLED"]),
  output: Schema.optionalKey(Schema.Array(Schema.String).check(Schema.isMaxLength(1))) })
const StoredPolicy = Schema.Struct({ effectiveRules: Permission.Ruleset, nativeDenyFloor: Permission.Ruleset })
const observationRoots = Object.freeze(["image_create", "video_create"])

/** Captures existing Location services; registration belongs to host/lead. Construction performs no vendor I/O. */
export const make = (options: Options = {}) => Effect.gen(function* () {
  const database = yield* Database.Service
  const location = yield* Location.Service
  const credentials = yield* Credential.Service
  const permissions = yield* PermissionV2.Service
  const agents = yield* AgentV2.Service
  const connections = yield* CapabilityConnections.make
  const jobs = yield* CapabilityJobs.make
  const policy = yield* CapabilityPolicy.make
  const artifacts = yield* CapabilityArtifacts.make(options.artifacts)
  const budgets = Object.freeze({ ...defaults, ...options.budgets })
  const fixtureOrigin = options.fixtureOrigin
  if (Object.values(budgets).some((n) => !Number.isSafeInteger(n) || n <= 0) ||
    budgets.responseBytes > defaults.responseBytes || budgets.downloadBytes > defaults.downloadBytes ||
    budgets.requestBytes > defaults.requestBytes || budgets.pixels > defaults.pixels || budgets.timeoutMillis > defaults.timeoutMillis)
    return yield* failure("unsupported_schema")
  if (fixtureOrigin !== undefined && (!URL.canParse(fixtureOrigin) || new URL(fixtureOrigin).origin !== fixtureOrigin ||
    new URL(fixtureOrigin).protocol !== "http:" || new URL(fixtureOrigin).hostname !== "127.0.0.1"))
    return yield* failure("target_denied")
  const placement = { projectID: location.project.id,
    location: Location.Ref.make({ directory: location.directory, workspaceID: location.workspaceID }) }
  const apiURL = (provider: "openai" | "runway", path: string) =>
    `${fixtureOrigin ? `${fixtureOrigin}${provider === "openai" ? "/v1" : ""}` : endpoints[provider]}${path}`
  const headers = (token: string, provider: "openai" | "runway") => ({ Authorization: `Bearer ${token}`,
    ...(provider === "runway" ? { "X-Runway-Version": "2024-11-06" } : {}) })

  const select = Effect.fn("CapabilityMedia.select")(function* (
    context: Tool.Context, input: ImageInput | VideoInput, action: string,
  ) {
    yield* policy.assert(context, { action, resources: [input.provider, input.connection.id, input.target.id, `purpose:${input.purpose}`] })
    const resolved = yield* connections.resolve(context, { provider: input.provider,
      connectionID: input.connection.id, targetID: input.target.id, action }).pipe(
        Effect.mapError((error) => error instanceof Capability.Failure ? error : failure("target_denied")))
    if (resolved.connection.generation !== input.connection.generation || resolved.target.generation !== input.target.generation ||
      resolved.target.environment !== input.target.environment) return yield* failure("stale_descriptor")
    if (resolved.endpoint.replace(/\/$/, "") !== endpoints[input.provider]) return yield* failure("unsupported_operation")
    const resource = Schema.decodeUnknownOption(TargetResource)(resolved.resource)
    if (Option.isNone(resource) || resource.value.purpose !== input.purpose) return yield* failure("target_denied")
    const credential = yield* connections.loadCredential(context, resolved, action)
    yield* accessToken(credential)
    return resolved
  })

  const producer = Effect.fn("CapabilityMedia.producer")(function* (context: Tool.Context, expected?: string) {
    const binding = yield* CapabilityInvocation.require(context, placement)
    if (!observationRoots.includes(binding.rootToolName) || (expected !== undefined && binding.rootToolName !== expected))
      return yield* failure("invocation_binding_mismatch")
    return { owner: binding.owner, producer: binding.invocation, rootToolName: binding.rootToolName } satisfies CapabilityJobs.ProducerProof
  })
  const record = (ref: Capability.JobRef) => database.db.select().from(CapabilityJobTable)
    .where(eq(CapabilityJobTable.id, ref.id)).get().pipe(Effect.orDie)

  const submitToken = Effect.fn("CapabilityMedia.submitToken")(function* (
    context: Tool.Context, resolved: CapabilityConnections.Resolution, action: string, purpose: string,
  ) {
    yield* policy.assert(context, { action, resources: [resolved.connection.provider, resolved.connection.id, resolved.target.id, `purpose:${purpose}`] })
    const credential = yield* connections.loadCredential(context, resolved, action)
    return yield* accessToken(credential)
  })

  // HTTP stays interruptible. Once bytes arrive, parsing and durable ACK form one protected handoff.
  const acknowledge = <A>(proof: CapabilityJobs.ProducerProof, submitting: CapabilityJobs.Receipt,
    io: Effect.Effect<Uint8Array, Capability.Failure>, schema: Schema.Codec<A>,
    completed: (value: A) => Pick<CapabilityJobs.TransitionInput, "state" | "providerID" | "observation">,
  ) => Effect.uninterruptibleMask((restore) => Effect.gen(function* () {
    const response = yield* restore(io).pipe(Effect.result,
      Effect.onInterrupt(() => jobs.observeHost(proof, submitting.ref,
        { expectedGeneration: submitting.generation, state: "unknown", observation: {} }).pipe(Effect.asVoid)))
    const parsed = response._tag === "Success" ? yield* json(response.success, schema).pipe(Effect.result) : response
    const receipt = yield* jobs.observeHost(proof, submitting.ref, { expectedGeneration: submitting.generation,
      ...(parsed._tag === "Success" ? completed(parsed.success) : { state: "unknown" as const, observation: {} }) })
    return { parsed, receipt }
  }))

  // Separate trusted-host authorization. Proof establishes provenance, never grants polling/download authority.
  const hostCredential = Effect.fn("CapabilityMedia.hostCredential")(function* (
    proof: CapabilityJobs.ProducerProof, ref: Capability.JobRef, action: string,
  ) {
    if (proof.rootToolName !== "video_create") return yield* failure("target_denied")
    yield* jobs.readHost(proof, ref)
    return yield* agents.withPermissions(proof.owner.agentID, () => database.db.transaction((tx) => Effect.gen(function* () {
      const row = yield* tx.select().from(CapabilityJobTable).where(eq(CapabilityJobTable.id, ref.id)).get().pipe(Effect.orDie)
      if (!row?.connection || !row.target || row.operation !== "video_create" || row.connection.provider !== "runway")
        return yield* failure("target_denied")
      const connection = yield* tx.select().from(CapabilityConnectionTable)
        .where(eq(CapabilityConnectionTable.id, row.connection.id)).get().pipe(Effect.orDie)
      const target = yield* tx.select().from(CapabilityTargetTable).where(eq(CapabilityTargetTable.id, row.target.id)).get().pipe(Effect.orDie)
      const bound = yield* tx.select().from(CapabilityBindingTable).where(and(
        eq(CapabilityBindingTable.target_id, row.target.id), eq(CapabilityBindingTable.session_id, proof.owner.sessionID),
        eq(CapabilityBindingTable.agent_id, proof.owner.agentID),
      )).get().pipe(Effect.orDie)
      if (!connection || !target || connection.state !== "active" || connection.provider !== "runway" ||
        connection.generation !== row.connection.generation || target.generation !== row.target.generation ||
        target.environment !== row.target.environment || row.target.connectionID !== connection.id || target.connection_id !== connection.id ||
        connection.project_id !== proof.owner.projectID || connection.directory !== proof.owner.location.directory ||
        (connection.workspace_id ?? undefined) !== proof.owner.location.workspaceID ||
        connection.endpoint.replace(/\/$/, "") !== endpoints.runway || !bound ||
        ![row.operation, action].every((value) => bound.actions.includes(value) || bound.actions.includes("*")))
        return yield* failure("target_denied")
      const stored = yield* Schema.decodeUnknownEffect(StoredPolicy)(row.observation).pipe(Effect.orDie)
      const resource = Schema.decodeUnknownOption(TargetResource)(target.resource)
      if (Option.isNone(resource)) return yield* failure("target_denied")
      const resources = ["runway", connection.id, target.id, `purpose:${resource.value.purpose}`]
      if (resources.some((resource) =>
        PermissionV2.evaluate(action, resource, stored.nativeDenyFloor.filter((rule) => rule.effect === "deny")).effect === "deny" ||
        PermissionV2.evaluate(action, resource, stored.effectiveRules).effect !== "allow")) return yield* failure("target_denied")
      if ((yield* permissions.evaluate({ sessionID: proof.owner.sessionID, agent: proof.owner.agentID, action, resources })) !== "allow")
        return yield* failure("target_denied")
      if (!connection.credential_id) return yield* failure("authentication_required")
      const saved = yield* credentials.get(connection.credential_id)
      if (!saved || saved.id !== connection.credential_id || saved.integrationID !== connection.integration_id)
        return yield* failure("authentication_revoked")
      const token = yield* accessToken(saved.value)
      return { token, purpose: resource.value.purpose }
    }), { behavior: "immediate" })).pipe(Effect.catchTag("SqlError", Effect.die),
      Effect.catchTag("Session.NotFoundError", () => Effect.fail(failure("target_denied"))))
  })

  const observeHost = Effect.fn("CapabilityMedia.observeHost")(function* (supplied: Observe): Effect.fn.Return<Capability.Result,
    Capability.Failure | CapabilityArtifacts.Failure> {
    // Snapshot caller-owned proof before waits; host inputs never contain a credential or claim URL.
    const proof = structuredClone(supplied.proof)
    if (proof.rootToolName !== "video_create") return yield* failure("target_denied")
    const ref = { ...supplied.jobRef }
    const operation = supplied.operation
    const liveRoot = supplied.liveRoot ? { ...supplied.liveRoot } : undefined
    if (!["observe", "materialize", "cancel"].includes(operation)) return yield* failure("unsupported_operation")
    const read = yield* jobs.readHost(proof, ref)
    const row = yield* record(ref)
    if (!row || row.operation !== "video_create" || !read.providerID) return yield* failure("unsupported_operation")
    if (liveRoot) {
      const active = yield* producer(liveRoot)
      if (active.owner.projectID !== proof.owner.projectID || active.owner.sessionID !== proof.owner.sessionID ||
        active.owner.agentID !== proof.owner.agentID || active.owner.location.directory !== proof.owner.location.directory ||
        active.owner.location.workspaceID !== proof.owner.location.workspaceID) return yield* failure("target_denied")
      // Full policy/persisted-root checks via read, not an invented producer Tool.Context.
      yield* jobs.read(liveRoot, ref)
    }
    if (["failed", "cancelled", "lost"].includes(read.receipt.state) || read.receipt.observation.materialization === "complete")
      return project(read.receipt)
    const action = `video_create.${operation === "cancel" ? "cancel" : "observe"}`
    const authorized = yield* hostCredential(proof, ref, action)
    if (liveRoot) yield* policy.assert(liveRoot, { action, resources: ["runway", ...(row.connection ? [row.connection.id] : []),
      ...(row.target ? [row.target.id] : []), `purpose:${authorized.purpose}`] })
    const current = yield* hostCredential(proof, ref, action)
    if (current.purpose !== authorized.purpose) return yield* failure("target_denied")
    if (operation === "cancel") {
      // Pinned provider declares no cancel endpoint: no DELETE guess and no fabricated confirmation.
      const next = yield* jobs.observeHost(proof, ref, { expectedGeneration: read.receipt.generation,
        state: read.receipt.state, observation: { ...read.receipt.observation, cancellation: "unsupported" } })
      return { status: "partial", receipt: ref.id, summary: "Provider cancellation unsupported",
        completedEffects: [], unresolvedEffects: ["provider-cancellation-unsupported"], artifactRefs: next.observation.artifactRefs ?? [] }
    }
    const observed = yield* Effect.uninterruptibleMask((restore) => Effect.gen(function* () {
      const response = yield* restore(request(apiURL("runway", `/v1/tasks/${read.providerID}`),
        { headers: headers(current.token, "runway") }, Math.min(budgets.responseBytes, 64 * 1024), budgets.timeoutMillis))
      const task = yield* json(response, Task)
      if (task.id !== read.providerID) return yield* failure("outcome_unknown")
      if (task.status === "FAILED" || task.status === "CANCELLED") {
        // Remote cancellation ends generation; never invent a local cancellation request or acknowledgement.
        const receipt = yield* jobs.observeHost(proof, ref, { expectedGeneration: read.receipt.generation,
          state: "failed", observation: { remoteOutcome: "failed" } })
        return { task, receipt }
      }
      if (task.status !== "SUCCEEDED") {
        if (read.receipt.state === "completed") return yield* failure("outcome_unknown")
        const receipt = yield* jobs.observeHost(proof, ref, { expectedGeneration: read.receipt.generation,
          state: task.status === "RUNNING" ? "running" : read.receipt.state, observation: read.receipt.observation })
        return { task, receipt }
      }
      const receipt = read.receipt.state === "completed" ? read.receipt : yield* jobs.observeHost(proof, ref,
        { expectedGeneration: read.receipt.generation, state: "completed", observation: { remoteOutcome: "completed", materialization: "pending" } })
      return { task, receipt }
    }))
    const task = observed.task
    const completed = observed.receipt
    if (task.status === "CANCELLED") return { status: "partial", receipt: ref.id, summary: "Remote cancellation observed",
      completedEffects: ["remote-cancellation-observed"], unresolvedEffects: [], artifactRefs: [] }
    if (task.status !== "SUCCEEDED") return project(completed)
    if (operation !== "materialize" || !liveRoot) return project(completed)
    const materialized = yield* Effect.gen(function* () {
      if (!task.output || task.output.length !== 1) return yield* failure("acquisition_failed")
      const url = yield* downloadURL(task.output[0], fixtureOrigin)
      const download = yield* hostCredential(proof, ref, "video_create.download")
      yield* policy.assert(liveRoot, { action: "video_create.download", resources: ["runway", ...(row.connection ? [row.connection.id] : []),
        ...(row.target ? [row.target.id] : []), `purpose:${download.purpose}`] })
      const current = yield* hostCredential(proof, ref, "video_create.download")
      if (current.purpose !== download.purpose) return yield* failure("target_denied")
      const data = yield* request(url, { headers: new URL(url).origin === new URL(endpoints.runway).origin
        ? headers(current.token, "runway") : {} }, budgets.downloadBytes, budgets.timeoutMillis)
      // Artifact store is authoritative. Until lead adds structural MP4 support this fails explicitly.
      return yield* artifacts.publish(liveRoot, { data, mime: "video/mp4", kind: "video", verification: "observed",
        metadata: { provider: "runway" } }, [{ action: "video_create.download", resources: ["runway", ...(row.connection ? [row.connection.id] : []),
          ...(row.target ? [row.target.id] : []), `purpose:${current.purpose}`] }])
    }).pipe(Effect.result, Effect.onInterrupt(() => jobs.observeHost(proof, ref,
      { expectedGeneration: completed.generation, state: "completed", observation: { remoteOutcome: "completed", materialization: "failed" } }).pipe(Effect.asVoid)))
    const published = yield* jobs.observeHost(proof, ref, { expectedGeneration: completed.generation, state: "completed",
      observation: { remoteOutcome: "completed", materialization: materialized._tag === "Success" ? "complete" : "failed",
        ...(materialized._tag === "Success" ? { artifactRefs: [materialized.success] } : {}) } })
    return project(published)
  })

  const createImage = Effect.fn("CapabilityMedia.createImage")(function* (supplied: ImageInput, context: Tool.Context) {
    const input = snapshotRequest(supplied)
    const proof = yield* producer(context, "image_create")
    const invalid = validateImage(input)
    if (invalid) return yield* invalid
    const resolved = yield* select(context, input, "image_create")
    const admitted = yield* jobs.admit(context, { kind: "worker", operation: "image_create", requestHash: requestHash(input, proof),
      connection: resolved.connection, target: resolved.target })
    const ref = admitted.ref
    const current = yield* jobs.read(context, ref)
    if (admitted.reused || current.state !== "intent") return project(current)
    const mime = input.options.format === "png" ? "image/png" : "image/jpeg"
    const captured = { bytes: 0 }
    const inputs = yield* Effect.forEach(input.inputArtifactRefs, (ref) => Effect.gen(function* () {
      const source = yield* artifacts.read(context, ref)
      captured.bytes += source.data.byteLength
      if (captured.bytes > budgets.downloadBytes) return yield* failure("quota_exceeded")
      yield* image(source.data, source.metadata.mime, budgets)
      return source
    }))
    const body = { model: input.model, prompt: input.prompt, n: input.options.count, size: input.options.size,
      quality: input.options.quality, output_format: input.options.format, background: input.options.background }
    const payload = input.operation === "edit" ? yield* multipart(body, inputs.map((source, index) => ({
      name: "image[]", filename: `input-${index}.${source.metadata.mime === "image/png" ? "png" : "jpeg"}`,
      mime: source.metadata.mime, data: source.data,
    })), budgets.requestBytes) : yield* jsonBody(body, budgets.requestBytes)
    const submitting = yield* jobs.transition(context, ref, { expectedGeneration: current.generation, state: "submitting", observation: {} })
    const token = yield* submitToken(context, resolved, "image_create", input.purpose)
    const handoff = yield* acknowledge(proof, submitting, request(apiURL("openai", `/images/${input.operation === "edit" ? "edits" : "generations"}`),
      { method: "POST", headers: { ...headers(token, "openai"), ...(input.operation === "edit" ? {} : { "Content-Type": "application/json" }) },
        body: payload }, budgets.responseBytes, budgets.timeoutMillis, budgets.requestBytes), Images,
      () => ({ state: "completed", observation: { remoteOutcome: "completed", materialization: "pending" } }))
    if (handoff.parsed._tag === "Failure") return project(handoff.receipt)
    const submitted = handoff.parsed.success
    const completed = handoff.receipt
    const retained: Capability.ArtifactRef[] = []
    const publication = yield* Effect.gen(function* () {
      if (submitted.data.length !== input.options.count) return yield* failure("acquisition_failed")
      yield* Effect.forEach(submitted.data, (value) => Effect.gen(function* () {
        const data = yield* base64(value.b64_json, budgets.downloadBytes)
        const dimensions = yield* image(data, mime, budgets)
        const ref = yield* artifacts.publish(context, { data, mime, kind: "image", verification: "observed",
          metadata: { provider: "openai", model: input.model, ...dimensions } }, [{ action: "image_create",
            resources: ["openai", resolved.connection.id, resolved.target.id, `purpose:${input.purpose}`] }])
        retained.push(ref)
      }))
    }).pipe(Effect.result, Effect.onInterrupt(() => jobs.observeHost(proof, ref, { expectedGeneration: completed.generation,
      state: "completed", observation: { remoteOutcome: "completed", materialization: "failed", artifactRefs: retained } }).pipe(Effect.asVoid)))
    const published = yield* jobs.observeHost(proof, ref, { expectedGeneration: completed.generation, state: "completed",
      observation: { remoteOutcome: "completed", materialization: publication._tag === "Success" ? "complete" : "failed", artifactRefs: retained } })
    return project(published)
  })

  const createVideo = Effect.fn("CapabilityMedia.createVideo")(function* (supplied: VideoInput, context: Tool.Context) {
    const input = snapshotRequest(supplied)
    const proof = yield* producer(context, "video_create")
    const invalid = validateVideo(input)
    if (invalid) return yield* invalid
    const resolved = yield* select(context, input, "video_create")
    const admitted = yield* jobs.admit(context, { kind: "provider", operation: "video_create", requestHash: requestHash(input, proof),
      connection: resolved.connection, target: resolved.target })
    const ref = admitted.ref
    const current = yield* jobs.read(context, ref)
    if (admitted.reused || current.state !== "intent") return project(current)
    const source = input.inputArtifactRefs[0] ? yield* artifacts.read(context, input.inputArtifactRefs[0]) : undefined
    if (source && input.operation === "image-to-video") yield* image(source.data, source.metadata.mime, budgets)
    if (source && input.operation === "edit" && source.metadata.mime !== "video/mp4") return yield* failure("unsupported_operation")
    if (source && source.data.byteLength > budgets.downloadBytes) return yield* failure("quota_exceeded")
    const body = { model: input.model, promptText: input.prompt, ratio: input.options.ratio,
      ...(input.operation === "edit" ? {} : { duration: input.options.duration }) }
    const field = input.operation === "edit" ? "videoUri" : "promptImage"
    const envelope = yield* jsonBody({ ...body, ...(source ? { [field]: "" } : {}) }, budgets.requestBytes)
    const payload = source ? yield* Effect.gen(function* () {
      const uri = yield* dataURL(source.data, source.metadata.mime, budgets.requestBytes - Buffer.byteLength(envelope))
      return yield* jsonBody({ ...body, [field]: uri }, budgets.requestBytes)
    }) : envelope
    const submitting = yield* jobs.transition(context, ref, { expectedGeneration: current.generation, state: "submitting", observation: {} })
    const token = yield* submitToken(context, resolved, "video_create", input.purpose)
    const path = input.operation === "generate" ? "/v1/text_to_video" : input.operation === "edit" ? "/v1/video_to_video" : "/v1/image_to_video"
    const handoff = yield* acknowledge(proof, submitting, request(apiURL("runway", path), { method: "POST", headers: { ...headers(token, "runway"),
      "Content-Type": "application/json" }, body: payload }, Math.min(budgets.responseBytes, 64 * 1024), budgets.timeoutMillis, budgets.requestBytes),
      Submitted, (value) => ({ state: "submitted", providerID: value.id, observation: {} }))
    return project(handoff.receipt)
  })

  const liveObserve = Effect.fn("CapabilityMedia.liveObserve")(function* (
    input: typeof ObserveInput.Type, context: Tool.Context,
  ) {
    yield* producer(context, "video_create")
    yield* jobs.read(context, input.jobRef)
    const row = yield* record(input.jobRef)
    if (!row) return yield* failure("stale_descriptor")
    const stored = yield* Schema.decodeUnknownEffect(Schema.Struct({ rootToolName: Schema.String }))(row.observation).pipe(Effect.orDie)
    return yield* observeHost({ proof: { owner: row.owner, producer: row.invocation, rootToolName: stored.rootToolName },
      jobRef: input.jobRef, operation: input.operation, liveRoot: context })
  })
  const tools = {
    image_create: Tool.make({ description: "Generate/edit OpenAI images using explicit bound connection and authorized Artifact inputs. Returns immutable Artifacts; uncertain paid submissions never retry.",
      input: ImageInput, output: Capability.Result, execute: (input, context) => createImage(input, context).pipe(toolErrors),
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }] }),
    video_create: Tool.make({ description: "Submit Runway video generation/edit and return durable Job immediately. Observe/materialize known Job without resubmitting. Cancellation unsupported by pinned provider contract.",
      input: Schema.Union([VideoInput, ObserveInput]), output: Capability.Result,
      execute: (input, context) => ("jobRef" in input ? liveObserve(input, context) : createVideo(input, context)).pipe(toolErrors),
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }] }),
  }
  return { tools, observeHost }
})
export type Interface = Effect.Success<ReturnType<typeof make>>

function snapshotRequest<A extends ImageInput | VideoInput>(supplied: A) {
  const input = structuredClone(supplied)
  Object.freeze(input.connection)
  Object.freeze(input.target)
  Object.freeze(input.options)
  input.inputArtifactRefs.forEach((ref) => Object.freeze(ref))
  Object.freeze(input.inputArtifactRefs)
  return Object.freeze(input)
}

/** Fixed-position canonical payload: property insertion order cannot alter identity; Artifact revisions stay exact. */
function requestHash(input: ImageInput | VideoInput, proof: CapabilityJobs.ProducerProof) {
  return createHash("sha256").update(JSON.stringify([
    "media-request-v1", proof.rootToolName, input.provider, input.model, input.operation, input.prompt,
    input.provider === "openai" ? [input.options.size, input.options.quality, input.options.format, input.options.background, input.options.count]
      : [input.options.ratio, input.options.duration],
    input.inputArtifactRefs.map((ref) => [ref.id, ref.revision]), input.purpose,
    [input.connection.id, input.connection.provider, input.connection.generation],
    [input.target.id, input.target.connectionID, input.target.generation, input.target.environment],
    [proof.owner.projectID, proof.owner.location.directory, proof.owner.location.workspaceID ?? null, proof.owner.sessionID, proof.owner.agentID],
  ])).digest("hex")
}

function accessToken(value: Credential.Value) {
  if (value.type === "oauth" && (!Number.isSafeInteger(value.expires) || value.expires <= Date.now())) return Effect.fail(failure("authentication_required"))
  const token = value.type === "key" ? value.key : value.access
  return token.length > 0 && token.length <= 16384 && !/[\s\u0000-\u001f\u007f]/.test(token)
    ? Effect.succeed(token) : Effect.fail(failure("authentication_required"))
}

function toolErrors<A>(effect: Effect.Effect<A, CapabilityArtifacts.Error>) {
  return effect.pipe(Effect.exit, Effect.flatMap((exit) => Exit.isSuccess(exit) ? Effect.succeed(exit.value) :
    Effect.failCause(Cause.fromReasons<Tool.Failure>(exit.cause.reasons.flatMap((reason) =>
    reason._tag === "Fail" ? Cause.fail(new Tool.Failure({
      message: `Media capability failed: ${"code" in reason.error ? reason.error.code : "artifact_storage_failed"}`,
    })).reasons.map((next) => next.annotate(Context.makeUnsafe(new Map(reason.annotations)))) : [reason]),
  ))))
}

function project(receipt: CapabilityJobs.Receipt): Capability.Result {
  const ref = receipt.ref.id
  if (receipt.state === "completed") {
    if (receipt.observation.materialization === "complete" && receipt.observation.artifactRefs?.length)
      return { status: "completed", receipt: ref, summary: "Media artifact published", verification: "observed", artifactRefs: receipt.observation.artifactRefs }
    return { status: "partial", receipt: ref, summary: "Provider completed; artifact materialization incomplete",
      completedEffects: ["provider-completed"], unresolvedEffects: [receipt.observation.materialization === "failed" ? "materialization-failed" : "materialization-pending"],
      artifactRefs: receipt.observation.artifactRefs ?? [] }
  }
  if (["submitting", "unknown", "lost", "intent"].includes(receipt.state)) return { status: "unknown", receipt: ref,
    summary: "Submission outcome uncertain; automatic resubmission disabled", reconciliationRef: ref }
  if (receipt.state === "cancelled" || receipt.state === "failed") return { status: "partial", receipt: ref,
    summary: receipt.state === "cancelled" ? "Provider cancellation observed" : "Provider failure observed",
    completedEffects: [receipt.state === "cancelled" ? "provider-cancelled" : "provider-failed"], unresolvedEffects: [], artifactRefs: [] }
  return { status: "submitted", receipt: ref, summary: "Provider task submitted; artifact not yet published", jobRef: receipt.ref }
}

function downloadURL(value: string, fixtureOrigin: string | undefined) {
  if (value !== value.trim() || !URL.canParse(value)) return Effect.fail(failure("target_denied"))
  const url = new URL(value)
  if (url.username || url.password || url.hash || value.length > 8192) return Effect.fail(failure("target_denied"))
  if (fixtureOrigin !== undefined && url.origin === fixtureOrigin) return Effect.succeed(url.href)
  // Pinned source declares only API host. CDN deployments stay unsupported until independently qualified.
  return url.protocol === "https:" && !url.port && url.hostname === "api.dev.runwayml.com"
    ? Effect.succeed(url.href) : Effect.fail(failure("unsupported_operation"))
}

export * as CapabilityDocuments from "./index"

import { Effect } from "effect"
import { Tool } from "../../tool/tool"
import { CapabilityArtifacts } from "../artifact"
import { NativeDocuments } from "./native"
import { Edit, Output, Read } from "./schema"

export const make = (options: CapabilityArtifacts.Options = {}) => Effect.gen(function* () {
  const native = yield* NativeDocuments.make(options)
  return Object.freeze({
    document_read: Tool.make({ description: "Read an authorized local PDF artifact: text, geometry, metadata, fields; optional bounded PNG raster. No OCR.",
      input: Read, output: Output,
      execute: (input, context) => native.execute("document_read", "pdf", input, context, [input.artifact], ["application/pdf"]),
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }],
    }),
    document_edit: Tool.make({ description: "Create, fill, truly flatten, merge, split, rotate or stamp local PDF artifacts. Edits use expectedRevision CAS. Encryption unsupported.",
      input: Edit, output: Output,
      execute: (input, context) => {
        if ("expectedRevision" in input && input.expectedRevision !== input.artifact.revision)
          return Effect.fail(new Tool.Failure({ message: "revision_conflict: Expected revision does not match artifact" }))
        return native.execute("document_edit", "pdf", input, context,
          "artifacts" in input ? input.artifacts : "artifact" in input ? [input.artifact] : [], ["application/pdf"],
          "expectedRevision" in input ? input.artifact : undefined)
      },
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }],
    }),
  })
})

export * as CapabilitySheets from "./index"

import { Effect } from "effect"
import { Tool } from "../../tool/tool"
import { CapabilityArtifacts } from "../artifact"
import { NativeDocuments } from "../document/native"
import { Output } from "../document/schema"
import { Edit, Read, mime } from "./schema"

export const make = (options: CapabilityArtifacts.Options = {}) => Effect.gen(function* () {
  const native = yield* NativeDocuments.make(options)
  return Object.freeze({
    sheet_read: Tool.make({ description: "Read authorized XLSX or UTF-8 CSV artifact. Literal values, formulas and cached results are distinct. Bounded ranges; no formula evaluation.",
      input: Read, output: Output,
      execute: (input, context) => native.execute("sheet_read", "sheet", input, context, [input.artifact], input.format === "csv" ? ["text/csv", "text/csv; charset=utf-8"] : [mime]),
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }],
    }),
    sheet_edit: Tool.make({ description: "Create/edit XLSX cells, styles, names; limited A1 restructure. Create/edit/import/export UTF-8 CSV, literal by default. Formulas require explicit opt-in. No calculation engine, macros or external refresh.",
      input: Edit, output: Output,
      execute: (input, context) => {
        if ("expectedRevision" in input && input.expectedRevision !== input.artifact.revision)
          return Effect.fail(new Tool.Failure({ message: "revision_conflict: Expected revision does not match artifact" }))
        return native.execute("sheet_edit", "sheet", input, context, "artifact" in input ? [input.artifact] : [],
          input.format === "csv" ? ["text/csv", "text/csv; charset=utf-8"] : [mime],
          "expectedRevision" in input ? input.artifact : undefined)
      },
      toModelOutput: ({ output }) => [{ type: "text", text: JSON.stringify(output) }],
    }),
  })
})
